class BankAccount:
    def __init__(self):
        """
        Initializes a new bank account with a balance of 0.
        """
        self.balance = 0

    def deposit(self, amount):
        """
        Deposits a specified amount into the account if the amount is positive.

        :param amount: The amount to deposit.
        """
        if amount > 0:
            self.balance += amount
        else:
            print("Deposit amount must be positive.")

    def withdraw(self, amount):
        """
        Withdraws a specified amount from the account if the amount is positive and sufficient funds are available.

        :param amount: The amount to withdraw.
        """
        if amount > self.balance:
            print("Insufficient funds.")
        elif amount < 0:
            print("Withdrawal amount must be positive.")
        else:
            self.balance -= amount

    def check_balance(self):
        """
        Returns the current balance of the account.

        :return: The current balance.
        """
        return self.balance

def factorial(n):
    """
    Computes the factorial of a non-negative integer n using recursion.

    Args:
        n (int): A non-negative integer.

    Returns:
        int: The factorial of the input number n.

    Raises:
        ValueError: If n is a negative number or not an integer.
    """
    if not isinstance(n, int):
        raise ValueError("Input must be an integer.")
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers.")
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

