def calculate_discount(original_price, discount_percentage):
    """
    Calculate the final price of an item after applying a discount percentage.

    Parameters:
    original_price (float): The original price of the item.
    discount_percentage (float): The discount percentage to be applied.

    Returns:
    float: The final price of the item after applying the discount, rounded to two decimal places.
    """
    if discount_percentage < 0:
        discounted_price = original_price + abs((discount_percentage / 100) * original_price)
    elif discount_percentage > 100:
        discounted_price = 0.0
    else:
        discounted_price = original_price - (discount_percentage / 100) * original_price

    return round(discounted_price, 2)

def format_duration(seconds):
    """
    Converts a given number of seconds into a human-readable format.

    Parameters:
    seconds (int): The total number of seconds to be converted.

    Returns:
    str: A string representing the duration in the format "X hours, Y minutes, and Z seconds",
         omitting any part of the duration that is zero.
    """
    hours = minutes = remaining_seconds = 0

    if seconds >= 3600:
        hours = seconds // 3600
        seconds %= 3600
    if seconds >= 60:
        minutes = seconds // 60
        remaining_seconds = seconds % 60
    else:
        remaining_seconds = seconds

    time_parts = []

    if hours > 0:
        time_parts.append(f"{hours} hour{'s' if hours > 1 else ''}")
    if minutes > 0:
        time_parts.append(f"{minutes} minute{'s' if minutes > 1 else ''}")
    if remaining_seconds > 0:
        time_parts.append(f"{remaining_seconds} second{'s' if remaining_seconds > 1 else ''}")

    if len(time_parts) > 2:
        return ', '.join(time_parts[:-1]) + f", and {time_parts[-1]}"
    elif len(time_parts) == 2:
        return f"{time_parts[0]} and {time_parts[1]}"
    elif len(time_parts) == 1:
        return time_parts[0]
    else:
        return "0 seconds"

def count_odd_even_digits(n):
    """
    Returns a dictionary with the count of odd and even digits in the given integer n.

    Parameters:
    n (int): The integer to analyze.

    Returns:
    dict: A dictionary with keys 'odd' and 'even' representing the counts of odd and even digits.
    """
    if n == 0:
        return {'odd': 0, 'even': 1}

    counts = {'odd': 0, 'even': 0}
    n = abs(n)

    while n > 0:
        digit = n % 10
        if digit % 2 == 0:
            counts['even'] += 1
        else:
            counts['odd'] += 1
        n = n // 10

    return counts

def calculate(operations, operands):
    """
    Perform a sequence of arithmetic operations on a list of operands.

    Parameters:
    operations (list of str): A list of operations ("add", "subtract", "multiply", "divide").
    operands (list of int/float): A list of operands to apply the operations to.

    Returns:
    int/float/None: The result of the operations, or None if an error occurs.
    """
    if len(operations) != len(operands) - 1:
        raise ValueError("The number of operations must be one less than the number of operands.")

    result = operands[0]

    for i, operation in enumerate(operations):
        try:
            if operation == "add":
                result += operands[i + 1]
            elif operation == "subtract":
                result -= operands[i + 1]
            elif operation == "multiply":
                result *= operands[i + 1]
            elif operation == "divide":
                if operands[i + 1] == 0:
                    raise ZeroDivisionError("Division by zero is not allowed.")
                result /= operands[i + 1]
            else:
                raise ValueError(f"Invalid operation: {operation}")
        except Exception as e:
            print(f"Error during {operation} with operand {operands[i + 1]}: {e}")
            return None

    return result

