def merge_files(file_paths, output_path):
    """
    Merges the contents of multiple files into a single output file.

    Parameters:
    file_paths (list of str): List of file paths to be merged.
    output_path (str): Path to the output file where the merged content will be written.
    """
    try:
        with open(output_path, 'w') as outfile:
            for file_path in file_paths:
                try:
                    with open(file_path, 'r') as infile:
                        outfile.write(infile.read())
                except FileNotFoundError:
                    print(f"Error: The file {file_path} does not exist.")
                except Exception as e:
                    print(f"An error occurred while processing the file {file_path}: {str(e)}")
    except Exception as e:
        print(f"An error occurred while writing to the output file {output_path}: {str(e)}")

def most_frequent_char(s: str) -> str:
    """
    Finds the most frequent character in a given string, ignoring spaces.
    If there are multiple characters with the same highest frequency,
    returns the one that appears first in the string.

    :param s: The input string consisting of lowercase English letters and spaces.
    :return: The most frequent character in the string, ignoring spaces.
    """
    frequency = {}
    for char in s:
        if char != ' ':
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1

    max_frequency = 0
    most_frequent = None
    for char in s:
        if char != ' ':
            if frequency[char] > max_frequency:
                max_frequency = frequency[char]
                most_frequent = char

    return most_frequent

