class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def find_lca(root, u, v):
    if root is None or root.value == u or root.value == v:
        return root
    left_lca = find_lca(root.left, u, v)
    right_lca = find_lca(root.right, u, v)
    if left_lca and right_lca:
        return root
    return left_lca if left_lca else right_lca

def path_sum(root, u, v):
    lca = find_lca(root, u, v)
    return sum_values_on_path(lca, u) + sum_values_on_path(lca, v) - lca.value

def sum_values_on_path(root, target):
    if root is None:
        return 0
    if root.value == target:
        return root.value
    left_sum = sum_values_on_path(root.left, target)
    right_sum = sum_values_on_path(root.right, target)
    if left_sum > 0 or right_sum > 0:
        return root.value + max(left_sum, right_sum)
    return 0

