def min_drones(packages, maxWeight):
    """
    Returns the minimum number of drones required to deliver all the packages with the given max weight constraint.
    """
    packages.sort(reverse=True)  # Sort packages in descending order
    num_drones = 0
    while packages:
        current_weight = 0
        i = 0
        while i < len(packages):
            if current_weight + packages[i] <= maxWeight:
                current_weight += packages.pop(i)
            else:
                i += 1
        num_drones += 1
    return num_drones

class ListNode:
    def __init__(self, val: int = 0, next=None):
        self.val = val
        self.next = next

def reverseBetween(head: ListNode, m: int, n: int) -> ListNode:
    if not head or m == n:
        return head

    dummy = ListNode(0)
    dummy.next = head
    pre = dummy

    for _ in range(m - 1):
        pre = pre.next

    current = pre.next
    next = current.next

    for _ in range(n - m):
        current.next = next.next
        next.next = pre.next
        pre.next = next
        next = current.next

    return dummy.next

