class MaxStack:

    def __init__(self):
        """
        Initialize your data structure here.
        """
        self.stack = []
        self.max_stack = []

    def push(self, x: int) -> None:
        self.stack.append(x)
        if not self.max_stack or x >= self.max_stack[-1]:
            self.max_stack.append(x)

    def pop(self) -> int:
        if self.stack:
            value = self.stack.pop()
            if value == self.max_stack[-1]:
                self.max_stack.pop()
            return value

    def top(self) -> int:
        if self.stack:
            return self.stack[-1]

    def getMax(self) -> int:
        if self.max_stack:
            return self.max_stack[-1]

def can_flow_to(grid):
    """
    Determine the number of unique cells the water can flow to starting from (0, 0).

    :param grid: List[List[int]], a 2D integer array representing the heights.
    :return: int, number of unique cells the water can flow to.
    """
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    direction_vectors = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # north, south, west, east

    def dfs(r, c):
        visited.add((r, c))
        for dr, dc in direction_vectors:
            new_r, new_c = r + dr, c + dc
            if 0 <= new_r < rows and 0 <= new_c < cols and (new_r, new_c) not in visited:
                if grid[new_r][new_c] < grid[r][c]:
                    dfs(new_r, new_c)

    dfs(0, 0)
    return len(visited) - 1  # subtract 1 to exclude the starting cell (0, 0)

