class BankAccount:
    def __init__(self, owner, balance=0):
        """Initialize a new bank account with an owner and an optional initial balance."""
        if not isinstance(owner, str):
            raise ValueError("Owner must be a string.")
        if not isinstance(balance, (int, float)) or balance < 0:
            raise ValueError("Balance must be a non-negative number.")
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        """Deposit a specified amount of money into the account."""
        if not isinstance(amount, (int, float)) or amount <= 0:
            raise ValueError("Deposit amount must be a positive number.")
        self.balance += amount
        print(f"Added {amount} to the balance.")

    def withdraw(self, amount):
        """Withdraw a specified amount of money from the account if sufficient funds are available."""
        if not isinstance(amount, (int, float)) or amount <= 0:
            raise ValueError("Withdrawal amount must be a positive number.")
        if amount > self.balance:
            print("Insufficient funds.")
        else:
            self.balance -= amount
            print(f"Withdrew {amount} from the balance.")

    def display_balance(self):
        """Display the current balance of the account."""
