def prime_generator(limit):
    """A generator to yield prime numbers up to a specified limit.

    Args:
        limit (int): The upper bound up to which prime numbers are generated.

    Yields:
        int: The next prime number up to the limit provided.
    """
    if limit < 2:
        return

    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False

    for num in range(2, int(limit ** 0.5) + 1):
        if sieve[num]:
            yield num
            for multiple in range(num * num, limit + 1, num):
                sieve[multiple] = False

    for num in range(int(limit ** 0.5) + 1, limit + 1):
        if sieve[num]:
            yield num

def is_prime(n):
    """Return True if n is a prime number, False otherwise."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def filter_primes(lst):
    """Return a list of prime numbers from the input list."""
    return [num for num in lst if is_prime(num)]

def numIslands(grid):
    """
    Returns the number of islands in the given m x n binary matrix grid.
    An island is surrounded by water and is formed by connecting adjacent lands horizontally or vertically.
    """
    if not grid or not grid[0]:
        return 0

    def dfs(grid, r, c):
        grid[r][c] = 0
        for x, y in [(r-1,c), (r+1,c), (r,c-1), (r,c+1)]:
            if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == 1:
                dfs(grid, x, y)

    islands = 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 1:
                dfs(grid, r, c)
                islands += 1

    return islands

import string

def count_words(input_string):
    """
    Counts the occurrences of each word in a given string, ignoring case and punctuation.

    :param input_string: A string that may contain punctuation and is case-sensitive.
    :return: A dictionary with words as keys and their counts as values.
    """
    input_string = input_string.lower()
    input_string = input_string.translate(str.maketrans('', '', string.punctuation))
    words = input_string.split()
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1
    return word_count

# Example usage:
# print(count_words("Hello, hello world!"))  # Output: {'hello': 2, 'world': 1}

