from collections import deque

def remove_invalid_parentheses(s):
    def is_valid(string):
        balance = 0
        for char in string:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    if not s:
        return [""]

    visited = set([s])
    queue = deque([s])
    valid_expressions = []
    found = False

    while queue:
        current = queue.popleft()
        if is_valid(current):
            valid_expressions.append(current)
            found = True
        if found:
            continue
        for i in range(len(current)):
            if current[i] != '(' and current[i] != ')':
                continue
            next_expr = current[:i] + current[i+1:]
            if next_expr not in visited:
                visited.add(next_expr)
                queue.append(next_expr)

    return valid_expressions

