def swap_keys_values(original_dict: dict) -> dict:
    """
    Constructs a new dictionary with keys and values swapped from the original dictionary.
    If multiple keys share the same value, the corresponding value in the new dictionary
    is a list of all those keys.

    :param original_dict: A dictionary with unique keys.
    :return: A new dictionary with keys and values swapped.
    """
    swapped_dict = {}
    for key, value in original_dict.items():
        if value in swapped_dict:
            if isinstance(swapped_dict[value], list):
                swapped_dict[value].append(key)
            else:
                swapped_dict[value] = [swapped_dict[value], key]
        else:
            swapped_dict[value] = key
    return swapped_dict

def longest_valid_parentheses(s: str) -> int:
    """
    Finds the length of the longest valid (well-formed) parentheses substring in the given string `s`.

    :param s: A string consisting of '(' and ')' characters.
    :return: The length of the longest valid parentheses substring.
    """
    max_length = 0
    stack = [-1]  # Initialize stack with base value -1

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_length = max(max_length, i - stack[-1])

    return max_length

def convert_to_json(data):
    """
    Serializes a given Python dictionary into a JSON string.

    Args:
    data (dict): The dictionary to be serialized.

    Returns:
    str: A JSON string representation of the input dictionary.

    Raises:
    TypeError: If the dictionary contains unsupported data types.
    """
    if isinstance(data, dict):
        items = []
        for key, value in data.items():
            items.append(f'"{convert_to_json(key)}": {convert_to_json(value)}')
        return f"{{{', '.join(items)}}}"
    elif isinstance(data, list):
        items = []
        for item in data:
            items.append(convert_to_json(item))
        return f"[{', '.join(items)}]"
    elif isinstance(data, (str, bool)):
        if isinstance(data, bool):
            return f"{str(data).lower()}"
        return f'"{data}"'
    elif data is None:
        return "null"
    elif isinstance(data, (int, float)):
        return str(data)
    else:
        raise TypeError(f"Type {type(data)} not serializable")

