def shortest_subset_length(s, dictionary):
    """
    Determines the length of the shortest subset of words from dictionary that can form the string s.
    A word can be used multiple times and must be concatenated in the same order.
    Returns -1 if no such subset can form s.
    """
    # Initialize a dictionary to store the minimum length to form each substring of s
    dp = {0: 0}  # {end_index: min_length}

    for i in range(1, len(s) + 1):
        # Initialize min_length for the current substring
        min_length = float('inf')
        for word in dictionary:
            if s[:i].endswith(word):
                start_index = i - len(word)
                if start_index in dp:
                    min_length = min(min_length, dp[start_index] + 1)
        if min_length != float('inf'):
            dp[i] = min_length

    return dp.get(len(s), -1)

