def min_path_sum(matrix):
    """
    Returns the minimum sum of any path from the top-left cell to the bottom-right cell
    of a given m x n integer matrix.
    """
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])

    # Initialize the dp array with the same dimensions as the matrix
    dp = [[0] * n for _ in range(m)]

    # Fill in the dp array with the minimum path sums
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                dp[i][j] = matrix[i][j]
            elif i == 0:
                dp[i][j] = dp[i][j-1] + matrix[i][j]
            elif j == 0:
                dp[i][j] = dp[i-1][j] + matrix[i][j]
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    return dp[m-1][n-1]

def max_dist_to_closest(s: str) -> int:
    """
    Given a binary string representing a row of seats where '1' is occupied and '0' is empty,
    returns the index of the empty seat that has the maximum distance to the nearest occupied seat.
    """
    n = len(s)
    if '0' not in s:
        return -1

    left = [-1] * n
    right = [-1] * n

    # Fill left distance array
    distance = float('inf')
    for i in range(n):
        if s[i] == '1':
            distance = 0
        else:
            if distance != float('inf'):
                distance += 1
        left[i] = distance

    # Fill right distance array
    distance = float('inf')
    for i in range(n-1, -1, -1):
        if s[i] == '1':
            distance = 0
        else:
            if distance != float('inf'):
                distance += 1
        right[i] = distance

    # Find the maximum distance
    max_distance = -1
    index_with_max_distance = -1
    for i in range(n):
        if s[i] == '0':
            min_distance = min(left[i], right[i])
            if min_distance > max_distance:
                max_distance = min_distance
                index_with_max_distance = i

    return index_with_max_distance

