def can_find_increasing_subsequence_of_length_3(sequence):
    n = len(sequence)
    if n < 3:
        return False

    left_min = [float('inf')] * n
    right_max = [float('-inf')] * n

    left_min[0] = sequence[0]
    for i in range(1, n):
        left_min[i] = min(left_min[i-1], sequence[i])

    right_max[n-1] = sequence[n-1]
    for i in range(n-2, -1, -1):
        right_max[i] = max(right_max[i+1], sequence[i])

    for i in range(1, n-1):
        if left_min[i-1] < sequence[i] < right_max[i+1]:
            return True

    return False

def max_prefix_sum(changes):
