def sum_order_quantity(order_text):
    total = 0
    if not order_text:
        return 0
    for part in order_text.split(','):
        part = part.strip()
        if part.count(':') != 1:
            continue
        name, qty_text = part.split(':')
        name = name.strip()
        qty_text = qty_text.strip()
        if not name:
            continue
        try:
            qty = int(qty_text)
        except ValueError:
            continue
        if qty < 1:
            continue
        total += qty
    return total

def sieve_of_eratosthenes(max_num):
    """
    Returns a set of prime numbers up to max_num using the Sieve of Eratosthenes algorithm.

    :param max_num: The upper limit for finding prime numbers.
    :return: A set of prime numbers up to max_num.
    """
    if max_num < 2:
        return set()

    is_prime = [True] * (max_num + 1)
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(max_num**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, max_num + 1, start):
                is_prime[multiple] = False

    return {num for num, prime in enumerate(is_prime) if prime}

def filter_primes(numbers):
    """
    Filters the input list to return only the prime numbers.

    :param numbers: A list of integers.
    :return: A list of prime numbers from the input list.
    """
    if not numbers:
        return []

    max_num = max(numbers)
    primes_set = sieve_of_eratosthenes(max_num)

    return [num for num in numbers if num in primes_set]

def convert_keys_to_lowercase(nested_structure):
    """
    Recursively converts all keys in a nested dictionary or list of dictionaries to lowercase.

    :param nested_structure: A dictionary or list containing nested dictionaries.
    :return: A new dictionary or list with all keys converted to lowercase.
    """
    if isinstance(nested_structure, dict):
        return {key.lower(): convert_keys_to_lowercase(value) for key, value in nested_structure.items()}
    elif isinstance(nested_structure, list):
        return [convert_keys_to_lowercase(element) for element in nested_structure]
    else:
        return nested_structure

