def count_primes(n):
    """
    Return the number of prime numbers less than or equal to `n`.

    This implementation uses the Sieve of Eratosthenes algorithm for efficiency.

    :param n: int, the upper bound (inclusive) of the range to check for prime numbers
    :return: int, the count of prime numbers less than or equal to `n`
    """
    if n < 2:
        return 0

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    return sum(is_prime)

def find_min_max(numbers):
    """
    Returns a tuple containing the smallest and largest numbers in the list.
    If the list is empty, returns None.

    :param numbers: List of integers
    :return: Tuple of (min, max) or None if the list is empty
    """
    if not numbers:
        return None

    minimum = maximum = numbers[0]

    for number in numbers:
        if number < minimum:
            minimum = number
        elif number > maximum:
            maximum = number

    return (minimum, maximum)

