def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def multiply_non_primes(lst):
    """Multiply non-prime numbers in the list by 2."""
    return [x if is_prime(x) else x * 2 for x in lst]

