def is_prime(n):
    """
    Check if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def sum_of_primes(a, b):
    """
    Returns the sum of all prime numbers between a and b (inclusive).
    """
    if a > b:
        a, b = b, a
    return sum(i for i in range(a, b + 1) if is_prime(i))

