def evaluate_expression(s):
    def evaluate(tokens):
        stack = []
        num = 0
        sign = 1
        result = 0
        for token in tokens:
            if token.isdigit():
                num = num * 10 + int(token)
            elif token == '+':
                result += sign * num
                num = 0
                sign = 1
            elif token == '-':
                result += sign * num
                num = 0
                sign = -1
            elif token == '(':
                stack.append(result)
                stack.append(sign)
                result = 0
                sign = 1
            elif token == ')':
                result += sign * num
                num = 0
                result *= stack.pop()  # sign before the parenthesis
                result += stack.pop()  # result calculated before the parenthesis
        return result + sign * num

    return evaluate(list(s.replace(' ', '')))

