from typing import List

def process_transactions(balances: List[int], transactions: List[List[str]]) -> List[int]:
    for transaction in transactions:
        if transaction[0] == "Deposit":
            account, amount = transaction[1] - 1, transaction[2]
            balances[account] += amount
        elif transaction[0] == "Withdraw":
            account, amount = transaction[1] - 1, transaction[2]
            if balances[account] >= amount:
                balances[account] -= amount
        elif transaction[0] == "Transfer":
            from_account, to_account, amount = transaction[1] - 1, transaction[2] - 1, transaction[3]
            if balances[from_account] >= amount:
                balances[from_account] -= amount
                balances[to_account] += amount
    return balances

