def is_bipartite_graph(n, edges):
    def bfs(start, color):
        queue = [start]
        color[start] = 0

        while queue:
            node = queue.pop(0)

            for neighbor in graph[node]:
                if color[neighbor] == -1:  # Not colored yet
                    color[neighbor] = 1 - color[node]
                    queue.append(neighbor)
                elif color[neighbor] == color[node]:
                    return False
        return True

    # Create adjacency list for the graph
    graph = {i: [] for i in range(1, n + 1)}
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Color array, -1 means not colored yet
    color = [-1] * (n + 1)

    for node in range(1, n + 1):
        if color[node] == -1:
            if not bfs(node, color):
                return False
    return True

