def max_k_length_subsequence(arr, k):
    """
    Returns the maximum sum of a k-length subsequence with the largest sum.
    """
    if k <= 0 or not arr or k > len(arr):
        return 0

    # Sort the array in descending order and take the sum of the first k elements
    sorted_arr = sorted(arr, reverse=True)
    return sum(sorted_arr[:k])

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def removeConsecutiveSumToZero(head):
    """
    Remove consecutive sequences of nodes that sum up to zero from the linked list.
    """
    dummy = ListNode(0)
    dummy.next = head
    prefix_sum = 0
    sum_map = {0: dummy}
    current = head

    while current:
        prefix_sum += current.val
        if prefix_sum in sum_map:
            prev = sum_map[prefix_sum]
            sum_val_check = prefix_sum
            node = prev.next

            while node != current.next:
                sum_val_check += node.val
                if node != current:
                    sum_map.pop(sum_val_check, None)
                node = node.next
            prev.next = current.next
        else:
            sum_map[prefix_sum] = current

        current = current.next

    return dummy.next

def parse_employee_record(record):
    parts = record.split(',')
    if len(parts) != 3:
        return 'INVALID'

    name = parts[0].strip()
    score_text = parts[1].strip()
    dept = parts[2].strip()

    if name == '' or dept == '':
        return 'INVALID'
    if score_text == '' or not (score_text.isdigit() or (score_text.startswith('-') and score_text[1:].isdigit())):
        return 'INVALID'

    score = int(score_text)
    if score < 0 or score > 100:
        return 'INVALID'

    if score >= 90:
        grade = 'A'
    elif score >= 80:
        grade = 'B'
    elif score >= 70:
        grade = 'C'
    else:
        grade = 'D'

    return f'{name}-{dept}-{grade}'

def flatten_json(json_object, parent_key='', sep='.'):
    """
    Flattens a nested dictionary into a single-level dictionary with concatenated keys.

    :param json_object: The dictionary to be flattened.
    :param parent_key: The base key string used in recursive calls.
    :param sep: The separator used between keys.
    :return: A flattened dictionary.
    """
    items = {}
    for k, v in json_object.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.update(flatten_json(v, new_key, sep=sep))
        else:
            items[new_key] = v
    return items

# Example usage:
input_json = {"a": {"b": {"c": 1}}}
flattened_output = flatten_json(input_json)
print(flattened_output)  # Output: {'a.b.c': 1}

def count_strings(string_list):
    """
    Returns a dictionary with each unique string from the list as keys and their counts as values.

    :param string_list: List of strings
    :return: Dictionary with string counts
    """
    counts = {}
    for string in string_list:
        if string in counts:
            counts[string] += 1
        else:
            counts[string] = 1
    return counts

