from typing import List

def can_partition_k_subsets(arr: List[int], k: int) -> bool:
    def backtrack(i, k, subset_sum, subset_target, visited):
        if k == 0:
            return True
        if subset_sum == subset_target:
            return backtrack(0, k - 1, 0, subset_target, visited)
        for j in range(i, len(arr)):
            if not visited[j] and subset_sum + arr[j] <= subset_target:
                visited[j] = True
                if backtrack(j + 1, k, subset_sum + arr[j], subset_target, visited):
                    return True
                visited[j] = False
        return False

    total_sum = sum(arr)
    if total_sum % k != 0:
        return False
    subset_target = total_sum // k
    visited = [False] * len(arr)
    return backtrack(0, k, 0, subset_target, visited)

def find_peaks(nums, k):
    peaks = []
    n = len(nums)

    for i in range(n):
        left = nums[i - 1] if i - 1 >= 0 else float('-inf')
        right = nums[i + 1] if i + 1 < n else float('-inf')

        if nums[i] >= left and nums[i] >= right:
            peaks.append((nums[i], i))

    return len(peaks), sorted(peaks, key=lambda x: x[1])

