def find_pair_with_difference(arr, x):
    """
    Returns a pair of integers from the sorted array 'arr' whose difference is 'x'.
    If no such pair exists, returns an empty pair.
    """
    left, right = 0, 1
    while right < len(arr):
        diff = arr[right] - arr[left]
        if diff == x and left != right:
            return (arr[left], arr[right])
        elif diff < x:
            right += 1
        else:
            left += 1
    return ()

