import heapq

def min_elevation_effort(grid):
    """
    Returns the minimum effort required for the hike.
    """
    n = len(grid)
    if n == 0:
        return 0

    def get_neighbors(x, y):
        for dx, dy in [(1, 0), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                yield nx, ny

    def dijkstra():
        pq = [(0, 0, 0)]  # (effort, x, y)
        efforts = [[float('inf')] * n for _ in range(n)]
        efforts[0][0] = 0

        while pq:
            effort, x, y = heapq.heappop(pq)
            if x == n - 1 and y == n - 1:
                return effort

            for nx, ny in get_neighbors(x, y):
                new_effort = max(effort, abs(grid[nx][ny] - grid[x][y]))
                if new_effort < efforts[nx][ny]:
                    efforts[nx][ny] = new_effort
                    heapq.heappush(pq, (new_effort, nx, ny))

    return dijkstra()

