def displaced_duplicates(nums):
    """
    Returns displaced duplicates in the form of pairs of their first and second positions.

    Parameters:
    nums (list): A 0-indexed array of integers.

    Returns:
    list: List of tuples containing pairs of first and second positions of displaced duplicates.
    """
    seen = {}
    result = []

    for i, num in enumerate(nums):
        # Check if we have seen this number before
        if num in seen:
            # Add the pair only if it's not consecutive
            if seen[num] != i - 1:
                result.append((seen[num], i))
            else:
                # Update the position if it's consecutive
                seen[num] = i
        else:
            # Store the first occurrence of the number
            seen[num] = i

    return result

