def max_ones(grid, steps):
    """
    Determines the maximum number of 1's that can be collected in 'steps' moves starting from any cell.
    """
    rows, cols = len(grid), len(grid[0])

    def dfs(x, y, steps_remaining):
        if steps_remaining == 0:
            return grid[x][y]

        max_ones_collected = 0
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        original_value = grid[x][y]
        grid[x][y] = -1  # Mark the cell as visited

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != -1:
                max_ones_collected = max(max_ones_collected, dfs(nx, ny, steps_remaining - 1))

        grid[x][y] = original_value  # Restore the original value
        return max_ones_collected + original_value

    max_ones_overall = 0
    for i in range(rows):
        for j in range(cols):
            if steps == 0:
                max_ones_overall = max(max_ones_overall, grid[i][j])
            else:
                max_ones_collected = dfs(i, j, steps)
                max_ones_overall = max(max_ones_overall, max_ones_collected)

    return max_ones_overall

