def find_largest_pairwise_product(numbers):
    """
    Computes the largest product of any two distinct numbers in the list.

    Parameters:
    numbers (list of int): A list of integers.

    Returns:
    int or None: The largest product of two distinct numbers, or None if the list has fewer than two numbers.
    """
    if len(numbers) < 2:
        return None

    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    for number in numbers:
        if number > max1:
            max2 = max1
            max1 = number
        elif number > max2:
            max2 = number

        if number < min1:
            min2 = min1
            min1 = number
        elif number < min2:
            min2 = number

    return max(max1 * max2, min1 * min2)

import math

class Vector2D:
    def __init__(self, x: float, y: float):
        """Initialize the vector with x and y coordinates."""
        self.x = x
        self.y = y

    def __add__(self, other: 'Vector2D') -> 'Vector2D':
        """Overload the addition operator to add two vectors."""
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other: 'Vector2D') -> 'Vector2D':
        """Overload the subtraction operator to subtract one vector from another."""
        return Vector2D(self.x - other.x, self.y - other.y)

    def dot(self, other: 'Vector2D') -> float:
        """Compute the dot product of two vectors."""
        return self.x * other.x + self.y * other.y

    def magnitude(self) -> float:
        """Compute the magnitude (length) of the vector."""
        return math.sqrt(self.x ** 2 + self.y ** 2)

def compute_gcd(a, b):
    """
    Compute the greatest common divisor of two numbers using the Euclidean algorithm.

    Parameters:
    a (int): The first integer.
    b (int): The second integer.

    Returns:
    int: The greatest common divisor of a and b.
    """
    if a == 0:
        return b
    elif b == 0:
        return a
    else:
        return compute_gcd(b, a % b)

def print_person_info(person_info, indent=0):
    """
    Prints the contents of a dictionary in a structured and readable format.

    Args:
    person_info (dict): The dictionary containing personal information.
    indent (int): The current level of indentation for nested structures.
    """
    for key, value in person_info.items():
        if isinstance(value, dict):
            print(' ' * indent + f"{key}:")
            print_person_info(value, indent + 4)
        elif isinstance(value, list):
            print(' ' * indent + f"{key}:")
            for item in value:
                print(' ' * (indent + 4) + f"- {item}")
        else:
            print(' ' * indent + f"{key}: {value}")

