def remove_nulls(d):
    """
    Recursively remove all null (None in Python) values from a dictionary.

    Args:
    d (dict): The dictionary to clean.

    Returns:
    dict: A new dictionary with all null values removed, or None if the resulting dictionary is empty.
    """
    if not isinstance(d, dict):
        return d

    cleaned_dict = {}
    for key, value in d.items():
        if value is not None:
            cleaned_value = remove_nulls(value)
            if cleaned_value is not None:
                cleaned_dict[key] = cleaned_value

    return cleaned_dict if cleaned_dict else None

