def calculate_balances(transactions):
    """
    Calculate the final balances for each account after processing a list of transactions.

    :param transactions: List of tuples, where each tuple contains (account_id, transaction_type, amount)
    :return: Dictionary with account IDs as keys and final balances as values
    """
    balances = {}
    for account_id, transaction_type, amount in transactions:
        if account_id not in balances:
            balances[account_id] = 0
        if transaction_type == 'deposit':
            balances[account_id] += amount
        elif transaction_type == 'withdrawal':
            balances[account_id] -= amount
    return balances

class Inventory:
    def __init__(self):
        """Initialize an empty inventory."""
        self.items = {}

    def add_item(self, item, quantity):
        """
        Add a specified quantity of an item to the inventory.
        If the item already exists, update its quantity.

        :param item: str, the name of the item to add
        :param quantity: int, the quantity of the item to add
        """
        if item in self.items:
            self.items[item] += quantity
        else:
            self.items[item] = quantity

    def remove_item(self, item, quantity):
        """
        Remove a specified quantity of an item from the inventory.
        If the quantity to be removed exceeds the available quantity, the item should be removed entirely.

        :param item: str, the name of the item to remove
        :param quantity: int, the quantity of the item to remove
        """
        if item in self.items:
            if self.items[item] > quantity:
                self.items[item] -= quantity
            else:
                del self.items[item]

    def get_inventory(self):
        """
        Return the current state of the inventory as a dictionary.

        :return: dict, where keys are item names and values are quantities
        """
        return self.items

def classify_values(data):
    """
    Classify each value in a comma-separated string as an integer, float, or string.

    Parameters:
    data (str): A string containing comma-separated values.

    Returns:
    dict: A dictionary with keys as the original values and values as their types ('int', 'float', 'str').
    """
    values = data.split(',')
    classified_dict = {}

    for value in values:
        try:
            classified_dict[value] = int(value)
        except ValueError:
            try:
                classified_dict[value] = float(value)
            except ValueError:
                classified_dict[value] = value

    type_dict = {k: type(v).__name__ for k, v in classified_dict.items()}

    return type_dict

