class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def longest_even_odd_alternating_path(root):
    def dfs(node, parent_value, path_length):
        if not node:
            return path_length

        # Check if current node continues the even-odd alternating path
        is_alternating = (node.val % 2) != (parent_value % 2)
        new_length = path_length + 1 if is_alternating else 1

        # Debug: Print the path explored
        if is_alternating:
            print(f"Node {node.val} continues the alternating path. New length: {new_length}.")
        else:
            print(f"Node {node.val} does not alternate. Resetting path length.")

        # Traverse left and right children
        left_length = dfs(node.left, node.val, new_length)
        right_length = dfs(node.right, node.val, new_length)

        return max(new_length, left_length, right_length)

    return dfs(root, root.val ^ 1, 0) if root else 0

