def remove_comments(s):
    """
    Removes line and block comments from the input string.
    Line comments start with // and end at the end of the line.
    Block comments start with /* and end with */ and can be nested.
    """
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i:i+2] == '//':
            i += 2
            while i < n and s[i] != '\n':
                i += 1
        elif s[i:i+2] == '/*':
            nest_level = 1
            i += 2
            while i < n and nest_level > 0:
                if s[i:i+2] == '/*':
                    nest_level += 1
                    i += 2
                elif s[i:i+2] == '*/':
                    nest_level -= 1
                    i += 2
                else:
                    i += 1
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def isBalanced(root):
    def check_height(node):
        if not node:
            return 0, True

        left_height, left_balanced = check_height(node.left)
        right_height, right_balanced = check_height(node.right)

        current_height = max(left_height, right_height) + 1
        if abs(left_height - right_height) > 1:
            return current_height, False

        return current_height, left_balanced and right_balanced

    _, balanced = check_height(root)
    return balanced

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_word = False


class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_word = True


def findWords(board, words):
    def dfs(board, node, i, j, path, visited, result):
        if node.is_word:
            result.add(path)
            node.is_word = False  # avoid duplicate word entries

        if i < 0 or i >= len(board) or j < 0 or j >= len(board[0]) or board[i][j] not in node.children or (i, j) in visited:
            return

        visited.add((i, j))
        char = board[i][j]
        next_node = node.children[char]

        for x, y in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            dfs(board, next_node, i + x, j + y, path + char, visited, result)

        visited.remove((i, j))

    if not board or not board[0]:
        return []

    trie = Trie()
    for word in words:
        trie.insert(word)

    result = set()
    for i in range(len(board)):
        for j in range(len(board[0])):
            visited = set()
            dfs(board, trie.root, i, j, '', visited, result)

    return list(result)

