from collections import deque

# Helper function to check if position is valid and within bounds
def is_valid(x, y, m, n, grid, visited):
    return 0 <= x < m and 0 <= y < n and not visited[x][y] and grid[x][y] == 1

def bfs(grid, m, n, change_pos=None):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[False] * n for _ in range(m)]
    queue = deque([(0, 0, 0)])  # (row, col, steps)
    if change_pos:
        # Temporarily change water cell to land
        grid[change_pos[0]][change_pos[1]] = 1

    visited[0][0] = True

    while queue:
        x, y, steps = queue.popleft()

        if (x, y) == (m-1, n-1):
            if change_pos:
                # Revert temporary change
                grid[change_pos[0]][change_pos[1]] = 0
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny, m, n, grid, visited):
                visited[nx][ny] = True
                queue.append((nx, ny, steps + 1))

    if change_pos:
        # Revert temporary change
        grid[change_pos[0]][change_pos[1]] = 0

    return -1

def min_flips(grid):
    m = len(grid)
    n = len(grid[0])

    if grid[0][0] == 0:
        # If starting point is water, directly return -1
        return -1

    if bfs(grid, m, n) != -1:
        # If there is already a path without any change
        return 0

    # Try changing each water cell (0) to land (1) and check for path
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 0:
                if bfs(grid, m, n, (i, j)) != -1:
                    return 1

    return -1

class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def max_cost_path(root):
    if root is None:
        return 0

    def helper(node, current_cost):
        if not node:
            return current_cost

        # Traverse left and right subtree and calculate their respective costs
        left_cost = helper(node.left, current_cost + (abs(node.value - node.left.value) if node.left else 0))
        right_cost = helper(node.right, current_cost + (abs(node.value - node.right.value) if node.right else 0))

        # Return the maximum cost from left or right subtree
        return max(left_cost, right_cost)

    return helper(root, 0)

