def can_form(word, word_set, memo):
    if word in memo:
        return memo[word]
    for i in range(1, len(word)):
        left, right = word[:i], word[i:]
        if left in word_set and (right in word_set or can_form(right, word_set, memo)):
            memo[word] = True
            return True
    memo[word] = False
    return False

def longest_concatenated_word(words):
    word_set = set(words)
    memo = {}
    longest = ""

    for word in words:
        word_set.remove(word)
        if can_form(word, word_set, memo):
            if len(word) > len(longest) or (len(word) == len(longest) and word < longest):
                longest = word
        word_set.add(word)

    return longest

