def find_triplets(numbers, target):
    """
    Finds all unique triplets in the list that sum up to the target value.

    :param numbers: List of integers.
    :param target: Target sum for the triplets.
    :return: List of unique triplets (tuples) that sum up to the target value.
    """
    numbers.sort()
    triplets = set()

    for i in range(len(numbers) - 2):
        left, right = i + 1, len(numbers) - 1

        while left < right:
            current_sum = numbers[i] + numbers[left] + numbers[right]

            if current_sum == target:
                triplets.add((numbers[i], numbers[left], numbers[right]))
                left += 1
                right -= 1
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return list(triplets)

