def sort_nested_dict(d):
    """
    Recursively sorts a nested dictionary by keys at all levels.

    Parameters:
    d (dict): The dictionary to be sorted.

    Returns:
    dict: A new dictionary sorted by keys at all levels.
    """
    sorted_dict = {}
    for key, value in sorted(d.items()):
        if isinstance(value, dict):
            sorted_dict[key] = sort_nested_dict(value)
        else:
            sorted_dict[key] = value
    return sorted_dict

