from collections import deque

def word_ladder_length(startWord, endWord, wordList):
    """
    Returns the length of the shortest transformation sequence from startWord to endWord,
    altering one character at a time and using only words from wordList.
    """
    if endWord not in wordList:
        return 0

    wordSet = set(wordList)
    queue = deque([(startWord, 1)])

    while queue:
        currentWord, level = queue.popleft()
        if currentWord == endWord:
            return level

        for i in range(len(currentWord)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                nextWord = currentWord[:i] + c + currentWord[i+1:]
                if nextWord in wordSet:
                    wordSet.remove(nextWord)
                    queue.append((nextWord, level + 1))

    return 0

