def rob(nums, k):
    """
    Returns the maximum amount of money that can be robbed from the houses,
    considering that after robbing one house, you must skip at least k houses.

    :param nums: List[int] - list of integers representing the amount of money at each house
    :param k: int - the number of houses you must skip after robbing one house
    :return: int - the maximum amount of money you can rob
    """
    if not nums:
        return 0

    n = len(nums)
    if k >= n:
        return max(nums)

    dp = [0] * n
    dp[0] = nums[0]

    for i in range(1, n):
        if i <= k:
            dp[i] = max(dp[i-1], nums[i])
        else:
            dp[i] = max(dp[i-1], nums[i] + dp[i-k-1])

    return max(dp)

