import heapq

def get_skyline(buildings):
    # Events are (x, h) where x is the coordinate and h is the height
    events = sorted([(L, -H, R) for L, R, H in buildings] + list({(R, 0, 0) for L, R, H in buildings}))
    result, heap = [[0, 0]], [(0, float("inf"))]

    for x, negH, R in events:
        while heap[0][1] <= x:
            heapq.heappop(heap)
        if negH:
            heapq.heappush(heap, (negH, R))
        if result[-1][1] != -heap[0][0]:
            result.append([x, -heap[0][0]])

    return result[1:]

