def is_balanced(expression):
    """
    Determines if the given expression containing only parentheses, brackets, and braces is balanced.

    :param expression: A string consisting of '(', ')', '{', '}', '[' and ']'.
    :return: True if the expression is balanced, False otherwise.
    """
    stack = []
    matching_bracket = {")": "(", "}": "{", "]": "["}

    for char in expression:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if not stack or matching_bracket[char] != stack.pop():
                return False
        else:
            return False  # In case the string contains characters other than () {} []

    return not stack

