import csv
from collections import defaultdict

def calculate_average_salaries(file_path):
    """
    Calculate the average salary for each department from a CSV file.

    Args:
    file_path (str): The path to the CSV file.

    Returns:
    dict: A dictionary with department names as keys and average salaries as values.
    """
    department_salaries = defaultdict(list)
    try:
        with open(file_path, mode='r', newline='') as file:
            reader = csv.DictReader(file)
            if 'Department' not in reader.fieldnames or 'Salary' not in reader.fieldnames:
                raise ValueError("CSV file must contain 'Department' and 'Salary' columns.")

            for row in reader:
                department = row['Department']
                try:
                    salary = float(row['Salary'])
                except ValueError:
                    print(f"Warning: Skipping row with invalid salary value: {row}")
                    continue
                department_salaries[department].append(salary)

    except FileNotFoundError:
        print(f"Error: File {file_path} not found.")
        return {}
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

    average_salaries = {dept: sum(salaries) / len(salaries) for dept, salaries in department_salaries.items()}
    return average_salaries

