def min_traversal_time(grid):
    """
    Returns the minimum traversal time from the top-left to the bottom-right corner of the grid.
    """
    if not grid or not grid[0]:
        return 0

    n, m = len(grid), len(grid[0])
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = grid[0][0]

    # Fill first row
    for j in range(1, m):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill first column
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the dp table
    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[n-1][m-1]

def count_k_length_subarrays_with_sum(nums, k, target):
    """
    Returns the number of unique k-length subarrays that sum up to the target.
    """
    if not nums or k > len(nums):
        return 0

    count = 0
    current_sum = sum(nums[:k])

    if current_sum == target:
        count += 1

    for i in range(k, len(nums)):
        current_sum += nums[i] - nums[i - k]
        if current_sum == target:
            count += 1

    return count

