def pacificAtlantic(matrix):
    """
    Returns the number of cells from which water can flow to both the Pacific and Atlantic Ocean.
    """
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])

    def dfs(matrix, visited, i, j):
        visited.add((i, j))
        for x, y in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]:
            if 0 <= x < m and 0 <= y < n and (x, y) not in visited and matrix[x][y] >= matrix[i][j]:
                dfs(matrix, visited, x, y)

    pacific_reachable = set()
    atlantic_reachable = set()

    for i in range(m):
        dfs(matrix, pacific_reachable, i, 0)
        dfs(matrix, atlantic_reachable, i, n-1)

    for j in range(n):
        dfs(matrix, pacific_reachable, 0, j)
        dfs(matrix, atlantic_reachable, m-1, j)

    return len(pacific_reachable & atlantic_reachable)

