def findLongestWord(s, words):
    """
    Returns the longest word in words that can be formed by deleting some characters of s
    without reordering the remaining characters. If there is more than one possible result,
    returns the longest word with the smallest lexicographical order. If no valid word can be
    formed, returns an empty string.
    """
    def is_subsequence(x):
        it = iter(s)
        return all(char in it for char in x)

    longest_word = ''
    for word in words:
        if is_subsequence(word):
            if len(word) > len(longest_word) or (len(word) == len(longest_word) and word < longest_word):
                longest_word = word
    return longest_word

