def findClosestElements(arr, k, x):
    """
    Returns the k closest integers to x in the array.
    """
    left = 0
    right = len(arr) - 1
    while right - left >= k:
        if abs(arr[left] - x) > abs(arr[right] - x):
            left += 1
        else:
            right -= 1

    return arr[left:left + k]

