def max_k_consecutive_sum(nums, threshold):
    """
    Returns the maximum integer k such that there exists k consecutive elements in the array nums with their sum not exceeding the given threshold.
    """
    n = len(nums)
    left, right = 1, n

    def can_find_k(k):
        current_sum = sum(nums[:k])
        if current_sum <= threshold:
            return True
        for i in range(k, n):
            current_sum += nums[i] - nums[i - k]
            if current_sum <= threshold:
                return True
        return False

    max_k = -1
    while left <= right:
        mid = (left + right) // 2
        if can_find_k(mid):
            max_k = mid
            left = mid + 1
        else:
            right = mid - 1

    return max_k

