def possible_bipartition(n, edges):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    color = {}

    for node in range(1, n + 1):  # assuming animals are labeled from 1 to n
        if node not in color:
            queue = deque([node])
            color[node] = 0  # starting color
            while queue:
                current = queue.popleft()
                for neighbor in graph[current]:
                    if neighbor not in color:
                        color[neighbor] = 1 - color[current]  # flip color
                        queue.append(neighbor)
                    elif color[neighbor] == color[current]:
                        return False
    return True

