def shortest_substring(s):
    """
    Returns the shortest substring containing at least one 'G', one 'A', and one 'C'.
    If no such substring exists, returns an empty string.
    """
    if not s or len(set(s)) < 3:
        return ""

    required_chars = {'G', 'A', 'C'}
    min_length = float('inf')
    shortest_sub = ""

    left = 0
    char_count = {'G': 0, 'A': 0, 'C': 0}

    for right, char in enumerate(s):
        if char in char_count:
            char_count[char] += 1

        while all(char_count[c] > 0 for c in required_chars):
            current_length = right - left + 1
            if current_length < min_length:
                min_length = current_length
                shortest_sub = s[left:right+1]

            if s[left] in char_count:
                char_count[s[left]] -= 1
            left += 1

    return shortest_sub

