def min_max_items_group(numbers, k):
    """
    Returns the smallest possible value of the largest number of items in any group
    after distributing the given items into exactly k groups.
    """
    def is_feasible(limit):
        groups = 1
        current_sum = 0

        for num in numbers:
            if current_sum + num > limit:
                groups += 1
                current_sum = num
                if groups > k:
                    return False
            else:
                current_sum += num
        return True

    left, right = max(numbers), sum(numbers)

    while left < right:
        mid = (left + right) // 2
        if is_feasible(mid):
            right = mid
        else:
            left = mid + 1

    return left

def count_unique_sum_pairs(boxes, target):
    seen = set()
    freq = {}
    for x in boxes:
        freq[x] = freq.get(x, 0) + 1
    ans = 0
    used = set()
    for x in freq:
        y = target - x
        if y not in freq:
            continue
        a, b = (x, y) if x <= y else (y, x)
        if (a, b) in used:
            continue
        if a == b:
            if freq[a] >= 2:
                ans += 1
                used.add((a, b))
        else:
            ans += 1
            used.add((a, b))
    return ans

