def find_max_value(root):
    """
    Finds and returns the maximum value in a binary tree.

    :param root: TreeNode, the root of the binary tree
    :return: int or None, the maximum value in the tree or None if the tree is empty
    """
    if root is None:
        return None

    def dfs(node):
        if node is None:
            return float('-inf')
        left_max = dfs(node.left)
        right_max = dfs(node.right)
        return max(node.value, left_max, right_max)

    return dfs(root)

def find_triplets(nums, target):
    """
    Finds all unique triplets in the list `nums` that sum up to `target`.

    :param nums: List of integers.
    :param target: Integer representing the target sum.
    :return: List of lists, where each inner list contains three integers that add up to `target`.
    """
    nums.sort()
    triplets = []
    n = len(nums)

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == target:
                triplets.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return triplets

