def is_prime(n):
    """Check if the number n is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_max_prime_in_list(lst):
    """Find the maximum prime number in a given list of integers."""
    max_prime = None
    for number in lst:
        if is_prime(number):
            if max_prime is None or number > max_prime:
                max_prime = number
    return max_prime

