def sum_of_primes(n):
    """
    Calculate the sum of all prime numbers up to a given number n using the Sieve of Eratosthenes algorithm.

    :param n: The upper limit up to which prime numbers are summed.
    :return: The sum of all prime numbers less than or equal to n.
    """
    if n < 2:
        return 0

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n + 1, start):
                is_prime[multiple] = False

    return sum(num for num, prime in enumerate(is_prime) if prime)

def longest_common_substring(s1, s2):
    """
    Finds the longest common substring between two given strings.

    :param s1: First input string.
    :param s2: Second input string.
    :return: The longest common substring.
    """
    dp = [[0] * (len(s2) + 1) for _ in range(len(s1) + 1)]
    longest_length = 0
    end_index_s1 = 0

    for i in range(1, len(s1) + 1):
        for j in range(1, len(s2) + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > longest_length:
                    longest_length = dp[i][j]
                    end_index_s1 = i
            else:
                dp[i][j] = 0

    return s1[end_index_s1 - longest_length:end_index_s1]

