def parse_json(json_string):
    """
    Parses a JSON string and returns a dictionary with all keys in lowercase.
    If the JSON string is invalid, returns an empty dictionary.

    :param json_string: A string representing the JSON data.
    :return: A dictionary with all keys in lowercase or an empty dictionary if invalid.
