def longest_increasing_subsequence(nums):
    """
    Finds and returns the longest increasing subsequence in the list of integers nums.

    :param nums: List[int] - A list of integers which may contain both positive and negative numbers.
    :return: List[int] - The longest increasing subsequence.
    """
    if not nums:
        return []

    tails = []
    predecessors = [-1] * len(nums)
    size = 0

    for i, x in enumerate(nums):
        left, right = 0, size
        while left != right:
            mid = (left + right) // 2
            if tails[mid] < x:
                left = mid + 1
            else:
                right = mid

        if left == size:
            tails.append(0)

        tails[left] = x
        if left != 0:
            predecessors[i] = tails.index(tails[left - 1])

        if left == size:
            size += 1

    lis = []
    k = tails.index(tails[size - 1])
    for _ in range(size):
        lis.append(nums[k])
        k = predecessors[k]
    lis.reverse()

    return lis

