def min_operations_to_match(source, target):
    """
    Returns the minimum number of operations required to make `source` an exact match to `target`.
    """
    if len(source) != len(target):
        raise ValueError("Source and Target arrays must be of the same length.")

    operations = 0
    for s, t in zip(source, target):
        if s < t:
            operations += (t - s)

    return operations

