def is_hill_sequence(nums):
    """
    Determine if the given array nums is a Hill Sequence.
    A Hill Sequence has a peak element where all elements before
    it are in ascending order and all elements after it are 
    in descending order.

    Args:
    nums (list[int]): List of integers.

    Returns:
    bool: True if nums is a Hill Sequence, False otherwise.
    """
    if len(nums) < 3:
        return False

    peak_found = False
    peak_index = -1
    n = len(nums)

    for i in range(1, n - 1):
        if nums[i - 1] < nums[i] > nums[i + 1]:
            peak_found = True
            peak_index = i
            break

    if not peak_found:
        return False

    for i in range(peak_index):
        if nums[i] >= nums[i + 1]:
            return False

    for i in range(peak_index, n - 1):
        if nums[i] <= nums[i + 1]:
            return False

    return True

