class Grid:
    def __init__(self, m: int, n: int):
        """
        Initializes the grid with m rows and n columns.
        """
        self.grid = [[0] * n for _ in range(m)]
        self.m = m
        self.n = n

    def setUniformValue(self, r1: int, r2: int, c1: int, c2: int, value: int):
        """
        Sets all the cells in the subgrid from (r1, c1) to (r2, c2) to the specified value.
        """
        for i in range(r1, r2 + 1):
            for j in range(c1, c2 + 1):
                self.grid[i][j] = value

    def querySum(self, r1: int, r2: int, c1: int, c2: int) -> int:
        """
        Returns the sum of all the cells in the subgrid from (r1, c1) to (r2, c2).
        """
        total_sum = 0
        for i in range(r1, r2 + 1):
            for j in range(c1, c2 + 1):
                total_sum += self.grid[i][j]
        return total_sum

