def lexicographically_smallest_sequence(arr):
    """
    Returns the lexicographically smallest sequence by removing exactly one element from the list.
    """
    n = len(arr)

    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            return arr[:i] + arr[i+1:]

    # If no such element is found, remove the last element
    return arr[:-1]

def max_sum_submatrix(matrix, k):
    """
    Finds the maximum sum of any submatrix that contains exactly k elements.

    :param matrix: List[List[int]]: 2D integer array.
    :param k: int: Number of elements the submatrix should contain.
    :return: int: Maximum sum of such a submatrix.
    """
    rows = len(matrix)
    cols = len(matrix[0])
    max_sum = float('-inf')

    # Generate all possible submatrices
    for r1 in range(rows):
        for c1 in range(cols):
            for r2 in range(r1, rows):
                for c2 in range(c1, cols):
                    # Get all elements in the submatrix (r1, c1) to (r2, c2)
                    elements = []
                    for r in range(r1, r2+1):
                        for c in range(c1, c2+1):
                            elements.append(matrix[r][c])
                    # Check if the submatrix contains exactly k elements
                    if len(elements) == k:
                        max_sum = max(max_sum, sum(elements))

    return max_sum

def unique_paths_with_obstacles(grid):
    """
    Returns the number of unique paths from the top-left corner to the bottom-right corner in a grid with obstacles.
    """
    m, n = len(grid), len(grid[0])

    # Early exit if the start or end node is an obstacle
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    # Initialize a 2D dp array
    dp = [[0 for _ in range(n)] for _ in range(m)]

    # Number of ways to reach the start cell is 1 if it's not an obstacle
    dp[0][0] = 1

    # Fill the dp table
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0  # No way to reach or pass through an obstacle
            else:
                # Add ways from the left cell (if within bounds)
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                # Add ways from the top cell (if within bounds)
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    # The answer is the number of ways to reach the bottom-right corner
    return dp[m-1][n-1]

