def longest_repeated_subsequence_length(s):
    """
    Returns the length of the longest subsequence that appears at least twice as a substring.
    """
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Building the dp array
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if s[i - 1] == s[j - 1] and i != j:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The value at dp[n][n] will be the length of the longest repeating subsequence
    return dp[n][n]

def count_active_orders(logs):
    ever_seen = set()
    active = set()
    for action, order_id in logs:
        if action == "activate":
            ever_seen.add(order_id)
            active.add(order_id)
        elif action == "cancel":
            active.discard(order_id)
        elif action == "restore":
            if order_id in ever_seen:
                active.add(order_id)
                ever_seen.add(order_id)
    return len(active)

def shift_string(s):
    """
    Shifts each letter in the string by three positions forward in the alphabet.
    Non-alphabetical characters remain unchanged.

    :param s: Input string to be shifted.
    :return: String with each letter shifted by three positions.
    """
    def shift_char(c):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + 3) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + 3) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c) for c in s)

