def fibonacci(n):
    """
    Computes the nth Fibonacci number using recursion.

    Parameters:
    n (int): The position in the Fibonacci sequence (0-indexed).

    Returns:
    int: The nth Fibonacci number.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

from typing import Union

def factorial(n: int) -> Union[int, str]:
    """
    Calculate the factorial of a given non-negative integer using recursion.
    If the input is negative, return a custom error message.

    :param n: Integer for which the factorial is to be calculated.
    :return: Factorial of the integer if non-negative, otherwise an error message.
    """
    if n < 0:
        return "Factorial is not defined for negative numbers."
    elif n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

