def inorder_traversal(root):
    """
    Perform an in-order traversal of a binary tree and return the node values in a list.

    :param root: TreeNode, the root of the binary tree
    :return: List[int], the values of the nodes in in-order traversal order
    """
    def traverse(node):
        if not node:
            return []
        return traverse(node.left) + [node.val] + traverse(node.right)

    return traverse(root)

def create_dict_from_tuples(tuples_list):
    """
    Constructs a dictionary from a list of tuples where each key maps to a list of values.
    If a key appears multiple times, all corresponding values are appended to the list.

    :param tuples_list: List of tuples, where each tuple contains a key and a value.
    :return: Dictionary with keys mapping to lists of values.
    """
    result_dict = {}
    for key, value in tuples_list:
        if key in result_dict:
            result_dict[key].append(value)
        else:
            result_dict[key] = [value]
    return result_dict

