def generate_report(sales_data):
    """
    Generates a report summarizing the total sales for each quarter from the given sales data.

    Parameters:
    sales_data (dict): A dictionary with month names as keys and sales figures as values.

    Returns:
    str: A formatted string with total sales for each quarter, or None if input is invalid.
    """
    if not isinstance(sales_data, dict):
        return None

    quarters = {
        'Q1': ['January', 'February', 'March'],
        'Q2': ['April', 'May', 'June'],
        'Q3': ['July', 'August', 'September'],
        'Q4': ['October', 'November', 'December']
    }

    quarter_totals = {quarter: 0 for quarter in quarters}

    for month, sales in sales_data.items():
        if not isinstance(sales, (int, float)):
            return None
        for quarter, months in quarters.items():
            if month in months:
                quarter_totals[quarter] += sales

    report = ', '.join([f"{quarter}: {total}" for quarter, total in quarter_totals.items()])
    return report

