class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def addTwoNumbers(headA, headB):
    """
    Adds two numbers represented by linked lists headA and headB
    and returns the sum as a new linked list.
    """
    def linkedListToNumber(head):
        number = 0
        while head:
            number = number * 10 + head.val
            head = head.next
        return number

    def numberToLinkedList(number):
        if number == 0:
            return ListNode(0)
        prev_node = None
        for digit in str(number)[::-1]:
            node = ListNode(int(digit))
            node.next = prev_node
            prev_node = node
        return prev_node

    numA = linkedListToNumber(headA)
    numB = linkedListToNumber(headB)
    total = numA + numB

    return numberToLinkedList(total)

def evaluate_expression(s: str) -> int:
    def operate(a, b, op):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return int(a / b)  # Integer division truncating towards zero

    if not s:
        return 0

    n = len(s)
    current_num = 0
    stack = []
    operation = '+'
    i = 0

    while i < n:
        char = s[i]
        if char.isdigit():
            current_num = current_num * 10 + int(char)
        if char in "+-*/" or i == n - 1:
            if operation == '+':
                stack.append(current_num)
            elif operation == '-':
                stack.append(-current_num)
            elif operation == '*':
                stack[-1] = stack[-1] * current_num
            elif operation == '/':
                stack[-1] = int(stack[-1] / current_num)
            operation = char
            current_num = 0
        i += 1

    return sum(stack)

