def stringPartition(s):
    """
    Divides the input string s into substrings such that each substring contains distinct characters only.
    Returns a list of the lengths of each substring.
    """
    if not s:
        return []

    partitions = []
    current_partition = ""

    for char in s:
        if char in current_partition:
            partitions.append(len(current_partition))
            current_partition = char
        else:
            current_partition += char

    # Append the last partition
    if current_partition:
        partitions.append(len(current_partition))

    return partitions

