def min_extra_characters(s, dict_words):
    """
    Returns the minimum number of extra characters left over if you concatenate words from the dictionary to form the given string s.
    """
    def helper(s, dict_words, memo):
        if s in memo:
            return memo[s]
        if not s:
            return 0

        min_till_now = float('inf')
        for word in dict_words:
            if s.startswith(word):
                min_till_now = min(min_till_now, helper(s[len(word):], dict_words, memo))

        memo[s] = min_till_now if min_till_now != float('inf') else 1 + helper(s[1:], dict_words, memo)
        return memo[s]

    memo = {}
    return helper(s, dict_words, memo)

