def count_special_pairs(numbers, k):
    """
    Returns the count of all special pairs (i, j) such that numbers[i] + numbers[j] = k and i < j.

    Args:
    numbers (list of int): A list of unique non-negative integers.
    k (int): The target sum value.

    Returns:
    int: The count of all special pairs.
    """
    count = 0
    seen = {}

    for i, num in enumerate(numbers):
        complement = k - num
        if complement in seen:
            count += seen[complement]

        if num in seen:
            seen[num] += 1
        else:
            seen[num] = 1

    return count

