def can_sum_to_target(arr, target):
    """
    Given an array of positive integers and a target integer, checks
    if it is possible to create a sum to target by placing '+' or '-'
    between each pair of adjacent elements.
    """
    def helper(index, current_sum):
        if index == len(arr):
            return current_sum == target

        return helper(index + 1, current_sum + arr[index]) or helper(index + 1, current_sum - arr[index])

    return helper(1, arr[0]) if arr else target == 0

