def count_winners(nums, k):
    """
    Returns the count of participants who are considered winners.
    """
    nums_sorted = sorted(nums, reverse=True)
    if k >= len(nums):
        return len(nums)

    cutoff_score = nums_sorted[k-1]
    count = 0

    for score in nums:
        if score >= cutoff_score:
            count += 1

    return count

