class DataStructure:
    def __init__(self):
        """
        Initialize an empty data structure.
        """
        self.data = []

    def insert(self, k):
        """
        Insert integer k into the data structure.
        """
        self.data.append(k)
        self.data.sort()

    def erase(self, k):
        """
        Remove integer k from the data structure if it exists.
        """
        if k in self.data:
            self.data.remove(k)

    def get_max(self):
        """
        Return the maximum value in the data structure.
        """
        if self.data:
            return self.data[-1]
        return float('-inf')

    def get_min(self):
        """
        Return the minimum value in the data structure.
        """
        if self.data:
            return self.data[0]
        return float('inf')

def process_operations(operations):
    ds = DataStructure()
    results = []
    for operation in operations:
        if operation.startswith("insert("):
            value = int(operation[7:-1])
            ds.insert(value)
        elif operation.startswith("erase("):
            value = int(operation[6:-1])
            ds.erase(value)
        elif operation == "get_max()":
            results.append(ds.get_max())
        elif operation == "get_min()":
            results.append(ds.get_min())
    return results

