def min_containers(weights, maxLoad):
    """
    Returns the minimum number of containers needed to carry all weights
    without exceeding the maxLoad per container.

    :param weights: List of integer weights
    :param maxLoad: Integer representing the maximum load per container
    :return: Integer representing the minimum number of containers needed
    """
    weights.sort(reverse=True)
    containers = []

    for weight in weights:
        placed = False
        for container in containers:
            if sum(container) + weight <= maxLoad:
                container.append(weight)
                placed = True
                break
        if not placed:
            containers.append([weight])

    return len(containers)

def split_array_minimize_max_sum(arr, k):
    """
    Divide an array into k non-empty subarrays such that the maximum sum of the elements
    in any subarray is minimized. Return the minimum possible value of that maximum sum.
    """
    def can_split(maximum_sum):
        current_sum = 0
        required_subarrays = 1
        for num in arr:
            if current_sum + num > maximum_sum:
                required_subarrays += 1
                current_sum = num
                if required_subarrays > k:
                    return False
            else:
                current_sum += num
        return True

    low, high = max(arr), sum(arr)
    while low < high:
        mid = (low + high) // 2
        if can_split(mid):
            high = mid
        else:
            low = mid + 1

    return low

