def pacific_atlantic(matrix):
    if not matrix or not matrix[0]:
        return []

    rows, cols = len(matrix), len(matrix[0])
    pacific_reachable = [[False] * cols for _ in range(rows)]
    atlantic_reachable = [[False] * cols for _ in range(rows)]

    def dfs(x, y, reachable):
        reachable[x][y] = True
        directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and not reachable[nx][ny] and matrix[nx][ny] >= matrix[x][y]:
                dfs(nx, ny, reachable)

    for i in range(rows):
        dfs(i, 0, pacific_reachable)
        dfs(i, cols - 1, atlantic_reachable)
    for j in range(cols):
        dfs(0, j, pacific_reachable)
        dfs(rows - 1, j, atlantic_reachable)

    result = []
    for i in range(rows):
        for j in range(cols):
            if pacific_reachable[i][j] and atlantic_reachable[i][j]:
                result.append([i, j])

    return result

