def subtract_one(digits):
    """
    Subtracts one from a non-negative integer represented as an array of digits.
    """
    n = len(digits)

    # Starting from the end of the array
    for i in range(n-1, -1, -1):
        if digits[i] > 0:
            digits[i] -= 1
            break
        else:
            digits[i] = 9
    # Remove leading zero if any, except if the result is zero
    if digits[0] == 0 and n > 1:
        digits = digits[1:]

    return digits

