def count_paths(n, edges, dest, restricted):
    from collections import defaultdict

    def dfs(node):
        if node == dest:
            return 1
        visited.add(node)
        path_count = 0
        for neighbor in graph[node]:
            if neighbor not in visited and neighbor not in restricted_set:
                path_count += dfs(neighbor)
        visited.remove(node)
        return path_count

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    restricted_set = set(restricted)
    visited = set()

    return dfs(1)

