class MaxStack:
    def __init__(self):
        self.stack = []
        self.maxStack = []

    def push(self, x):
        self.stack.append(x)
        if not self.maxStack or x >= self.maxStack[-1]:
            self.maxStack.append(x)

    def pop(self):
        if self.stack:
            popped_value = self.stack.pop()
            if popped_value == self.maxStack[-1]:
                self.maxStack.pop()
            return popped_value

    def top(self):
        if self.stack:
            return self.stack[-1]

    def peekMax(self):
        if self.maxStack:
            return self.maxStack[-1]

    def popMax(self):
        if self.maxStack:
            max_value = self.maxStack[-1]
            buffer = []
            while self.stack[-1] != max_value:
                buffer.append(self.stack.pop())
            self.stack.pop()
            self.maxStack.pop()
            while buffer:
                self.push(buffer.pop())
            return max_value

