def count_good_substrings(s):
    """
    Returns the number of distinct good substrings of s.
    A good substring has all distinct characters.
    """
    n = len(s)
    good_substrings = set()

    for i in range(n):
        seen = set()
        for j in range(i, n):
            if s[j] in seen:
                break
            seen.add(s[j])
            good_substrings.add(s[i:j + 1])

    return len(good_substrings)

