class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_max_heap(nums):
    """
    Constructs a max-heap based binary tree from a list of non-negative integers.

    Args:
    nums (list of int): List of non-negative integers.

    Returns:
    TreeNode: The root of the max-heap tree.
    """
    def heapify(nums, n, i):
        largest = i
        left = 2 * i + 1
        right = 2 * i + 2

        if left < n and nums[i] < nums[left]:
            largest = left

        if right < n and nums[largest] < nums[right]:
            largest = right

        if largest != i:
            nums[i], nums[largest] = nums[largest], nums[i]
            heapify(nums, n, largest)

    n = len(nums)

    for i in range(n // 2 - 1, -1, -1):
        heapify(nums, n, i)

    nodes = [TreeNode(val=num) for num in nums]

    for i in range(n):
        if 2 * i + 1 < n:
            nodes[i].left = nodes[2 * i + 1]
        if 2 * i + 2 < n:
            nodes[i].right = nodes[2 * i + 2]

    return nodes[0]

