def find_subarray_with_sum(arr, x):
    """
    Finds a subarray whose sum is exactly x.
    """
    current_sum = 0
    start_index = 0
    sum_dict = {}

    for end_index in range(len(arr)):
        current_sum += arr[end_index]

        if current_sum == x:
            return arr[start_index:end_index + 1]

        if current_sum - x in sum_dict:
            return arr[sum_dict[current_sum - x] + 1:end_index + 1]

        sum_dict[current_sum] = end_index

    return []

