def sum_and_height(root, n):
    if not root:
        return (0, 0)

    def calculate_sum_at_level(node, level):
        if not node:
            return 0
        if level == 0:
            return node.value
        return calculate_sum_at_level(node.left, level - 1) + calculate_sum_at_level(node.right, level - 1)

    def calculate_height(node):
        if not node:
            return 0
        return 1 + max(calculate_height(node.left), calculate_height(node.right))

    sum_at_n = calculate_sum_at_level(root, n)
    height = calculate_height(root)

    return (sum_at_n, height)

def count_errors_common_to_all_services(events):
    service_errors = {}
    for service_name, error_code in events:
        if service_name not in service_errors:
            service_errors[service_name] = set()
        service_errors[service_name].add(error_code)

    if not service_errors:
        return 0

    common = None
    for errors in service_errors.values():
        if common is None:
            common = set(errors)
        else:
            common &= errors
    return len(common) if common is not None else 0

def find_overlaps(intervals1, intervals2):
    """
    Finds and merges overlapping intervals between two lists of intervals.

    :param intervals1: List of tuples representing the first set of intervals.
    :param intervals2: List of tuples representing the second set of intervals.
    :return: List of tuples representing the merged overlapping intervals.
    """
    def merge_intervals(intervals):
        """
        Merges a list of intervals if they overlap.

        :param intervals: List of tuples representing intervals.
        :return: List of merged intervals.
        """
        if not intervals:
            return []

        intervals.sort(key=lambda x: x[0])

        merged = [intervals[0]]
        for current in intervals[1:]:
            last_merged = merged[-1]
            if current[0] <= last_merged[1]:
                merged[-1] = (last_merged[0], max(last_merged[1], current[1]))
            else:
                merged.append(current)
        return merged

    def find_interval_overlaps(int1, int2):
        """
        Finds the overlap between two intervals.

        :param int1: Tuple representing the first interval.
        :param int2: Tuple representing the second interval.
        :return: Tuple representing the overlapping interval or None if no overlap.
        """
        if int1[0] <= int2[1] and int2[0] <= int1[1]:
            return (max(int1[0], int2[0]), min(int1[1], int2[1]))
        return None

    overlaps = []
    for i1 in intervals1:
        for i2 in intervals2:
            overlap = find_interval_overlaps(i1, i2)
            if overlap:
                overlaps.append(overlap)

    return merge_intervals(overlaps)

def convert_to_lowercase(input_dict):
    """
    Converts all keys in the input dictionary to lowercase. If a value is a string,
    it converts it to lowercase. If a value is a list, it converts all elements
    in the list to lowercase. If a value is a dictionary, it recursively processes
    it in the same manner. All other data types remain unchanged.

    :param input_dict: Dictionary with keys and values of various data types.
    :return: A new dictionary with keys and string values converted to lowercase.
    """
    def lower_value(value):
        if isinstance(value, dict):
            return convert_to_lowercase(value)
        elif isinstance(value, list):
            return [lower_value(item) for item in value]
        elif isinstance(value, str):
            return value.lower()
        else:
            return value

    return {key.lower(): lower_value(value) for key, value in input_dict.items()}

import os

def list_directory_contents(directory_path):
    """
    Lists all files and subdirectories within the specified directory, including their full paths.
    Handles cases where the directory does not exist or is not accessible.

    :param directory_path: A string representing the directory path.
    """
    try:
        if not os.path.exists(directory_path):
            print(f"The directory '{directory_path}' does not exist.")
            return
        if not os.path.isdir(directory_path):
            print(f"The path '{directory_path}' is not a directory.")
            return

        for root, dirs, files in os.walk(directory_path):
            for name in files + dirs:
                print(os.path.join(root, name))
    except PermissionError:
        print(f"Permission denied: unable to access '{directory_path}'.")
    except Exception as e:
        print(f"An error occurred: {e}")

