def find_common_substrings(s1, s2, min_length):
    """
    Returns a list of all unique common substrings of s1 and s2 with a length of at least min_length.

    :param s1: First input string
    :param s2: Second input string
    :param min_length: Minimum length of common substrings to find
    :return: List of unique common substrings
    """
    common_substrings = set()
    substrings_s1 = {}

    for i in range(len(s1)):
        for j in range(i + min_length, len(s1) + 1):
            substring = s1[i:j]
            substring_length = len(substring)
            if substring_length not in substrings_s1:
                substrings_s1[substring_length] = set()
            substrings_s1[substring_length].add(substring)

    for i in range(len(s2)):
        for j in range(i + min_length, len(s2) + 1):
            substring = s2[i:j]
            substring_length = len(substring)
            if substring_length in substrings_s1 and substring in substrings_s1[substring_length]:
                common_substrings.add(substring)

    return list(common_substrings)

def fibonacci(n, memo=None):
    """
    Computes the nth Fibonacci number using memoization.

    Parameters:
    n (int): The position in the Fibonacci sequence.
    memo (dict, optional): A dictionary to store previously computed Fibonacci numbers.

    Returns:
    int: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    else:
        memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
        return memo[n]

def word_count(strings_list):
    """
    Returns a dictionary with words as keys and their respective counts as values.

    :param strings_list: List of strings to process.
    :return: Dictionary with word counts.
    """
    count_dict = {}
    for string in strings_list:
        words = string.split()
        for word in words:
            word = word.lower()
            if word in count_dict:
                count_dict[word] += 1
            else:
                count_dict[word] = 1
    return count_dict

def find_longest_increasing_subsequence(numbers):
    """
    Finds the length of the longest increasing subsequence in a list of integers using dynamic programming.

    :param numbers: List of integers
    :return: Length of the longest increasing subsequence
    """
    if not numbers:
        return 0

    dp = [1] * len(numbers)

    for i in range(1, len(numbers)):
        for j in range(i):
            if numbers[i] > numbers[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

