from collections import defaultdict, OrderedDict

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.minFreq = 0
        self.freq = defaultdict(OrderedDict)
        self.keyVal = {}
        self.keyFreq = {}

    def _update(self, key, value=None):
        freq = self.keyFreq[key]
        self.freq[freq].pop(key)

        if not self.freq[freq]:
            del self.freq[freq]
            if self.minFreq == freq:
                self.minFreq += 1

        if value is not None:
            self.keyVal[key] = value
        self.keyFreq[key] += 1
        self.freq[self.keyFreq[key]][key] = self.keyVal[key]

    def get(self, key: int) -> int:
        if key not in self.keyVal:
            return -1
        self._update(key)
        return self.keyVal[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return

        if key in self.keyVal:
            self._update(key, value)
        else:
            if len(self.keyVal) >= self.capacity:
                k, _ = self.freq[self.minFreq].popitem(last=False)
                del self.keyVal[k]
                del self.keyFreq[k]

            self.keyVal[key] = value
            self.keyFreq[key] = 1
            self.minFreq = 1
            self.freq[1][key] = value

