def count_distinct_triplets(arr, target):
    """
    Returns the number of distinct triplets (i, j, k) such that
    0 <= i < j < k < len(arr) and arr[i] + arr[j] + arr[k] == target
    """
    n = len(arr)
    count = 0

    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                if arr[i] + arr[j] + arr[k] == target:
                    count += 1

    return count

def is_balanced_parentheses(s: str) -> bool:
    """
    Determines if a string of parentheses is balanced.

    Args:
    s (str): The string containing parentheses to be checked.

    Returns:
    bool: True if the string is balanced, False otherwise.
    """
    matching_parentheses = {')': '(', ']': '[', '}': '{'}
    stack = []

    for char in s:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses.keys():
            if stack and stack[-1] == matching_parentheses[char]:
                stack.pop()
            else:
                return False

    return len(stack) == 0

