def pacificAtlantic(heights):
    if not heights:
        return []

    def dfs(x, y, visited, prev_height):
        if ((x, y) in visited or 
            x < 0 or x >= len(heights) or 
            y < 0 or y >= len(heights[0]) or 
            heights[x][y] < prev_height):
            return
        visited.add((x, y))
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            dfs(x + dx, y + dy, visited, heights[x][y])

    pacific, atlantic = set(), set()
    rows, cols = len(heights), len(heights[0])

    for i in range(rows):
        dfs(i, 0, pacific, heights[i][0])  # Left edge (Pacific)
        dfs(i, cols - 1, atlantic, heights[i][cols - 1])  # Right edge (Atlantic)
    for j in range(cols):
        dfs(0, j, pacific, heights[0][j])  # Top edge (Pacific)
        dfs(rows - 1, j, atlantic, heights[rows - 1][j])  # Bottom edge (Atlantic)

    return list(map(list, pacific & atlantic))

