from collections import deque

def shortest_bridge(grid):
    n = len(grid)

    def get_neighbors(x, y):
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                yield nx, ny

    def dfs(x, y):
        stack = [(x, y)]
        while stack:
            i, j = stack.pop()
            if (i, j) not in visited:
                visited.add((i, j))
                grid[i][j] = 2 # Marking the island with a 2
                for ni, nj in get_neighbors(i, j):
                    if grid[ni][nj] == 1:
                        stack.append((ni, nj))
                q.append((i, j)) # For BFS later

    # Step 1: Find the first island and mark it
    found = False
    visited = set()
    q = deque()
    for i in range(n):
        if found:
            break
        for j in range(n):
            if grid[i][j] == 1:
                dfs(i, j)
                found = True
                break

    # Step 2: Use BFS to find the shortest path to the second island
    steps = 0
    while q:
        for _ in range(len(q)):
            x, y = q.popleft()
            for nx, ny in get_neighbors(x, y):
                if grid[nx][ny] == 1:
                    return steps
                if grid[nx][ny] == 0:
                    grid[nx][ny] = 2
                    q.append((nx, ny))
        steps += 1

    return -1

