class MaxConsecutiveSum:
    def __init__(self, nums, k):
        self.nums = nums
        self.k = k

    def findMaxConsecutiveSum(self):
        if not self.nums or self.k <= 0 or self.k > len(self.nums):
            return 0

        # Calculate the sum of the first 'k' elements
        max_sum = current_sum = sum(self.nums[:self.k])

        # Use a sliding window to find the maximum sum of 'k' consecutive elements
        for i in range(self.k, len(self.nums)):
            current_sum += self.nums[i] - self.nums[i - self.k]
            max_sum = max(max_sum, current_sum)

        return max_sum

