def min_max_work(tasks, d):
    def feasible(capacity):
        days = 1
        total = 0
        for task in tasks:
            if total + task <= capacity:
                total += task
            else:
                days += 1
                total = task
        return days <= d

    left, right = max(tasks), sum(tasks)

    while left < right:
        mid = (left + right) // 2
        if feasible(mid):
            right = mid
        else:
            left = mid + 1

    return left

