def can_form_sentence(s, words):
    """
    Returns true if the sentence can be constructed by following the exact order
    and lengths of the words specified in the `words` array, otherwise returns false.
    """
    s_split = s.split()
    if len(s_split) != len(words):
        return False
    for i, word in enumerate(s_split):
        if len(word) != words[i]:
            return False
    return True

def pacific_atlantic(grid):
    if not grid or not grid[0]:
        return []

    m, n = len(grid), len(grid[0])

    def bfs(starts):
        visited = set(starts)
        queue = starts[:]
        while queue:
            i, j = queue.pop(0)
            for di, dj in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and (ni, nj) not in visited and grid[ni][nj] >= grid[i][j]:
                    visited.add((ni, nj))
                    queue.append((ni, nj))
        return visited

    pacific_starts = [(i, 0) for i in range(m)] + [(0, j) for j in range(1, n)]
    atlantic_starts = [(i, n - 1) for i in range(m)] + [(m - 1, j) for j in range(n - 1)]

    pacific_reachable = bfs(pacific_starts)
    atlantic_reachable = bfs(atlantic_starts)

    return list(pacific_reachable.intersection(atlantic_reachable))

