def longest_contiguous_subarray(nums):
    """
    Returns the length of the longest contiguous subarray where every element
    is either strictly increasing or strictly decreasing.
    """
    if len(nums) < 2:
        return 0

    max_len = 1
    current_len = 1
    is_increasing = None

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            if is_increasing is None or is_increasing:
                current_len += 1
            else:
                current_len = 2
            is_increasing = True
        elif nums[i] < nums[i - 1]:
            if is_increasing is None or not is_increasing:
                current_len += 1
            else:
                current_len = 2
            is_increasing = False
        else:
            current_len = 1
            is_increasing = None

        max_len = max(max_len, current_len)

    return max_len

def count_bounded_range_subarrays(difficulties, d):
    from collections import deque
    maxdq = deque()
    mindq = deque()
    left = 0
    ans = 0
    for right, val in enumerate(difficulties):
        while maxdq and maxdq[-1] < val:
            maxdq.pop()
        maxdq.append(val)
        while mindq and mindq[-1] > val:
            mindq.pop()
        mindq.append(val)
        while maxdq[0] - mindq[0] > d:
            if difficulties[left] == maxdq[0]:
                maxdq.popleft()
            if difficulties[left] == mindq[0]:
                mindq.popleft()
            left += 1
        ans += right - left + 1
    return ans

def max_profit(nums):
    """
    Calculate the maximum profit from a single buy and sell of stock.

    :param nums: List[int] - A list of integers representing stock prices.
    :return: int - The maximum profit that can be achieved.
    """
    if not nums or len(nums) < 2:
        return 0

    min_price = nums[0]
    max_profit = 0

    for price in nums:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

class Library:
    def __init__(self):
        """Initialize an empty dictionary to store books and a counter for the number of books."""
        self.books = {}
        self.book_count = 0

    def add_book(self, isbn, title, author):
        """Adds a book to the library with ISBN as the unique identifier."""
        if isbn in self.books:
            print(f"Book with ISBN {isbn} already exists in the library.")
        else:
            self.books[isbn] = {'title': title, 'author': author}
            self.book_count += 1
            print(f"Book '{title}' by {author} added to the library.")

    def remove_book(self, isbn):
        """Removes a book from the library using ISBN."""
        if isbn in self.books:
            removed_book = self.books.pop(isbn)
            self.book_count -= 1
            print(f"Book '{removed_book['title']}' by {removed_book['author']} removed from the library.")
        else:
            print(f"No book with ISBN {isbn} found in the library.")

    def list_books(self):
        """Lists all books in the library."""
        if not self.books:
            print("No books found in the library.")
        else:
            print("Listing all books in the library:")
            for isbn, book in self.books.items():
                print(f"ISBN: {isbn}, Title: {book['title']}, Author: {book['author']}")

    def get_book_count(self):
        """Returns the number of books in the library."""
        return self.book_count

