def calculate(expression):
    """
    Evaluates a simple arithmetic expression provided as a string.

    Args:
    expression (str): A string representing the arithmetic operation to be performed.

    Returns:
    float or str: The result of the arithmetic operation as a float, or an error message as a string.
    """
    try:
        num1, operator, num2 = expression.split()
        num1 = float(num1)
        num2 = float(num2)

        if operator == '+':
            return num1 + num2
        elif operator == '-':
            return num1 - num2
        elif operator == '*':
            return num1 * num2
        elif operator == '/':
            if num2 == 0:
                return "Error: Division by zero"
            return num1 / num2
        else:
            return "Error: Invalid operator"
    except ValueError:
        return "Error: Invalid input format"

def fibonacci(n, memo=None):
    """
    Calculate the n-th Fibonacci number using recursion with memoization.

    :param n: The position in the Fibonacci sequence (0-indexed).
    :param memo: A dictionary to store previously computed Fibonacci numbers.
    :return: The n-th Fibonacci number.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    return memo[n]

def shortest_common_supersequence(str1, str2):
    """
    Finds the shortest common supersequence of two strings.

    :param str1: First input string.
    :param str2: Second input string.
    :return: The shortest common supersequence of str1 and str2.
    """
    m, n = len(str1), len(str2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    i, j = m, n
    s = []
    while i > 0 and j > 0:
        if str1[i - 1] == str2[j - 1]:
            s.append(str1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            s.append(str1[i - 1])
            i -= 1
        else:
            s.append(str2[j - 1])
            j -= 1

    while i > 0:
        s.append(str1[i - 1])
        i -= 1
    while j > 0:
        s.append(str2[j - 1])
        j -= 1

    s.reverse()
    return ''.join(s)

def factorial(n):
    """
    Calculate the factorial of a non-negative integer n using recursion.

    Parameters:
    n (int): The number to compute the factorial of. Must be in the range 0 ≤ n ≤ 20.

    Returns:
    int: The factorial of the number n.
    """
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

