def net_balance(transactions):
    """
    Computes the net balance for each user from a list of transactions.

    Parameters:
    transactions (list of list): A list where each inner list contains a transaction ID,
                                 sender's ID, receiver's ID, and transaction amount.

    Returns:
    dict: A dictionary with user IDs as keys and their net balances as values.
    """
    balance = {}

    for transaction in transactions:
        _, sender, receiver, amount = transaction

        if sender in balance:
            balance[sender] -= amount
        else:
            balance[sender] = -amount

        if receiver in balance:
            balance[receiver] += amount
        else:
            balance[receiver] = amount

    return balance

def min_cut(s: str) -> int:
    """
    Returns the minimum number of cuts needed for a palindrome partitioning of the string s.

    :param s: A string consisting of lowercase English letters.
    :return: An integer representing the minimum number of cuts needed.
    """
    n = len(s)
    dp = [0] * n
    pali = [[False] * n for _ in range(n)]

    for i in range(n-1, -1, -1):
        min_cuts = float('inf')
        for j in range(i, n):
            if s[i] == s[j] and (j - i < 2 or pali[i+1][j-1]):
                pali[i][j] = True
                if j == n - 1:
                    min_cuts = 0
                else:
                    min_cuts = min(min_cuts, dp[j+1] + 1)
        dp[i] = min_cuts

    return dp[0]

def largest_island_perimeter(grid):
    """
    Returns the perimeter of the largest island in the grid.
    """
    def dfs(r, c):
        stack = [(r, c)]
        visited.add((r, c))
        perimeter = 0
        island_size = 0

        while stack:
            x, y = stack.pop()
            island_size += 1

            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n:
                    if grid[nx][ny] == '0':
                        perimeter += 1
                    elif grid[nx][ny] == '1' and (nx, ny) not in visited:
                        stack.append((nx, ny))
                        visited.add((nx, ny))
                else:
                    perimeter += 1

        return perimeter, island_size

    m, n = len(grid), len(grid[0])
    visited = set()
    max_perimeter = 0

    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1' and (i, j) not in visited:
                perimeter, island_size = dfs(i, j)
                if island_size > 0:
                    max_perimeter = max(max_perimeter, perimeter)

    return max_perimeter

class TreeNode:
    def __init__(self, val=0, left=None, right=None, sibling=None):
        self.val = val
        self.left = left
        self.right = right
        self.sibling = sibling

def populate_sibling_pointers(root):
    if not root:
        return None

    current = root
    dummy = TreeNode()
    while current:
        level_current = dummy
        while current:
            if current.left:
                level_current.sibling = current.left
                level_current = level_current.sibling
            if current.right:
                level_current.sibling = current.right
                level_current = level_current.sibling
            current = current.sibling
        current = dummy.sibling
        dummy.sibling = None

    return root

