    def __init__(self):
        self.check_ins = {}
        self.travel_times = {}

    def checkIn(self, id, stationName, t):
        self.check_ins[id] = (stationName, t)

    def checkOut(self, id, stationName, t):
        start_station, start_time = self.check_ins.pop(id)
        trip = (start_station, stationName)
        if trip not in self.travel_times:
            self.travel_times[trip] = (0, 0)
        total_time, total_trips = self.travel_times[trip]
        total_time += t - start_time
        total_trips += 1
        self.travel_times[trip] = (total_time, total_trips)

    def getAverageTime(self, startStation, endStation):
        total_time, total_trips = self.travel_times[(startStation, endStation)]
        return total_time / total_trips

