def min_path_sum(matrix):
    """
    Finds the path from top-left to bottom-right in a matrix such that the sum of 
    integers along the path is minimized. Returns the minimum sum and the path taken.
    Path is returned as a list of coordinates.
    """
    if not matrix or not matrix[0]:
        return 0, []

    m, n = len(matrix), len(matrix[0])

    # Initialize a dp array to store the minimum sum up to each cell
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = matrix[0][0]

    # Populate the dp table and path tracking
    for i in range(m):
        for j in range(n):
            if i == 0 and j > 0:
                dp[i][j] = dp[i][j-1] + matrix[i][j]
            elif j == 0 and i > 0:
                dp[i][j] = dp[i-1][j] + matrix[i][j]
            elif i > 0 and j > 0:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    # Backtrack to find the path
    path = []
    i, j = m - 1, n - 1
    path.append((i, j))
    while i > 0 or j > 0:
        if i == 0:
            j -= 1
        elif j == 0:
            i -= 1
        elif dp[i-1][j] < dp[i][j-1]:
            i -= 1
        else:
            j -= 1
        path.append((i, j))

    return dp[m-1][n-1], path[::-1]

