def maxProfit(k, prices):
    n = len(prices)
    if n == 0:
        return 0

    if k >= n // 2:
        # If we can do transactions as much as we want
        return sum(
            max(prices[i + 1] - prices[i], 0)
            for i in range(n - 1)
        )

    profits = [[0] * n for _ in range(k + 1)]

    for t in range(1, k + 1):
        max_diff = -prices[0]
        for i in range(1, n):
            profits[t][i] = max(profits[t][i - 1], prices[i] + max_diff)
            max_diff = max(max_diff, profits[t - 1][i] - prices[i])

    return profits[k][n - 1]

