def can_form_increasing_sequence(arr):
    def is_strictly_increasing(a):
        for i in range(1, len(a)):
            if a[i-1] >= a[i]:
                return False
        return True

    # Check if arr is already strictly increasing
    if is_strictly_increasing(arr):
        return True

    # Try removing each element and check if the resulting array is strictly increasing
    for i in range(len(arr)):
        if is_strictly_increasing(arr[:i] + arr[i+1:]):
            return True

    return False

