def longest_valid_subarray(s, k):
    """
    Returns the length of the longest contiguous subarray where the number of '0's does not exceed k.
    """
    left = 0
    max_length = 0
    zeros_count = 0

    for right in range(len(s)):
        if s[right] == '0':
            zeros_count += 1

        while zeros_count > k:
            if s[left] == '0':
                zeros_count -= 1
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

