def min_distance(houses, m):
    houses.sort()
    n = len(houses)
    if m >= n:
        return 0

    dp = [[float('inf')] * m for _ in range(n)]

    for i in range(n):
        dp[i][0] = sum(abs(houses[j] - houses[i//2]) for j in range(i+1))

    for k in range(1, m):
        for i in range(k, n):
            for j in range(k-1, i):
                dp[i][k] = min(dp[i][k], dp[j][k-1] + sum(abs(houses[l] - houses[(j+1 + i)//2]) for l in range(j+1, i+1)))

    return dp[-1][-1]

