def find_pivot_index(arr):
    """
    This function returns the pivot index of a rotated sorted array. If the array is not rotated,
    it returns 0.
    """
    if not arr:
        return -1  # Handle empty array edge case

    low, high = 0, len(arr) - 1

    while low < high:
        mid = (low + high) // 2

        # If mid element is greater than high element, the pivot must be in the right half
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid

    return low

