def shortest_palindrome(s):
    """
    Returns the shortest palindrome p such that s can be formed by appending zero or more characters to the end of p.
    """
    if s == s[::-1]:
        return s

    rev_s = s[::-1]
    for i in range(len(s)):
        if s.startswith(rev_s[i:]):
            return rev_s[:i] + s
    return ""

