def count_unique_reactions(element, effectPairs):
    """
    Returns the number of unique special reactions in the element.

    :param element: String, the elemental string.
    :param effectPairs: List of pairs of characters representing special reactions.
    :return: Integer, number of unique special reactions.
    """
    unique_reactions = set()

    effects_set = {(pair[0], pair[1]) for pair in effectPairs}

    for i in range(len(element) - 1):
        if (element[i], element[i + 1]) in effects_set:
            unique_reactions.add(element[i] + element[i + 1])

    return len(unique_reactions)

def format_settings(text):
    settings = {}
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        key, value = line.split('=', 1)
        settings[key.strip()] = value.strip()
    return ';'.join(f"{key}:{settings[key]}" for key in sorted(settings))

def find_target_sentences(sentences, targets):
    """
    Returns a dictionary where each key is a target word (in lowercase) and each value is a list of sentences
    (in lowercase) that contain the target word as a substring. The comparison is case-insensitive.

    :param sentences: List of sentences (strings).
    :param targets: List of target words (strings).
    :return: Dictionary with target words as keys and lists of sentences as values.
    """
    lower_sentences = [sentence.lower() for sentence in sentences]
    result = {target.lower(): [] for target in targets}

    for sentence in lower_sentences:
        for target in targets:
            if target.lower() in sentence:
                result[target.lower()].append(sentence)

    return result

