def min_energy_cost(grid):
    """
    Computes the minimum energy cost to move from the top-left corner to the bottom-right corner of the grid.

    :param grid: List[List[int]] - A 2D list representing the energy cost grid.
    :return: int - The minimum energy cost to reach the bottom-right corner.
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    dp = [[0] * cols for _ in range(rows)]

    dp[0][0] = grid[0][0]

    for j in range(1, cols):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    for i in range(1, rows):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[rows-1][cols-1]

def factorize_number(n):
    """
    Returns a dictionary with prime factors as keys and their respective exponents as values.

    :param n: Integer to be factorized
    :return: Dictionary of prime factors and their exponents
    """
    def prime_factors(n):
        i = 2
        factors = {}
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors[i] = factors.get(i, 0) + 1
        if n > 1:
            factors[n] = factors.get(n, 0) + 1
        return factors

    return prime_factors(n)

