def max_mushrooms(grid):
    """
    Returns the maximum number of mushrooms Mario can collect from the first column to the last column.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Create a memoization table to store the maximum mushrooms collected to each cell
    dp = [[0] * n for _ in range(m)]

    # Initialize the first column of dp with the values of the grid
    for i in range(m):
        dp[i][0] = grid[i][0]

    # Fill the dp table
    for j in range(1, n):
        for i in range(m):
            max_from_left = dp[i][j-1]  # from left
            if i > 0:
                max_from_left_up = dp[i-1][j-1]  # from left-up
            else:
                max_from_left_up = 0
            if i < m-1:
                max_from_left_down = dp[i+1][j-1]  # from left-down
            else:
                max_from_left_down = 0
            dp[i][j] = grid[i][j] + max(max_from_left, max_from_left_up, max_from_left_down)

    # The result is the maximum value in the last column
    return max(dp[i][n-1] for i in range(m))

def word_break(s, dict):
    from collections import defaultdict
    def _word_break(s, dict, memo):
        if s in memo: 
            return memo[s]
        if not s: 
            return ['']

        res = []
        for word in dict:
            if s.startswith(word):
                sublist = _word_break(s[len(word):], dict, memo)
                for sub in sublist:
                    res.append(word + ("" if sub == "" else " ") + sub)
        memo[s] = sorted(res)
        return memo[s]

    memo = {}
    return _word_break(s, dict, memo)

