def increasing_triplet(nums):
    """
    Returns true if there exists a subsequence of length 3 that forms an increasing triplet subsequence.
    Otherwise, returns false.
    """
    if not nums or len(nums) < 3:
        return False

    first = float('inf')
    second = float('inf')

    for n in nums:
        if n <= first:
            first = n
        elif n <= second:
            second = n
        else:
            return True

    return False

