def evaluate_expression(expression):
    """
    Evaluates a given arithmetic expression with no parentheses.
    """

    # Splitting the expression by space character
    tokens = expression.split()

    # Stack for numbers and operators
    num_stack = []
    op_stack = []

    # Precedence of operators
    precedence = {'+':1, '-':1, '*':2, '/':2}

    def apply_operator(op):
        """
        Apply the operator to the top two values in the num_stack.
        """
        right = num_stack.pop()
        left = num_stack.pop()
        if op == '+':
            num_stack.append(left + right)
        elif op == '-':
            num_stack.append(left - right)
        elif op == '*':
            num_stack.append(left * right)
        elif op == '/':
            if isinstance(left, int) and isinstance(right, int):
                num_stack.append(left // right)
            else:
                num_stack.append(left / right)

    for token in tokens:
        if token.isdigit() or ('.' in token):
            num_stack.append(float(token) if '.' in token else int(token))
        else:
            while (op_stack and precedence[op_stack[-1]] >= precedence[token]):
                apply_operator(op_stack.pop())
            op_stack.append(token)

    while op_stack:
        apply_operator(op_stack.pop())

    return float(num_stack[0])

