def minPathSum(grid):
    """
    Given a grid of size m x n filled with non-negative integers, find a path from the top left to the bottom right
    which minimizes the sum of all numbers along its path. You can only move to the right or down from a cell.

    :param grid: List[List[int]], 2D list representing the grid
    :return: int, minimum sum possible to reach the bottom-right corner
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])

    # Initialize the DP table with the same dimensions as the grid
    dp = [[0] * cols for _ in range(rows)]

    # Fill the DP table
    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                dp[i][j] = grid[i][j]  # Starting point
            elif i == 0:
                dp[i][j] = dp[i][j-1] + grid[i][j]  # First row (can only come from the left)
            elif j == 0:
                dp[i][j] = dp[i-1][j] + grid[i][j]  # First column (can only come from above)
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]  # Choose min from top or left

    return dp[rows-1][cols-1]

