def min_completion_time(times):
    """
    Returns the minimum possible time needed to complete all tasks using two workers.

    :param times: List[int] - An array of integers where times[i] is the time needed to complete the i-th task
    :return: int - The minimum time needed to complete all tasks
    """
    times.sort(reverse=True)

    worker1 = 0
    worker2 = 0

    for time in times:
        if worker1 <= worker2:
            worker1 += time
        else:
            worker2 += time

    return max(worker1, worker2)

