def max_non_consecutive_sum(arr):
    """
    Returns the sum of the largest subsequence in the array where no two consecutive elements are included.
    """
    if not arr:
        return 0
    if len(arr) == 1:
        return arr[0]

    incl = arr[0]
    excl = 0

    for i in range(1, len(arr)):
        new_excl = max(incl, excl)
        incl = excl + arr[i]
        excl = new_excl

    return max(incl, excl)

