def calculate_total_sales(transactions):
    """
    Calculate the total sales for each customer from a list of transactions.

    :param transactions: List of dictionaries, each representing a transaction with keys 'transaction_id', 'customer_id', 'amount', and 'timestamp'.
    :return: Dictionary with customer IDs as keys and their total sales amounts as values.
    """
    total_sales = {}
    for transaction in transactions:
        customer_id = transaction['customer_id']
        amount = transaction['amount']
        if customer_id in total_sales:
            total_sales[customer_id] += amount
        else:
            total_sales[customer_id] = amount
    return total_sales

