def solution(s):
    result = {}
    for item in s.split(';'):
        if '=' not in item:
            continue
        key, value = item.split('=', 1)
        key = key.strip()
        value = value.strip()
        if key == '':
            continue
        result[key] = value
    return result

def solution(inventory):
    result = {}
    for item in inventory.split('/'):
        item = item.strip()
        if 'x' not in item:
            continue
        code, qty_str = item.split('x', 1)
        code = code.strip()
        qty_str = qty_str.strip()
        if not code.isalnum():
            continue
        if not qty_str.isdigit():
            continue
        qty = int(qty_str)
        if qty < 1:
            continue
        result[code] = result.get(code, 0) + qty
    return result

def count_suspicious_devices(logs, window):
    from collections import defaultdict

    device_logs = defaultdict(list)
    for timestamp, device_id, ip in logs:
        device_logs[device_id].append((timestamp, ip))

    suspicious = 0
    for items in device_logs.values():
        items.sort()
        ips = set()
        left = 0
        for right, (t, ip) in enumerate(items):
            while items[left][0] < t - window:
                ips.discard(items[left][1])
                left += 1
            if len(ips) > 0 and ip not in ips:
                suspicious += 1
                break
            ips.add(ip)
    return suspicious

def evaluate_rpn(expression: str) -> int:
    """
    Evaluates a given Reverse Polish Notation (RPN) expression.

    :param expression: A string representing a mathematical expression in RPN.
    :return: The result of the evaluated expression as an integer, or None if division by zero occurs.
    """
    tokens = expression.split()
    stack = []
    operators = {'+', '-', '*', '/'}

    for token in tokens:
        if token not in operators:
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            try:
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    if b == 0:
                        return None
                    stack.append(a // b)
            except ZeroDivisionError:
                return None

    return stack[0]

import random

def partition(nums, low, high):
    """
    Partitions the list around a pivot element such that elements greater than the pivot are on the left,
    and elements less than the pivot are on the right.
    """
    pivot_index = random.randint(low, high)
    pivot_value = nums[pivot_index]
    nums[pivot_index], nums[high] = nums[high], nums[pivot_index]
    store_index = low
    for i in range(low, high):
        if nums[i] > pivot_value:
            nums[store_index], nums[i] = nums[i], nums[store_index]
            store_index += 1
    nums[store_index], nums[high] = nums[high], nums[store_index]
    return store_index

def quickselect(nums, low, high, k_smallest):
    """
    Returns the k-th smallest element in the list within the range [low, high].
    """
    if low == high:
        return nums[low]

    pivot_index = partition(nums, low, high)

    if k_smallest == pivot_index:
        return nums[k_smallest]
    elif k_smallest < pivot_index:
        return quickselect(nums, low, pivot_index - 1, k_smallest)
    else:
        return quickselect(nums, pivot_index + 1, high, k_smallest)

def find_kth_largest(nums, k):
    """
    Finds the k-th largest element in the list.
    """
    return quickselect(nums, 0, len(nums) - 1, k - 1)

def swap_dict(input_dict):
    """
    Constructs a new dictionary where each unique element from the lists in the input dictionary
    becomes a key, and the value is a list of all original keys that had this element in their list.

    :param input_dict: A dictionary with string keys and list of string values.
    :return: A dictionary with string keys and list of string values, with keys and values swapped.
    """
    new_dict = {}
    for key, value_list in input_dict.items():
        for value in value_list:
            if value not in new_dict:
                new_dict[value] = [key]
            else:
                new_dict[value].append(key)
    return new_dict

