def two_sum(nums, target):
    """
    Finds the indices of the two distinct elements in nums that sum up to target.

    :param nums: List[int] - A list of integers.
    :param target: int - The target sum.
    :return: List[int] - Indices of the two elements that add up to the target.
    """
    num_map = {}
    for index, num in enumerate(nums):
        complement = target - num
        if complement in num_map:
            return [num_map[complement], index]
        num_map[num] = index

def fibonacci(n):
    """
    Computes the nth Fibonacci number using recursion.

    Parameters:
    n (int): The position in the Fibonacci sequence.

    Returns:
    int or None: The nth Fibonacci number if n is non-negative, otherwise None.
    """
    if n < 0:
        return None
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

class TreeNode:
    def __init__(self, val=0, children=None):
        self.val = val
        self.children = children if children is not None else []

def find_max_depth(tree):
    """
    Computes the maximum depth of a tree.

    :param tree: TreeNode, the root of the tree
    :return: int, the maximum depth of the tree
    """
    if tree is None:
        return 0
    if not tree.children:
        return 1
    return 1 + max(find_max_depth(child) for child in tree.children)

def recursive_sum(numbers):
    """
    Recursively calculates the sum of all integers in a list.

    Parameters:
    numbers (list of int): The list of integers to sum.

    Returns:
    int: The sum of all integers in the list.
    """
    if not numbers:
        return 0
    else:
        return numbers[0] + recursive_sum(numbers[1:])

class TreeNode:
    """Node class representing a node in a binary search tree."""
    def __init__(self, key):
        self.left = None  # Left child of the node
        self.right = None # Right child of the node
        self.val = key    # Value of the node

class BinarySearchTree:
    """Binary Search Tree class with methods for insertion, searching, and deletion."""
    def __init__(self):
        self.root = None  # Root of the tree

    def insert(self, key):
        """Insert a new node with the given key into the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert_recursively(self.root, key)

    def _insert_recursively(self, current_node, key):
        """Helper method to insert a new node with the given key recursively."""
        if key < current_node.val:
            if current_node.left is None:
                current_node.left = TreeNode(key)
            else:
                self._insert_recursively(current_node.left, key)
        elif key > current_node.val:
            if current_node.right is None:
                current_node.right = TreeNode(key)
            else:
                self._insert_recursively(current_node.right, key)

    def search(self, key):
        """Search for a node with the given key in the BST."""
        return self._search_recursively(self.root, key)

    def _search_recursively(self, current_node, key):
        """Helper method to search for a node with the given key recursively."""
        if current_node is None or current_node.val == key:
            return current_node
        if key < current_node.val:
            return self._search_recursively(current_node.left, key)
        else:
            return self._search_recursively(current_node.right, key)

    def delete(self, key):
        """Delete the node with the given key from the BST."""
        self.root = self._delete_recursively(self.root, key)

    def _delete_recursively(self, current_node, key):
        """Helper method to delete the node with the given key recursively."""
        if current_node is None:
            return current_node

        if key < current_node.val:
            current_node.left = self._delete_recursively(current_node.left, key)
        elif key > current_node.val:
            current_node.right = self._delete_recursively(current_node.right, key)
        else:
            if current_node.left is None:
                return current_node.right
            elif current_node.right is None:
                return current_node.left

            current_node.val = self._min_value_node(current_node.right).val
            current_node.right = self._delete_recursively(current_node.right, current_node.val)

        return current_node

    def _min_value_node(self, node):
        """Helper method to find the node with the minimum value in a given subtree."""
        current = node
        while current.left is not None:
            current = current.left
        return current

def find_first_non_repeating_char(s):
    """
    Returns the first non-repeating character in the string.
    If no such character exists, returns None.

    :param s: Input string consisting of lowercase English letters.
    :return: The first non-repeating character or None.
    """
    char_count = {}

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in s:
        if char_count[char] == 1:
            return char

    return None

