import re

def parse_html_tags(html_content):
    """
    Parses the given HTML content and returns a dictionary with the count of each opening tag.

    :param html_content: A string representing the HTML content.
    :return: A dictionary with tag names as keys and their counts as values.
    """
    tag_pattern = re.compile(r'<(/?)(\w+)')
    tags = tag_pattern.findall(html_content)
    tag_counts = {}

    for is_closing, tag in tags:
        if not is_closing:
            if tag in tag_counts:
                tag_counts[tag] += 1
            else:
                tag_counts[tag] = 1

    return tag_counts

