from queue import PriorityQueue

def can_flow(grid, x, y, visited, max_height):
    """
    Helper function to perform DFS and check if water can flow from (0,0) to (m-1, n-1) at a given max height.
    """
    if x == len(grid) - 1 and y == len(grid[0]) - 1:
        return True

    directions = [(0,1), (1,0), (0,-1), (-1,0)]
    visited.add((x, y))

    for dx, dy in directions:
        nx, ny = x + dx, y + dy
        if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and (nx, ny) not in visited and grid[nx][ny] <= max_height:
            if can_flow(grid, nx, ny, visited, max_height):
                return True
    return False

def find_min_height(grid):
    """
    Main function to find the minimum height needed to ensure water flow from top-left corner to bottom-right corner.
    Uses binary search and DFS to find the solution.
    """
    rows, cols = len(grid), len(grid[0])
    left, right = max(grid[0][0], grid[rows-1][cols-1]), max(max(row) for row in grid)

    while left < right:
        mid = (left + right) // 2
        if can_flow(grid, 0, 0, set(), mid):
            right = mid
        else:
            left = mid + 1

    return left

def count_equal_submatrices(grid):
    """
    Given a 2D integer matrix grid, returns the number of submatrices that have all their elements equal.
    """
    def is_uniform_submatrix(i1, j1, i2, j2):
        val = grid[i1][j1]
        for i in range(i1, i2 + 1):
            for j in range(j1, j2 + 1):
                if grid[i][j] != val:
                    return False
        return True

    n = len(grid)
    m = len(grid[0])
    count = 0

    for i1 in range(n):
        for j1 in range(m):
            for i2 in range(i1, n):
                for j2 in range(j1, m):
                    if is_uniform_submatrix(i1, j1, i2, j2):
                        count += 1

    return count

