def max_temperature_spike(temperatures):
    """
    Finds the maximum number of consecutive days of increasing temperatures.
    If no such spike exists, returns 1.

    :param temperatures: List of integers representing daily temperatures.
    :returns: The maximum number of consecutive days in a temperature spike, or 1 if no such spike exists.
    """
    if not temperatures:
        return 0

    max_spike = 1
    current_spike = 1

    for i in range(1, len(temperatures)):
        if temperatures[i] > temperatures[i-1]:
            current_spike += 1
            if current_spike > max_spike:
                max_spike = current_spike
        else:
            current_spike = 1

    return max_spike

