from collections import deque, defaultdict

def min_buses_to_destination(routes, source, destination):
    if source == destination:
        return 0

    def build_graph(routes):
        graph = defaultdict(set)
        for route_index, route in enumerate(routes):
            stops = route.split(',')
            for stop in stops:
                graph[stop].add(route_index)
        return graph

    graph = build_graph(routes)
    queue = deque([(source, 0)])
    visited_stops = {source}
    visited_routes = set()

    while queue:
        current_stop, buses_taken = queue.popleft()
        for route_index in graph[current_stop]:
            if route_index in visited_routes:
                continue
            visited_routes.add(route_index)
            route_stops = routes[route_index].split(',')
            for stop in route_stops:
                if stop == destination:
                    return buses_taken + 1
                if stop not in visited_stops:
                    visited_stops.add(stop)
                    queue.append((stop, buses_taken + 1))

    return -1

