from collections import deque

class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def build_tree_from_level_order(values):
    if not values:
        return None

    root = TreeNode(values[0])
    queue = deque([root])

    i = 1
    while i < len(values):
        current = queue.popleft()
        if values[i] is not None:
            current.left = TreeNode(values[i])
            queue.append(current.left)
        i += 1

        if i < len(values) and values[i] is not None:
            current.right = TreeNode(values[i])
            queue.append(current.right)
        i += 1

    return root

def reverse_level_order_traversal(root):
    if not root:
        return []

    result, queue = deque(), deque([root])

    while queue:
        level_length = len(queue)
        level = []
        for _ in range(level_length):
            node = queue.popleft()
            level.append(node.value)

            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

        result.appendleft(level)

    return list(result)

def traverse_tree_from_array(values):
    root = build_tree_from_level_order(values)
    return reverse_level_order_traversal(root)

