def has_arithmetic_triplet(arr):
    """
    Returns True if there exists a triple (i, j, k) such that
    arr[i], arr[j], and arr[k] form an arithmetic progression.
    """
    n = len(arr)
    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                if arr[j] - arr[i] == arr[k] - arr[j]:
                    return True
    return False

