def majority_element(nums):
    """
    Returns the list of elements that appear more than n/3 times in the array.
    If no such element exists, returns an empty list.
    """
    if not nums:
        return []

    n = len(nums)
    count1, count2, candidate1, candidate2 = 0, 0, None, None

    for num in nums:
        if candidate1 is not None and num == candidate1:
            count1 += 1
        elif candidate2 is not None and num == candidate2:
            count2 += 1
        elif count1 == 0:
            candidate1, count1 = num, 1
        elif count2 == 0:
            candidate2, count2 = num, 1
        else:
            count1 -= 1
            count2 -= 1

    result = []
    for c in (candidate1, candidate2):
        if c is not None and nums.count(c) > n // 3:
            result.append(c)

    return result

def generate_parentheses(n):
    """
    Generate all combinations of n pairs of valid parentheses.
    """
    def backtrack(s='', left=0, right=0):
        if len(s) == 2 * n:
            result.append(s)
            return
        if left < n:
            backtrack(s+'(', left+1, right)
        if right < left:
            backtrack(s+')', left, right+1)

    result = []
    backtrack()
    return result

