def count_palindromic_substrings(s):
    """
    Returns the total number of palindromic substrings in the given string s.
    """
    n = len(s)
    palindromes = [[False] * n for _ in range(n)]
    count = 0

    for i in range(n):
        palindromes[i][i] = True
        count += 1

    for i in range(n - 1):
        if s[i] == s[i + 1]:
            palindromes[i][i + 1] = True
            count += 1

    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and palindromes[i + 1][j - 1]:
                palindromes[i][j] = True
                count += 1

    return count

