def min_subset_difference(arr):
    """
    Returns the minimum difference between the sums of two partitions of the array.
    """
    n = len(arr)
    total_sum = sum(arr)
    target = total_sum // 2

    # Create a DP array to store subset sums
    dp = [[False] * (target + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if j >= arr[i-1]:
                dp[i][j] = dp[i-1][j] or dp[i-1][j-arr[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

    # Find the closest sum to target
    for j in range(target, -1, -1):
        if dp[n][j]:
            subset_sum = j
            break

    other_subset_sum = total_sum - subset_sum
    return abs(other_subset_sum - subset_sum)

