def minCutPalindrome(s):
    n = len(s)

    if n == 0:
        return 0

    dp = [0] * n
    palindrome = [[False] * n for _ in range(n)]

    for i in range(n):
        minCut = i
        for j in range(i+1):
            if s[j] == s[i] and (i-j <= 1 or palindrome[j+1][i-1]):
                palindrome[j][i] = True
                minCut = 0 if j == 0 else min(minCut, dp[j-1] + 1)
        dp[i] = minCut

    return dp[-1]

