from collections import deque
from typing import List, Tuple

def sliding_puzzle(board: List[List[int]]) -> int:
    target = ((1, 2, 3), (4, 5, 0))
    m, n = 2, 3

    def serialize(board: List[List[int]]) -> Tuple[Tuple[int, ...], Tuple[int, ...]]:
        return tuple(tuple(row) for row in board)

    def get_neighbors(state: Tuple[Tuple[int, ...], Tuple[int, ...]]) -> List[Tuple[Tuple[int, ...], Tuple[int, ...]]]:
        flat_board = [x for row in state for x in row]
        empty_index = flat_board.index(0)
        x, y = empty_index // n, empty_index % n 

        neighbors = []
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy 
            if 0 <= nx < m and 0 <= ny < n:
                new_board = list(flat_board)
                new_board[empty_index], new_board[nx * n + ny] = new_board[nx * n + ny], new_board[empty_index]
                new_board_2d = tuple(tuple(new_board[i*n:(i+1)*n]) for i in range(m))
                neighbors.append(new_board_2d)
        return neighbors

    initial_state = serialize(board)
    if initial_state == target:
        return 0

    queue = deque([(initial_state, 0)])
    seen = set()
    seen.add(initial_state)

    while queue:
        state, moves = queue.popleft()

        for neighbor in get_neighbors(state):
            if neighbor == target:
                return moves + 1
            if neighbor not in seen:
                seen.add(neighbor)
                queue.append((neighbor, moves + 1))

    return -1

def generate_unique_integers(n, k):
    """
    Generate an array of the first n integers such that each integer is unique and
    the absolute difference between each pair of consecutive integers is less than
    or equal to k. If such an array is not possible, return an empty array.

    :param n: Number of integers to generate.
    :param k: Maximum allowed absolute difference between consecutive integers.
    :return: List of integers meeting the criteria.
    """
    if n <= 0:
        return []

    result = []
    used = set()

    current = 1
    while len(result) < n:
        result.append(current)
        used.add(current)
        next_num = current + 1 if current < (n + k) else current - 1

        while next_num in used or abs(next_num - current) > k:
            if next_num in used: 
                next_num += 1

            if abs(next_num - current) > k:
                break

        if next_num in used or abs(next_num - current) > k:
            break

        current = next_num

    if len(result) == n:
        return result
    else:
        return []

