def count_peak_hours(log_line):
    counts = {}
    for token in log_line.split():
        if len(token) != 5 or token[2] != ':':
            continue
        hh, mm = token[:2], token[3:]
        if not (hh.isdigit() and mm.isdigit()):
            continue
        h = int(hh)
        m = int(mm)
        if 0 <= h <= 23 and 0 <= m <= 59:
            counts[h] = counts.get(h, 0) + 1
    if not counts:
        return -1
    best_hour = None
    best_count = -1
    for hour, count in counts.items():
        if count > best_count or (count == best_count and hour < best_hour):
            best_hour = hour
            best_count = count
    return best_hour

def sum_order_quantities(order_text):
    result = {}
    parts = order_text.split(';')
    for part in parts:
        item = part.strip()
        if not item:
            continue
        if item.count(':') != 1:
            continue
        name, qty_text = item.split(':')
        name = name.strip()
        qty_text = qty_text.strip()
        if not name:
            continue
        try:
            qty = int(qty_text)
        except ValueError:
            continue
        if qty < 0:
            continue
        result[name] = result.get(name, 0) + qty
    return dict(sorted(result.items()))

def factorial(n):
    """
    Calculate the factorial of a given number using recursion.

    The factorial of a non-negative integer n is the product of all positive integers less than or equal to n.
    Factorial of 0 is defined as 1. Factorial is undefined for negative numbers.

    Args:
    n (int): The number to calculate the factorial of.

    Returns:
    int or None: The factorial of the number if it is non-negative. If n is negative, returns None.
    """
    if n == 0:
        return 1
    elif n < 0:
        return None
    else:
        return n * factorial(n - 1)

def longestIncreasingSubsequence(nums):
    """
    Finds the longest increasing subsequence in a list of integers.

    :param nums: List[int] - A list of integers.
    :return: List[int] - The longest increasing subsequence.
    """
    if not nums:
        return []

    tails = []
    lis = []
    backtracking = [-1] * len(nums)

    for new_index, num in enumerate(nums):
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        if left == len(tails):
            tails.append(num)
            lis.append(num)
        else:
            tails[left] = num
            if left < len(lis) - 1:
                lis[left] = num

        if left != 0:
            backtracking[new_index] = tails[left - 1]

    result = []
    last_value = tails[-1]
    for i in range(len(nums) - 1, -1, -1):
        if nums[i] == last_value:
            result.append(nums[i])
            last_value = backtracking[i]
            if last_value == -1:
                break

    return result[::-1]

class Car:
    def __init__(self, make, model, year):
        """
        Initializes a new Car instance with the given make, model, and year.
        Odometer is set to 0 and the car is initially not running.
        """
        self.make = make
        self.model = model
        self.year = year
        self.odometer = 0  # in miles
        self.is_running = False

    def start(self):
        """
        Starts the car if it is not already running.
        """
        if not self.is_running:
            self.is_running = True
            print(f"The {self.year} {self.make} {self.model} is now running.")
        else:
            print(f"The {self.year} {self.make} {self.model} is already running.")

    def stop(self):
        """
        Stops the car if it is running.
        """
        if self.is_running:
            self.is_running = False
            print(f"The {self.year} {self.make} {self.model} has been stopped.")
        else:
            print(f"The {self.year} {self.make} {self.model} is already stopped.")

    def drive(self, distance):
        """
        Drives the car a specified distance if it is running and updates the odometer.
        The distance must be non-negative.
        """
        if self.is_running:
            if distance >= 0:
                self.odometer += distance
                print(f"The {self.year} {self.make} {self.model} drove {distance} miles. Total odometer reading is {self.odometer} miles.")
            else:
                print("You cannot drive a negative distance.")
        else:
            print("Start the car before driving.")

def factorial(n):
    """
    Calculate the factorial of a non-negative integer n using recursion.

    Parameters:
    n (int): Non-negative integer

    Returns:
    int: Factorial of n

    Raises:
    ValueError: If n is negative
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    elif n == 0:
        return 1
    else:
        return n * factorial(n - 1)

def swap_dict(input_dict):
    """
    Swaps the keys and values of a dictionary where each key maps to a list of values.
    If multiple keys have the same value, only the last key-value pair is retained.

    :param input_dict: Dictionary with string keys and list of integer values.
    :return: Dictionary with integer keys and string values.
    """
    result = {}
    for key, values in input_dict.items():
        for value in values:
            result[value] = key
    return result

