def find_max_difference(nums):
    """
    Computes the maximum difference between any two elements in the list,
    where the larger element comes after the smaller one in the list.

    Parameters:
    nums (list of int): The list of integers.

    Returns:
    tuple: A tuple containing the maximum difference and the pair of elements
           that produce this difference.
    """
    if len(nums) < 2:
        raise ValueError("List should contain at least two elements")

    min_num = float('inf')
    max_num = float('-inf')
    min_index = max_index = 0

    for index, num in enumerate(nums):
        if num < min_num:
            min_num = num
            min_index = index
        if num > max_num:
            max_num = num
            max_index = index

    if min_index < max_index:
        return max_num - min_num, (nums[min_index], nums[max_index])
    else:
        return max_num - min_num, (nums[max_index], nums[min_index])

def average_gpa(student_gpas):
    """
    Computes the average GPA for each student from a list of tuples.

    Parameters:
    student_gpas (list of tuples): A list where each tuple contains a student's name and their GPA.

    Returns:
    dict: A dictionary with student names as keys and their average GPA as values.
    """
    student_dict = {}

    for name, gpa in student_gpas:
        if name in student_dict:
            student_dict[name][0] += gpa
            student_dict[name][1] += 1
        else:
            student_dict[name] = [gpa, 1]

    average_gpa_dict = {name: total_gpa / count for name, (total_gpa, count) in student_dict.items()}

    return average_gpa_dict

