def classify_reviews(reviews):
    """
    Classifies each review in the list as 'positive', 'negative', or 'neutral'
    based on the presence of specific keywords.

    :param reviews: List of strings, where each string is a customer review.
    :return: List of strings, where each string is the sentiment classification
             of the corresponding review.
    """
    positive_keywords = {'good', 'great', 'excellent', 'amazing', 'love', 'fantastic', 'wonderful', 'positive', 'best'}
    negative_keywords = {'bad', 'terrible', 'poor', 'worst', 'disappointing', 'hate', 'negative', 'awful', 'worst'}

    def classify(review):
        words = set(review.lower().split())
        if positive_keywords.intersection(words):
            return "positive"
        elif negative_keywords.intersection(words):
            return "negative"
        else:
            return "neutral"

    return [classify(review) for review in reviews]

