def remove_duplicate_letters(s):
    """
    Removes duplicate letters from the given string and returns the resultant string.
    The letters in the final string are in the order they first appear in `s`.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

