def min_time_to_complete_tasks(tasks, k):
    # Helper function to check if a given time limit is feasible
    def is_feasible(time_limit):
        workers = 1
        current_time = 0

        for task in tasks:
            if current_time + task <= time_limit:
                current_time += task
            else:
                workers += 1
                if workers > k or task > time_limit:
                    return False
                current_time = task

        return True

    # Binary search for the minimal time required to complete all tasks
    left, right = max(tasks), sum(tasks)

    while left < right:
        mid = (left + right) // 2
        if is_feasible(mid):
            right = mid
        else:
            left = mid + 1

    return left

