def get_max_len(arr):
    """
    Returns the length of the longest subarray with a positive product.
    """
    max_len = 0
    pos_len = 0
    neg_len = 0

    for num in arr:
        if num == 0:
            pos_len = 0
            neg_len = 0
        elif num > 0:
            pos_len += 1
            if neg_len != 0:
                neg_len += 1
            else:
                neg_len = 0
        else:
            temp = pos_len
            if neg_len != 0:
                pos_len = neg_len + 1
            else:
                pos_len = 0
            neg_len = temp + 1

        max_len = max(max_len, pos_len)

    return max_len

