def is_feasible(books, k, max_pages):
    students_required = 1
    current_sum = 0

    for pages in books:
        if current_sum + pages > max_pages:
            students_required += 1
            current_sum = pages

            if students_required > k:
                return False
        else:
            current_sum += pages

    return True

def min_max_pages(books, k):
    if len(books) < k:
        return -1

    left, right = max(books), sum(books)
    result = right

    while left <= right:
        mid = (left + right) // 2

        if is_feasible(books, k, mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result

