from typing import List

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

def findWords(board: List[List[str]], words: List[str]) -> List[str]:
    def dfs(node, x, y, path, visited):
        if node.is_end_of_word:
            result.add(path)

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(board) and 0 <= ny < len(board[0]) and (nx, ny) not in visited:
                char = board[nx][ny]
                if char in node.children:
                    visited.add((nx, ny))
                    dfs(node.children[char], nx, ny, path + char, visited)
                    visited.remove((nx, ny))

    trie = Trie()
    for word in words:
        trie.insert(word)

    result = set()
    for i in range(len(board)):
        for j in range(len(board[0])):
            char = board[i][j]
            if char in trie.root.children:
                dfs(trie.root.children[char], i, j, char, {(i, j)})

    return sorted(list(result))

