def smallestWindow(s):
    if not s:
        return ""

    # All unique characters in the string
    unique_chars = set(s)
    unique_count = len(unique_chars)

    n = len(s)
    min_window = s
    min_length = n + 1

    left = 0
    char_count = {}

    for right in range(n):
        char_count[s[right]] = char_count.get(s[right], 0) + 1

        while len(char_count) == unique_count:
            if right - left + 1 < min_length:
                min_length = right - left + 1
                min_window = s[left:right + 1]

            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

    return min_window

def pacific_atlantic(matrix):
    if not matrix or not matrix[0]:
        return []

    rows, cols = len(matrix), len(matrix[0])

    def dfs(x, y, visited, prev_height):
        if (x, y) in visited or x < 0 or y < 0 or x >= rows or y >= cols or matrix[x][y] < prev_height:
            return
        visited.add((x, y))
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            dfs(x + dx, y + dy, visited, matrix[x][y])

    pacific_reachable = set()
    atlantic_reachable = set()

    for i in range(rows):
        dfs(i, 0, pacific_reachable, matrix[i][0])
        dfs(i, cols - 1, atlantic_reachable, matrix[i][cols - 1])

    for j in range(cols):
        dfs(0, j, pacific_reachable, matrix[0][j])
        dfs(rows - 1, j, atlantic_reachable, matrix[rows - 1][j])

    return list(pacific_reachable & atlantic_reachable)

