class MinStack:
    def __init__(self):
        """
        Initialize your data structure here.
        """
        self.stack = []
        self.min_stack = []

    def push(self, x: int) -> None:
        """
        Push element x onto stack.
        """
        self.stack.append(x)
        if not self.min_stack or x <= self.min_stack[-1]:
            self.min_stack.append(x)

    def pop(self) -> None:
        """
        Removes the element on top of the stack.
        """
        if self.stack:
            top = self.stack.pop()
            if top == self.min_stack[-1]:
                self.min_stack.pop()

    def top(self) -> int:
        """
        Get the top element.
        """
        if self.stack:
            return self.stack[-1]

    def getMin(self) -> int:
        """
        Retrieve the minimum element in the stack.
        """
        if self.min_stack:
            return self.min_stack[-1]

def max_treasures(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]

    dp[0][0] = grid[0][0]

    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[m-1][n-1]

def most_common_domain(emails):
    counts = {}
    for raw in emails.split(','):
        email = raw.strip()
        if email.count('@') != 1:
            continue
        local, domain = email.split('@')
        if not local or not domain:
            continue
        counts[domain] = counts.get(domain, 0) + 1
    if not counts:
        return ''
    best_domain = None
    best_count = -1
    for domain, count in counts.items():
        if count > best_count or (count == best_count and domain < best_domain):
            best_domain = domain
            best_count = count
    return best_domain

def max_subarray_with_k_distinct(orders, k):
    if k <= 0:
        return 0
    from collections import defaultdict
    count = defaultdict(int)
    left = 0
    best = 0
    distinct = 0
    for right, value in enumerate(orders):
        if count[value] == 0:
            distinct += 1
        count[value] += 1
        while distinct > k:
            lv = orders[left]
            count[lv] -= 1
            if count[lv] == 0:
                distinct -= 1
            left += 1
        if distinct == k:
            best = max(best, right - left + 1)
    return best

