class TemperatureConverter:
    def to_fahrenheit(self, temperature, scale):
        """
        Convert the given temperature to Fahrenheit.

        :param temperature: The temperature value to convert.
        :param scale: The current scale of the temperature ('celsius', 'fahrenheit', 'kelvin').
        :return: The temperature converted to Fahrenheit.
        :raises ValueError: If the scale is unknown.
        """
        if scale.lower() == 'celsius':
            return (temperature * 9/5) + 32
        elif scale.lower() == 'kelvin':
            return (temperature - 273.15) * 9/5 + 32
        elif scale.lower() == 'fahrenheit':
            return temperature
        else:
            raise ValueError("Unknown temperature scale")

    def to_celsius(self, temperature, scale):
        """
        Convert the given temperature to Celsius.

        :param temperature: The temperature value to convert.
        :param scale: The current scale of the temperature ('celsius', 'fahrenheit', 'kelvin').
        :return: The temperature converted to Celsius.
        :raises ValueError: If the scale is unknown.
        """
        if scale.lower() == 'fahrenheit':
            return (temperature - 32) * 5/9
        elif scale.lower() == 'kelvin':
            return temperature - 273.15
        elif scale.lower() == 'celsius':
            return temperature
        else:
            raise ValueError("Unknown temperature scale")

    def to_kelvin(self, temperature, scale):
        """
        Convert the given temperature to Kelvin.

        :param temperature: The temperature value to convert.
        :param scale: The current scale of the temperature ('celsius', 'fahrenheit', 'kelvin').
        :return: The temperature converted to Kelvin.
        :raises ValueError: If the scale is unknown.
        """
        if scale.lower() == 'celsius':
            return temperature + 273.15
        elif scale.lower() == 'fahrenheit':
            return (temperature - 32) * 5/9 + 273.15
        elif scale.lower() == 'kelvin':
            return temperature
        else:
            raise ValueError("Unknown temperature scale")

def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def filter_primes(numbers):
    """Filter and return a list of prime numbers from the input list."""
    return [num for num in numbers if is_prime(num)]

