import re

def parse_expr(input_expr):
    """
    Parses an arithmetic expression string into an abstract syntax tree (AST).

    :param input_expr: A string representing an arithmetic expression.
    :return: A nested dictionary representing the AST of the expression.
    """
    def tokenize(expr):
        """
        Tokenizes the input expression string.

        :param expr: A string representing an arithmetic expression.
        :return: A list of tokens.
        """
        expr = expr.replace(" ", "")
        return re.findall(r'\(|\)|\+|\-|\*|\/|\d+|[a-zA-Z_]\w*', expr)

    def parse(tokens):
        """
        Parses a list of tokens into an AST.

        :param tokens: A list of tokens.
        :return: A nested dictionary representing the AST.
        """
        def parse_expr():
            token = tokens.pop(0)
            if token == '(':
                left = parse_expr()
                op = tokens.pop(0)
                right = parse_expr()
                tokens.pop(0)  # Remove the closing parenthesis
                return {'op': op, 'left': left, 'right': right}
            elif token.isdigit():
                return {'val': int(token)}
            else:
                return {'val': token}

        return parse_expr()

    return parse(tokenize(input_expr))

