class Stack:
    def __init__(self):
        self.stack = []
        self.min_stack = []

    def push(self, x):
        """Push element x onto stack."""
        self.stack.append(x)
        if not self.min_stack or x <= self.min_stack[-1]:
            self.min_stack.append(x)

    def pop(self):
        """Removes the element on top of the stack."""
        if self.stack:
            top = self.stack.pop()
            if top == self.min_stack[-1]:
                self.min_stack.pop()

    def top(self):
        """Get the top element."""
        if self.stack:
            return self.stack[-1]
        return None

    def is_empty(self):
        """Returns whether the stack is empty."""
        return len(self.stack) == 0

    def get_min(self):
        """Retrieve the minimum element in the stack."""
        if self.min_stack:
            return self.min_stack[-1]
        return None

def find_duplicates(input_list):
    """
    Identifies and returns a list of integers that appear more than once in the input list.

    :param input_list: List of integers
    :return: List of integers that appear more than once
    """
    count_dict = {}
    duplicates = []

    for num in input_list:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    for num, count in count_dict.items():
        if count > 1:
            duplicates.append(num)

    return duplicates

