def longest_zigzag_subsequence(nums):
    """
    Returns the length of the longest zigzag subsequence in nums.
    A subsequence is called zigzag if the differences between consecutive 
    elements are strictly alternating between positive and negative.

    :param nums: List[int], the input list of integers
    :return: int, length of the longest zigzag subsequence
    """
    if not nums:
        return 0

    n = len(nums)
    if n == 1:
        return 1

    up = [1] * n
    down = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                up[i] = max(up[i], down[j] + 1)
            elif nums[i] < nums[j]:
                down[i] = max(down[i], up[j] + 1)

    return max(max(up), max(down))

def valid_palindrome(s):
    """
    Returns whether it is possible to make the string a palindrome after removing at most one character.

    :param s: str - input string containing only lowercase alphabetic characters.
    :return: bool - True if the string can be made palindrome by removing at most one character, otherwise False.
    """
    def is_palindrome(s, left, right):
        """ Helper function to check if the substring s[left:right+1] is a palindrome """
        while left < right:
            if s[left] != s[right]:
                return False
            left += 1
            right -= 1
        return True

    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            # Check by removing one character from either side
            return is_palindrome(s, left + 1, right) or is_palindrome(s, left, right - 1)
        left += 1
        right -= 1

    return True

