def min_deletions_to_make_palindrome(s):
    """
    Returns the minimum number of deletions required to make the string `s` a palindrome.
    """
    def longest_palindromic_subsequence(s):
        n = len(s)
        dp = [[0] * (n + 1) for _ in range(n + 1)]

        for i in range(n):
            for j in range(n):
                if s[i] == s[n - j - 1]:
                    dp[i + 1][j + 1] = dp[i][j] + 1
                else:
                    dp[i + 1][j + 1] = max(dp[i][j + 1], dp[i + 1][j])
        return dp[n][n]

    lps_length = longest_palindromic_subsequence(s)
    return len(s) - lps_length

