def find_peak_element(arr):
    """
    Returns the index of any one peak element in the array.
    If no peak element exists, returns -1.
    """
    n = len(arr)

    if n == 0:
        return -1
    if n == 1:
        return 0

    # Check the first element
    if arr[0] > arr[1]:
        return 0

    # Check the last element
    if arr[n - 1] > arr[n - 2]:
        return n - 1

    # Check the rest of the array
    for i in range(1, n - 1):
        if arr[i] > arr[i - 1] and arr[i] > arr[i + 1]:
            return i

    return -1

