from typing import List

def min_containers(weights: List[int], maxLoad: int) -> int:
    weights.sort(reverse=True)
    containers = []

    for w in weights:
        placed = False
        for i in range(len(containers)):
            if containers[i] + w <= maxLoad:
                containers[i] += w
                placed = True
                break
        if not placed:
            containers.append(w)

    return len(containers)

class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def longest_consecutive_path(root):
    def dfs(node, parent_value, length):
        if not node:
            return length
        current_length = length + 1 if parent_value + 1 == node.value else 1
        left_length = dfs(node.left, node.value, current_length)
        right_length = dfs(node.right, node.value, current_length)
        return max(current_length, left_length, right_length)

    return dfs(root, root.value - 1, 0) if root else 0

