def minimize_max_cookies(nums, k):
    """
    This function distributes the cookies such that the maximum number of cookies
    any child gets is minimized.
    """
    def canDistributeWithMaxSum(max_sum):
        current_sum, parts = 0, 1
        for num in nums:
            if current_sum + num > max_sum:
                parts += 1
                current_sum = num
                if parts > k:
                    return False
            else:
                current_sum += num
        return True

    left, right = max(nums), sum(nums)

    while left < right:
        mid = (left + right) // 2
        if canDistributeWithMaxSum(mid):
            right = mid
        else:
            left = mid + 1

    return left

