import bisect

def max_sum_submatrix(mat, k):
    def max_sum_no_larger_than_k(nums, k):
        max_sum = float('-inf')
        sum_so_far = 0
        sorted_prefix_sums = [0]
        for num in nums:
            sum_so_far += num
            idx = bisect.bisect_left(sorted_prefix_sums, sum_so_far - k)
            if idx < len(sorted_prefix_sums):
                max_sum = max(max_sum, sum_so_far - sorted_prefix_sums[idx])
            bisect.insort(sorted_prefix_sums, sum_so_far)
        return max_sum

    m, n = len(mat), len(mat[0])
    max_sum = float('-inf')
    for left in range(n):
        row_sums = [0] * m
        for right in range(left, n):
            for i in range(m):
                row_sums[i] += mat[i][right]
            max_sum = max(max_sum, max_sum_no_larger_than_k(row_sums, k))
    return max_sum

