def can_students_sit_comfortably(arr, space, n):
    positions = sorted(zip(arr, space))

    for i in range(len(positions)):
        seat, required_space = positions[i]
        # Checking the space on the left side
        if i == 0:
            left_boundary = 0
        else:
            left_boundary = positions[i-1][0] + positions[i-1][1] + 1
        left_space = seat - left_boundary

        if left_space < required_space:
            return False

        # Checking the space on the right side
        if i == len(positions) - 1:
            right_boundary = n - 1
        else:
            right_boundary = positions[i+1][0] - positions[i+1][1] - 1
        right_space = right_boundary - seat

        if right_space < required_space:
            return False

    return True

