def longest_arith_seq_length(arr):
    if len(arr) <= 1:
        return len(arr)

    dp = [{} for _ in range(len(arr))]
    max_length = 2

    for i in range(1, len(arr)):
        for j in range(i):
            diff = arr[i] - arr[j]
            if diff in dp[j]:
                dp[i][diff] = dp[j][diff] + 1
            else:
                dp[i][diff] = 2
            max_length = max(max_length, dp[i][diff])

    return max_length

