def min_moves_with_positive_slope(points):
    """
    Returns the minimum number of moves required to move from the first point to the last point in the array,
    visiting each point in the order given with only positive slope allowed.
    """
    n = len(points)
    moves = 0
    for i in range(n - 1):
        if points[i+1][0] > points[i][0] and points[i+1][1] > points[i][1]:
            moves += 1
        else:
            return -1
    return moves

