from collections import defaultdict

def can_split_into_two_increasing_subsequences(nums):
    """
    Returns True if nums can be split into two strictly increasing subsequences, else False.
    """
    # Dictionary to store frequency of each number
    frequency = defaultdict(int)
    for num in nums:
        frequency[num] += 1

    tails = []  # List to store end elements of increasing subsequences
    for num in nums:
        # Add new subsequence or extend if possible
        found = False
        for i in range(len(tails)):
            if tails[i] < num:
                tails[i] = num
                found = True
                break
        if not found:
            tails.append(num)
        if len(tails) > 2:
            return False
    return True

def rearrange_heights(heights):
    """
    Rearranges the list of heights such that no two adjacent heights differ by 1 or less.
    Returns an empty list if such an arrangement is not possible.
    """
    heights.sort()

    n = len(heights)
    if n < 2:
        return heights

    for i in range(1, n):
        if heights[i] - heights[i-1] <= 1:
            break
    else:
        return heights

    left, right = heights[:n // 2], heights[n // 2:]
    rearranged = []

    for r, l in zip(right, left):
        rearranged.append(r)
        rearranged.append(l)

    if n % 2 == 1:
        rearranged.append(right[-1])

    for i in range(1, len(rearranged)):
        if abs(rearranged[i] - rearranged[i-1]) <= 1:
            return []

    return rearranged

