def min_swaps_to_transform(s1, s2):
    """
    Returns the minimum number of adjacent swaps required to transform s1 into s2.
    If it is impossible to do so, return -1.
    """
    def count_frequency(s):
        # Helper function to count frequency of each character in a string
        freq = {}
        for char in s:
            if char in freq:
                freq[char] += 1
            else:
                freq[char] = 1
        return freq

    # Check if transformation is possible by comparing character frequencies
    if count_frequency(s1) != count_frequency(s2):
        return -1

    # Convert s1 to a list to perform swaps
    s1 = list(s1)
    swaps = 0

    for i in range(len(s1)):
        # When s1[i] != s2[i], we need to swap s1[i] with the next correct character
        if s1[i] != s2[i]:
            j = i
            while s1[j] != s2[i]:
                j += 1
            # Perform adjacent swaps to bring s2[i] to position i
            while j > i:
                s1[j], s1[j - 1] = s1[j - 1], s1[j]
                swaps += 1
                j -= 1
    return swaps

