class Matrix:
    def __init__(self, data):
        """
        Initializes a Matrix instance with a 2D list.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def add(self, other):
        """
        Adds two matrices of the same dimensions and returns a new Matrix instance with the result.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for addition")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtracts one matrix from another of the same dimensions and returns a new Matrix instance with the result.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for subtraction")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiplies two matrices where the number of columns in the first matrix is equal to the number of rows in the second matrix,
        and returns a new Matrix instance with the result.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns of first matrix must be equal to number of rows of second matrix")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def transpose(self):
        """
        Returns a new Matrix instance that is the transpose of the original matrix.
        """
        result = [
            [self.data[i][j] for i in range(self.rows)]
            for j in range(self.cols)
        ]
        return Matrix(result)

    def print_matrix(self):
        """
        Prints the matrix in a readable format.
        """
        for row in self.data:
            print(" ".join(map(str, row)))

from typing import List

def generate_prime_numbers(limit: int) -> List[int]:
    """
    Generate a list of prime numbers up to a given limit.

    :param limit: An integer representing the upper bound for prime number generation.
    :return: A list of prime numbers from 2 up to and including the limit.
    """
    def is_prime(n: int) -> bool:
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = []
    for num in range(2, limit + 1):
        if is_prime(num):
            primes.append(num)

    return primes

def character_frequency(s):
    """
    Calculate the frequency of each alphabetic character in the string, ignoring case and non-alphabetic characters.

    :param s: Input string containing alphabetic characters, digits, punctuation, and whitespace.
    :return: Dictionary with keys as lowercase alphabetic characters and values as their frequencies.
    """
    frequency = {}
    s = s.lower()

    for char in s:
        if char.isalpha():
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1

    return frequency

