def filter_primes(numbers):
    """
    Filter a list of numbers, returning a new list containing only the prime numbers.

    :param numbers: List of numbers to be filtered.
    :return: List of prime numbers from the input list.
    :raises ValueError: If the input list contains non-numeric values.
    """

    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = []
    for num in numbers:
        if not isinstance(num, (int, float)):
            raise ValueError(f"Non-numeric value found in the list: {num}")
        if is_prime(num):
            primes.append(num)

    return primes

