def levenshtein_distance(s1, s2):
    """
    Computes the Levenshtein distance between two strings.

    :param s1: First string
    :param s2: Second string
    :return: Levenshtein distance as an integer
    """
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)

    if len(s2) == 0:
        return len(s1)

    previous_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        current_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = previous_row[j + 1] + 1
            deletions = current_row[j] + 1
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row

    return previous_row[-1]

def string_similarity(s1, s2):
    """
    Computes the similarity score between two strings based on the Levenshtein distance.

    :param s1: First string
    :param s2: Second string
    :return: Similarity score as a float between 0 and 1
    """
    if not s1 and not s2:
        return 1.0
    lev_distance = levenshtein_distance(s1, s2)
    return 1 - lev_distance / max(len(s1), len(s2))

