def min_partitions(s):
    """
    Returns the minimum number of parts the string 's' can be partitioned into,
    such that each part contains at least one of each character 'a', 'b', and 'c'.
    """
    n = len(s)
    if n < 3:
        return 0

    a_count = b_count = c_count = 0
    partitions = 0

    for char in s:
