def find_peak_mountain_array(arr):
    """
    This function returns the peak element in the mountain array.
    If no valid mountain array structure is present, it returns -1.
    """
    if len(arr) < 3:
        return -1

    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        if arr[mid] < arr[mid + 1]:
            left = mid + 1
        else:
            right = mid

    # Verify that the array is a valid mountain array
    if left == 0 or left == len(arr) - 1:
        return -1

    return arr[left]

