def min_path_sum(matrix):
    """
    Return the minimum cost to reach from the top-left corner to the bottom-right corner of the matrix.
    You can only move right or down at each step.
    """
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])

    for i in range(1, m):
        matrix[i][0] += matrix[i-1][0]  # Fill in the first column by adding the cell above

    for j in range(1, n):
        matrix[0][j] += matrix[0][j-1]  # Fill in the first row by adding the cell to the left

    for i in range(1, m):
        for j in range(1, n):
            matrix[i][j] += min(matrix[i-1][j], matrix[i][j-1])  # Choose the minimum path sum from the top or from the left

    return matrix[-1][-1]  # The bottom-right corner will contain the minimum path sum

