def evaluate_expression(expression):
    """
    Evaluates a valid mathematical expression and returns the result as an integer.
    Division should truncate toward zero.
    """
    def operate(operand1, operand2, operator):
        if operator == '+':
            return operand1 + operand2
        elif operator == '-':
            return operand1 - operand2
        elif operator == '*':
            return operand1 * operand2
        elif operator == '/':
            return int(operand1 / operand2)  # Truncate toward zero

    current_number = 0
    result = 0
    last_operator = '+'
    stack = []

    for i, char in enumerate(expression):
        if char.isdigit():
            current_number = current_number * 10 + int(char)
        if char in '+-*/' or i == len(expression) - 1:
            if last_operator in '+-':
                if last_operator == '+':
                    stack.append(current_number)
                else:
                    stack.append(-current_number)
            elif last_operator in '*/':
                if last_operator == '*':
                    stack.append(stack.pop() * current_number)
                else:
                    stack.append(int(stack.pop() / current_number))
            current_number = 0
            last_operator = char

    return sum(stack)

