def maxProfit(k, prices):
    if not prices or k == 0:
        return 0

    n = len(prices)

    # If k >= n // 2, then we can complete as many transactions as we want.
    if k >= n // 2:
        return sum(max(prices[i + 1] - prices[i], 0) for i in range(n - 1))

    # dp[i][j] represents the maximum profit up to day i with at most j transactions.
    dp = [[0] * (k + 1) for _ in range(n)]

    for j in range(1, k + 1):
        max_diff = -prices[0]
        for i in range(1, n):
            dp[i][j] = max(dp[i - 1][j], prices[i] + max_diff)
            max_diff = max(max_diff, dp[i][j - 1] - prices[i])

    return dp[-1][-1]

def longestIncreasingPath(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    memo = [[-1] * n for _ in range(m)]

    def dfs(x, y):
        if memo[x][y] != -1:
            return memo[x][y]

        longest = 1
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] > grid[x][y]:
                longest = max(longest, 1 + dfs(nx, ny))

        memo[x][y] = longest
        return longest

    max_path = 0
    for i in range(m):
        for j in range(n):
            max_path = max(max_path, dfs(i, j))

    return max_path

