def min_changes_to_anagram(s1, s2):
    from collections import Counter

    # Count frequency of each character in s1 and s2
    count_s1 = Counter(s1)
    count_s2 = Counter(s2)

    # Calculate the number of changes for each character
    changes = 0
    for char in count_s1:
        if char in count_s2:
            # Calculate the difference in counts for characters present in both strings
            changes += abs(count_s1[char] - count_s2[char])
        else:
            # All characters in s1 that are not in s2 must be changed
            changes += count_s1[char]

    for char in count_s2:
        if char not in count_s1:
            # All characters in s2 that are not in s1 must be added to changes
            changes += count_s2[char]

    # Since each change may have been counted twice, halve the final count
    return changes // 2

