def distinct_substrings_in_concatenated_string(p):
    """
    Returns the number of distinct non-empty substrings of `p` that 
    can be found at least once in an infinitely concatenated string of `p`.
    """
    n = len(p)
    substrings = set()

    for i in range(n):
        for j in range(i + 1, n + 1):
            substrings.add(p[i:j])

    return len(substrings)

