def nextClosestTime(time):
    """
    Given a string time in the format "HH:MM", returns the next closest time 
    that can be formed by reusing the current digits of time.
    """
    # Extract digits from the given time string
    digits = {int(x) for x in time if x != ':'}
    current_minutes = int(time[:2]) * 60 + int(time[3:])

    while True:
        current_minutes = (current_minutes + 1) % (24 * 60)
        next_time = f'{current_minutes // 60:02}:{current_minutes % 60:02}'
        if all(int(c) in digits for c in next_time if c != ':'):
            return next_time

