from collections import Counter
from typing import List

def findAnagrams(s: str, p: str) -> List[int]:
    """
    Finds all start indices of p's anagrams in s and returns them as a list in ascending order.
    """
    len_s, len_p = len(s), len(p)
    result = []
    if len_p > len_s:
        return result

    p_count = Counter(p)
    s_count = Counter()

    for i in range(len_s):
        s_count[s[i]] += 1  # add current char to the window

        if i >= len_p:
            if s_count[s[i - len_p]] == 1:
                del s_count[s[i - len_p]]  # remove char at the beginning as it slides out of the window
            else:
                s_count[s[i - len_p]] -= 1  # decrement count of the char as it slides

        if s_count == p_count:
            result.append(i - len_p + 1)

    return result

