def count_divisible_pairs(arr, k):
    """
    Returns the count of distinct pairs (i, j) where i < j such that arr[i] + arr[j] is divisible by k.
    """
    count = 0
    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n):
            if (arr[i] + arr[j]) % k == 0:
                count += 1
    return count

def num_islands(grid):
    """
    Returns the number of distinct islands in the given 2D grid.
    """
    if not grid:
        return 0

    def dfs(x, y):
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] == 0:
            return
        grid[x][y] = 0  # mark as visited
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            dfs(nx, ny)

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    islands = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                islands += 1
                dfs(i, j)
    return islands

