def remove_duplicate_letters(s):
    """
    Returns the lexicographically smallest string that can be obtained 
    by removing duplicate letters from the input string.
    """
    counter = {char: 0 for char in set(s)}
    for char in s:
        counter[char] += 1

    stack = []
    seen = set()

    for char in s:
        if char in seen:
            counter[char] -= 1
            continue

        while stack and char < stack[-1] and counter[stack[-1]] > 0:
            seen.remove(stack.pop())

        stack.append(char)
        seen.add(char)
        counter[char] -= 1

    return ''.join(stack)

