def unobstructed_view_buildings(arr, v):
    """
    Returns the number of buildings that have an unobstructed view from the left
    within the given distance v.
    """
    count = 0
    for i in range(len(arr)):
        has_view = True
        for j in range(1, v + 1):
            if i - j >= 0 and arr[i - j] >= arr[i]:
                has_view = False
                break
        if has_view:
            count += 1
    return count

