def can_frog_reach_last_stone(stones, k):
    """
    Determines if the frog can reach the last stone given the jumping constraint k.

    :param stones: List[int] - List of stone weights.
    :param k: int - Maximum allowed absolute difference in weight for a jump.
    :return: bool - True if the frog can reach the last stone, False otherwise.
    """
    n = len(stones)
    if n == 1:
        return True

    reachable = [False] * n
    reachable[0] = True

    for i in range(n):
        if reachable[i]:
            for j in range(i + 1, n):
                if abs(stones[j] - stones[i]) <= k:
                    reachable[j] = True
                    if j == n - 1:
                        return True
                else:
                    break
    return reachable[-1]

