def find_longest_increasing_subsequence(numbers):
    """
    Finds the longest increasing subsequence in the given list of integers.

    :param numbers: List of integers.
    :return: List of integers representing the longest increasing subsequence.
    """
    if not numbers:
        return []

    tails = [0] * len(numbers)
    size = 0

    for number in numbers:
        left, right = 0, size
        while left != right:
            mid = (left + right) // 2
            if tails[mid] < number:
                left = mid + 1
            else:
                right = mid

        tails[left] = number
        if left == size:
            size += 1

    longest_increasing_subsequence = []
    current_value = tails[size - 1]
    for i in reversed(range(len(numbers))):
        if numbers[i] == current_value:
            longest_increasing_subsequence.append(numbers[i])
            if size > 1:
                current_value = tails[size - 2]
            size -= 1
        if size == 0:
            break

    return list(reversed(longest_increasing_subsequence))

def fibonacci(n, memo=None):
    """
    Calculate the nth Fibonacci number using memoization to optimize time complexity.

    :param n: The position in the Fibonacci sequence (0-indexed).
    :param memo: A dictionary to store previously computed Fibonacci numbers.
    :return: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    return memo[n]

