def find_kth_smallest(root, k):
    """
    Returns the k-th smallest element in a binary search tree (BST).

    :param root: TreeNode, the root of the BST.
    :param k: int, the order of the smallest element to find.
    :return: int, the k-th smallest element in the BST.
    """
    def inorder(node):
        if node is None:
            return []
        return inorder(node.left) + [node.val] + inorder(node.right)

    inorder_list = inorder(root)
    return inorder_list[k - 1]

