def remove_duplicates(s):
    """
    Removes adjacent duplicates in the string until no adjacent duplicates remain.
    """
    stack = []
    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)
    return ''.join(stack)

