def shortest_valid_substring(s):
    n = len(s)
    min_length = float('inf')

    for left in range(n):
        count = {'a': 0, 'b': 0, 'c': 0}
        for right in range(left, n):
            if s[right] in count:
                count[s[right]] += 1
            if count['a'] == count['b'] == count['c'] and count['a'] > 0:
                min_length = min(min_length, right - left + 1)

    return min_length if min_length != float('inf') else -1

