def can_be_non_decreasing_by_removing_one(arr):
    """
    Given an array of integers `arr`, determines if it is possible to make the array
    non-decreasing by removing exactly one integer.
    """
    def is_non_decreasing(a):
        return all(x <= y for x, y in zip(a, a[1:]))

    n = len(arr)
    for i in range(n):
        if is_non_decreasing(arr[:i] + arr[i+1:]):
            return True
    return False

