def min_moves_to_equal_elements(heights):
    """
    Function to determine the minimum number of moves required to make all elements
    of the array equal by incrementing or decrementing any element by 1.
    """
    if not heights:
        return 0

    median = sorted(heights)[len(heights)//2]
    return sum(abs(h - median) for h in heights)

from collections import deque

def shortest_distance_to_land(grid):
    """
    Returns the shortest distance from any building to the nearest land.
    If there is no land, returns -1.
    """
    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def bfs(start):
        queue = deque([start])
        visited = [[False] * n for _ in range(n)]
        visited[start[0]][start[1]] = True
        distance = 0

        while queue:
            level_size = len(queue)
            distance += 1

            for _ in range(level_size):
                r, c = queue.popleft()
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc]:
                        if grid[nr][nc] == 1:
                            return distance
                        if grid[nr][nc] == 0:
                            queue.append((nr, nc))
                            visited[nr][nc] = True
        return -1

    shortest = float('inf')
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 2:
                dist = bfs((r, c))
                if dist != -1:
                    shortest = min(shortest, dist)

    return shortest if shortest != float('inf') else -1

