def min_deletions_to_transform(s, t):
    m, n = len(s), len(t)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_len = dp[m][n]

    if lcs_len != n:
        return -1
    return m - n

def min_path_sum(matrix):
    """
    Returns the minimum sum of a path from the top-left corner to the bottom-right corner,
    moving only down or right. If it's impossible to have a path that ends with a positive 
    value in the bottom-right cell, return -1.
    """
    if not matrix or not matrix[0] or matrix[-1][-1] <= 0:
        return -1

    m, n = len(matrix), len(matrix[0])
    dp = [[float('inf')] * n for _ in range(m)]
    dp[0][0] = matrix[0][0]

    for i in range(m):
        for j in range(n):
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + matrix[i][j])
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + matrix[i][j])

    result = dp[-1][-1]
    return result if result > 0 else -1

def islandPerimeter(grid):
    """
    Computes and returns the perimeter of the island in the grid.

    :param grid: List[List[int]] - 2D array representing the grid.
    :return: int - The perimeter of the island.
    """
    rows, cols = len(grid), len(grid[0])
    perimeter = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                # Set perimeter to 4 for this land (1)
                perimeter += 4
                # Check the top cell
                if r > 0 and grid[r-1][c] == 1:
                    perimeter -= 2
                # Check the left cell
                if c > 0 and grid[r][c-1] == 1:
                    perimeter -= 2

    return perimeter

