def calculate(s):
    """
    This function evaluates a basic arithmetic expression string `s` that may contain
    non-negative integers, '+', '-', '*', '/', and empty spaces. The function respects
    standard operator precedence and integer division truncates toward zero.

    :param s: String containing the arithmetic expression
    :return: Evaluated integer result of the expression
    """
    def operate(op, b, a):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return int(a / b)  # Ensure truncation towards zero

    num = 0  # Current number being processed
    stack = []  # Stack to keep numbers and intermediate results
    sign = '+'  # Previous operation
    s = s.replace(' ', '')  # Remove spaces

    for i, char in enumerate(s):
        if char.isdigit():
            num = num * 10 + int(char)
        if char in '+-*/' or i == len(s) - 1:
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign in '*/':
                top = stack.pop()
                stack.append(operate(sign, num, top))
            sign = char
            num = 0

    return sum(stack)

