def longest_bitonic_subsequence(nums):
    if not nums:
        return 0

    n = len(nums)

    # Increasing subsequence length ending at each index
    increase_seq = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                increase_seq[i] = max(increase_seq[i], increase_seq[j] + 1)

    # Decreasing subsequence length starting from each index
    decrease_seq = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if nums[i] > nums[j]:
                decrease_seq[i] = max(decrease_seq[i], decrease_seq[j] + 1)

    # Combine the results of increasing and decreasing subsequences
    max_length = 0
    for i in range(n):
        max_length = max(max_length, increase_seq[i] + decrease_seq[i] - 1)

    return max_length

