from collections import Counter

def min_swaps_to_equal(s1, s2):
    """
    Check if s1 can be converted to s2 by swapping characters and determine the minimum number
    of swaps required. If not possible, return -1.
    """

    if len(s1) != len(s2):
        return -1

    if Counter(s1) != Counter(s2):
        return -1

    # Character frequency match, proceed with Minimum Swaps calculation
    swaps = 0
    s1_list = list(s1)

    for i in range(len(s1)):
        if s1_list[i] != s2[i]:
            # Find correct character from the remaining part of the list
            for j in range(i + 1, len(s1)):
                if s1_list[j] == s2[i]:
                    s1_list[i], s1_list[j] = s1_list[j], s1_list[i]
                    swaps += 1
                    break

    return swaps

