def count_vowel_substrings(s, k):
    """
    Returns the number of substrings of length k that contain at least one vowel.
    """
    if k > len(s):
        return 0

    vowels = set("aeiou")
    count = 0

    for i in range(len(s) - k + 1):
        substring = s[i:i+k]
        if any(char in vowels for char in substring):
            count += 1

    return count

def count_visible_chars(s):
    depth = 0
    count = 0
    for ch in s:
        if ch in '([{':
            depth += 1
        elif ch in ')]}':
            depth -= 1
        else:
            if depth == 0:
                count += 1
    return count

def count_alternating_codes(n):
    if n <= 0:
        return 0
    return 2

def count_stack_ways(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 1, 2
    if n == 2:
        return 2
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b

