def longest_concatenated_word(words):
    def can_form(word, word_set):
        if word in memo:
            return memo[word]
        for i in range(1, len(word)):
            prefix = word[:i]
            suffix = word[i:]
            if prefix in word_set and (suffix in word_set or can_form(suffix, word_set)):
                memo[word] = True
                return True
        memo[word] = False
        return False

    words = set(words)
    longest = 0
    memo = {}

    for word in words:
        if can_form(word, words):
            longest = max(longest, len(word))

    return longest

