def longest_palindromic_subarray_length(arr):
    from collections import Counter

    def can_form_palindrome(counter):
        odd_count = sum(1 for x in counter.values() if x % 2 != 0)
        return odd_count <= 1

    def subarray_length(start, end):
        subarray = arr[start:end+1]
        counter = Counter(subarray)
        if can_form_palindrome(counter):
            return end - start + 1
        return 0

    max_length = 0
    n = len(arr)
    for i in range(n):
        for j in range(i, n):
            max_length = max(max_length, subarray_length(i, j))

    return max_length

