def split_string_into_k_parts(s, k):
    if len(s) < k:
        return -1  # Not possible to split into more parts than the length of the string

    def can_split_with_max_len(max_len):
        parts, current_part_len = 1, 0

        for char in s:
            if current_part_len + 1 > max_len:
                parts += 1
                current_part_len = 0
                if parts > k:
                    return False
            current_part_len += 1

        return True

    low, high = 1, len(s)
    while low < high:
        mid = (low + high) // 2
        if can_split_with_max_len(mid):
            high = mid
        else:
            low = mid + 1

    return low

