def canPartitionKSubsets(arr, k):
    def can_partition(start, k, current_sum, subset_sum, used):
        if k == 0:
            return True
        if current_sum == subset_sum:
            return can_partition(0, k - 1, 0, subset_sum, used)
        for i in range(start, len(arr)):
            if not used[i] and current_sum + arr[i] <= subset_sum:
                used[i] = True
                if can_partition(i + 1, k, current_sum + arr[i], subset_sum, used):
                    return True
                used[i] = False
        return False

    total_sum = sum(arr)
    if total_sum % k != 0:
        return False
    subset_sum = total_sum // k
    used = [False] * len(arr)
    arr.sort(reverse=True)  # optimization step to try larger numbers first
    return can_partition(0, k, 0, subset_sum, used)

def is_balanced_parentheses(expression):
    """
    Determines if the parentheses in the given expression are balanced.

    :param expression: A string containing various characters, including parentheses.
    :return: True if the parentheses are balanced, False otherwise.
    """
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def islandPerimeter(grid):
    """
    Calculates the perimeter of the island in the grid.
    """
    rows = len(grid)
    cols = len(grid[0])
    perimeter = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                perimeter += 4  # start with 4 sides per land cell

                # check for adjacent land cells to subtract shared borders
                if r > 0 and grid[r-1][c] == 1:
                    perimeter -= 2  # subtract 2 for shared border with upper cell
                if c > 0 and grid[r][c-1] == 1:
                    perimeter -= 2  # subtract 2 for shared border with left cell

    return perimeter

def is_balanced(s):
    """
    Determines if the string of brackets is balanced.

    Args:
    s (str): The string of brackets to be checked.

    Returns:
    bool: True if the string is balanced, False otherwise.
    """
    stack = []
    bracket_pairs = {
        ')': '(',
        '}': '{',
        ']': '['
    }

    for char in s:
        if char in bracket_pairs.values():
            stack.append(char)
        elif char in bracket_pairs.keys():
            if stack == [] or stack.pop() != bracket_pairs[char]:
                return False
        else:
            return False

    return stack == []

