def calculate(s: str) -> int:
    """
    Evaluate the arithmetic expression given in string form and return the result as an integer.
    """
    s = s.replace(' ', '')
    def evaluate(tokens):
        stack = []
        num = 0
        sign = '+'
        for i, token in enumerate(tokens):
            if token.isdigit():
                num = num * 10 + int(token)
            if token in '+-*/' or i == len(tokens) - 1:
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack.append(stack.pop() * num)
                elif sign == '/':
                    stack.append(int(stack.pop() / num))  # use int() to truncate toward zero
                sign = token
                num = 0
        return sum(stack)

    return evaluate(s)

