from heapq import heappush, heappop

def trapRainWater(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    heap = []

    # Push all the boundary cells into the heap and mark them as visited
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m-1 or j == 0 or j == n-1:
                heappush(heap, (grid[i][j], i, j))
                visited[i][j] = True

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    water_trapped = 0

    while heap:
        current_height, x, y = heappop(heap)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                water_trapped += max(0, current_height - grid[nx][ny])
                heappush(heap, (max(current_height, grid[nx][ny]), nx, ny))
                visited[nx][ny] = True

    return water_trapped

