def shortestUniqueSubsequence(s):
    """
    Returns the shortest unique subsequence of s with each character appearing exactly once
    while preserving the relative order of characters in s.
    """
    seen = set()
    result = []

    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)

    return ''.join(result)

def flatten_dict(d, parent_key='', sep='_'):
    """
    Recursively flattens a nested dictionary into a single-level dictionary.

    Parameters:
    d (dict): The dictionary to flatten.
    parent_key (str): The base key string for recursion (used internally).
    sep (str): The separator to use between keys.

    Returns:
    dict: A flattened dictionary with concatenated keys.
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

