from collections import deque, defaultdict

def num_buses_to_destination(routes, start, end):
    """
    Returns the minimum number of buses required to travel from start to end stop using the given routes.
    If it is not possible, returns -1.
    """
    if start == end:
        return 0

    # Map each stop to the routes that pass through it
    stop_to_routes = defaultdict(set)
    for route_id, route in enumerate(routes):
        for stop in route:
            stop_to_routes[stop].add(route_id)

    # BFS initialization
    visited_stops = set()
    visited_routes = set()
    queue = deque([(start, 0)])  # (current stop, buses taken)
    visited_stops.add(start)

    while queue:
        current_stop, buses_taken = queue.popleft()

        for route_id in stop_to_routes[current_stop]:
            if route_id in visited_routes:
                continue
            visited_routes.add(route_id)

            for stop in routes[route_id]:
                if stop == end:
                    return buses_taken + 1
                if stop not in visited_stops:
                    visited_stops.add(stop)
                    queue.append((stop, buses_taken + 1))

    return -1

