def longest_exact_k_distinct(logs, k):
    from collections import defaultdict

    left = 0
    freq = defaultdict(int)
    distinct = 0
    best = 0

    for right, value in enumerate(logs):
        if freq[value] == 0:
            distinct += 1
        freq[value] += 1

        while distinct > k:
            left_value = logs[left]
            freq[left_value] -= 1
            if freq[left_value] == 0:
                distinct -= 1
            left += 1

        if distinct == k:
            best = max(best, right - left + 1)

    return best

def kth_smallest_from_sorted_lists(lists, k):
    non_empty = [arr for arr in lists if arr]
    if not non_empty:
        raise ValueError('At least one element required')

    lo = min(arr[0] for arr in non_empty)
    hi = max(arr[-1] for arr in non_empty)

    def count_le(x):
        total = 0
        for arr in non_empty:
            l, r = 0, len(arr)
            while l < r:
                m = (l + r) // 2
                if arr[m] <= x:
                    l = m + 1
                else:
                    r = m
            total += l
        return total

    while lo < hi:
        mid = (lo + hi) // 2
        if count_le(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

def kth_smallest_pair_sum(prices, k):
    prices = sorted(prices)
    n = len(prices)

    def count_le(target):
        count = 0
        left = n - 1
        for i in range(n):
            while left > i and prices[i] + prices[left] > target:
                left -= 1
            if left <= i:
                break
            count += left - i
        return count

    lo, hi = prices[0] + prices[1], prices[-1] + prices[-2]
    if lo > hi:
        lo, hi = hi, lo

    while lo < hi:
        mid = (lo + hi) // 2
        if count_le(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

def longest_unique_route(route):
    seen = {}
    left = 0
    best = 0

    for right, value in enumerate(route):
        if value in seen and seen[value] >= left:
            left = seen[value] + 1
        seen[value] = right
        best = max(best, right - left + 1)

    return best

def longest_subarray_sum_target(transactions, target):
    prefix = 0
    first_seen = {0: -1}
    best = 0

    for i, value in enumerate(transactions):
        prefix += value
        need = prefix - target
        if need in first_seen:
            best = max(best, i - first_seen[need])
        if prefix not in first_seen:
            first_seen[prefix] = i

    return best

def optimize_prime_check(n):
    """
    Determines if a given integer n is a prime number using an optimized algorithm.

    Parameters:
    n (int): The integer to check for primality.

    Returns:
    bool: True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def create_inverted_index(texts):
    """
    Create an inverted index from a list of documents.

    Parameters:
    texts (list of str): A list of documents, where each document is a string.

    Returns:
    dict: An inverted index mapping terms to lists of document indices.
    """
    inverted_index = {}
    for doc_idx, document in enumerate(texts):
        words = document.split()
        for word in words:
            word = word.lower().strip('.,!?;:"()[]{}')
            if word:
                if word not in inverted_index:
                    inverted_index[word] = [doc_idx]
                elif doc_idx not in inverted_index[word]:
                    inverted_index[word].append(doc_idx)
    return inverted_index

class TemperatureConverter:
