def is_isomorphic(s: str, t: str) -> bool:
    """
    Determines if two strings are isomorphic.

    Args:
    s (str): The first string.
    t (str): The second string.

    Returns:
    bool: True if the strings are isomorphic, False otherwise.
    """
    mapping_s_to_t = {}
    mapping_t_to_s = {}

    for char_s, char_t in zip(s, t):
        if char_s in mapping_s_to_t:
            if mapping_s_to_t[char_s] != char_t:
                return False
        else:
            mapping_s_to_t[char_s] = char_t

        if char_t in mapping_t_to_s:
            if mapping_t_to_s[char_t] != char_s:
                return False
        else:
            mapping_t_to_s[char_t] = char_s

    return True

def convert_binary_to_decimal(binary_str):
    """
    Converts a binary number (given as a string) to its decimal equivalent.

    Parameters:
    binary_str (str): A string representing a binary number.

    Returns:
    int or str: The decimal equivalent of the binary number if valid, 
                otherwise an error message string.
    """
    if not isinstance(binary_str, str):
        return "Error: Input must be a string representing a binary number."

    if not all(char in {'0', '1'} for char in binary_str):
        return "Error: Input contains invalid characters. Only '0' and '1' are allowed."

    try:
        return int(binary_str, 2)
    except ValueError:
        return "Error: Could not convert input to a decimal number."

def is_valid(s: str) -> bool:
    """
    Determines if the input string s containing only '(', ')', '{', '}', '[' and ']' is valid.
    A string is valid if all opening brackets have a corresponding closing bracket of the same type
    and the brackets are closed in the correct order.

    :param s: The input string consisting of brackets.
    :return: True if the string is valid, False otherwise.
    """
    matching_pairs = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in matching_pairs.values():
            stack.append(char)
        elif char in matching_pairs.keys():
            if stack and stack[-1] == matching_pairs[char]:
                stack.pop()
            else:
                return False
        else:
            return False

    return not stack

def find_longest_increasing_subsequence(nums):
    """
    Returns the longest increasing subsequence in the given list of integers.

    :param nums: List[int] - A list of integers which may include duplicates.
    :return: List[int] - The longest increasing subsequence.
    """
    if not nums:
        return []

    dp = [nums[0]]
    subsequences = [[nums[0]]]

    for num in nums[1:]:
        if num > dp[-1]:
            dp.append(num)
            subsequences.append(subsequences[-1] + [num])
        else:
            pos = 0
            for i in range(len(dp)):
                if dp[i] >= num:
                    pos = i
                    break
            dp[pos] = num
            if pos == 0:
                subsequences[pos] = [num]
            else:
                subsequences[pos] = subsequences[pos - 1] + [num]

    return subsequences[-1]

import json
import os

def count_available_products_by_category(file_path):
    """
    Reads a JSON file and returns a dictionary with the count of available products in each category.

    Parameters:
    file_path (str): The path to the JSON file.

    Returns:
    dict: A dictionary mapping each category to the number of available products in that category.
    """
    categories_count = {}
    try:
        if not os.path.exists(file_path):
            print(f"Error: The file {file_path} does not exist.")
            return categories_count

        encodings = ['utf-8', 'utf-16']
        for encoding in encodings:
            try:
                with open(file_path, 'r', encoding=encoding) as file:
                    products_data = json.load(file)
                    for product in products_data:
                        if product['availability']:
                            categories_count[product['category']] = categories_count.get(product['category'], 0) + 1
                    break
            except UnicodeDecodeError:
                continue
        else:
            print(f"Error: Could not decode the file {file_path} with {encodings}.")
            return categories_count
    except json.JSONDecodeError:
        print(f"Error: The file {file_path} is not a valid JSON file.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    return categories_count

