def subset_sum(nums, targetSum):
    """
    Determine if there exists a subset of the list of unique positive integers 
    `nums` whose sum is equal to `targetSum`. If such a subset exists, return 
    a list containing the subset's integers. Otherwise, return an empty list.
    """
    def dfs(index, current_sum, path):
        if current_sum == targetSum:
            return path
        if index >= len(nums) or current_sum > targetSum:
            return []
        # Explore the path including nums[index]
        include_result = dfs(index + 1, current_sum + nums[index], path + [nums[index]])
        if include_result:
            return include_result
        # Explore the path excluding nums[index]
        exclude_result = dfs(index + 1, current_sum, path)
        return exclude_result

    return dfs(0, 0, [])

def getMaximumGold(grid):
    def dfs(x, y, current_gold):
        current_gold += grid[x][y]
        max_gold = current_gold

        temp = grid[x][y]
        grid[x][y] = 0  # Mark the cell as visited by setting it to 0

        # Explore all four possible directions
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] > 0:
                max_gold = max(max_gold, dfs(nx, ny, current_gold))

        grid[x][y] = temp  # Unmark the cell
        return max_gold

    max_gold_collected = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] > 0:
                max_gold_collected = max(max_gold_collected, dfs(i, j, 0))

    return max_gold_collected

