from typing import List, Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def generateTrees(n: int) -> List[Optional[TreeNode]]:
    if n == 0:
        return []

    def generate(start, end):
        if start > end:
            return [None]

        all_trees = []
        for i in range(start, end + 1):
            # Generate all left subtrees
            left_trees = generate(start, i - 1)

            # Generate all right subtrees
            right_trees = generate(i + 1, end)

            # Connect left and right subtrees to the root i
            for l in left_trees:
                for r in right_trees:
                    current_tree = TreeNode(i)
                    current_tree.left = l
                    current_tree.right = r
                    all_trees.append(current_tree)

        return all_trees

    return generate(1, n)

class NotificationSystem:
    def __init__(self):
        self.friends = {}
        self.posts = {}

    def addFriend(self, user1, user2):
        if user1 not in self.friends:
            self.friends[user1] = set()
        if user2 not in self.friends:
            self.friends[user2] = set()
        self.friends[user1].add(user2)
        self.friends[user2].add(user1)

    def post(self, user, content):
        notification = f"User {user} posted: {content}"
        if user in self.friends:
            for friend in self.friends[user]:
                if friend not in self.posts:
                    self.posts[friend] = []
                self.posts[friend].append(notification)

    def getNotifications(self, user):
        if user not in self.posts:
            return []
        return self.posts[user]

import heapq

def rearrange_array(nums, k):
    """
    Rearranges the array such that the difference between consecutive elements is minimized,
    and no element is moved more than k positions away from its original position.
    """
    # Use a min-heap to keep track of the smallest elements within the window of size min(len(nums), k+1)
    if k == 0:
        return nums

    n = len(nums)
    result = []
    min_heap = []

    for i in range(n):
        heapq.heappush(min_heap, nums[i])

        if i >= k:
            result.append(heapq.heappop(min_heap))

        if i == n - 1:
            while min_heap:
                result.append(heapq.heappop(min_heap))

    return result

