def infix_to_postfix(s):
    """
    Converts an infix expression to its equivalent postfix expression.
    """
    precedence = {
        '^': 3,
        '*': 2,
        '/': 2,
        '+': 1,
        '-': 1
    }
    associativity = {
        '^': 'R',
        '*': 'L',
        '/': 'L',
        '+': 'L',
        '-': 'L'
    }

    def has_higher_precedence(op1, op2):
        if precedence[op1] > precedence[op2]:
            return True
        elif precedence[op1] < precedence[op2]:
            return False
        else:
            return associativity[op1] == 'L'

    output = []
    stack = []

    for char in s:
        if char.isalnum():
            output.append(char)
        elif char in precedence:
            while stack and stack[-1] != '(' and has_higher_precedence(stack[-1], char):
                output.append(stack.pop())
            stack.append(char)
        elif char == '(':
            stack.append(char)
        elif char == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()  # pop '('

    while stack:
        output.append(stack.pop())

    return ''.join(output)

