def is_subsequence(s, t):
    it = iter(t)
    return all(char in it for char in s)

def find_shortest_supersequence(words):
    from itertools import permutations

    min_length = float('inf')
    best_supersequence = None

    for perm in permutations(words):
        supersequence_candidate = perm[0]
        for next_word in perm[1:]:
            # Merge supersequence_candidate with next_word
            merged = ""
            it = iter(supersequence_candidate)
            for char in next_word:
                if char in it:
                    merged += char
                else:
                    break
            supersequence_candidate += next_word[len(merged):]

        if len(supersequence_candidate) < min_length or (len(supersequence_candidate) == min_length and supersequence_candidate < best_supersequence):
            min_length = len(supersequence_candidate)
            best_supersequence = supersequence_candidate

    return best_supersequence

