def max_depth_binary_tree(tree):
    """
    Returns the maximum depth of the binary tree represented by the array `tree`.
    """
    def dfs(index):
        if index >= len(tree) or tree[index] is None:
            return -1  # Returning -1 because we're counting edges, not nodes
        left_depth = dfs(2 * index + 1)
        right_depth = dfs(2 * index + 2)
        return max(left_depth, right_depth) + 1

    return dfs(0)

