def check_subarray_sum(nums, k):
    """
    Check if there exists a continuous subarray of size at least 2 that sums up to a multiple of k.
    """
    if k == 0:  # Special case when k is zero
        for i in range(len(nums) - 1):
            if nums[i] == 0 and nums[i + 1] == 0:
                return True
        return False

    prefix_sum = 0
    prefix_sums = {0: -1}  # Store prefix sums and their indices

    for i, num in enumerate(nums):
        prefix_sum += num
        if k != 0:
            prefix_sum %= k

        if prefix_sum in prefix_sums:
            if i - prefix_sums[prefix_sum] > 1:
                return True
        else:
            prefix_sums[prefix_sum] = i

    return False

