def pacificAtlantic(matrix):
    if not matrix or not matrix[0]:
        return []

    def dfs(x, y, visited, prev_height):
        if (x, y) in visited or x < 0 or y < 0 or x >= m or y >= n or matrix[x][y] < prev_height:
            return
        visited.add((x, y))
        for direction in directions:
            new_x, new_y = x + direction[0], y + direction[1]
            dfs(new_x, new_y, visited, matrix[x][y])

    m, n = len(matrix), len(matrix[0])
    pacific_visited = set()
    atlantic_visited = set()
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    for i in range(m):
        dfs(i, 0, pacific_visited, matrix[i][0])
        dfs(i, n - 1, atlantic_visited, matrix[i][n - 1])
    for j in range(n):
        dfs(0, j, pacific_visited, matrix[0][j])
        dfs(m - 1, j, atlantic_visited, matrix[m - 1][j])

    return list(pacific_visited & atlantic_visited)

