import heapq

def shortest_path(n, edges, src, dst):
    """
    Returns the shortest path distance from source node `src` to target node `dst` in a directed weighted graph.
    If there is no path, return -1.
    """
    # Create adjacency list
    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    # Priority queue to hold (distance, node) tuples
    pq = [(0, src)]
    # Distance array initialized with infinity
    dist = {i: float('inf') for i in range(n)}
    dist[src] = 0

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_node == dst:
            return current_dist

        if current_dist > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_dist + weight
            if distance < dist[neighbor]:
                dist[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return -1 if dist[dst] == float('inf') else dist[dst]

