def max_sum_no_adjacent(nums, k):
    def helper(nums, k, start, cache):
        if k == 0:
            return 0
        if start >= len(nums):
            return float('-inf')
        if (start, k) in cache:
            return cache[(start, k)]

        include = nums[start] + helper(nums, k - 1, start + 2, cache)
        exclude = helper(nums, k, start + 1, cache)
        cache[(start, k)] = max(include, exclude)
        return cache[(start, k)]

    cache = {}
    result = helper(nums, k, 0, cache)
    return result if result != float('-inf') else 0

