def findLongestSubstring(s: str, k: int) -> int:
    def longestSubstringUtil(start, end):
        if end - start < k:  # If length of substring is less than k, not possible
            return 0

        # Frequency table
        count = {}
        for i in range(start, end):
            count[s[i]] = count.get(s[i], 0) + 1

        for mid in range(start, end):
            if count[s[mid]] >= k:
                continue

            midNext = mid + 1
            while midNext < end and count[s[midNext]] < k:
                midNext += 1
            return max(longestSubstringUtil(start, mid), longestSubstringUtil(midNext, end))

        return end - start  # Whole substring valid

    return longestSubstringUtil(0, len(s))

