def longest_substring_with_k_repeats(s, k):
    """
    Returns the length of the longest substring such that every character in the substring appears at least k times.
    """
    def helper(sub_s, k):
        if not sub_s or k > len(sub_s):
            return 0

        char_count = {c: sub_s.count(c) for c in set(sub_s)}

        for idx, ch in enumerate(sub_s):
            if char_count[ch] < k:
                return max(helper(sub_s[:idx], k), helper(sub_s[idx + 1:], k))

        return len(sub_s)

    return helper(s, k)

