from collections import deque

def min_moves(grid):
    """
    Finds the minimum number of moves required to traverse from the top-left
    corner of the grid to the bottom-right corner with given movement constraints.
    """
    if not grid or not grid[0]:
        return -1

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    start = (0, 0)
    end = (rows - 1, cols - 1)

    if start == end:
        return 0

    queue = deque([(0, 0, 0)])  # (row, col, distance)
    visited = set()
    visited.add((0, 0))

    while queue:
        row, col, dist = queue.popleft()

        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                if grid[nr][nc] <= grid[row][col] + 1:
                    if (nr, nc) == end:
                        return dist + 1
                    queue.append((nr, nc, dist + 1))
                    visited.add((nr, nc))

    return -1

def exist(board, word):
    def backtrack(r, c, word):
        if len(word) == 0:  # All characters are checked
            return True
        if r < 0 or r >= len(board) or c < 0 or c >= len(board[0]) or board[r][c] != word[0]:
            return False

        ret = False
        board[r][c] = '#'  # mark the cell as visited
        for row_offset, col_offset in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            ret = backtrack(r + row_offset, c + col_offset, word[1:])
            if ret:
                break

        board[r][c] = word[0]  # unmark the cell
        return ret

    for r in range(len(board)):
        for c in range(len(board[0])):
            if backtrack(r, c, word):
                return True
    return False

