def unique_ipv4s(log_line):
    import re

    def valid_ip(ip):
        parts = ip.split('.')
        if len(parts) != 4:
            return False
        for part in parts:
            if not part.isdigit():
                return False
            if part != '0' and part.startswith('0'):
                return False
            if not 0 <= int(part) <= 255:
                return False
        return True

    candidates = re.findall(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', log_line)
    seen = set()
    result = []
    for ip in candidates:
        if valid_ip(ip) and ip not in seen:
            seen.add(ip)
            result.append(ip)
    return result

def find_substring_pattern(strings):
    """
    Finds the longest common substring pattern among all the strings in the list.
    If there are multiple substrings of the same maximum length, returns the lexicographically smallest one.

    :param strings: List of strings
    :return: Longest common substring pattern
    """
    if not strings:
        return ""

    def is_common_substring(substring):
        return all(substring in string for string in strings)

    first_string = strings[0]
    max_length = 0
    longest_common_substrings = []

    for start in range(len(first_string)):
        for end in range(start + 1, len(first_string) + 1):
            substring = first_string[start:end]
            if is_common_substring(substring):
                if len(substring) > max_length:
                    max_length = len(substring)
                    longest_common_substrings = [substring]
                elif len(substring) == max_length:
                    longest_common_substrings.append(substring)

    return min(longest_common_substrings)

