def sum_at_level(root, level):
    """
    Returns the sum of all node values at the specified level in a binary tree.

    :param root: TreeNode, the root of the binary tree.
    :param level: int, the level at which to calculate the sum of node values.
    :return: int, the sum of node values at the specified level, or 0 if the level does not exist.
    """
    if not root:
        return 0
    queue = [(root, 0)]
    level_sum = 0
    while queue:
        node, current_level = queue.pop(0)
        if current_level == level:
            level_sum += node.value
        elif current_level < level:
            if node.left:
                queue.append((node.left, current_level + 1))
            if node.right:
                queue.append((node.right, current_level + 1))
        else:
            break
    return level_sum

def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def largest_prime_factor(n):
    """Find the largest prime factor of a number."""
    largest_factor = -1

    while n % 2 == 0:
        largest_factor = 2
        n //= 2

    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            largest_factor = i
            n //= i

    if n > 2:
        largest_factor = n

    return largest_factor

def find_largest_prime_factor(nums):
    """Find the largest prime factor of the largest number in the list."""
    if not nums:
        return -1

    largest_num = max(nums)

    if largest_num < 2:
        return -1

    return largest_prime_factor(largest_num)

