def calculate(s: str) -> int:
    def helper(s: list) -> int:
        stack = []
        num = 0
        sign = 1
        while len(s) > 0:
            c = s.pop(0)
            if c.isdigit():
                num = num * 10 + int(c)
            elif c == '+':
                stack.append(sign * num)
                num = 0
                sign = 1
            elif c == '-':
                stack.append(sign * num)
                num = 0
                sign = -1
            elif c == '(':
                num = helper(s)
            elif c == ')':
                stack.append(sign * num)
                return sum(stack)
        stack.append(sign * num)
        return sum(stack)

    # Convert the input string into a list of characters for easy manipulation
    return helper(list(s))

