        self.next = next

def longest_increasing_subsequence(head):
    """
    Find the longest increasing subsequence in a linked list and return it as a list of node values.
    """
    if not head:
        return []

    # Transform linked list to an array to simplify LIS finding
    arr = []
    current = head
    while current:
        arr.append(current.value)
        current = current.next

    if not arr:
        return []

    # Array to store our increasing subsequence
    lis, backtrack = [], []
    for i in range(len(arr)):
        lis.append(1)
        backtrack.append(None)
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1
                backtrack[i] = j

    # Find the index of the max LIS
    max_index = 0
    for i in range(1, len(lis)):
        if lis[i] > lis[max_index]:
            max_index = i

    # Reconstruct LIS from backtrack table
    sequence = []
    i = max_index
    while i is not None:
        sequence.append(arr[i])
        i = backtrack[i]

    return sequence[::-1]  # reverse to get the correct order

def longest_increasing_subsequence_with_max_difference(arr, d):
    n = len(arr)
    if n == 0:
        return 0

    # dp[i] will store the length of the longest increasing subsequence ending with arr[i]
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and arr[i] - arr[j] <= d:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def can_partition_k_subsets(arr, k):
    total_sum = sum(arr)
    if total_sum % k != 0:
        return False
    target_sum = total_sum // k

    arr.sort(reverse=True)
    used = [False] * len(arr)

    def backtrack(start, k, current_sum):
        if k == 1:
            return True
        if current_sum == target_sum:
            return backtrack(0, k - 1, 0)
        for i in range(start, len(arr)):
            if not used[i] and current_sum + arr[i] <= target_sum:
                used[i] = True
                if backtrack(i + 1, k, current_sum + arr[i]):
                    return True
                used[i] = False
        return False

    return backtrack(0, k, 0)

