def are_similar(word1, word2):
    """
    Check if two words are similar by swapping at most two characters.
    """
    if word1 == word2:
        return True

    if len(word1) != len(word2):
        return False

    # Finding the positions where the characters differ
    different_chars = [(w1, w2) for w1, w2 in zip(word1, word2) if w1 != w2]

    # If there are exactly 2 positions where the characters differ,
    # check if they can be swapped to make the words identical.
    if len(different_chars) == 2 and different_chars[0] == different_chars[1][::-1]:
        return True

    return False

def find_similar_word_sets(words):
    """
    Determine the number of distinct sets of similar words in the given list.
    """
    from collections import defaultdict

    similar_sets = []

    for word in words:
        added = False
        # Compare the current word with all sets
        for s in similar_sets:
            if any(are_similar(word, w) for w in s):
                s.add(word)
                added = True
                break
        if not added:
            similar_sets.append({word})

    return len(similar_sets)

