def min_time(jobs, k):
    def is_feasible(time_limit):
        worker_count = 1
        current_time = 0

        for job in jobs:
            if current_time + job <= time_limit:
                current_time += job
            else:
                worker_count += 1
                current_time = job
                if worker_count > k:
                    return False
        return True

    left, right = max(jobs), sum(jobs)
    while left < right:
        mid = (left + right) // 2
        if is_feasible(mid):
            right = mid
        else:
            left = mid + 1

    return left

def longest_palindromic_substring(s, queries):
    def find_longest_palindrome_at(s, left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left + 1:right]

    def longest_palindrome(s):
        result = ""
        for i in range(len(s)):
            # Find the longest odd-length palindrome with center at i
            palindrome_odd = find_longest_palindrome_at(s, i, i)
            if len(palindrome_odd) > len(result):
                result = palindrome_odd
            # Find the longest even-length palindrome with centers at i and i+1
            palindrome_even = find_longest_palindrome_at(s, i, i + 1)
            if len(palindrome_even) > len(result):
                result = palindrome_even
        return len(result)

    results = []
    for start, end in queries:
        substring = s[start:end+1]
        results.append(longest_palindrome(substring))

    return results

