def longest_zigzag_subsequence(nums):
    """
    Returns the length of the longest zigzag subsequence of the array nums.
    """
    if not nums:
        return 0

    n = len(nums)
    if n == 1:
        return 1

    up = 1
    down = 1

    for i in range(1, n):
        if nums[i] > nums[i - 1]:
            up = down + 1
        elif nums[i] < nums[i - 1]:
            down = up + 1

    return max(up, down)

