def find_top_two_students(results):
    """
    Given a list of tuples (student_name, score), return a list containing the names of the students
    with the highest and second highest scores. If no second highest score exists, return only the
    highest scoring student's name.
    """
    if not results:
        return []

    first = second = float('-inf')
    first_student = second_student = None

    for name, score in results:
        if score > first:
            second, second_student = first, first_student
            first, first_student = score, name
        elif first > score > second:
            second, second_student = score, name

    if second_student is not None:
        return [first_student, second_student]
    else:
        return [first_student]

