def flip_to_balance(s):
    """
    Given a binary string `s`, return the index of the bit to flip to balance the count of '1's and '0's.
    If the string is already balanced, return -1.
    """
    count_0 = s.count('0')
    count_1 = s.count('1')

    if count_0 == count_1:
        return -1

    if count_0 > count_1:
        target = '0'
    else:
        target = '1'

    for index, char in enumerate(s):
        if char == target:
            return index

    return -1  # Default return value, should never hit this line

