def max_non_adjacent_sum(root):
    def helper(node):
        if not node:
            return 0, 0

        left_with, left_without = helper(node.left)
        right_with, right_without = helper(node.right)

        with_node = node.val + left_without + right_without
        without_node = max(left_with, left_without) + max(right_with, right_without)

        return with_node, without_node

    return max(helper(root))

