def min_operations_to_make_k_increasing(arr, k):
    def length_of_lis(seq):
        # This function calculates the length of the Longest Increasing Subsequence (LIS) in 'seq'
        lis = []
        for element in seq:
            if len(lis) == 0 or element >= lis[-1]:
                lis.append(element)
            else:
                left, right = 0, len(lis)-1
                while left < right:
                    mid = (left + right) // 2
                    if lis[mid] <= element:
                        left = mid + 1
                    else:
                        right = mid
                lis[left] = element
        return len(lis)

    n = len(arr)
    total_operations = 0

    for start in range(k):
        subsequence = []
        for i in range(start, n, k):
            subsequence.append(arr[i])

        length_of_subsequence = len(subsequence)
        length_of_lis_subsequence = length_of_lis(subsequence)

        total_operations += (length_of_subsequence - length_of_lis_subsequence)

    return total_operations

