def reverseKGroup(head, k):
    def reverseLinkedList(head, k):
        new_head = None
        ptr = head

        while k > 0:
            next_node = ptr.next
            ptr.next = new_head
            new_head = ptr
            ptr = next_node
            k -= 1

        return new_head

    count = 0
    ptr = head

    while ptr and count < k:
        ptr = ptr.next
        count += 1

    if count == k:
        reversed_head = reverseLinkedList(head, k)
        if head:
            head.next = reverseKGroup(ptr, k)
        return reversed_head

    return head

