from typing import List

def min_coins(nums: List[int], target1: int, target2: int) -> int:
    def coin_change(coins, amount):
        dp = [float('inf')] * (amount + 1)
        dp[0] = 0
        for coin in coins:
            for x in range(coin, amount + 1):
                dp[x] = min(dp[x], dp[x - coin] + 1)
        return dp[amount] if dp[amount] != float('inf') else -1

    # Find the minimum coins required for both targets separately
    min_coins_target1 = coin_change(nums, target1)
    min_coins_target2 = coin_change(nums, target2)

    if min_coins_target1 == -1 or min_coins_target2 == -1:
        return -1
    return min_coins_target1 + min_coins_target2

