import heapq

def max_water_volume(heights):
    if not heights or not heights[0]:
        return 0

    m, n = len(heights), len(heights[0])
    visited = [[False] * n for _ in range(m)]
    heap = []

    # Push all the border cells onto the heap and mark them visited
    for i in range(m):
        for j in [0, n-1]:
            heapq.heappush(heap, (heights[i][j], i, j))
            visited[i][j] = True

    for j in range(n):
        for i in [0, m-1]:
            heapq.heappush(heap, (heights[i][j], i, j))
            visited[i][j] = True

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    water_volume = 0
    while heap:
        height, x, y = heapq.heappop(heap)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                water_volume += max(0, height - heights[nx][ny])
                heapq.heappush(heap, (max(height, heights[nx][ny]), nx, ny))

    return water_volume

def compact_config(config):
    data = {}
    for item in config.split(';'):
        key, value = item.split(':', 1)
        data[key] = value
    items = [(k, v) for k, v in data.items() if v != '']
    items.sort(key=lambda x: (len(x[0]), x[0]))
    return ';'.join(f'{k}={v}' for k, v in items)

def apply_price_updates(n, updates):
    class Node:
        __slots__ = ("left", "right", "val", "lazy")
        def __init__(self):
            self.left = None
            self.right = None
            self.val = 0
            self.lazy = None

    root = Node()

    def push(node):
        if node.lazy is None:
            return
        if node.left is None:
            node.left = Node()
        if node.right is None:
            node.right = Node()
        node.left.val = node.lazy
        node.right.val = node.lazy
        node.left.lazy = node.lazy
        node.right.lazy = node.lazy
        node.lazy = None

    def update(node, l, r, ql, qr, value):
        if ql <= l and r <= qr:
            node.val = value
            node.lazy = value
            return
        push(node)
        mid = (l + r) // 2
        if ql <= mid:
            if node.left is None:
                node.left = Node()
            update(node.left, l, mid, ql, qr, value)
        if qr > mid:
            if node.right is None:
                node.right = Node()
            update(node.right, mid + 1, r, ql, qr, value)

    def query(node, l, r, idx):
        if node.lazy is not None or (node.left is None and node.right is None):
            return node.val
        mid = (l + r) // 2
        if idx <= mid:
            return query(node.left, l, mid, idx)
        return query(node.right, mid + 1, r, idx)

    for l, r, p in updates:
        update(root, 1, n, l, r, p)

    return [query(root, 1, n, i) for i in range(1, n + 1)]

def max_window_lengths(amounts, queries):
    n = len(amounts)
    ans = []
    for l, r, d in queries:
        best = 0
        i = l
        j = l
        for i in range(l, r + 1):
            if j < i:
                j = i
            while j <= r and amounts[j] - amounts[i] <= d:
                j += 1
            best = max(best, j - i)
        ans.append(best)
    return ans

def topk_prefix_sums(events, queries):
    import bisect

    times = [t for t, _ in events]
    scores = [s for _, s in events]
    all_scores = sorted(set(scores), reverse=True)
    idx = {v: i + 1 for i, v in enumerate(all_scores)}
    size = len(all_scores)

    class Fenwick:
        def __init__(self, n):
            self.n = n
            self.bit = [0] * (n + 1)
        def add(self, i, v):
            while i <= self.n:
                self.bit[i] += v
                i += i & -i
        def sum(self, i):
            s = 0
            while i > 0:
                s += self.bit[i]
                i -= i & -i
            return s

    cnt_tree = Fenwick(size)
    sum_tree = Fenwick(size)

    def sum_top_k(k):
        total_cnt = cnt_tree.sum(size)
        if k >= total_cnt:
            return sum_tree.sum(size)
        lo, hi = 1, size
        while lo < hi:
            mid = (lo + hi) // 2
            if cnt_tree.sum(mid) >= k:
                hi = mid
            else:
                lo = mid + 1
        pos = lo
        cnt_before = cnt_tree.sum(pos - 1)
        sum_before = sum_tree.sum(pos - 1)
        need = k - cnt_before
        return sum_before + need * all_scores[pos - 1]

    order = sorted(range(len(queries)), key=lambda i: queries[i][0])
    ans = [0] * len(queries)
    j = 0
    for qi in order:
        t, k = queries[qi]
        while j < len(events) and events[j][0] <= t:
            s = events[j][1]
            p = idx[s]
            cnt_tree.add(p, 1)
            sum_tree.add(p, s)
            j += 1
        ans[qi] = sum_top_k(k)
    return ans

