def min_steps_to_target(nums, target):
    """
    Returns the minimum number of steps required to reach an element equal to target in the circular array nums.
    If the target does not exist in the array, returns -1.
    """
    n = len(nums)
    if target not in nums:
        return -1

    min_steps = float('inf')
    for i in range(n):
        if nums[i] == target:
            min_steps = min(min_steps, i, n - i)

    return min_steps

