class Matrix:
    def __init__(self, data):
        """
        Initializes a Matrix object with a 2D list of numbers.

        :param data: A 2D list of numbers representing the matrix.
        :raises ValueError: If the input data is not a valid 2D list of numbers.
        """
        if not all(isinstance(row, list) and len(row) == len(data[0]) for row in data):
            raise ValueError("Input data should be a 2D list with consistent row lengths.")
        if not all(isinstance(item, (int, float)) for row in data for item in row):
            raise ValueError("All items in the input data should be numbers.")
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if data else 0

    def add(self, other):
        """
        Adds another matrix to this matrix.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the sum of the two matrices.
        :raises ValueError: If the matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be added.")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtracts another matrix from this matrix.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the difference of the two matrices.
        :raises ValueError: If the matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions to be subtracted.")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiplies this matrix by another matrix.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the product of the two matrices.
        :raises ValueError: If the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to the number of rows in the second matrix.")
        result = [
            [
                sum(self.data[i][k] * other.data[k][j] for k in range(self.cols))
                for j in range(other.cols)
            ]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __str__(self):
        """
        Returns a string representation of the matrix.

        :return: A string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

