def evaluate(expression):
    """
    Evaluates a mathematical expression and returns the result as an integer.
    """
    def precedence(op):
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/':
            return 2
        return 0

    def apply_op(a, b, op):
        if op == '+':
            return a + b
        if op == '-':
            return a - b
        if op == '*':
            return a * b
        if op == '/':
            return a // b

    def evaluate_expression(tokens):
        values = []
        ops = []

        i = 0
        while i < len(tokens):
            if tokens[i] == ' ':
                i += 1
                continue
            elif tokens[i] == '(':
                ops.append(tokens[i])
            elif tokens[i].isdigit():
                val = 0
                while i < len(tokens) and tokens[i].isdigit():
                    val = (val * 10) + int(tokens[i])
                    i += 1
                values.append(val)
                i -= 1
            elif tokens[i] == ')':
                while len(ops) != 0 and ops[-1] != '(':
                    val2 = values.pop()
                    val1 = values.pop()
                    op = ops.pop()
                    values.append(apply_op(val1, val2, op))
                ops.pop()
            else:
                while (len(ops) != 0 and precedence(ops[-1]) >= precedence(tokens[i])):
                    val2 = values.pop()
                    val1 = values.pop()
                    op = ops.pop()
                    values.append(apply_op(val1, val2, op))
                ops.append(tokens[i])
            i += 1

        while len(ops) != 0:
            val2 = values.pop()
            val1 = values.pop()
            op = ops.pop()
            values.append(apply_op(val1, val2, op))

        return values[-1]

    return evaluate_expression(expression)

from collections import deque

def time_to_propagate_signal(grid):
    if not grid:
        return -1

    rows, cols = len(grid), len(grid[0])
    queue = deque()
    visited = set()
    empty_cells = 0

    # Initialize the queue with all starting points and count empty cells
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                queue.append((r, c, 0))  # (row, column, time)
                visited.add((r, c))
            elif grid[r][c] == 0:
                empty_cells += 1

    # Edge case: if no empty cells exist
    if empty_cells == 0:
        return 0

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    max_time = 0

    while queue:
        r, c, time = queue.popleft()

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                if grid[nr][nc] == 0:
                    visited.add((nr, nc))
                    queue.append((nr, nc, time + 1))
                    max_time = time + 1
                    empty_cells -= 1

    # If there are still empty cells that cannot be reached
    if empty_cells > 0:
        return -1

    return max_time

