def differ_by_one_char(word1, word2):
    """
    Returns True if word1 and word2 differ by exactly one character, otherwise False.
    """
    if len(word1) != len(word2):
        return False

    differences = sum(1 for a, b in zip(word1, word2) if a != b)
    return differences == 1


def build_graph(words):
    """
    Builds an adjacency list for the words where an edge exists if the words differ by exactly one character.
    """
    graph = {word: [] for word in words}

    for i in range(len(words)):
        for j in range(i + 1, len(words)):
            if differ_by_one_char(words[i], words[j]):
                graph[words[i]].append(words[j])
                graph[words[j]].append(words[i])

    return graph


def dfs(word, graph, visited):
    """
    Performs depth-first search to compute the size of the connected component.
    """
    stack = [word]
    size = 0

    while stack:
        current = stack.pop()
        if not visited[current]:
            visited[current] = True
            size += 1
            for neighbor in graph[current]:
                if not visited[neighbor]:
                    stack.append(neighbor)

    return size


def largest_connected_set(words):
    """
    Determines the size of the largest connected set of words.
    """
    if not words:
        return 0

    graph = build_graph(words)
    visited = {word: False for word in words}
    max_size = 0

    for word in words:      
        if not visited[word]:
            component_size = dfs(word, graph, visited)
            max_size = max(max_size, component_size)

    return max_size

