def exist(board, word):
    """
    Returns True if the word exists in the grid following the specified rules,
    otherwise returns False.
    """
    def dfs(board, word, i, j, index):
        if index == len(word):
            return True
        if i < 0 or i >= len(board) or j < 0 or j >= len(board[0]) or board[i][j] != word[index]:
            return False
        temp = board[i][j]
        board[i][j] = '#'  # Mark this cell as used
        found = (dfs(board, word, i+1, j, index+1) or
                 dfs(board, word, i-1, j, index+1) or
                 dfs(board, word, i, j+1, index+1) or
                 dfs(board, word, i, j-1, index+1))
        board[i][j] = temp  # Unmark this cell
        return found

    for i in range(len(board)):
        for j in range(len(board[0])):
            if board[i][j] == word[0] and dfs(board, word, i, j, 0):
                return True

    return False

