def factorial(n, memo=None):
    """
    Computes the factorial of a given non-negative integer n using recursion and memoization.

    Parameters:
    n (int): The non-negative integer for which the factorial is to be computed.
    memo (dict, optional): A dictionary to store previously computed factorial values for memoization.

    Returns:
    int: The factorial of the given integer n.
    """
    if memo is None:
        memo = {}
    if n == 0:
        return 1
    elif n in memo:
        return memo[n]
    else:
        memo[n] = n * factorial(n - 1, memo)
        return memo[n]

