import math

def generate_prime_numbers(n):
    """
    Generate a list of the first n prime numbers using an efficient algorithm.

    Parameters:
    n (int): The number of prime numbers to generate.

    Returns:
    list: A list containing the first n prime numbers.
    """
    if n <= 0:
        return []

    if n < 6:
        upper_bound = 15
    else:
        upper_bound = int(n * (math.log(n) + math.log(math.log(n))))

    is_prime = [True] * (upper_bound + 1)
    p = 2
    while p * p <= upper_bound:
        if is_prime[p]:
            for i in range(p * p, upper_bound + 1, p):
                is_prime[i] = False
        p += 1

    primes = []
    for p in range(2, upper_bound + 1):
        if is_prime[p]:
            primes.append(p)
            if len(primes) == n:
                break

    return primes

class TextEditor:
    def __init__(self):
        self.text = ""
        self.history = []
        self.undo_stack = []

    def insert(self, text):
        self.history.append(self.text)
        self.text += text
        self.undo_stack = []  # Clear redo stack when new operation is performed

    def delete(self, k):
        self.history.append(self.text)
        if k >= len(self.text):
            self.text = ""
        else:
            self.text = self.text[:-k]
        self.undo_stack = []  # Clear redo stack when new operation is performed

    def undo(self):
        if self.history:
            last_state = self.history.pop()
            self.undo_stack.append(self.text)
            self.text = last_state

    def redo(self):
        if self.undo_stack:
            last_undone_state = self.undo_stack.pop()
            self.history.append(self.text)
            self.text = last_undone_state

    def currentText(self):
        return self.text

