def does_subarray_sum_to_x(nums, x):
    """
    Checks whether there exists a subarray of nums that adds up to x.
    """
    current_sum = 0
    prefix_sums = {0}

    for num in nums:
        current_sum += num
        if (current_sum - x) in prefix_sums:
            return True
        prefix_sums.add(current_sum)

    return False

def largest_prime_factor(numbers):
    """
    Finds the largest prime factor of the last element in the list.
    Returns None if the last element is 0 or negative.
    """
    def is_prime(n):
        """
        Checks if a number n is a prime number.
        """
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def largest_prime_factor_of(n):
        """
        Finds the largest prime factor of a given number n.
        """
        largest_prime = None
        while n % 2 == 0:
            largest_prime = 2
            n //= 2
        for i in range(3, int(n**0.5) + 1, 2):
            while n % i == 0:
                if is_prime(i):
                    largest_prime = i
                n //= i
        if n > 2 and is_prime(n):
            largest_prime = n
        return largest_prime

    last_number = numbers[-1]
    if last_number <= 0:
        return None
    return largest_prime_factor_of(last_number)

