from collections import Counter

def isPossibleDivide(nums, k):
    """
    Determines if the array can be divided into consecutive subsequences of length k.

    Parameters:
    nums (List[int]): The array of integers.
    k (int): The length of each consecutive subsequence.

    Returns:
    bool: True if the array can be divided into consecutive subsequences of length k, otherwise False.
    """
    if len(nums) % k != 0:
        return False

    num_count = Counter(nums)
    nums.sort()

    for num in nums:
        if num_count[num] > 0:
            for i in range(num, num + k):
                if num_count[i] > 0:
                    num_count[i] -= 1
                else:
                    return False
    return True

