def modifyString(s):
    """
    Modifies the input string by replacing all '?' with any lowercase letter
    such that no two adjacent characters are the same.
    """
    s = list(s)
    for i in range(len(s)):
        if s[i] == '?':
            for ch in 'abc':
                if (i == 0 or s[i - 1] != ch) and (i == len(s) - 1 or s[i + 1] != ch):
                    s[i] = ch
                    break
    return ''.join(s)

