def find_prime_numbers(n):
    """
    Returns a list of all prime numbers less than or equal to n.

    :param n: The upper limit integer up to which prime numbers are to be found.
    :return: A list of prime numbers up to n.
    """
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n + 1, start):
                is_prime[multiple] = False

    return [num for num, prime in enumerate(is_prime) if prime]

from collections import deque

def min_minutes_to_burn_forest(forest):
    rows, cols = len(forest), len(forest[0])
    queue = deque()
    tree_count = 0

    # Initialize queue with all fire positions and count trees
    for r in range(rows):
        for c in range(cols):
            if forest[r][c] == '2':
                queue.append((r, c, 0))  # (row, col, minutes)
            elif forest[r][c] == '1':
                tree_count += 1

    def neighbors(r, c):
        for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
            if 0 <= nr < rows and 0 <= nc < cols:
                yield (nr, nc)

    minutes = 0

    while queue:
        r, c, minutes = queue.popleft()
        for nr, nc in neighbors(r, c):
            if forest[nr][nc] == '1':  # If it's a tree
                forest[nr][nc] = '2'
                tree_count -= 1
                queue.append((nr, nc, minutes + 1))

    return minutes if tree_count == 0 else -1

