def evaluate_expression(expression):
    """
    Evaluates a fully parenthesized mathematical expression consisting of 
    non-negative integers and the operators +, -, *, and /.
    """
    def helper(exp, index):
        if exp[index].isdigit():
            start = index
            while index < len(exp) and exp[index].isdigit():
                index += 1
            return int(exp[start:index]), index

        if exp[index] == '(':
            index += 1  # skip '('
            left_value, index = helper(exp, index)
            op = exp[index]
            index += 1  # skip operator
            right_value, index = helper(exp, index)
            if exp[index] == ')':
                index += 1  # skip ')'
            if op == '+':
                return left_value + right_value, index
            elif op == '-':
                return left_value - right_value, index
            elif op == '*':
                return left_value * right_value, index
            elif op == '/':
                return left_value // right_value, index
            else:
                raise ValueError("Invalid Operator")

    result, _ = helper(expression, 0)
    return result

