def fibonacci(n):
    """
    Calculate the nth Fibonacci number using recursion.

    Args:
    n (int): The position in the Fibonacci sequence to calculate. Must be a non-negative integer.

    Returns:
    int: The nth Fibonacci number.

    Raises:
    ValueError: If the input is a negative integer.
    """
    if n < 0:
        raise ValueError("Input should be a non-negative integer.")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

def inorder_traversal(tree):
    """
    Perform an in-order traversal of a binary tree represented as a nested tuple.

    :param tree: A tuple representing the binary tree.
    :return: A list of integers representing the in-order traversal of the tree.
    """
    def traverse(subtree):
        if subtree is not None:
            yield from traverse(subtree[1])  # Traverse the left subtree
            yield subtree[0]                 # Visit the root node
            yield from traverse(subtree[2])  # Traverse the right subtree

    return list(traverse(tree))

def longest_common_subsequence(str1, str2):
    """
    Finds the longest common subsequence between two strings using dynamic programming.

    :param str1: First input string.
    :param str2: Second input string.
    :return: Longest common subsequence as a string.
    """
    m, n = len(str1), len(str2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if str1[i - 1] == str2[j - 1]:
            lcs.append(str1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    lcs.reverse()
    return ''.join(lcs)

