def is_palindrome(s):
    """
    Determines if the given string s is a palindrome, ignoring spaces, punctuation, and capitalization.

    :param s: The input string to check.
    :return: True if s is a palindrome, False otherwise.
    """
    def is_alphanumeric(c):
        """
        Checks if a character is alphanumeric.

        :param c: The character to check.
        :return: True if c is alphanumeric, False otherwise.
        """
        return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9')

    def to_lowercase(c):
        """
        Converts an uppercase character to lowercase.

        :param c: The character to convert.
        :return: The lowercase version of c if c is uppercase, otherwise c.
        """
        if 'A' <= c <= 'Z':
            return chr(ord(c) - ord('A') + ord('a'))
        return c

    def check_palindrome(left, right):
        """
        Recursively checks if the substring s[left:right+1] is a palindrome.

        :param left: The left index of the substring.
        :param right: The right index of the substring.
        :return: True if the substring is a palindrome, False otherwise.
        """
        while left < right and not is_alphanumeric(s[left]):
            left += 1
        while left < right and not is_alphanumeric(s[right]):
            right -= 1
        if left >= right:
            return True
        if to_lowercase(s[left]) != to_lowercase(s[right]):
            return False
        return check_palindrome(left + 1, right - 1)

    return check_palindrome(0, len(s) - 1)

def average_grades(grades):
    """
    Calculate the average grade for each student in the given dictionary.

    Parameters:
    grades (dict): A dictionary where keys are student IDs and values are lists of grades.

    Returns:
    dict: A dictionary with student IDs as keys and their average grades as values.
    """
    averages = {}
    for student_id, grades_list in grades.items():
        if grades_list:
            averages[student_id] = sum(grades_list) / len(grades_list)
        else:
            averages[student_id] = 0
    return averages

