class ShoppingOptimizer:
    def __init__(self, costs, money):
        """
        Initializes the object with costs array and money.
        """
        self.costs = costs
        self.money = money

    def maximizeItems(self):
        """
        Returns the maximum number of items you can buy with the given money.
        """
        sorted_costs = sorted(self.costs)
        total_items = 0
        for cost in sorted_costs:
            if self.money >= cost:
                self.money -= cost
                total_items += 1
            else:
                break
        return total_items

    def spend(self, itemIndex):
        """
        If the item with index itemIndex can be bought with the remaining money, 
        reduce the money accordingly and return the cost of the item. 
        Otherwise, return -1.
        """
        if 0 <= itemIndex < len(self.costs):
            if self.money >= self.costs[itemIndex]:
                self.money -= self.costs[itemIndex]
                return self.costs[itemIndex]
            else:
                return -1
        else:
            return -1

