def evaluate_expression(s):
    """
    Evaluate the given numeric expression string and return the result.
    The expression can include non-negative integers and the '+', '-', '*', and '/' operators.
    Division is integer division, and the function handles operator precedence and parentheses.
    """
    def helper(tokens):
        stack = []
        num = 0
        sign = '+'

        while len(tokens) > 0:
            token = tokens.pop(0)

            if token.isdigit():
                num = int(token)

            if token == '(':
                num = helper(tokens)

            if (not token.isdigit() and token != ' ') or len(tokens) == 0:
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack.append(stack.pop() * num)
                elif sign == '/':
                    stack.append(int(stack.pop() / num))

                sign = token
                num = 0

            if token == ')':
                break

        return sum(stack)

    tokens = list(s.replace(' ', ''))
    return helper(tokens)

