def is_k_fault_tolerant(n, edges, k):
    from itertools import combinations
    from collections import defaultdict

    def is_connected(graph, num_vertices, skip_nodes=set()):
        visited = set()
        def dfs(node):
            if node in visited:
                return
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in skip_nodes:
                    dfs(neighbor)

        # Start DFS traversal from any node that is not among skip_nodes
        for start_node in range(num_vertices):
            if start_node not in skip_nodes:
                dfs(start_node)
                break

        # Check if all nodes are visited, excluding skip_nodes
        for node in range(num_vertices):
            if node not in skip_nodes and node not in visited:
                return False
        return True

    # Create adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Check all combinations of k nodes
    for nodes_to_fail in combinations(range(n), k):
        if not is_connected(graph, n, set(nodes_to_fail)):
            return False

    return True

