from collections import deque

def minDistance(grid):
    if not grid or not grid[0]:
        return -1

    rows, cols = len(grid), len(grid[0])
    buildings = sum(val == 1 for row in grid for val in row)
    hit = [[0] * cols for _ in range(rows)]
    dist_sum = [[0] * cols for _ in range(rows)]

    def bfs(start_row, start_col):
        visited = [[False] * cols for _ in range(rows)]
        queue = deque([(start_row, start_col, 0)])
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        while queue:
            row, col, dist = queue.popleft()
            for dr, dc in directions:
                r, c = row + dr, col + dc
                if 0 <= r < rows and 0 <= c < cols and not visited[r][c] and grid[r][c] == 0:
                    visited[r][c] = True
                    hit[r][c] += 1
                    dist_sum[r][c] += dist + 1
                    queue.append((r, c, dist + 1))

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                bfs(row, col)

    result = float('inf')
    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 0 and hit[row][col] == buildings:
                result = min(result, dist_sum[row][col])

    return result if result != float('inf') else -1

