def classify_sql_queries(queries):
    """
    Classifies each SQL query into one of the categories: SELECT, INSERT, UPDATE, DELETE, or OTHER.

    :param queries: List of SQL queries as strings.
    :return: List of categories corresponding to each query.
    """
    categories = []
    for query in queries:
        if query.upper().startswith("SELECT"):
            categories.append("SELECT")
        elif query.upper().startswith("INSERT"):
            categories.append("INSERT")
        elif query.upper().startswith("UPDATE"):
            categories.append("UPDATE")
        elif query.upper().startswith("DELETE"):
            categories.append("DELETE")
        else:
            categories.append("OTHER")
    return categories

