def can_reach_end(grid):
    """
    This function determines if the vacuum can reach the bottom-right corner of the room.
    Args:
    grid (list): a two-dimensional list representing the room.

    Returns:
    bool: True if the vacuum can reach the bottom-right corner, False otherwise.
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return False

    m, n = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0)]  # right, down

    def dfs(x, y):
        if x == m - 1 and y == n - 1:
            return True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 0:
                # Mark the cell as visited
                grid[nx][ny] = -1
                if dfs(nx, ny):
                    return True
        return False

    return dfs(0, 0)

