def evaluate_expression(expression: str) -> int:
    def precedence(op):
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/':
            return 2
        return 0

    def apply_op(a, b, op):
        if op == '+':
            return a + b
        if op == '-':
            return a - b
        if op == '*':
            return a * b
        if op == '/':
            return int(a / b)  # to ensure the result is an integer

    def compute_values(values, operators):
        b = values.pop()
        a = values.pop()
        op = operators.pop()
        values.append(apply_op(a, b, op))

    values = []
    operators = []
    i = 0

    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue

        if expression[i].isdigit():
            val = 0
            while i < len(expression) and expression[i].isdigit():
                val = (val * 10) + int(expression[i])
                i += 1
            values.append(val)
            i -= 1
        else:
            while (operators and precedence(operators[-1]) >= precedence(expression[i])):
                compute_values(values, operators)
            operators.append(expression[i])
        i += 1

    while operators:
        compute_values(values, operators)

    return values[0]

