def longest_concat_substring_length(s, wordDict):
    word_set = set(wordDict)
    n = len(s)
    max_len = 0

    # Create a DP array to store the longest length
    dp = [0] * (n+1)

    for i in range(1, n+1):
        for j in range(i):
            if s[j:i] in word_set:
                dp[i] = max(dp[i], dp[j] + (i - j))

    return max(dp)

