def longest_zigzag(nums):
    """
    Function to find the length of the longest zigzag subsequence in an array.
    """
    if not nums:
        return 0

    n = len(nums)
    if n == 1:
        return 1

    up = [1] * n
    down = [1] * n

    for i in range(1, n):
        for j in range(0, i):
            if nums[i] > nums[j]:
                up[i] = max(up[i], down[j] + 1)
            elif nums[i] < nums[j]:
                down[i] = max(down[i], up[j] + 1)

    return max(up[n-1], down[n-1])

def minimum_jumps(nums):
    """
    Returns the minimum number of jumps required to move from the first point to the last point in the array.
    If it is not possible to reach the last point, return -1.
    """
    n = len(nums)
    if n == 0:
        return -1

    jumps = [float('inf')] * n
    jumps[0] = 0

    for i in range(1, n):
        for j in range(i):
            if i <= j + nums[j] and jumps[j] != float('inf'):
                jumps[i] = min(jumps[i], jumps[j] + 1)

    return jumps[-1] if jumps[-1] != float('inf') else -1

