def max_distance(nums1, nums2):
    """
    Returns the maximum distance of any valid pair (i, j) such that nums1[i] <= nums2[j] and j >= i.
    If there are no valid pairs, returns 0.
    """
    max_dist = 0
    n = len(nums1)

    for i in range(n):
        for j in range(i, n):
            if nums1[i] <= nums2[j]:
                max_dist = max(max_dist, j - i)

    return max_dist

