def trap_rain_water(nums):
    """
    Calculate the total volume of water that can be trapped between the elevations after a heavy rain.

    Args:
    nums (List[int]): A list of integers representing the elevations.

    Returns:
    int: The total volume of trapped water.
    """
    if not nums or len(nums) < 3:
        return 0

    left, right = 0, len(nums) - 1
    left_max, right_max = nums[left], nums[right]
    total_water = 0

    while left < right:
        if nums[left] < nums[right]:
            if nums[left] >= left_max:
                left_max = nums[left]
            else:
                total_water += left_max - nums[left]
            left += 1
        else:
            if nums[right] >= right_max:
                right_max = nums[right]
            else:
                total_water += right_max - nums[right]
            right -= 1

    return total_water

