def min_operations_to_empty(nums):
    from collections import Counter

    num_counts = Counter(nums)
    operations = 0

    while num_counts:
        k = min(num_counts)
        operations += 1

        if k in num_counts:
            del num_counts[k]
        if k + 1 in num_counts:
            del num_counts[k + 1]

    return operations

def canReachEnd(maze):
    def isValid(x, y):
        return 0 <= x < len(maze) and 0 <= y < len(maze[0]) and maze[x][y] == 0

    def dfs(x, y):
        if x == len(maze) - 1 and y == len(maze[0]) - 1:
            return True
        maze[x][y] = -1  # mark as visited
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:  # move up, down, left, right
            nx, ny = x + dx, y + dy
            if isValid(nx, ny) and dfs(nx, ny):
                return True
        return False

    if maze[0][0] == 1 or maze[-1][-1] == 1:
        return False

    return dfs(0, 0)

