def longest_multiple_subsequence(nums):
    if not nums:
        return 0

    nums.sort()
    dp = [1] * len(nums)

    for i in range(len(nums)):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def min_distance_to_mailboxes(nums, k):
    """
    Returns the minimum total distance between each house and its nearest mailbox.
    The nums list is sorted and dynamic programming is used to find the best
    locations to place k mailboxes.
    """

    # Utility function to calculate distance for a segment
    def distance(start, end):
        median_index = (start + end) // 2
        median = nums[median_index]
        return sum(abs(nums[i] - median) for i in range(start, end + 1))

    n = len(nums)
    nums.sort()

    # dp[i][j]: the minimum distance to place j+1 mailboxes among the first i+1 houses
    dp = [[float('inf')] * k for _ in range(n)]

    for i in range(n):
        dp[i][0] = distance(0, i)

    for j in range(1, k):
        for i in range(n):
            for m in range(i):
                dp[i][j] = min(dp[i][j], dp[m][j-1] + distance(m + 1, i))

    return dp[-1][-1]

