def count_pairs_with_difference(prices, k):
    from collections import Counter

    if k < 0:
        return 0

    counts = Counter(prices)
    result = 0

    if k == 0:
        for value in counts.values():
            if value >= 2:
                result += 1
        return result

    for x in counts:
        if x + k in counts:
            result += 1

    return result

