def factorial(n: int) -> int:
    """
    Calculate the factorial of a non-negative integer n using recursion.

    Parameters:
    n (int): A non-negative integer whose factorial is to be computed.

    Returns:
    int: The factorial of the given integer n.

    Raises:
    ValueError: If n is a negative integer.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    elif n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

def find_max(nested_list):
    """
    Returns the maximum integer value found in a nested list of integers.

    :param nested_list: A nested list of integers.
    :return: The maximum integer value found in the nested list.
    """
    max_val = float('-inf')

    def dfs(lst):
        nonlocal max_val
        for item in lst:
            if isinstance(item, list):
                dfs(item)
            else:
                max_val = max(max_val, item)

    dfs(nested_list)
    return max_val

