    Calculate the average grades for each student in the given dictionary.

    :param grades_dict: A dictionary with student names as keys and lists of grades as values.
    :return: A dictionary with student names as keys and their average grades as values.
    """
    average_grades = {}
    for student, grades in grades_dict.items():
        average_grades[student] = sum(grades) / len(grades) if grades else 0
