def count_subsequences(s, t):
    """
    Counts the number of times the string t appears as a subsequence in the string s.

    :param s: The string in which to search for subsequences.
    :param t: The subsequence to count within the string s.
    :return: The number of times t appears as a subsequence in s.
    """
    def helper(i, j, memo={}):
        if (i, j) in memo:
            return memo[(i, j)]
        if j == len(t):
            return 1
        if i == len(s):
            return 0
        if s[i] == t[j]:
            result = helper(i + 1, j + 1, memo) + helper(i + 1, j, memo)
        else:
            result = helper(i + 1, j, memo)
        memo[(i, j)] = result
        return result

    return helper(0, 0)

