def invert_dict(input_dict: dict) -> dict:
    """
    Inverts the given dictionary such that keys become values and values become keys.
    If multiple keys share the same value, the new dictionary maps this value to a list of keys.

    :param input_dict: A dictionary with unique keys.
    :return: A new dictionary with inverted keys and values.
    """
    inverted = {}
    for key, value in input_dict.items():
        if value in inverted:
            if isinstance(inverted[value], list):
                inverted[value].append(key)
            else:
                inverted[value] = [inverted[value], key]
        else:
            inverted[value] = key
    return inverted

def calculate_discounted_price(original_price, discount_rate):
    """
    Calculate the discounted price of an item.

    Parameters:
    original_price (float): The original price of the item.
    discount_rate (float): The discount rate as a percentage.

    Returns:
    float: The final price after applying the discount.
    """
    if discount_rate > 100:
        return 0
    elif discount_rate < 0:
        return original_price + abs(discount_rate)
    else:
        return original_price - (original_price * (discount_rate / 100))

def word_frequencies(words):
    """
    Returns a dictionary with words as keys and their frequencies as values.

    :param words: List of strings representing words.
    :return: Dictionary with word frequencies.
    """
    frequency_dict = {}
    for word in words:
        if word in frequency_dict:
            frequency_dict[word] += 1
        else:
            frequency_dict[word] = 1
    return frequency_dict

