def convert_units(value: float, from_unit: str, to_unit: str) -> float:
    """
    Convert a given value from one unit to another.
    Supports metric and imperial units for length, weight, and temperature.

    :param value: The value to be converted.
    :param from_unit: The unit of the value provided (e.g., 'm', 'ft', 'kg', 'lb', 'C', 'F').
    :param to_unit: The unit to which to convert the value (e.g., 'ft', 'm', 'lb', 'kg', 'F', 'C').
    :return: The converted value.
    :raises ValueError: If the unit conversion is not supported.
    """

    # Define conversion factors for length
    length_factors = {
        'm': {'ft': 3.28084},
        'ft': {'m': 0.3048},
    }

    # Define conversion factors for weight
    weight_factors = {
        'kg': {'lb': 2.20462},
        'lb': {'kg': 0.453592},
    }

    # Define temperature conversion formulas
    def celsius_to_fahrenheit(c_value: float) -> float:
        return (c_value * 9/5) + 32

    def fahrenheit_to_celsius(f_value: float) -> float:
        return (f_value - 32) * 5/9

    temperature_formulas = {
        'C': {'F': celsius_to_fahrenheit},
        'F': {'C': fahrenheit_to_celsius},
    }

    # Determine the type of conversion based on the units
    if from_unit in length_factors and to_unit in length_factors[from_unit]:
        conversion_factor = length_factors[from_unit][to_unit]
        return value * conversion_factor
    elif from_unit in weight_factors and to_unit in weight_factors[from_unit]:
        conversion_factor = weight_factors[from_unit][to_unit]
        return value * conversion_factor
    elif from_unit in temperature_formulas and to_unit in temperature_formulas[from_unit]:
        conversion_function = temperature_formulas[from_unit][to_unit]
        return conversion_function(value)
    else:
        raise ValueError(f"Conversion from {from_unit} to {to_unit} is not supported.")

# Example usage:
if __name__ == "__main__":
    try:
        print(convert_units(1.75, 'm', 'ft'))  # Convert 1.75 meters to feet
        print(convert_units(50, 'kg', 'lb'))   # Convert 50 kg to pounds
        print(convert_units(0, 'C', 'F'))     # Convert 0 Celsius to Fahrenheit
        print(convert_units(100, 'F', 'C'))   # Convert 100 Fahrenheit to Celsius
    except ValueError as e:
        print(e)

