def remove_k_digits(s: str, k: int) -> str:
    if k == 0:
        return s
    stack = []
    for char in s:
        while k > 0 and stack and stack[-1] > char:
            stack.pop()
            k -= 1
        stack.append(char)
    # If k still > 0, remove the last k elements
    while k > 0:
        stack.pop()
        k -= 1
    return ''.join(stack)

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Codec:

    def serialize(self, root):
        """Encodes a tree to a single string.

        :type root: TreeNode
        :rtype: str
        """
        def rserialize(node):
            if not node:
                return 'None,'
            return str(node.val) + ',' + rserialize(node.left) + rserialize(node.right)

        return rserialize(root)

    def deserialize(self, data):
        """Decodes your encoded data to tree.

        :type data: str
        :rtype: TreeNode
        """
        def rdeserialize(data_iter):
            val = next(data_iter)
            if val == 'None':
                return None
            node = TreeNode(int(val))
            node.left = rdeserialize(data_iter)
            node.right = rdeserialize(data_iter)
            return node

        data_list = data.split(',')
        data_iter = iter(data_list)
        return rdeserialize(data_iter)

