def min_concatenation(s, words):
    words_set = set(words)
    dp = [float('inf')] * (len(s) + 1)
    dp[0] = 0

    for i in range(1, len(s) + 1):
        for word in words_set:
            if s[:i].endswith(word):
                dp[i] = min(dp[i], dp[i - len(word)] + 1)

    return dp[-1] if dp[-1] != float('inf') else -1

