def max_jumps(arr, d):
    n = len(arr)
    dp = [1] * n

    # Pair each index with its value, then sort by value
    sorted_indices = sorted(range(n), key=lambda x: arr[x])

    for i in sorted_indices:
        for direction in [-1, 1]:
            for j in range(1, d + 1):
                ni = i + direction * j
                if 0 <= ni < n and arr[i] > arr[ni]:
                    dp[i] = max(dp[i], dp[ni] + 1)
                else:
                    break

    return max(dp)

