def can_partition_k_subsets(arr, k):
    """
    Function to determine if an array can be partitioned into k subsets with equal sum.
    """
    total_sum = sum(arr)
    if total_sum % k != 0:
        return False

    target_sum = total_sum // k
    arr.sort(reverse=True)

    if arr[0] > target_sum:
        return False

    subsets = [0] * k

    def can_partition(index):
        if index == len(arr):
            return all(subset == target_sum for subset in subsets)

        for i in range(k):
            if subsets[i] + arr[index] <= target_sum:
                subsets[i] += arr[index]
                if can_partition(index + 1):
                    return True
                subsets[i] -= arr[index]
            if subsets[i] == 0:
                break

        return False

    return can_partition(0)

