from collections import defaultdict

def num_matching_subseq(text, words):
    """
    Return the total count of subsequences of `text` that are equal to any word in `words`.
    """
    def is_subsequence(s, t):
        it = iter(t)
        return all(c in it for c in s)

    word_count = defaultdict(int)
    for word in words:
        word_count[word] += 1

    total_count = 0
    for word, count in word_count.items():
        if is_subsequence(word, text):
            total_count += count
    return total_count

