def can_divide_into_k_groups(nums, k):
    """
    Determine if it's possible to divide the piles into exactly k groups 
    such that the total number of stones in each group is the same.
    """
    total_stones = sum(nums)
    n = len(nums)

    # Check if total_stones can be divided into k groups
    if total_stones % k != 0:
        return False

    target = total_stones // k

    # Check if it's possible to partition the array into subsets with given sum
    def can_partition(current_idx, current_sum, groups_formed, used):
        if groups_formed == k - 1:
            return True  # If we've successfully formed k-1 groups, the last group is automatically valid

        if current_sum == target:
            return can_partition(0, 0, groups_formed + 1, used)  # Move to form the next group

        for i in range(current_idx, n):
            if not used[i] and current_sum + nums[i] <= target:
                used[i] = True
                if can_partition(i + 1, current_sum + nums[i], groups_formed, used):
                    return True
                used[i] = False

        return False

    used = [False] * n
    return can_partition(0, 0, 0, used)

