def longest_zigzag_sequence(arr):
    """
    Given an array of integers, find the length of the longest subsequence that is a Zigzag sequence.
    """
    if len(arr) < 2:
        return len(arr)

    up = [1] * len(arr)
    down = [1] * len(arr)

    for i in range(1, len(arr)):
        for j in range(i):
            if arr[i] > arr[j]:
                up[i] = max(up[i], down[j] + 1)
            elif arr[i] < arr[j]:
                down[i] = max(down[i], up[j] + 1)

    return max(max(up), max(down))

def num_islands(grid):
    """
    This function calculates the number of islands in a given grid using DFS.
    """
    if not grid:
        return 0

    def dfs(grid, r, c):
        if r < 0 or r >= len(grid) or c < 0 or c >= len(grid[0]) or grid[r][c] == 0:
            return
        grid[r][c] = 0
        dfs(grid, r-1, c)
        dfs(grid, r+1, c)
        dfs(grid, r, c-1)
        dfs(grid, r, c+1)

    count = 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 1:
                dfs(grid, r, c)
                count += 1
    return count

def min_moves_to_equalize_islands(grid):
    """
    This function calculates the minimum number of moves needed to make all islands in the grid of equal size.
    """
    islands = []
    m, n = len(grid), len(grid[0])

    def dfs(grid, r, c):
        if r < 0 or r >= m or c < 0 or c >= n or grid[r][c] != 1:
            return 0
        grid[r][c] = -1 # Mark the cell as visited
        size = 1
        size += dfs(grid, r - 1, c)
        size += dfs(grid, r + 1, c)
        size += dfs(grid, r, c - 1)
        size += dfs(grid, r, c + 1)
        return size

    for r in range(m):
        for c in range(n):
            if grid[r][c] == 1:
                islands.append(dfs(grid, r, c))

    if len(islands) == 0:
        return 0

    target_size = round(sum(islands) / len(islands))
    moves = 0
    for size in islands:
        moves += abs(size - target_size)

    return moves // 2 # Since each move changes the size by 2

