                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and (nx, ny) not in visited:
                        if grid[nx][ny] == 1:
                            return steps
                        visited.add((nx, ny))
                        queue.append((nx, ny))
            steps += 1
        return -1

    if len(islands) < 2:
        return -1

    island1 = islands[0]
    island2 = islands[1]

    island1_queue = deque(island1)
    visited_from_island1 = set(island1)

    return bfs(island1_queue, visited_from_island1)

