def max_sum_of_longest_path(arr):
    if not arr or arr[0] == -1:
        return 0

    def dfs(index):
        if index >= len(arr) or arr[index] == -1:
            return (0, 0)  # (sum, depth)

        left_index = 2 * index + 1
        right_index = 2 * index + 2

        left_sum, left_depth = dfs(left_index)
        right_sum, right_depth = dfs(right_index)

        if left_depth > right_depth:
            return (left_sum + arr[index], left_depth + 1)
        elif right_depth > left_depth:
            return (right_sum + arr[index], right_depth + 1)
        else:
            return (max(left_sum, right_sum) + arr[index], left_depth + 1)

    max_sum, _ = dfs(0)
    return max_sum

