def decrypt_message(encrypted_message):
    """
    Decrypts a message encoded with a Caesar cipher using a shift of 3.

    Parameters:
    encrypted_message (str): The message to be decrypted.

    Returns:
    str: The decrypted message.
    """
    def shift_char(c):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') - 3) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') - 3) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c) for c in encrypted_message)

