def min_max_difference(root):
    """
    Computes the minimum absolute difference between the values of any two different nodes in a binary search tree.

    :param root: TreeNode, the root of the binary search tree
    :return: int, the minimum absolute difference between the values of any two different nodes
    """
    def inorder_traversal(node, prev, min_diff):
        if not node:
            return min_diff

        min_diff = inorder_traversal(node.left, prev, min_diff)

        if prev[0] is not None:
            min_diff = min(min_diff, node.val - prev[0])

        prev[0] = node.val

        min_diff = inorder_traversal(node.right, prev, min_diff)

        return min_diff

    prev = [None]
    min_diff = float('inf')

    return inorder_traversal(root, prev, min_diff)

