import heapq

def furthest_building(heights, bricks, ladders):
    min_heap = []
    for i in range(len(heights) - 1):
        diff = heights[i + 1] - heights[i]
        if diff > 0:
            heapq.heappush(min_heap, diff)
        if len(min_heap) > ladders:
            bricks -= heapq.heappop(min_heap)
        if bricks < 0:
            return i
    return len(heights) - 1

from typing import List

class Solution:
    def longestIncreasingPath(self, grid: List[List[int]]) -> int:
        if not grid or not grid[0]:
            return 0

        m, n = len(grid), len(grid[0])
        dp = [[-1 for _ in range(n)] for _ in range(m)]  # -1 indicates unvisited

        def dfs(x, y):
            if dp[x][y] != -1:
                return dp[x][y]

            directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
            max_length = 1

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] > grid[x][y]:
                    max_length = max(max_length, 1 + dfs(nx, ny))

            dp[x][y] = max_length
            return dp[x][y]

        result = 0
        for i in range(m):
            for j in range(n):
                result = max(result, dfs(i, j))

        return result

def find_and_replace_pattern(words, pattern):
    def matches(word):
        mapping = {}
        reverse_mapping = {}

        for w_char, p_char in zip(word, pattern):
            if w_char not in mapping:
                if p_char in reverse_mapping:
                    return False
                mapping[w_char] = p_char
                reverse_mapping[p_char] = w_char
            elif mapping[w_char] != p_char:
                return False

        return True

    return [word for word in words if matches(word)]

