from collections import deque

def min_distance_to_nearest_building(grid):
    rows = len(grid)
    cols = len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start_i, start_j):
        visited = [[False]*cols for _ in range(rows)]
        queue = deque([(start_i, start_j, 0)])
        visited[start_i][start_j] = True
        max_distance = 0

        while queue:
            i, j, dist = queue.popleft()
            for direction in directions:
                ni, nj = i + direction[0], j + direction[1]
                if 0 <= ni < rows and 0 <= nj < cols and not visited[ni][nj]:
                    visited[ni][nj] = True
                    if grid[ni][nj] == 1:
                        return dist + 1
                    queue.append((ni, nj, dist + 1))

        return float('inf')

    empty_lots = [(i, j) for i in range(rows) for j in range(cols) if grid[i][j] == 0]

    if not empty_lots:
        return -1

    min_distance = float('inf')

    for i, j in empty_lots:
        distance = bfs(i, j)
        if distance < min_distance:
            min_distance = distance

    return min_distance if min_distance != float('inf') else -1

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def sumOfLeftSubtree(root: TreeNode) -> int:
    """
    Returns the sum of the values of each node in the tree's left subtree.
    """
    if not root or not root.left:
        return 0

    def subtreeSum(node: TreeNode) -> int:
        if not node:
            return 0
        return node.val + subtreeSum(node.left) + subtreeSum(node.right)

    return subtreeSum(root.left)

def find_substring_indices(s, words):
    from collections import Counter

    if not s or not words:
        return []

    word_length = len(words[0])
    word_count = len(words)
    total_length = word_length * word_count
    word_counter = Counter(words)

    result = []

    for i in range(len(s) - total_length + 1):
        seen = {}
        for j in range(word_count):
            word = s[i + j * word_length: i + (j + 1) * word_length]
            if word in word_counter:
                seen[word] = seen.get(word, 0) + 1
                if seen[word] > word_counter[word]:
                    break
            else:
                break
        else:
            result.append(i)

    return sorted(result)

