def find_critical_nodes(n, edges):
    from collections import defaultdict

    # Helper function to perform DFS
    def dfs(node, discovery, low, parent, time, graph, visited, articulation_points):
        visited[node] = True
        discovery[node] = low[node] = time[0]
        time[0] += 1
        child_count = 0
        is_articulation = False

        for neighbor in graph[node]:
            if not visited[neighbor]:
                parent[neighbor] = node
                child_count += 1
                dfs(neighbor, discovery, low, parent, time, graph, visited, articulation_points)

                low[node] = min(low[node], low[neighbor])

                if parent[node] is None and child_count > 1:
                    is_articulation = True
                if parent[node] is not None and low[neighbor] >= discovery[node]:
                    is_articulation = True
            elif neighbor != parent[node]:
                low[node] = min(low[node], discovery[neighbor])

        if is_articulation:
            articulation_points.add(node)

    graph = defaultdict(list)
    for edge in edges:
        graph[edge[0]].append(edge[1])
        graph[edge[1]].append(edge[0])

    discovery = [-1] * n
    low = [-1] * n
    parent = [None] * n
    time = [0]
    visited = [False] * n
    articulation_points = set()

    for i in range(n):
        if not visited[i] and graph[i]:
            dfs(i, discovery, low, parent, time, graph, visited, articulation_points)

    return sorted(articulation_points)

