def max_coins(nums):
    """
    Returns the maximum number of coins that can be collected according to the given rules.
    """
    n = len(nums)
    if n == 0:
        return 0
    elif n == 1:
        return nums[0]
    elif n == 2:
        return max(nums[0], nums[1])

    dp = [0] * n
    dp[0] = nums[0]
    dp[1] = max(nums[0], nums[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + nums[i])

    return dp[-1]

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def reverse_k_segments(head, k, m):
    def reverse_segment(head, m):
        prev = None
        current = head
        tail = head

        for _ in range(m):
            if not current:
                return prev, tail, current
            nxt = current.next
            current.next = prev
            prev = current
            current = nxt

        return prev, tail, current

    if not head or k <= 0 or m <= 0:
        return head

    dummy = ListNode(0)
    dummy.next = head
    prev_end = dummy
    current = head

    while True:
        tail = current
        for _ in range(m * k):
            if not tail:
                return dummy.next
            tail = tail.next

        for _ in range(k):
            if not current:
                return dummy.next
            new_head, new_tail, next_segment_start = reverse_segment(current, m)
            prev_end.next = new_head
            new_tail.next = next_segment_start
            prev_end = new_tail
            current = next_segment_start

    return dummy.next

