def rearrange_string(input_str):
    """
    Rearranges the input string to have all letters before all digits,
    while ignoring spaces in the final output but preserving a single
    space between groups of letters and digits if needed.
    """
    letters = []
    digits = []
    result = []

    for char in input_str:
        if char.isalpha():
            letters.append(char)
        elif char.isdigit():
            digits.append(char)

    letters_str = ''.join(letters)
    digits_str = ''.join(digits)

    if letters_str and digits_str:
        return f"{letters_str} {digits_str}"
    else:
        return letters_str + digits_str

