def max_gold_robbed(gold):
    """
    Function to determine the maximum gold that can be robbed without robbing two consecutive houses.
    :param gold: List of gold amounts stored in each house.
    :return: Maximum amount of gold that can be robbed.
    """
    if not gold:
        return 0

    n = len(gold)
    if n == 1:
        return gold[0]
    elif n == 2:
        return max(gold[0], gold[1])

    dp = [0] * n
    dp[0] = gold[0]
    dp[1] = max(gold[0], gold[1])

    for i in range(2, n):
        dp[i] = max(dp[i - 1], gold[i] + dp[i - 2])

    return dp[-1]

