class MaxSumDataStructure:
    def __init__(self, nums1, nums2, k):
        self.nums1 = nums1
        self.nums2 = nums2
        self.k = k

    def maximizeSum(self):
        combined = self.nums1 + self.nums2
        heapq._heapify_max(combined)
        max_sum = 0
        for _ in range(self.k):
            max_sum += heapq._heappop_max(combined)
