def calculate(s: str) -> int:
    def helper(tokens):
        stack = []
        num = 0
        sign = '+'
        while len(tokens) > 0:
            token = tokens.pop(0)
            if token.isdigit():
                num = int(token)
            if token == '(':
                num = helper(tokens)
            if token in '+-*/)' or not tokens:
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack[-1] = stack[-1] * num
                elif sign == '/':
                    stack[-1] = int(stack[-1] / num)  # for Python 3 division truncation towards zero
                sign = token
                num = 0
            if token == ')':
                break
        return sum(stack)

    tokens = []
    i = 0
    while i < len(s):
        if s[i] == ' ':
            i += 1
            continue
        if s[i].isdigit():
            num = s[i]
            while i + 1 < len(s) and s[i + 1].isdigit():
                i += 1
                num += s[i]
            tokens.append(num)
        else:
            tokens.append(s[i])
        i += 1
    return helper(tokens)

