def maxSumTwoNoOverlap(arr, K, L):
    def maxSumSubarray(arr, length):
        n = len(arr)
        if n < length:
            return -1
        max_sum = -float('inf')
        current_sum = 0
        for i in range(length):
            current_sum += arr[i]
        max_sum = current_sum
        for i in range(length, n):
            current_sum += arr[i] - arr[i - length]
            if current_sum > max_sum:
                max_sum = current_sum
        return max_sum

    def maxSumWithFixedFirst(arr, K, L):
        n = len(arr)
        max_sum = -1
        for i in range(n - K + 1):
            sum1 = sum(arr[i:i + K])
            for j in range(n - L + 1):
                if j + L <= i or j >= i + K:
                    sum2 = sum(arr[j:j + L])
                    max_sum = max(max_sum, sum1 + sum2)
        return max_sum

    max_sum = max(maxSumWithFixedFirst(arr, K, L), maxSumWithFixedFirst(arr, L, K))

    return max_sum

