def longest_segment_with_exactly_m_unique(route, m):
    left = 0
    counts = {}
    best = 0
    for right, x in enumerate(route):
        counts[x] = counts.get(x, 0) + 1
        while len(counts) > m:
            y = route[left]
            counts[y] -= 1
            if counts[y] == 0:
                del counts[y]
            left += 1
        if len(counts) == m:
            best = max(best, right - left + 1)
    return best

