        self.events = {}

    def add_event(self, name, start_time, end_time):
        """Add or update an event with the given name, start time, and end time."""
        self.events[name] = (start_time, end_time)

    def remove_event(self, name):
        """Remove an event by name. Raise ValueError if the event does not exist."""
        if name not in self.events:
            raise ValueError(f"Event '{name}' not found.")
        del self.events[name]

    def get_overlapping_events(self, start_time, end_time):
        """Return a list of event names that overlap with the given time range."""
        overlapping_events = []
        for name, (event_start, event_end) in self.events.items():
            if start_time < event_end and end_time > event_start:
                overlapping_events.append(name)
        return overlapping_events

    def get_events(self):
        """Return a dictionary of all events."""
        return self.events.copy()

import os

def list_directory_contents(path):
    """
    Lists all files and subdirectories in the specified directory along with their sizes.

    Parameters:
    path (str): The path to the directory.

    Returns:
    None
    """
    try:
        for entry in os.listdir(path):
            full_path = os.path.join(path, entry)
            if os.path.isfile(full_path):
                size = os.path.getsize(full_path)
            else:
                size = sum(os.path.getsize(os.path.join(full_path, f)) 
                           for f in os.listdir(full_path) 
                           if os.path.isfile(os.path.join(full_path, f)))
            print(f'{entry} - {size} bytes')
    except FileNotFoundError:
        print(f'Error: The directory {path} does not exist.')
    except PermissionError:
        print(f'Error: Permission denied to access {path}.')
    except Exception as e:
        print(f'An unexpected error occurred: {e}')

def calculate_total_duration(log_file_path):
    """
    Reads a log file and returns a dictionary with the total duration of visits for each user.

    :param log_file_path: Path to the log file where each line contains a visit log in the format: timestamp, user_id, page_url, duration
    :return: A dictionary where the keys are user IDs and the values are the total duration of their visits
    """
    user_durations = {}
    try:
        with open(log_file_path, 'r') as file:
            for line in file:
                try:
                    timestamp, user_id, page_url, duration = line.strip().split(',')
                    duration = float(duration)
                    if user_id in user_durations:
                        user_durations[user_id] += duration
                    else:
                        user_durations[user_id] = duration
                except ValueError:
                    print(f"Skipping malformed line: {line}")
    except FileNotFoundError:
        print(f"File not found: {log_file_path}")
    except Exception as e:
        print(f"An error occurred: {str(e)}")

    return user_durations

def find_non_repeating_characters(s: str) -> list:
    """
    Returns a list of non-repeating characters in the given string, in the order they first appear.

    :param s: A string consisting of lowercase English letters.
    :return: A list of non-repeating characters.
    """
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    return [char for char in s if char_count[char] == 1]

def evaluate_expression(expression):
    """
    Evaluates a mathematical expression given as a string using a stack-based approach.

    :param expression: A string representing the mathematical expression.
    :return: A float representing the result of the evaluated expression.
    """
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def greater_precedence(op1, op2):
        return precedence(op1) > precedence(op2)

    operators = []
    values = []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        if expression[i] in '0123456789.':
            j = i
            while j < len(expression) and expression[j] in '0123456789.':
                j += 1
            values.append(float(expression[i:j]))
            i = j
        elif expression[i] in '+-*/':
            while (operators and operators[-1] != '(' and
                   greater_precedence(operators[-1], expression[i])):
                apply_operator(operators, values)
            operators.append(expression[i])
            i += 1
        elif expression[i] == '(':
            operators.append(expression[i])
            i += 1
        elif expression[i] == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # pop '('
            i += 1
    while operators:
        apply_operator(operators, values)

    return values[0]

