def min_jumps_to_reach_buildings(heights, maxJump):
    """
    Determine the minimum number of jumps to reach the top of each building.

    :param heights: List[int], where each element represents the height of a building.
    :param maxJump: int, the maximum height that can be jumped in one jump.
    :return: List[int], array of minimum jumps needed for each building or -1 if not possible.
    """
    result = []
    for height in heights:
        if height == 0:
            result.append(0)
        elif height <= maxJump:
            result.append(1)
        else:
            jumps = height // maxJump
            if height % maxJump != 0:
                jumps += 1
            result.append(jumps)
    return result

