def merge_sessions(sessions):
    """
    Merges overlapping sessions into single sessions.
    """
    # Normalize sessions for those that end past midnight
    normalized_sessions = []
    for start, end in sessions:
        if start <= end:
            normalized_sessions.append((start, end))
        else:
            # Split into two sessions
            normalized_sessions.append((start, 1439)) # until end of the day
            normalized_sessions.append((0, end)) # from start of the day

    # Sort sessions by start time and handle merging
    normalized_sessions.sort(key=lambda x: x[0])
    merged_sessions = []

    for session in normalized_sessions:
        if not merged_sessions or merged_sessions[-1][1] < session[0]:
            merged_sessions.append(session)
        else:
            merged_sessions[-1] = (merged_sessions[-1][0], max(merged_sessions[-1][1], session[1]))

    return merged_sessions

