class Matrix:
    def __init__(self, data):
        """
        Initialize a matrix with given 2D list data.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def transpose(self):
        """
        Return the transpose of the matrix.
        """
        transposed_data = [[self.data[j][i] for j in range(self.rows)] for i in range(self.cols)]
        return Matrix(transposed_data)

    def multiply(self, other):
        """
        Multiply the matrix with another matrix if dimensions are compatible.
        Raise ValueError if dimensions are not compatible.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in first matrix must be equal to number of rows in second matrix")

        result = [[0 for _ in range(other.cols)] for _ in range(self.rows)]

        for i in range(self.rows):
            for j in range(other.cols):
                for k in range(self.cols):
                    result[i][j] += self.data[i][k] * other.data[k][j]

        return Matrix(result)

    def print_matrix(self):
        """
        Print the matrix in a formatted way.
        """
        for row in self.data:
            print(" ".join(f"{val:5}" for val in row))

