def can_construct(s, words):
    """
    Returns True if `s` can be constructed by concatenating strings in `words`, otherwise False.
    """
    def can_construct_helper(s, words, memo):
        if s == "":
            return True
        if s in memo:
            return memo[s]

        for word in words:
            if s.startswith(word):
                if can_construct_helper(s[len(word):], words, memo):
                    memo[s] = True
                    return True

        memo[s] = False
        return False

    return can_construct_helper(s, words, {})

from collections import deque

def minimum_moves(grid):
    if not grid or not grid[0]:
        return -1

    m, n = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0)]  # Right, Down
    visited = [[False] * n for _ in range(m)]
    queue = deque([(0, 0, 0)])  # (row, col, steps)

    while queue:
        row, col, steps = queue.popleft()

        if row == m - 1 and col == n - 1:
            return steps

        if visited[row][col]:
            continue

        visited[row][col] = True

        max_steps = grid[row][col]
        for dr, dc in directions:
            for step in range(1, max_steps + 1):
                new_row, new_col = row + dr * step, col + dc * step
                if 0 <= new_row < m and 0 <= new_col < n and not visited[new_row][new_col]:
                    queue.append((new_row, new_col, steps + 1))

    return -1

