from collections import defaultdict

def longestSubarrayWithKDistinct(arr, k):
    if k == 0 or not arr:
        return 0

    left = 0
    max_length = 0
    char_count = defaultdict(int)

    for right in range(len(arr)):
        char_count[arr[right]] += 1

        while len(char_count) > k:
            char_count[arr[left]] -= 1
            if char_count[arr[left]] == 0:
                del char_count[arr[left]]
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

class Vehicle:
    def __init__(self, vehicle_type):
        self.vehicle_type = vehicle_type

class ParkingLot:
    def __init__(self, levels, rows_per_level, spots_per_row):
        self.levels = levels
        self.parking_space = [[[None for _ in range(spots_per_row)] for _ in range(rows_per_level)] for _ in range(levels)]
        self.spots_per_row = spots_per_row
        self.rows_per_level = rows_per_level

    def parkVehicle(self, vehicle):
        for level in range(self.levels):
            for row in range(self.rows_per_level):
                for spot in range(self.spots_per_row):
                    if self.parking_space[level][row][spot] is None:
                        self.parking_space[level][row][spot] = vehicle
                        return True
        return False

    def leaveVehicle(self, vehicle):
        for level in range(self.levels):
            for row in range(self.rows_per_level):
                for spot in range(self.spots_per_row):
                    if self.parking_space[level][row][spot] == vehicle:
                        self.parking_space[level][row][spot] = None
                        return True
        return False

    def getAvailableSpots(self):
        available_spots = 0
        for level in self.parking_space:
            for row in level:
                available_spots += row.count(None)
        return available_spots

    def isFull(self):
        return self.getAvailableSpots() == 0

