def beautiful_array(nums):
    def construct(l):
        if len(l) <= 1:
            return l
        odds = construct(l[::2])
        evens = construct(l[1::2])
        return odds + evens

    nums.sort()
    result = construct(nums)
    return result if is_beautiful(result) else []

def is_beautiful(nums):
    for i in range(len(nums)):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                return False
    return True

