def findSubstring(s, words):
    if not s or not words or not words[0]:
        return []

    word_length = len(words[0])
    word_count = len(words)
    substring_length = word_length * word_count
    word_frequency = {}
    for word in words:
        if word in word_frequency:
            word_frequency[word] += 1
        else:
            word_frequency[word] = 1

    result_indices = []

    for i in range(word_length):
        left = i
        window_words = {}
        word_used = 0

        for j in range(i, len(s) - word_length + 1, word_length):
            current_word = s[j:j + word_length]
            if current_word in word_frequency:
                if current_word in window_words:
                    window_words[current_word] += 1
                else:
                    window_words[current_word] = 1

                if window_words[current_word] <= word_frequency[current_word]:
                    word_used += 1
                while window_words[current_word] > word_frequency[current_word]:
                    left_word = s[left:left + word_length]
                    window_words[left_word] -= 1
                    if window_words[left_word] < word_frequency[left_word]:
                        word_used -= 1
                    left += word_length
                if word_used == word_count:
                    result_indices.append(left)
                    left_word = s[left:left + word_length]
                    window_words[left_word] -= 1
                    word_used -= 1
                    left += word_length
            else:
                window_words.clear()
                word_used = 0
                left = j + word_length

    return result_indices

