from collections import Counter

def check_inclusion(s: str, t: str) -> bool:
    """
    Checks if t contains a permutation that is a substring of s.
    """
    len_s, len_t = len(s), len(t)
    if len_s < len_t:
        return False

    count_t = Counter(t)
    count_window = Counter(s[:len_t])

    if count_window == count_t:
        return True

    for i in range(len_t, len_s):
        count_window[s[i]] += 1
        count_window[s[i - len_t]] -= 1
        if count_window[s[i - len_t]] == 0:
            del count_window[s[i - len_t]]

        if count_window == count_t:
            return True

    return False

