class AttendanceSystem:
    def __init__(self):
        self.attendance = {}
        self.total_days = set()
        self.attendance_record = {}

    def signIn(self, studentId, date):
        if studentId not in self.attendance:
            self.attendance[studentId] = set()
        self.attendance[studentId].add(date)
        self.total_days.add(date)

    def signOut(self, studentId, date):
        # Sign out operation for consistency, although we are only tracking sign in days for simplicity.
        if studentId not in self.attendance_record:
            self.attendance_record[studentId] = set()
        self.attendance_record[studentId].add(date)

    def calculateAttendance(self, studentId):
        attended_days = 0
        if studentId in self.attendance and studentId in self.attendance_record:
            attended_days = len(self.attendance[studentId].intersection(self.attendance_record[studentId]))
        total_class_days = len(self.total_days)
        if total_class_days == 0:
            return 0.0
        return (attended_days / total_class_days) * 100

