def find_critical_nodes(n, edges):
    from collections import defaultdict, deque

    def build_graph(n, edges):
        graph = defaultdict(list)
        for a, b in edges:
            graph[a].append(b)
            graph[b].append(a)
        return graph

    def bfs_count_components(graph, start, removed):
        visited = set()
        queue = deque([start])
        visited.add(start)

        while queue:
            node = queue.popleft()

            for neighbor in graph[node]:
                if neighbor not in visited and neighbor != removed:
                    visited.add(neighbor)
                    queue.append(neighbor)

        return visited

    def count_components(n, graph, removed):
        visited = set()
        count = 0

        for i in range(n):
            if i not in visited and i != removed:
                count += 1
                visited.update(bfs_count_components(graph, i, removed))

        return count

    graph = build_graph(n, edges)
    initial_components = count_components(n, graph, -1)
    critical_nodes = []

    for i in range(n):
        if count_components(n, graph, i) > initial_components:
            critical_nodes.append(i)

    return sorted(critical_nodes)

