def minimize_max_gap(scores, m):
    scores = sorted(scores)
    n = len(scores)
    if m <= 1:
        return 0

    def can(gap):
        count = 1
        last = scores[0]
        for x in scores[1:]:
            if x - last <= gap:
                count += 1
                last = x
                if count >= m:
                    return True
        return False

    left, right = 0, scores[-1] - scores[0]
    while left < right:
        mid = (left + right) // 2
        if can(mid):
            right = mid
        else:
            left = mid + 1
    return left

def flatten_dict(d, parent_key='', sep='_'):
    """
    Flattens a nested dictionary into a single-level dictionary with concatenated keys.

    :param d: The dictionary to flatten.
    :param parent_key: The base key string for recursion (used internally).
    :param sep: The separator to use between keys.
    :return: A flattened dictionary.
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

