def evaluate_expression(expression):
    """
    Evaluates a given mathematical expression and returns the result.

    :param expression: A string representing a valid mathematical expression.
    :return: An integer representing the result of the evaluated expression.
    """
    def evaluate(tokens, i):
        stack = []
        num = 0
        sign = '+'

        while i < len(tokens):
            token = tokens[i]
            if token.isdigit():
                num = num * 10 + int(token)
            if token in '+-*/' or i == len(tokens) - 1:
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack[-1] = stack[-1] * num
                elif sign == '/':
                    stack[-1] = int(stack[-1] / num)  # Ensure integer division

                sign = token
                num = 0

            if token == '(':
                num, i = evaluate(tokens, i + 1)
            elif token == ')':
                break

            i += 1

        return sum(stack), i

    return evaluate(expression, 0)[0]

def fibonacci(n):
    """
    Compute the nth Fibonacci number using recursion.

    Parameters:
    n (int): The position in the Fibonacci sequence.

    Returns:
    int or str: The nth Fibonacci number if n is a positive integer, otherwise an error message.
    """
    if n <= 0:
        return "Input should be a positive integer."
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

