def remove_and_sort(strings):
    """
    Removes duplicates from a list of strings and sorts them lexicographically,
    while preserving the case and order of first occurrence of each unique string.
    """
    seen = {}
    for s in reversed(strings):
        seen[s.lower()] = s
    return sorted(seen.values(), key=lambda s: s.lower())

