from typing import List
from collections import deque

def minWordsToFormTarget(words: List[str], target: str) -> int:
    def bfs():
        queue = deque([(target, 0)])  # (remaining target string, number of words used)
        seen = set()

        while queue:
            current_target, steps = queue.popleft()

            if current_target == "":
                return steps

            if current_target in seen:
                continue

            seen.add(current_target)

            for word in words:
                if current_target.startswith(word):
                    next_target = current_target[len(word):]
                    queue.append((next_target, steps + 1))

        return -1

    return bfs()

