class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def kthSmallest(root, k):
    """
    Returns the kth smallest element in a binary search tree (BST).

    :param root: TreeNode, the root of the BST
    :param k: int, the kth position to find the smallest element
    :return: int, the kth smallest element in the BST
    """
    def inorder_traversal(node):
        stack = []
        while node is not None or stack:
            while node is not None:
                stack.append(node)
                node = node.left
            node = stack.pop()
            yield node.val
            node = node.right

    iterator = inorder_traversal(root)
    for _ in range(k-1):
        next(iterator)
    return next(iterator)

def distinct_numbers_in_path(grid):
    """
    Given a matrix `grid` of dimensions n x m, return the number of distinct integers that 
    can be collected along any path from the top-left to the bottom-right corner.
    You are only allowed to move either down or right at any point in time.

    Parameters:
    grid (list[list[int]]): 2D list of integers

    Returns:
    int: Number of distinct integers collected along any path
    """
    from functools import lru_cache

    n = len(grid)
    m = len(grid[0])

    @lru_cache(None)
    def dfs(x, y):
        if x == n - 1 and y == m - 1:
            return {grid[x][y]}

        values = set()
        if x < n - 1:
            values.update(dfs(x + 1, y))
        if y < m - 1:
            values.update(dfs(x, y + 1))
        values.add(grid[x][y])
        return values

    return len(dfs(0, 0))

def max_area_of_island(grid):
    """
    Returns the maximum area of an island in the grid.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    def dfs(i, j):
        if i < 0 or j < 0 or i >= m or j >= n or grid[i][j] == 0:
            return 0
        grid[i][j] = 0  # mark visited by sinking the island
        area = 1  # current island's cell
        area += dfs(i - 1, j)
        area += dfs(i + 1, j)
        area += dfs(i, j - 1)
        area += dfs(i, j + 1)
        return area

    max_area = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                max_area = max(max_area, dfs(i, j))

    return max_area

