def lenLongestFibSubseq(arr):
    arr_set = set(arr)
    longest = 0
    n = len(arr)

    for i in range(n):
        for j in range(i + 1, n):
            x, y = arr[i], arr[j]
            length = 2

            while x + y in arr_set:
                x, y = y, x + y
                length += 1

            longest = max(longest, length)

    return longest if longest >= 3 else 0

def min_absolute_difference_indices(arr, x, y):
    x_indices = [i for i, val in enumerate(arr) if val == x]
    y_indices = [i for i, val in enumerate(arr) if val == y]

    if not x_indices or not y_indices:
        return -1

    min_diff = float('inf')
    for ix in x_indices:
        for iy in y_indices:
            min_diff = min(min_diff, abs(ix - iy))

    return min_diff

