def character_frequency_in_substrings(s, indices):
    """
    Compute the frequency of each character in the specified substrings.

    :param s: A string
    :param indices: A list of pairs where each pair represents the start and end indices of a substring
    :return: A list of dictionaries where each dictionary contains the frequency of characters in the substring
    """
    result = []
    for start, end in indices:
        substring = s[start:end+1]
        freq_dict = {}
        for char in substring:
            if char in freq_dict:
                freq_dict[char] += 1
            else:
                freq_dict[char] = 1
        result.append(freq_dict)
    return result

