def reverseKGroup(head, k):
    def reverse_linked_list(head, k):
        prev, curr = None, head
        for _ in range(k):
            nxt = curr.next
            curr.next = prev
            prev = curr
            curr = nxt
        return prev

    count = 0
    ptr = head

    while count < k and ptr:
        ptr = ptr.next
        count += 1

    if count == k:
        reversed_head = reverse_linked_list(head, k)
        head.next = reverseKGroup(ptr, k)
        return reversed_head

    return head

