def longestSubarray(nums):
    """
    Find the length of the longest contiguous subarray that contains at least
    one positive integer, one negative integer, and one zero.

    Parameters:
    nums (list): List of integers.

    Returns:
    int: Length of the longest subarray or 0 if no such subarray exists.
    """
    n = len(nums)
    max_len = 0

    for i in range(n):
        has_positive = has_negative = has_zero = False
        for j in range(i, n):
            if nums[j] > 0:
                has_positive = True
            elif nums[j] < 0:
                has_negative = True
            elif nums[j] == 0:
                has_zero = True

            if has_positive and has_negative and has_zero:
                max_len = max(max_len, j - i + 1)

    return max_len

def find_first_reach_index(prices, threshold):
    def helper(index, current_sum):
        if current_sum >= threshold:
            return index - 1
        if index == len(prices):
            return -1
        return helper(index + 1, current_sum + prices[index])

    return helper(0, 0)

def count_servers_within_distance(n, edges, start, dist):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    from collections import deque
    q = deque([(start, 0)])
    visited = {start}
    count = 0

    while q:
        node, d = q.popleft()
        if d > dist:
            continue
        count += 1
        if d == dist:
            continue
        for nei in graph[node]:
            if nei not in visited:
                visited.add(nei)
                q.append((nei, d + 1))

    return count

def remove_adjacent_duplicates(s: str) -> str:
    """
    Removes all duplicate adjacent characters from the input string.

    :param s: A string consisting of lowercase English letters.
    :return: A string with all duplicate adjacent characters removed.
    """
    if not s:
        return s

    result = [s[0]]

    for i in range(1, len(s)):
        if s[i] != result[-1]:
            result.append(s[i])

    return ''.join(result)

