import os

def search_keyword_in_files(file_paths, keyword):
    """
    Searches for a keyword in a list of CSV files and returns the locations where the keyword appears.

    Parameters:
    file_paths (list of str): List of file paths to search within.
    keyword (str): The keyword to search for.

    Returns:
    list of tuples: A list of tuples, each containing a file path and the line number where the keyword was found.
    """
    results = []

    for file_path in file_paths:
        if not os.path.exists(file_path):
            print(f"Warning: The file {file_path} does not exist.")
            continue

        try:
            with open(file_path, 'r', encoding='utf-8') as file:
                for line_number, line in enumerate(file, start=1):
                    if keyword in line:
                        results.append((file_path, line_number))
        except Exception as e:
            print(f"An error occurred while reading {file_path}: {e}")

    return results

def fibonacci(n, memo=None):
    """
    Computes the nth Fibonacci number using recursion with memoization.

    Parameters:
    n (int): The position in the Fibonacci sequence (non-negative integer).
    memo (dict): A dictionary to store previously computed Fibonacci numbers.

    Returns:
    int: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
        return memo[n]

