import re

def parse_polynomial(s):
    """
    Parses a polynomial expression string and returns a dictionary representing the polynomial.

    :param s: A string representing the polynomial expression.
    :return: A dictionary where keys are the powers of x and values are the corresponding coefficients.
    """
    pattern = r"([+-]?)\s*(\d*)(x?)(?:\^(\d*))?"
    polynomial = {}
    matches = re.finditer(pattern, s)

    for match in matches:
        sign, coeff, var, power = match.groups()
        sign_multiplier = -1 if sign == '-' else 1
        coeff = int(coeff) if coeff else (1 if var else 0)
        power = int(power) if power else (1 if var else 0)
        polynomial[power] = polynomial.get(power, 0) + (coeff * sign_multiplier)

    polynomial = {k: v for k, v in polynomial.items() if v != 0}

    return polynomial

# Example usage:
print(parse_polynomial("3x^2 - 2x + 5"))  # Output: {2: 3, 1: -2, 0: 5}
print(parse_polynomial("2x^2 + 3x - x + 4"))  # Output: {2: 2, 1: 2, 0: 4}
print(parse_polynomial("-x^2 + 5 - 3x"))  # Output: {2: -1, 1: -3, 0: 5}
print(parse_polynomial("7"))  # Output: {0: 7}
print(parse_polynomial("x"))  # Output: {1: 1}
print(parse_polynomial("-x"))  # Output: {1: -1}

def smallest_subarray_with_elements(arr, x, y):
    """
    Finds the smallest subarray that contains at least one occurrence of both x and y.

    :param arr: List of unique integers.
    :param x: Integer to be included in the subarray.
    :param y: Integer to be included in the subarray.
    :return: List representing the smallest subarray containing both x and y.
             Returns an empty list if no such subarray exists.
    """
    if x not in arr or y not in arr:
        return []

    n = len(arr)
    index_x, index_y = -1, -1
    min_len = float('inf')
    start, end = 0, 0

    for i in range(n):
        if arr[i] == x:
            index_x = i
        if arr[i] == y:
            index_y = i
        if index_x != -1 and index_y != -1:
            current_len = abs(index_x - index_y) + 1
            if current_len < min_len:
                min_len = current_len
                start = min(index_x, index_y)
                end = max(index_x, index_y)

    if min_len == float('inf'):
        return []
    return arr[start:end + 1]

class VotingSystem:
    def __init__(self):
        self.votes = {}
        self.candidates = {}

    def vote(self, voterId, candidate):
        if voterId in self.votes:
            previous_candidate = self.votes[voterId]
            self.candidates[previous_candidate] -= 1
            if self.candidates[previous_candidate] == 0:
                del self.candidates[previous_candidate]

        self.votes[voterId] = candidate
        if candidate in self.candidates:
            self.candidates[candidate] += 1
        else:
            self.candidates[candidate] = 1

    def retractVote(self, voterId):
        if voterId in self.votes:
            candidate = self.votes.pop(voterId)
            self.candidates[candidate] -= 1
            if self.candidates[candidate] == 0:
                del self.candidates[candidate]

    def getVoteCount(self, candidate):
        if candidate in self.candidates:
            return self.candidates[candidate]
        else:
            return 0

from collections import deque

def min_steps_with_k_obstacles(grid, k):
    """
    Returns the minimum number of steps to walk from [0, 0] to [m-1, n-1] 
    considering at most k obstacles removal.
    """
    m, n = len(grid), len(grid[0])
    if m == 1 and n == 1:
        return 0 if grid[0][0] == 0 else -1

    def is_valid(x, y):
        return 0 <= x < m and 0 <= y < n

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0, 0)])  # (x, y, steps, obstacles_removed)
    visited = {(0, 0, 0)}

    while queue:
        x, y, steps, obstacles_removed = queue.popleft()

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if is_valid(nx, ny):
                new_obstacles_removed = obstacles_removed + grid[nx][ny]

                if new_obstacles_removed <= k and (nx, ny, new_obstacles_removed) not in visited:
                    if nx == m - 1 and ny == n - 1:
                        return steps + 1

                    queue.append((nx, ny, steps + 1, new_obstacles_removed))
                    visited.add((nx, ny, new_obstacles_removed))

    return -1

