def can_cross(stones, k):
    """
    Determines if the frog can cross the river by jumping on stones

    Parameters:
    stones (List[int]): Positions of the stones in a one-dimensional array
    k (int): Maximum distance the frog can jump initially

    Returns:
    bool: True if the frog can reach the last stone, False otherwise
    """

    def can_reach(stones, pos, jump, memo):
        if (pos, jump) in memo:
            return memo[(pos, jump)]

        idx = stones.index(pos)
        if idx == len(stones) - 1:
            return True

        for next_jump in range(jump - 1, jump + 2):
            if next_jump > 0 and pos + next_jump in stones:
                if can_reach(stones, pos + next_jump, next_jump, memo):
                    memo[(pos, jump)] = True
                    return True

        memo[(pos, jump)] = False
        return False

    return can_reach(stones, stones[0], k, {})

