def group_pairs(nums):
    """
    Groups pairs of positive and negative numbers in the input array 'nums'.

    Parameters:
        nums (list): List of integers with each pair of positive and negative numbers.

    Returns:
        list: List where positive numbers are paired with their corresponding negative numbers.
    """

    pairs = {}
    result = []

    for num in nums:
        if num > 0:
            pairs[num] = None
        else:
            pairs[-num] = num

    for num in nums:
        if num > 0 and pairs[num] is not None:
            result.append(num)
            result.append(pairs[num])
            pairs[num] = None  # Mark the pair as processed

    return result

