def is_prime(num):
    """
    Helper function to check if a number is prime.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def next_prime(n):
    """
    Returns the smallest prime number that is greater than n.
    """
    candidate = n + 1
    while not is_prime(candidate):
        candidate += 1
    return candidate

