def max_non_adjacent_sum(arr):
    """
    Returns the maximum sum of elements in arr such that no two elements are adjacent.
    """
    if not arr:
        return 0
    if len(arr) == 1:
        return arr[0]

    include = arr[0]
    exclude = 0

    for i in range(1, len(arr)):
        new_exclude = max(include, exclude)
        include = exclude + arr[i]
        exclude = new_exclude

    return max(include, exclude)

