def four_sum(nums, target):
    """
    Determines if there are four distinct elements in nums such that their sum is equal to target.

    Arguments:
    nums -- list of integers
    target -- integer target sum

    Returns:
    bool -- True if such a quadruplet exists, False otherwise
    """
    nums.sort()
    n = len(nums)
    for i in range(n - 3):
        for j in range(i + 1, n - 2):
            left, right = j + 1, n - 1
            while left < right:
                current_sum = nums[i] + nums[j] + nums[left] + nums[right]
                if current_sum == target:
                    return True
                elif current_sum < target:
                    left += 1
                else:
                    right -= 1
    return False

