class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class SortedArrayToBST:
    def sortedArrayToBST(self, nums):
        """
        Converts a sorted array into a height-balanced binary search tree (BST).

        :param nums: List[int], a sorted array
        :return: TreeNode, the root of the height-balanced BST
        """
        if not nums:
            return None

        def convertListToBST(left, right):
            if left > right:
                return None

            mid = (left + right) // 2
            node = TreeNode(nums[mid])
            node.left = convertListToBST(left, mid - 1)
            node.right = convertListToBST(mid + 1, right)
            return node

        return convertListToBST(0, len(nums) - 1)

