from collections import defaultdict
import itertools

def find_common_subsequences(s1, s2, length):
    """
    Returns True if there is at least one common subsequence of given length `length` between strings `s1` and `s2`.
    """
    s1_subsequences = {s1[i:i+length] for i in range(len(s1) - length + 1)}
    s2_subsequences = {s2[i:i+length] for i in range(len(s2) - length + 1)}
    return not s1_subsequences.isdisjoint(s2_subsequences)

def find_group_count(files, k):
    """
    Returns the number of connected groups of files based on similarity defined by common subsequence of length `k`.
    """
    n = len(files)
    if n == 0:
        return 0

    adj_list = defaultdict(list)
    for i, j in itertools.combinations(range(n), 2):
        if find_common_subsequences(files[i], files[j], k):
            adj_list[i].append(j)
            adj_list[j].append(i)

    visited = [False] * n

    def dfs(file_index):
        stack = [file_index]
        while stack:
            node = stack.pop()
            for neighbor in adj_list[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)

    group_count = 0
    for i in range(n):
        if not visited[i]:
            group_count += 1
            visited[i] = True
            dfs(i)

    return group_count

