def min_sessions(tasks, sessionTime):
    """
    Returns the minimum number of sessions required to complete all tasks
    """

    n = len(tasks)
    max_mask = 1 << n
    dp = [float('inf')] * max_mask
    dp[0] = 0

    for mask in range(max_mask):
        current_sum = 0
        for i in range(n):
            if mask & (1 << i):
                current_sum += tasks[i]
        for j in range(n):
            if not (mask & (1 << j)):
                new_mask = mask | (1 << j)
                if current_sum % sessionTime + tasks[j] <= sessionTime:
                    dp[new_mask] = min(dp[new_mask], dp[mask] + (1 if current_sum % sessionTime == 0 else 0))
                else:
                    dp[new_mask] = min(dp[new_mask], dp[mask] + 1)

    return dp[max_mask - 1]

