def countDistinctIslands(grid):
    def dfs(x, y, pos, shape):
        if (x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] == 0):
            return
        grid[x][y] = 0
        shape.append(pos)
        dfs(x + 1, y, (pos[0] + 1, pos[1]), shape)
        dfs(x - 1, y, (pos[0] - 1, pos[1]), shape)
        dfs(x, y + 1, (pos[0], pos[1] + 1), shape)
        dfs(x, y - 1, (pos[0], pos[1] - 1), shape)

    shapes = set()
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                shape = []
                dfs(i, j, (0, 0), shape)
                shapes.add(tuple(shape))

    return len(shapes)

