from typing import List

def max_trees_to_visit(heights: List[int], d: int) -> int:
    n = len(heights)
    dp = [1] * n

    # Sort index based on heights for easier calculation
    index = list(range(n))
    index.sort(key=lambda x: heights[x])

    for i in index:
        for jump in range(1, d + 1):
            if i + jump < n and heights[i + jump] > heights[i]:
                dp[i + jump] = max(dp[i + jump], dp[i] + 1)
            if i - jump >= 0 and heights[i - jump] > heights[i]:
                dp[i - jump] = max(dp[i - jump], dp[i] + 1)

    return max(dp)

