def countUnobstructedBuildings(heights):
    """
    Returns the count of buildings with an unobstructed view.
    """
    if not heights or not heights[0]:
        return 0

    m, n = len(heights), len(heights[0])
    unobstructed_count = 0

    for i in range(m):
        for j in range(n):
            height = heights[i][j]
            unobstructed = all(heights[i][k] < height for k in range(n) if k != j) and \
                           all(heights[k][j] < height for k in range(m) if k != i)
            if unobstructed:
                unobstructed_count += 1

    return unobstructed_count

