def min_slicing_operations(nums):
    """
    Returns the minimum number of slicing operations required to sort nums in non-decreasing order.
    """
    if not nums:
        return 0

    sorted_nums = sorted(nums)
    n = len(nums)

    start, end = None, None

    for i in range(n):
        if nums[i] != sorted_nums[i]:
            if start is None:
                start = i
            end = i

    if start is None:
        return 0  # Already sorted

    if nums[start:end+1] == sorted_nums[start:end+1][::-1]:
        return 1

    return 2

