import heapq

def schedule_courses(courses):
    # Sort courses by their end time
    courses.sort(key=lambda x: x[1])
    total_time = 0
    max_courses = []

    for duration, end_time in courses:
        if total_time + duration <= end_time:
            heapq.heappush(max_courses, -duration)
            total_time += duration
        elif max_courses and -max_courses[0] > duration:
            total_time += duration + heapq.heappop(max_courses)
            heapq.heappush(max_courses, -duration)
            total_time -= -max_courses[0]

    return len(max_courses)

