def longest_non_decreasing_team(heights):
    n = len(heights)
    # Initialize dp array where dp[i] represents the length of the longest team ending at index i
    dp = [1] * n

    for i in range(1, n):
        if heights[i] >= heights[i - 1]:
            dp[i] = dp[i - 1] + 1

    # The result is the maximum value in dp array
    return max(dp)

def longest_increasing_subsequence(nums):
    """
    Finds and returns the longest increasing subsequence of the given list of integers.

    :param nums: List[int] - A list of integers.
    :return: List[int] - The longest increasing subsequence.
    """
    if not nums:
        return []

    tails = [0] * len(nums)
    tails[0] = nums[0]
    size = 1

    for num in nums[1:]:
        if num > tails[size - 1]:
            tails[size] = num
            size += 1
        else:
            left, right = 0, size - 1
            while left < right:
                mid = (left + right) // 2
                if tails[mid] < num:
                    left = mid + 1
                else:
                    right = mid
            tails[left] = num

    result = []
    current_value = tails[size - 1]
    for i in range(len(nums) - 1, -1, -1):
        if nums[i] == current_value:
            result.append(nums[i])
            if size > 1:
                current_value = tails[size - 2]
            size -= 1

    return result[::-1]

