import json
from datetime import datetime
from enum import Enum

class CustomEncoder(json.JSONEncoder):
    """Custom JSON encoder that handles datetime and Enum types."""
    def default(self, obj):
        if isinstance(obj, (datetime, Enum)):
            return str(obj)
        if hasattr(obj, '__dict__'):
            return obj.__dict__
        return super().default(obj)

def serialize_object(obj):
    """
    Serializes a given Python object into a JSON string.

    Args:
        obj: The Python object to serialize.

    Returns:
        A JSON string representation of the object.

    Raises:
        TypeError: If the object cannot be serialized.
    """
    try:
        return json.dumps(obj, cls=CustomEncoder)
    except TypeError as e:
        raise TypeError(f"Object of type {obj.__class__.__name__} is not JSON serializable") from e

