def longest_subarray_with_diff(arr, d):
    """
    Given an integer array `arr`, returns the length of the longest subarray
    in which the absolute difference between any two elements is <= d.
    """
    if not arr:
        return 0

    n = len(arr)
    max_length = 1
    start = 0

    for end in range(1, n):
        if max(arr[start:end+1]) - min(arr[start:end+1]) <= d:
            max_length = max(max_length, end - start + 1)
        else:
            start += 1
            while start < end and (max(arr[start:end+1]) - min(arr[start:end+1]) > d):
                start += 1

    return max_length

