def find_insert_index(heights, new_height):
    """
    Returns the index at which the new_height should be inserted in heights to keep it sorted.
    This function uses binary search to achieve O(log n) time complexity.
    """
    left, right = 0, len(heights)

    while left < right:
        mid = (left + right) // 2
        if heights[mid] < new_height:
            left = mid + 1
        else:
            right = mid

    return left

