def max_gold(grid):
    """
    Returns the maximum amount of gold that can be collected starting from the top-left corner
    to the bottom-right corner of the grid.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Create a 2D dp array to store the maximum gold collected upto each cell
    dp = [[0] * n for _ in range(m)]

    dp[0][0] = grid[0][0]

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            if i > 0 and j > 0:
                dp[i][j] = max(dp[i][j], dp[i-1][j-1] + grid[i][j])
            if i > 0:
                dp[i][j] = max(dp[i][j], dp[i-1][j] + grid[i][j])
            if j > 0:
                dp[i][j] = max(dp[i][j], dp[i][j-1] + grid[i][j])

    return dp[m-1][n-1]

