def accountsMerge(accounts):
    from collections import defaultdict

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        parent[find(x)] = find(y)

    # Map all emails to unique IDs and initialize the parent array
    email_to_id = {}
    parent = {}
    email_to_name = {}
    idx = 0

    for account in accounts:
        name = account[0]
        for email in account[1:]:
            if email not in email_to_id:
                email_to_id[email] = idx
                parent[idx] = idx
                idx += 1
            email_to_name[email] = name
            union(email_to_id[account[1]], email_to_id[email])

    # Group emails by their root parent
    id_to_emails = defaultdict(list)
    for email, id_ in email_to_id.items():
        root_id = find(id_)
        id_to_emails[root_id].append(email)

    # Build the output
    merged_accounts = []
    for emails in id_to_emails.values():
        emails.sort()
        name = email_to_name[emails[0]]
        merged_accounts.append([name] + emails)

    return merged_accounts

