        """
        Updates the score of the player with `playerId` by adding the `score` to their current score.
        If the player does not exist, they are added to the leaderboard with the given `score`.
        """
        if playerId not in self.scores:
            self.scores[playerId] = 0
        self.scores[playerId] += score

    def top(self, K):
        """
        Returns the sum of the scores of the top `K` players.
        """
        top_scores = sorted(self.scores.values(), reverse=True)[:K]
        return sum(top_scores)

    def reset(self, playerId):
        """
        Resets the score of the player with `playerId` to `0`.
        """
        if playerId in self.scores:
            self.scores[playerId] = 0

