def power(x, y):
    """
    Calculate the power of a number x raised to y without using the built-in power operator ** or any math library functions.

    :param x: The base number (integer)
    :param y: The exponent (integer)
    :return: The result of x raised to the power of y (float)
    """
    # Base case: any number raised to the power of 0 is 1
    if y == 0:
        return 1.0
    # If y is negative, calculate the positive power and take the reciprocal
    elif y < 0:
        return 1.0 / power(x, -y)
    # Recursive case: multiply x by the result of x raised to the power of y-1
    else:
        return x * power(x, y - 1)

