        self.left = left
        self.right = right

def sum_of_leaf_nodes(root: TreeNode) -> int:
    """
    Computes the sum of all leaf nodes in a binary tree using recursion.

    :param root: The root node of the binary tree.
    :return: The sum of all leaf nodes in the tree.
    """
    def is_leaf(node):
        return node is not None and node.left is None and node.right is None

    def recursive_sum(node):
        if node is None:
            return 0
        if is_leaf(node):
            return node.val
        return recursive_sum(node.left) + recursive_sum(node.right)

    return recursive_sum(root)

def find_closest_value(sorted_list, target):
    """
    Returns the element in the sorted list that is closest to the target.
    If two elements are equally close, returns the smaller one.

    :param sorted_list: List[int] - A sorted list of integers.
    :param target: int - The target integer.
    :return: int - The closest value in the sorted list to the target.
    """
    if not sorted_list:
        return None  # Handle the case of an empty list, if necessary.

    left, right = 0, len(sorted_list) - 1
    closest = sorted_list[0]  # Initialize with the first element.

    while left <= right:
        mid = (left + right) // 2
        current_value = sorted_list[mid]

        if abs(current_value - target) < abs(closest - target):
            closest = current_value
        elif abs(current_value - target) == abs(closest - target):
            closest = min(current_value, closest)

        if current_value < target:
            left = mid + 1
        elif current_value > target:
            right = mid - 1
        else:
            return current_value

    return closest

from typing import List

def find_longest_common_prefix(words: List[str], text: str) -> str:
    """
    Finds the longest common prefix among all words in the list that also appears as a prefix in the string text.

    :param words: List of words to find the common prefix from.
    :param text: The string in which to check for the common prefix.
    :return: The longest common prefix that appears in the text, or an empty string if none exists.
    """
    def common_prefix(str1: str, str2: str) -> str:
        """
        Finds the common prefix between two strings.

        :param str1: First string.
        :param str2: Second string.
        :return: The common prefix of str1 and str2.
        """
        min_length = min(len(str1), len(str2))
        for i in range(min_length):
            if str1[i] != str2[i]:
                return str1[:i]
        return str1[:min_length]

    if not words:
        return ""

    prefix = words[0]

    for word in words[1:]:
        prefix = common_prefix(prefix, word)
        if not prefix:
            return ""

    if text.startswith(prefix):
        return prefix

    for length in range(len(prefix), 0, -1):
        if text.startswith(prefix[:length]):
            return prefix[:length]

    return ""

def word_frequencies(text):
    """
    Processes a given string to return a list of tuples containing each word in lowercase
    and its frequency in the text, sorted alphabetically by the word.

    :param text: A string containing words separated by spaces.
    :return: A list of tuples with each tuple containing a word and its frequency.
    """
    text = text.lower()
    words = text.split()
    word_count = {}

    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    return sorted(word_count.items())

def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

