    Computes the maximum depth of nesting in a nested dictionary.

    Parameters:
    d (any): The input which may or may not be a dictionary.

    Returns:
    int: The maximum depth of the dictionary, or 0 if the input is not a dictionary or is empty.
    """
    if not isinstance(d, dict) or not d:
        return 0
    else:
        return 1 + max(find_max_depth(value) for value in d.values())

def can_partition_k_subsets(nums, k):
    """
    Determine if the list nums can be partitioned into k non-empty subsets 
    with equal sums.
    """
    total_sum = sum(nums)
    if total_sum % k != 0:
        return False

    target = total_sum // k
    nums.sort(reverse=True)
    used = [False] * len(nums)

    def backtrack(k, start, current_sum):
        if k == 0:
            return True
        if current_sum == target:
            return backtrack(k-1, 0, 0)
        for i in range(start, len(nums)):
            if not used[i] and current_sum + nums[i] <= target:
                used[i] = True
                if backtrack(k, i+1, current_sum + nums[i]):
                    return True
                used[i] = False
        return False

    return backtrack(k, 0, 0)

