    """
    Determines if each string in `words` can be formed using the characters in `chars`.
    Returns the sum of the lengths of all the strings in `words` that can be formed.
    """
    from collections import Counter

    chars_count = Counter(chars)

    def can_form(word):
        word_count = Counter(word)
        for char, count in word_count.items():
            if count > chars_count.get(char, 0):
                return False
        return True

