from typing import List

class Solution:
    def __init__(self, s: str, dict: List[str]):
        self.s = s
        self.dict = set(dict)  # Use a set for faster lookups
        self.memo = {}

    def canSegment(self) -> bool:
        return self._canSegment(self.s)

    def _canSegment(self, s: str) -> bool:
        if not s:
            return True
        if s in self.memo:
            return self.memo[s]

        for i in range(1, len(s) + 1):
            prefix = s[:i]
            if prefix in self.dict and self._canSegment(s[i:]):
                self.memo[s] = True
                return True

        self.memo[s] = False
        return False

from collections import Counter

def is_universal(b, words):
    """
    Helper function to determine if string b is a universal string for the array words.
    """
    b_counter = Counter(b)
    for word in words:
        word_counter = Counter(word)
        for char, count in word_counter.items():
            if b_counter[char] < count:
                return False
    return True

def universal_strings(words1, words2):
    """
    Returns an array of strings in words2 that are universal strings for words1.
