from typing import Optional

class TreeNode:
    """
    A class representing a node in a Binary Search Tree (BST).

    Attributes:
    - value (int): The value stored in the node.
    - left (Optional[TreeNode]): A reference to the left child.
    - right (Optional[TreeNode]): A reference to the right child.
    """
    def __init__(self, value: int):
        self.value = value
        self.left: Optional[TreeNode] = None
        self.right: Optional[TreeNode] = None

class BinarySearchTree:
    """
    A class representing a Binary Search Tree (BST).

    Methods:
    - insert(value: int) -> None: Inserts a new value into the BST.
    - search(value: int) -> bool: Searches for a value in the BST.
    - delete(value: int) -> None: Deletes a value from the BST.
    - in_order_traversal(root: Optional[TreeNode]) -> None: Prints the in-order traversal of the BST.
    """
    def __init__(self):
        self.root: Optional[TreeNode] = None

    def insert(self, value: int) -> None:
        """
        Inserts a new value into the BST. Duplicates go to the right subtree.
        """
        if self.root is None:
            self.root = TreeNode(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, current_node: TreeNode, value: int) -> None:
        """
        Helper method to insert a new value recursively.
        """
        if value <= current_node.value:
            if current_node.left is None:
                current_node.left = TreeNode(value)
            else:
                self._insert_recursively(current_node.left, value)
        else:
            if current_node.right is None:
                current_node.right = TreeNode(value)
            else:
                self._insert_recursively(current_node.right, value)

    def search(self, value: int) -> bool:
        """
        Searches for a value in the BST.
        """
        return self._search_recursively(self.root, value)

    def _search_recursively(self, current_node: Optional[TreeNode], value: int) -> bool:
        """
        Helper method to search for a value recursively.
        """
        if current_node is None:
            return False
        if current_node.value == value:
            return True
        if value < current_node.value:
            return self._search_recursively(current_node.left, value)
        return self._search_recursively(current_node.right, value)

    def delete(self, value: int) -> None:
        """
        Deletes a value from the BST.
        """
        self.root = self._delete_recursively(self.root, value)

    def _delete_recursively(self, current_node: Optional[TreeNode], value: int) -> Optional[TreeNode]:
        """
        Helper method to delete a value recursively.
        """
        if current_node is None:
            return None

        if value < current_node.value:
            current_node.left = self._delete_recursively(current_node.left, value)
        elif value > current_node.value:
            current_node.right = self._delete_recursively(current_node.right, value)
        else:
            if current_node.left is None:
                return current_node.right
            elif current_node.right is None:
                return current_node.left

            current_node.value = self._min_value_node(current_node.right).value
            current_node.right = self._delete_recursively(current_node.right, current_node.value)

        return current_node

    def _min_value_node(self, node: TreeNode) -> TreeNode:
        """
        Finds the node with the minimum value in a subtree.
        """
        current = node
        while current.left is not None:
            current = current.left
        return current

    def in_order_traversal(self, root: Optional[TreeNode]) -> None:
        """
        Prints the in-order traversal of the BST.
        """
        if root:
            self.in_order_traversal(root.left)
            print(root.value, end=" ")
            self.in_order_traversal(root.right)

def is_possible_to_partition(n, edges, k):
    from collections import defaultdict, deque

    if k > n:
        return False

    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    color = [-1] * n

    def bfs(start):
        queue = deque([start])
        color[start] = 0
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if color[neighbor] == -1:
                    color[neighbor] = 1 - color[node]
                    queue.append(neighbor)
                elif color[neighbor] == color[node]:
                    return False
        return True

    for node in range(n):
        if color[node] == -1:
            if not bfs(node):
                return False

    return True

