def min_moves_to_convert(s, t, k):
    """
    Returns the minimum number of moves required to convert string s into string t using at most k moves.
    If it's not possible, returns -1.
    """
    # Initial checks for quick returns
    if len(s) != len(t):
        return -1

    differing_positions = []
    for i in range(len(s)):
        if s[i] != t[i]:
            differing_positions.append(i)

    required_moves = len(differing_positions)

    if required_moves <= k:
        return required_moves
    else:
        return -1

