def transform_array(target, n):
    operations = []
    arr = [0] * n

    for i in range(len(target)):
        while arr[i] < target[i]:
            operations.append(f"Increase {i}")
            arr[i] += 1
        while arr[i] > target[i]:
            operations.append(f"Decrease {i}")
            arr[i] -= 1

    return operations

def max_profit(prices):
    """
    Calculate the maximum profit from a single buy and sell transaction.

    :param prices: List[int] - A list of integers representing the stock prices on different days.
    :return: int - The maximum profit that can be achieved.
    """
    if not prices:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

import json

def convert_to_json(data):
    """
    Converts all integer values in a dictionary to strings and returns a JSON string representation.

    :param data: A dictionary that may contain nested dictionaries and integer values.
    :return: A JSON string with all integer values converted to strings.
    """
    def convert_integers_to_strings(d):
        for key, value in d.items():
            if isinstance(value, int):
                d[key] = str(value)
            elif isinstance(value, dict):
                convert_integers_to_strings(value)

    convert_integers_to_strings(data)
    return json.dumps(data)

