def is_valid_parentheses(s: str) -> bool:
    """
    Determines if the input string s has balanced parentheses.

    :param s: A string containing only the characters '(', ')', '{', '}', '[' and ']'.
    :return: True if the string has balanced parentheses, otherwise False.
    """
    stack = []
    pairs = {"(": ")", "{": "}", "[": "]"}

    for char in s:
        if char in pairs:
            stack.append(char)
        else:
            if stack and pairs[stack[-1]] == char:
                stack.pop()
            else:
                return False

    return not stack

class TaskManager:
    def __init__(self):
        self.tasks = {}
        self.tasks_by_priority = {}

    def addTask(self, taskId, priority):
        if taskId not in self.tasks:
            self.tasks[taskId] = {
                'priority': priority,
                'users': set()
            }
            if priority not in self.tasks_by_priority:
                self.tasks_by_priority[priority] = []
            self.tasks_by_priority[priority].append(taskId)

    def assignUserToTask(self, taskId, userId):
        if taskId in self.tasks and userId not in self.tasks[taskId]['users']:
            self.tasks[taskId]['users'].add(userId)

    def getUsersAssignedToTask(self, taskId):
        if taskId in self.tasks:
            return list(self.tasks[taskId]['users'])
        return []

    def getTasksByPriority(self, priority):
        if priority in self.tasks_by_priority:
            return self.tasks_by_priority[priority]
        return []

class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        new_node = TreeNode(value)
        if self.root is None:
            self.root = new_node
        else:
            queue = [self.root]
            while queue:
                current = queue.pop(0)
                if not current.left:
                    current.left = new_node
                    break
                else:
                    queue.append(current.left)
                if not current.right:
                    current.right = new_node
                    break
                else:
                    queue.append(current.right)

    def maxDepth(self):
        def depth(node):
            if not node:
                return 0
            left_depth = depth(node.left)
            right_depth = depth(node.right)
            return max(left_depth, right_depth) + 1

        return depth(self.root)

