def stable_matching(preferences):
    n = len(preferences)
    student_preference_lists = preferences
    college_preference_lists = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            college_preference_lists[j].append(i)

    free_students = list(range(n))
    student_proposals = {i: 0 for i in range(n)}
    student_assignments = [-1] * n
    college_assignments = [-1] * n

    while free_students:
        student = free_students.pop(0)
        college = student_preference_lists[student][student_proposals[student]]
        student_proposals[student] += 1

        if college_assignments[college] == -1:
            college_assignments[college] = student
            student_assignments[student] = college
        else:
            current_assigned_student = college_assignments[college]
            current_preference_index = college_preference_lists[college].index(current_assigned_student)
            new_preference_index = college_preference_lists[college].index(student)

            if new_preference_index < current_preference_index:
                college_assignments[college] = student
                student_assignments[student] = college
                free_students.append(current_assigned_student)
                student_assignments[current_assigned_student] = -1
            else:
                free_students.append(student)

    return student_assignments

