from collections import deque

def is_one_letter_diff(word1, word2):
    """
    Check if word1 can be transformed to word2 by changing exactly one character.
    """
    diff_count = sum(1 for a, b in zip(word1, word2) if a != b)
    return diff_count == 1

def shortest_transformation_sequence(start, end, words):
    """
    Returns the length of the shortest transformation sequence from start to end word by changing exactly one character each step.
    If no such sequence exists, return 0.
    """
    if end not in words:
        return 0

    queue = deque([(start, 1)])  # (current_word, current_length)
    visited = set(start)

    while queue:
        current_word, current_length = queue.popleft()

        for word in list(words):
            if is_one_letter_diff(current_word, word):
                if word == end:
                    return current_length + 1
                if word not in visited:
                    visited.add(word)
                    queue.append((word, current_length + 1))

    return 0

