def min_swaps_to_transform(start, goal):
    """
    Returns the minimum number of swaps required to transform 'start' into 'goal'.
    If it is impossible, return -1.
    """
    if sorted(start) != sorted(goal):
        return -1

    def count_swaps(s1, s2):
        swaps = 0
        s1, s2 = list(s1), list(s2)
        for i in range(len(s1)):
            if s1[i] != s2[i]:
                swap_index = s1.index(s2[i], i)
                s1[i], s1[swap_index] = s1[swap_index], s1[i]
                swaps += 1
        return swaps

    return count_swaps(start, goal)

