def max_jumps(arr, d):
    def dfs(i, dp):
        if dp[i] != -1:
            return dp[i]
        max_reach = 1
        for direction in [-1, 1]:
            for j in range(1, d + 1):
                new_index = i + direction * j
                if new_index < 0 or new_index >= len(arr) or arr[new_index] >= arr[i]:
                    break
                max_reach = max(max_reach, 1 + dfs(new_index, dp))
        dp[i] = max_reach
        return dp[i]

    n = len(arr)
    dp = [-1] * n
    return max(dfs(i, dp) for i in range(n))

