def checkValidString(s):
    left_min = left_max = 0
    for char in s:
        if char == '(':
            left_min += 1
            left_max += 1
        elif char == ')':
            left_min = max(left_min - 1, 0)
            left_max -= 1
        else:  # char == '*'
            left_min = max(left_min - 1, 0)
            left_max += 1
        if left_max < 0:
            return False
    return left_min == 0

from itertools import combinations

def max_length_of_concatenated_keys(words, k):
    """
    Returns the length of the longest concatenation of any k keys from the array
    such that each key in the concatenation has unique characters and no two keys
    have any common characters.
    """
    def has_unique_characters(s):
        """
        Check if all characters in the string are unique.
        """
        return len(s) == len(set(s))

    def can_concatenate(s1, s2):
        """
        Check if two strings have no common characters.
        """
        return set(s1).isdisjoint(set(s2))

    valid_combinations = []
    for word_list in combinations(words, k):
        concatenated = "".join(word_list)
        if all(has_unique_characters(word) for word in word_list):
            if all(can_concatenate(word_list[i], word_list[j]) for i in range(len(word_list)) for j in range(i + 1, len(word_list))):
                valid_combinations.append(concatenated)

    return max(len(combo) for combo in valid_combinations) if valid_combinations else 0

