def is_palindrome(s):
    return s == s[::-1]

def split_into_palindromes(s, k):
    n = len(s)
    result = []

    def backtrack(start, cut):
        if cut == 0:
            if start == n:
                return True
            return False

        for end in range(start + 1, n + 1):
            sub_str = s[start:end]
            if is_palindrome(sub_str):
                result.append(sub_str)
                if backtrack(end, cut - 1):
                    return True
                result.pop()

        return False

    if backtrack(0, k):
        return result
    else:
        return []

