def mergeTrees(root1, root2):
    """
    Merges two binary trees into one by summing overlapping nodes.
    """
    if not root1 and not root2:
        return None
    if not root1:
        return root2
    if not root2:
        return root1

    merged = TreeNode(root1.val + root2.val)
    merged.left = mergeTrees(root1.left, root2.left)
    merged.right = mergeTrees(root1.right, root2.right)

    return merged

def max_path_sum(matrix):
    if not matrix or not matrix[0] or matrix[0][0] < 0 or matrix[-1][-1] < 0:
        return -1

    n = len(matrix)
    dp = [[-1] * n for _ in range(n)]

    # Initialize the starting cell
    dp[0][0] = matrix[0][0]

    # Fill in the dp table
    for i in range(n):
        for j in range(n):
            if matrix[i][j] < 0:
                dp[i][j] = -1
            else:
                if i > 0 and dp[i-1][j] != -1:
                    dp[i][j] = max(dp[i][j], dp[i-1][j] + matrix[i][j])
                if j > 0 and dp[i][j-1] != -1:
                    dp[i][j] = max(dp[i][j], dp[i][j-1] + matrix[i][j])

    return dp[-1][-1] if dp[-1][-1] != -1 else -1

