def min_value(expression):
    def dfs(nums, ops):
        if not ops:
            return nums[0]

        min_val = float('inf')
        for i in range(len(ops)):
            left = dfs(nums[:i+1], ops[:i])
            right = dfs(nums[i+1:], ops[i+1:])
            if ops[i] == '+':
                current_val = left + right
            else:
                current_val = left * right
            min_val = min(min_val, current_val)

        return min_val

    nums, ops = [], []
    i = 0
    while i < len(expression):
        if expression[i].isdigit():
            num = 0
            while i < len(expression) and expression[i].isdigit():
                num = num * 10 + int(expression[i])
                i += 1
            nums.append(num)
        else:
            ops.append(expression[i])
            i += 1

    return dfs(nums, ops)

