def is_complete_binary_tree(nums):
    """
    Determine if the binary tree represented by nums is complete.

    :param nums: List of integers representing the level-order traversal of the binary tree.
    :return: True if the binary tree is complete, otherwise False.
    """

    if not nums:
        return True

    n = len(nums)
    for i in range(n):
        if nums[i] is None:
            if any(nums[j] is not None for j in range(i + 1, n)):
                return False
    return True

