from collections import defaultdict, deque

def can_be_split(n, dislikes):
    """
    Determines if it's possible to split `n` employees into two teams such that
    no pair of employees who do not get along are on the same team.

    Args:
    - n (int): The number of employees.
    - dislikes (List[List[int]]): List of pairs of employees that do not get along.

    Returns:
    - bool: True if it is possible to split the employees, False otherwise.
    """
    def bfs(source):
        queue = deque([source])
        color[source] = 0
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in color:
                    color[neighbor] = 1 - color[node]
                    queue.append(neighbor)
                elif color[neighbor] == color[node]:
                    return False
        return True

    graph = defaultdict(list)
    for a, b in dislikes:
        graph[a].append(b)
        graph[b].append(a)

    color = {}
    for node in range(1, n+1):
        if node not in color:
            if not bfs(node):
                return False
    return True

