class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def dfs(node, depth, nodes_by_level):
    if not node:
        return
    if depth in nodes_by_level:
        nodes_by_level[depth].append(node.val)
    else:
        nodes_by_level[depth] = [node.val]
    dfs(node.left, depth + 1, nodes_by_level)
    dfs(node.right, depth + 1, nodes_by_level)

def min_sum_covering_levels(root, k):
    """
    Return the minimum sum of values of k nodes that cover all levels.
    """
    if not root:
        return 0

    nodes_by_level = {}
    dfs(root, 0, nodes_by_level)

    all_nodes = sorted([node for level in nodes_by_level.values() for node in level])
    return sum(all_nodes[:k])

