def shortest_exact_k_distinct_pages(pages: list[str], k: int) -> int:
    from collections import defaultdict

    n = len(pages)
    left = 0
    freq = defaultdict(int)
    distinct = 0
    best = None

    for right, page in enumerate(pages):
        if freq[page] == 0:
            distinct += 1
        freq[page] += 1

        while distinct > k:
            old = pages[left]
            freq[old] -= 1
            if freq[old] == 0:
                distinct -= 1
            left += 1

        if distinct == k:
            while freq[pages[left]] > 1:
                freq[pages[left]] -= 1
                left += 1
            length = right - left + 1
            if best is None or length < best:
                best = length

    return -1 if best is None else best

def is_balanced(expression):
    """
    Determines if the brackets in the given expression are balanced.

    :param expression: A string containing only the characters '()[]{}'.
    :return: True if the expression is balanced, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if not stack or bracket_map[char] != stack.pop():
                return False

    return not stack

