def calculate_gpa(grades):
    """
    Calculate the GPA based on the given grades dictionary.

    :param grades: A dictionary where keys are course names and values are grades as percentages.
    :return: The GPA as a float.
    :raises ValueError: If any grade is outside the range of 0-100.
    """
    if not grades:
        return 0.0

    def grade_to_gpa(grade):
        if 90 <= grade <= 100:
            return 4.0
        elif 80 <= grade <= 89:
            return 3.0
        elif 70 <= grade <= 79:
            return 2.0
        elif 60 <= grade <= 69:
            return 1.0
        elif 0 <= grade <= 59:
            return 0.0
        else:
            raise ValueError(f"Invalid grade encountered: {grade}")

    total_gpa = 0.0
    for grade in grades.values():
        total_gpa += grade_to_gpa(grade)

    return total_gpa / len(grades)

