    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def classify_numbers(numbers):
    """Classify numbers into even, odd, prime, and composite."""
    counts = {'even': 0, 'odd': 0, 'prime': 0, 'composite': 0}

    for num in numbers:
        if num % 2 == 0:
            counts['even'] += 1
        else:
            counts['odd'] += 1

        if num == 1:
            continue

        if is_prime(num):
            counts['prime'] += 1
        elif num > 1:
            counts['composite'] += 1

    return counts

