import json

def filter_movies(json_file_path):
    """
    Reads a JSON file containing a list of movies and prints the titles and genres
    of movies released in or after the year 2000. Handles invalid JSON data and file errors.

    :param json_file_path: str - The path to the JSON file.
    """
    try:
        with open(json_file_path, 'r') as file:
            movies = json.load(file)

            if not isinstance(movies, list):
                print("Invalid JSON format: root should be a list")
                return

            for movie in movies:
                if not isinstance(movie, dict):
                    print("Invalid JSON format: movie should be a dictionary")
                    continue

                title = movie.get('title')
                release_year = movie.get('release_year')
                genre = movie.get('genre')

                if title is None:
                    print("Invalid JSON format: missing 'title' property")
                    continue

                if release_year is None:
                    print(f"Invalid JSON format: missing 'release_year' property for {title}")
                    continue

                if genre is None:
                    print(f"Invalid JSON format: missing 'genre' property for {title}")
                    continue

                if release_year >= 2000:
                    print(f"Title: {title}, Genre: {genre}")

    except json.JSONDecodeError:
        print("Error decoding JSON file")
    except FileNotFoundError:
        print(f"File {json_file_path} not found")
    except Exception as e:
