def fibonacci(n):
    """
    Computes the nth Fibonacci number using recursion.

    Parameters:
    n (int): The position in the Fibonacci sequence.

    Returns:
    int or None: The nth Fibonacci number if n is non-negative, otherwise None.
    """
    if n < 0:
        return None
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

