from collections import defaultdict, deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def deepest_node(root: TreeNode, queries):
    def bfs_deepest_node(subtree_root):
        queue = deque([(subtree_root, 0)])
        max_depth = -1
        deepest_nodes = []

        while queue:
            current_node, current_depth = queue.popleft()

            if current_depth > max_depth:
                max_depth = current_depth
                deepest_nodes = [current_node.val]
            elif current_depth == max_depth:
                deepest_nodes.append(current_node.val)

            if current_node.left:
                queue.append((current_node.left, current_depth + 1))
            if current_node.right:
                queue.append((current_node.right, current_depth + 1))

        return min(deepest_nodes)

    node_map = {}

    def build_map(node):
        if node:
            node_map[node.val] = node
            build_map(node.left)
            build_map(node.right)

    build_map(root)

    result = []
    for q in queries:
        subtree_root = node_map[q]
        result.append(bfs_deepest_node(subtree_root))

    return result

