def is_one_edit_away(s1, s2):
    """
    Determines if s1 can be converted to s2 by performing at most one edit.
    An edit is defined as inserting a character, deleting a character, or replacing a character.
    """
    len1, len2 = len(s1), len(s2)
    if abs(len1 - len2) > 1:
        return False

    # Identify the shorter and the longer string
    if len1 > len2:
        s1, s2 = s2, s1
        len1, len2 = len2, len1

    # Started pointers for comparison
    index1 = index2 = 0
    found_difference = False

    while index1 < len1 and index2 < len2:
        if s1[index1] != s2[index2]:
            if found_difference:
                return False
            found_difference = True
            if len1 == len2:
                index1 += 1
        else:
            index1 += 1
        index2 += 1

    return True

