class ShoppingCart:
    def __init__(self):
        """Initialize an empty dictionary to store the cart items."""
        self.cart = {}

    def add_item(self, name, price, quantity):
        """
        Add an item to the cart or update its quantity if it already exists.

        :param name: str, the name of the item
        :param price: float, the price of the item
        :param quantity: int, the quantity of the item to add
        """
        if name in self.cart:
            self.cart[name]['quantity'] += quantity
        else:
            self.cart[name] = {'price': price, 'quantity': quantity}

    def remove_item(self, name, quantity=None):
        """
        Remove a specified quantity of an item from the cart or remove the item entirely if no quantity is specified or the quantity is greater than or equal to the current quantity.

        :param name: str, the name of the item to remove
        :param quantity: int, the quantity of the item to remove (optional)
        """
        if name in self.cart:
            if quantity is None or quantity >= self.cart[name]['quantity']:
                del self.cart[name]
            else:
                self.cart[name]['quantity'] -= quantity

    def view_cart(self):
        """Print the items in the cart."""
        if not self.cart:
            print("The cart is empty.")
        else:
            for name, details in self.cart.items():
                print(f"Item: {name}, Price: {details['price']}, Quantity: {details['quantity']}")

    def calculate_total(self):
        """
        Calculate the total cost of items in the cart.

        :return: float, the total cost
        """
        return sum(details['price'] * details['quantity'] for details in self.cart.values())

