def diffWaysToCompute(expression):
    """
    This function computes all possible results from computing all the different possible ways 
    to group numbers and operators in the input expression.
    """
    # Base case
    if expression.isdigit():
        return [int(expression)]

    results = []
    for index, char in enumerate(expression):
        if char in "+-*":
            left_results = diffWaysToCompute(expression[:index])
            right_results = diffWaysToCompute(expression[index+1:])
            for left in left_results:
                for right in right_results:
                    if char == '+':
                        results.append(left + right)
                    elif char == '-':
                        results.append(left - right)
                    elif char == '*':
                        results.append(left * right)
    return results

