def min_path_sum(grid):
    """
    Returns the minimum cost path sum to reach the bottom-right cell from the top-left cell.
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])

    # Initialize the first row by cumulatively adding the values
    for col in range(1, cols):
        grid[0][col] += grid[0][col - 1]

    # Initialize the first column by cumulatively adding the values
    for row in range(1, rows):
        grid[row][0] += grid[row - 1][0]

    # Update the rest of the grid
    for row in range(1, rows):
        for col in range(1, cols):
            grid[row][col] += min(grid[row - 1][col], grid[row][col - 1])

    return grid[rows - 1][cols - 1]

