def restore_ip_addresses(s):
    """
    Returns all possible valid IP addresses that can be formed by inserting dots into `s`.
    """
    def is_valid(segment):
        return len(segment) == 1 or (segment[0] != '0' and int(segment) <= 255)

    def backtrack(start=0, parts=[]):
        if start == len(s) and len(parts) == 4:
            addresses.append(".".join(parts))
        elif len(parts) < 4:
            for end in range(start + 1, min(start + 4, len(s) + 1)):
                segment = s[start:end]
                if is_valid(segment):
                    backtrack(end, parts + [segment])

    addresses = []
    backtrack()
    return sorted(addresses)

