def mergeAlternately(word1, word2):
    """
    Returns a string that is a combination of the longest possible sequence of
    alternating characters from word1 and word2. In the case of a tie,
    characters from word1 precede those from word2.
    """
    result = []
    len1, len2 = len(word1), len(word2)
    for i in range(max(len1, len2)):
        if i < len1:
            result.append(word1[i])
        if i < len2:
            result.append(word2[i])
    return ''.join(result)

