def shortest_palindrome(s):
    """
    Constructs the shortest possible palindrome by adding characters to the end of the given string.
    """
    def is_palindrome(x):
        return x == x[::-1]

    if is_palindrome(s):
        return s

    for i in range(len(s)):
        if is_palindrome(s[i:]):
            return s + s[:i][::-1]

    return s

