def count_pairs_divisible_by_m(attempts, m):
    rem_count = {}
    ans = 0
    for x in attempts:
        r = x % m
        need = (-r) % m
        ans += rem_count.get(need, 0)
        rem_count[r] = rem_count.get(r, 0) + 1
    return ans

def max_reward_path(rewards: list[int]) -> int:
    n = len(rewards)
    if n == 1:
        return rewards[0]
    dp = [0] * n
    dp[0] = rewards[0]
    dp[1] = max(rewards[1], rewards[0] + rewards[1])
    for i in range(2, n):
        dp[i] = rewards[i] + max(dp[i - 1], dp[i - 2])
    return dp[-1]

def reachable_accounts(n, edges, start):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
    visited = [False] * n
    stack = [start]
    visited[start] = True
    while stack:
        node = stack.pop()
        for nxt in graph[node]:
            if not visited[nxt]:
                visited[nxt] = True
                stack.append(nxt)
    result = [i for i in range(n) if visited[i] and i != start]
    return result

def sum_integers(d):
    """
    Recursively calculates the total sum of all integer values in a nested dictionary.

    :param d: A dictionary that may contain integers, strings, lists, or other dictionaries as values.
    :return: The total sum of all integer values in the dictionary.
    """
    total_sum = 0
    for key, value in d.items():
        if isinstance(value, int):
            total_sum += value
        elif isinstance(value, dict):
            total_sum += sum_integers(value)
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, int):
                    total_sum += item
    return total_sum

