def find_mode(numbers):
    """
    Finds the mode(s) of a list of integers.

    Parameters:
    numbers (list of int): The list of integers to find the mode(s) of.

    Returns:
    list of int: A list containing the mode(s) of the input list, sorted in ascending order.
    """
    if not numbers:
        return []

    frequency = {}
    for num in numbers:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    max_frequency = max(frequency.values())
    modes = [num for num, freq in frequency.items() if freq == max_frequency]

    return sorted(modes)

def generate_permutations(lst):
    """
    Generate all possible permutations of a given list of distinct integers.

    Parameters:
    lst (list): A list of distinct integers.

    Returns:
    list: A list of lists, where each inner list is a unique permutation of the input list.
    """
    if len(lst) == 0:
        return [[]]
    elif len(lst) == 1:
        return [lst]
    else:
        result = []
        for i in range(len(lst)):
            current = lst[i]
            remaining = lst[:i] + lst[i+1:]
            for p in generate_permutations(remaining):
                result.append([current] + p)
        return result

