def flipgame(front, back):
    same_numbers = {x for i, x in enumerate(front) if x == back[i]}

    res = float('inf')

    for num in front + back:
        if num not in same_numbers:
            res = min(res, num)

    return res if res != float('inf') else 0

def maximalRectangle(matrix):
    if not matrix:
        return 0

    max_area = 0
    n = len(matrix[0])
    heights = [0] * (n + 1)

    for row in matrix:
        for i in range(n):
            heights[i] = heights[i] + 1 if row[i] == '1' else 0

        stack = [-1]
        for j in range(n + 1):
            while heights[j] < heights[stack[-1]]:
                h = heights[stack.pop()]
                w = j - stack[-1] - 1
                max_area = max(max_area, h * w)
            stack.append(j)

    return max_area

def longest_increasing_subsequence(nums):
    """
    Finds the longest increasing subsequence in a list of integers.

    :param nums: List of integers.
    :return: List of integers representing the longest increasing subsequence.
    """
    if not nums:
        return []

    dp = [nums[0]]
    prev_index = [-1] * len(nums)
    max_length_index = 0

    for i in range(1, len(nums)):
        if nums[i] > dp[-1]:
            dp.append(nums[i])
            prev_index[i] = max_length_index
            max_length_index = i
        else:
            left, right = 0, len(dp) - 1
            while left < right:
                mid = (left + right) // 2
                if dp[mid] < nums[i]:
                    left = mid + 1
                else:
                    right = mid
            dp[left] = nums[i]
            if left != 0:
                prev_index[i] = (left - 1)

    lis = []
    while max_length_index != -1:
        lis.append(nums[max_length_index])
        max_length_index = prev_index[max_length_index]

    return lis[::-1]

