def calculate(s):
    """
    Evaluate a basic mathematical expression containing +, -, numbers, and parentheses.
    The expression is represented as a string.
    """
    def apply_ops(operators, values):
        operator = operators.pop()
        b = values.pop()
        a = values.pop()
        if operator == '+':
            values.append(a + b)
        elif operator == '-':
            values.append(a - b)

    operators, values = [], []
    i, n = 0, len(s)

    while i < n:
        if s[i] == ' ':
            i += 1
        elif s[i] == '(':
            operators.append(s[i])
            i += 1
        elif s[i] == ')':
            while operators and operators[-1] != '(':
                apply_ops(operators, values)
            operators.pop()  # pop '('
            i += 1
        elif s[i] in '+-':
            while (operators and operators[-1] in '+-'):
                apply_ops(operators, values)
            operators.append(s[i])
            i += 1
        else:  # Must be a number
            j = i
            while j < n and s[j].isdigit():
                j += 1
            values.append(int(s[i:j]))
            i = j

    while operators:
        apply_ops(operators, values)

    return values[0]

