def minimum_distance(words, word1, word2):
    """
    Returns the minimum distance between word1 and word2 in the list of words.
    Distance is defined as the number of elements between the two words (inclusive).
    """
    pos1, pos2 = -1, -1
    min_distance = float('inf')

    for i, word in enumerate(words):
        if word == word1:
            pos1 = i
        if word == word2:
            pos2 = i
        if pos1 != -1 and pos2 != -1:
            min_distance = min(min_distance, abs(pos2 - pos1) + 1)

    return min_distance

