class Fancy:
    def __init__(self):
        self.values = []
        self.additive = 0
        self.multiplicative = 1
        self.mod = 10**9 + 7

    def append(self, val: int) -> None:
        val = (val - self.additive) * pow(self.multiplicative, self.mod-2, self.mod) % self.mod
        self.values.append(val)

    def addAll(self, inc: int) -> None:
        self.additive = (self.additive + inc) % self.mod

    def multAll(self, m: int) -> None:
        self.additive = (self.additive * m) % self.mod
        self.multiplicative = (self.multiplicative * m) % self.mod

    def getIndex(self, idx: int) -> int:
        if idx >= len(self.values):
            return -1
        return (self.values[idx] * self.multiplicative + self.additive) % self.mod

