def searchRange(nums, target, findFirst):
    """
    Finds the range of indices for the given target in the sorted list nums.
    """
    def binarySearch(nums, target, findFirst):
        low, high = 0, len(nums) - 1
        result = -1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] == target:
                result = mid
                if findFirst:
                    high = mid - 1
                else:
                    low = mid + 1
            elif nums[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return result

    firstIndex = binarySearch(nums, target, True)
    lastIndex = binarySearch(nums, target, False)

    if firstIndex != -1:
        return [firstIndex, lastIndex]
    else:
        return [-1, -1]

