def max_buildings(heights, k):
    """
    Returns the maximum number of buildings that can be visited 
    starting from the first building and making at most k jumps.
    """
    n = len(heights)
    dp = [1] * n

    for i in range(n):
        for j in range(i + 1, n):
            if heights[j] > heights[i]:
                dp[j] = max(dp[j], dp[i] + 1)
                if dp[j] > k + 1:  # As we start counting from the first building
                    break

    return min(max(dp), k + 1)

