from collections import defaultdict

def findAllConcatenations(s, dict):
    if not dict or not s:
        return []

    word_len = len(dict[0])
    num_words = len(dict)
    total_len = word_len * num_words
    word_count = defaultdict(int)

    for word in dict:
        word_count[word] += 1

    def valid_substring(start):
        seen_words = defaultdict(int)
        words_used = 0
        for i in range(start, start + total_len, word_len):
            current_word = s[i:i+word_len]
            if current_word in word_count:
                if seen_words[current_word] < word_count[current_word]:
                    seen_words[current_word] += 1
                    words_used += 1
                else:
                    return False
            else:
                return False
        return words_used == num_words

    result_indices = []
    for i in range(len(s) - total_len + 1):
        if valid_substring(i):
            result_indices.append(i)

    return result_indices

