def count_valid_subsets(nums, limit):
    from itertools import product

    count = 0
    n = len(nums)

    for bits in product([0, 1], repeat=n):
        valid = True
        for i in range(n):
            if bits[i] == 1 and nums[i] > limit[i]:
                valid = False
                break
        if valid:
            count += 1

    return count

