def longest_mixed_run(scores):
    n = len(scores)
    if n < 3:
        return 0
    best = 0
    i = 0
    while i < n - 1:
        j = i
        while j + 1 < n and scores[j + 1] != scores[j]:
            j += 1
        if j - i + 1 >= 3:
            has_up = has_down = False
            for k in range(i, j):
                if scores[k + 1] > scores[k]:
                    has_up = True
                elif scores[k + 1] < scores[k]:
                    has_down = True
            if has_up and has_down:
                best = max(best, j - i + 1)
        i = j + 1 if j > i else i + 1
    return best

def find_anagrams(word, dictionary):
    """
    Returns a list of all unique anagrams of the given word from the dictionary.

    :param word: A string representing the word to find anagrams for.
    :param dictionary: A list of strings representing the dictionary of words.
    :return: A list of strings, each representing a unique anagram of the word.
    """
    def sorted_characters(s):
        return tuple(sorted(s.lower()))

    word_signature = sorted_characters(word)
    anagrams = set()

    for w in dictionary:
        if sorted_characters(w) == word_signature:
            anagrams.add(w.lower())

    return list(anagrams)

def canPartitionKSubsets(nums, k):
    """
    Determines if it is possible to partition the list into k non-empty subsets
    with equal sum.

    :param nums: List of integers to be partitioned.
    :param k: Number of subsets to partition the list into.
    :return: True if such a partition exists, otherwise False.
    """
    def can_partition(index, used, curr_sum):
        if k == 1:
            return True
        if curr_sum == target_sum:
            return can_partition(0, used, 0)
        for i in range(index, n):
            if not used[i] and curr_sum + nums[i] <= target_sum:
                used[i] = True
                if can_partition(i + 1, used, curr_sum + nums[i]):
                    return True
                used[i] = False
        return False

    total_sum = sum(nums)
    n = len(nums)
    if total_sum % k != 0:
        return False
    target_sum = total_sum // k
    nums.sort(reverse=True)
    used = [False] * n
    return can_partition(0, used, 0)

class Matrix:
    def __init__(self, data):
        """
        Initialize the Matrix with the given 2D list data.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def __add__(self, other):
        """
        Add two matrices of the same dimensions.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to add.")

        result_data = [[self.data[i][j] + other.data[i][j] for j in range(self.cols)] for i in range(self.rows)]
        return Matrix(result_data)

    def __sub__(self, other):
        """
        Subtract two matrices of the same dimensions.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to subtract.")

        result_data = [[self.data[i][j] - other.data[i][j] for j in range(self.cols)] for i in range(self.rows)]
        return Matrix(result_data)

    def __mul__(self, other):
        """
        Multiply two matrices where the number of columns in the first matrix
        is equal to the number of rows in the second matrix.
        """
        if not isinstance(other, Matrix) or self.cols != other.rows:
            raise ValueError("Number of columns of the first matrix must be equal to number of rows of the second matrix to multiply.")

        result_data = [[sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)] for i in range(self.rows)]
        return Matrix(result_data)

    def __str__(self):
        """
        Return a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

def parse_itemized_elements(text):
    """
    Parses a string containing itemized elements enclosed in square brackets and returns a dictionary
    with the count of each element.

    :param text: A string with itemized elements separated by commas.
    :return: A dictionary with item names as keys and their counts as values.
    """
    result = {}
    elements = text.split(',')
    for element in elements:
        element = element.strip()
        if element.startswith('[') and element.endswith(']'):
            item = element[1:-1]
            if item in result:
                result[item] += 1
            else:
                result[item] = 1
    return result

def evaluate_expression(s):
    """
    Evaluates a mathematical expression given as a string and returns the result.

    :param s: A string representing the mathematical expression.
    :return: An integer representing the result of the evaluated expression.
    """
    def calc(op1, op2, operator):
        if operator == '+':
            return op1 + op2
        elif operator == '-':
            return op1 - op2
        elif operator == '*':
            return op1 * op2
        elif operator == '/':
            return op1 / op2

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        values.append(calc(left, right, operator))

    def greater_precedence(op1, op2):
        return precedence(op1) > precedence(op2)

    values = []
    operators = []
    i = 0
    while i < len(s):
        if s[i] == ' ':
            i += 1
            continue
        elif s[i] in '0123456789':
            j = i
            while j < len(s) and s[j] in '0123456789':
                j += 1
            values.append(int(s[i:j]))
            i = j
        elif s[i] == '(':
            operators.append(s[i])
            i += 1
        elif s[i] == ')':
            while operators and operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
            i += 1
        else:
            # Operator
            while (operators and operators[-1] != '(' and
                   greater_precedence(operators[-1], s[i])):
                apply_operator(operators, values)
            operators.append(s[i])
            i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

