def flatten_dict(d, parent_key='', sep='.'):
    """
    Flattens a nested dictionary or a dictionary with list/tuple values.

    :param d: The dictionary to flatten.
    :param parent_key: The base key string to use for the current level.
    :param sep: The separator to use between keys.
    :return: A flattened dictionary.
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        elif isinstance(v, (list, tuple)):
            for i, item in enumerate(v):
                item_key = f"{new_key}[{i}]"
                if isinstance(item, dict):
                    items.extend(flatten_dict(item, item_key, sep=sep).items())
                else:
                    items.append((item_key, item))
        else:
            items.append((new_key, v))
    return dict(items)

def find_duplicate_chars(s):
    """
    Returns a list of characters that appear more than once in the string.
    Each character appears only once in the list, in the order of their first appearance.

    :param s: Input string consisting of lowercase English letters.
    :return: List of duplicate characters.
    """
    char_count = {}
    duplicates = []

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in s:
        if char_count[char] > 1 and char not in duplicates:
            duplicates.append(char)

    return duplicates

