from math import gcd

class Fraction:
    def __init__(self, numerator=0, denominator=1):
        """
        Initialize a Fraction object with a numerator and a denominator.
        Automatically simplifies the fraction.
        """
        if denominator == 0:
            raise ValueError("Denominator cannot be zero.")
        divisor = gcd(numerator, denominator)
        self.numerator = numerator // divisor
        self.denominator = denominator // divisor
        if self.denominator < 0:
            self.numerator = -self.numerator
            self.denominator = -self.denominator

    def __add__(self, other):
        """
        Add two Fraction objects.
        """
        if isinstance(other, Fraction):
            new_numerator = self.numerator * other.denominator + other.numerator * self.denominator
            new_denominator = self.denominator * other.denominator
            return Fraction(new_numerator, new_denominator)
        raise TypeError("Operand must be an instance of Fraction.")

    def __sub__(self, other):
        """
        Subtract one Fraction object from another.
        """
        if isinstance(other, Fraction):
            new_numerator = self.numerator * other.denominator - other.numerator * self.denominator
            new_denominator = self.denominator * other.denominator
            return Fraction(new_numerator, new_denominator)
        raise TypeError("Operand must be an instance of Fraction.")

    def __mul__(self, other):
        """
        Multiply two Fraction objects.
        """
        if isinstance(other, Fraction):
            new_numerator = self.numerator * other.numerator
            new_denominator = self.denominator * other.denominator
            return Fraction(new_numerator, new_denominator)
        raise TypeError("Operand must be an instance of Fraction.")

    def __truediv__(self, other):
        """
        Divide one Fraction object by another.
        """
        if isinstance(other, Fraction):
            if other.numerator == 0:
                raise ZeroDivisionError("Cannot divide by a fraction with a numerator of zero.")
            new_numerator = self.numerator * other.denominator
            new_denominator = self.denominator * other.numerator
            return Fraction(new_numerator, new_denominator)
        raise TypeError("Operand must be an instance of Fraction.")

    def __float__(self):
        """
        Convert the Fraction to a floating-point number.
        """
        return self.numerator / self.denominator

    def __int__(self):
        """
        Convert the Fraction to an integer.
        """
        return self.numerator // self.denominator

    def __str__(self):
        """
        Return a string representation of the Fraction.
        """
        if self.denominator == 1:
            return str(self.numerator)
        return f"{self.numerator}/{self.denominator}"

