from collections import deque

class minMutations:
    def __init__(self, start, goal, bank):
        self.start = start
        self.goal = goal
        self.bank = set(bank)  # Using set for O(1) lookups

    def getMinMutations(self):
        if self.goal not in self.bank:
            return -1

        def is_valid_mutation(current, next_str):
            count = 0
            for c1, c2 in zip(current, next_str):
                if c1 != c2:
                    count += 1
                if count > 1:
                    return False
            return count == 1

        queue = deque([(self.start, 0)])
        visited = set([self.start])

        while queue:
            current, mutations = queue.popleft()

            if current == self.goal:
                return mutations

            for candidate in list(self.bank):
                if candidate not in visited and is_valid_mutation(current, candidate):
                    visited.add(candidate)
                    queue.append((candidate, mutations + 1))

        return -1

