def countSubarraysWithProductLessThanK(arr, k):
    if k <= 1:
        return 0

    count = 0
    product = 1
    start = 0

    for end in range(len(arr)):
        product *= arr[end]

        while product >= k:
            product //= arr[start]
            start += 1

        count += end - start + 1

    return count

