def can_transform(start, end):
    """
    Returns True if the start string can be transformed into the end string character by character.
    """
    if len(start) != len(end):
        return False

    for s, e in zip(start, end):
        if s == e:
            continue

        # Calculate distance in the alphabet (considering circular nature)
        forward_steps = (ord(e) - ord(s)) % 26
        backward_steps = (ord(s) - ord(e)) % 26

        if not (forward_steps == 1 or backward_steps == 1):
            return False

    return True

def canPartitionKSubsets(arr, k):
    def canPartition(start, k, current_sum, target_sum, visited):
        if k == 1:
            return True  # only one subset left, no need to check
        if current_sum == target_sum:
            return canPartition(0, k - 1, 0, target_sum, visited)  # found one subset, looking for next

        for i in range(start, len(arr)):
            if not visited[i] and current_sum + arr[i] <= target_sum:
                visited[i] = True
                if canPartition(i + 1, k, current_sum + arr[i], target_sum, visited):
                    return True
                visited[i] = False

        return False

    if k == 0 or k > len(arr):
        return False

    total_sum = sum(arr)
    if total_sum % k != 0:
        return False

    target_sum = total_sum // k
    visited = [False] * len(arr)

    arr.sort(reverse=True)  # Sort to optimize backtracking

    return canPartition(0, k, 0, target_sum, visited)

