from itertools import combinations
import math

def largest_good_subset_size(nums):
    """
    Returns the size of the largest subset of nums where the product of its elements is a perfect square.
    """
    def is_perfect_square(n):
        return int(math.isqrt(n)) ** 2 == n

    n = len(nums)
    max_size = 0

    for r in range(1, n + 1):
        for subset in combinations(nums, r):
            product = math.prod(subset)
            if is_perfect_square(product):
                max_size = max(max_size, len(subset))

    return max_size

