from heapq import heappush, heappop
from collections import Counter, deque

def rearrange_string(s, k):
    if k == 0:
        return s

    frequency_map = Counter(s)
    max_heap = []

    for char, freq in frequency_map.items():
        heappush(max_heap, (-freq, char))

    queue = deque()
    result = []

    while max_heap:
        freq, char = heappop(max_heap)
        result.append(char)
        queue.append((char, freq + 1))

        if len(queue) < k:
            continue

        char, freq = queue.popleft()
        if -freq > 0:
            heappush(max_heap, (freq, char))

    if len(result) == len(s):
        return ''.join(result)
    else:
        return ""

