def sum_of_unique_substrings(s):
    """
    Calculate the sum of all possible unique substrings of the given string s.
    """
    unique_substrs = set()
    for i in range(len(s)):
        for j in range(i+1, len(s)+1):
            unique_substrs.add(s[i:j])

    total_sum = sum(int(substr) for substr in unique_substrs)
    return total_sum

