def longestDistinctivelySpacedSubsequence(arr, d):
    n = len(arr)
    if n == 0:
        return 0

    # dp[i] will store the length of the longest distinctively spaced subsequence ending at index i
    dp = [1] * n

    # Iterate through each element to find a valid distinctively spaced subsequence
    for i in range(n):
        for j in range(i):
            if abs(arr[i] - arr[j]) >= d:
                dp[i] = max(dp[i], dp[j] + 1)

    # The result is the maximum value in dp array
    return max(dp)

