from itertools import combinations

def subset_sum(nums, target):
    """
    Determine if there exists a subset of `nums` that adds up to `target`
    and contains at least 2 elements.
    """
    if len(nums) < 2:
        return False  # If there are fewer than 2 elements, it's impossible

    # Check all possible subsets of length 2 or more
    for r in range(2, len(nums) + 1):
        for subset in combinations(nums, r):
            if sum(subset) == target:
                return True
    return False

