def max_sum_k_elements(nums, k):
    """
    Returns the maximum sum possible by selecting k elements from nums.
    If k is greater than the length of nums or nums is empty, return 0.
    """
    if not nums or k <= 0:
        return 0

    if k >= len(nums):
        return sum(nums)

    nums.sort(reverse=True)
    return sum(nums[:k])

