def can_form_morphism(s1, s2):
    """
    Determines if a one-to-one mapping exists between the characters of s1 and s2.

    :param s1: First string.
    :param s2: Second string.
    :return: Boolean - True if a valid morphism exists, otherwise False.
    """
    # A one-to-one morphism can exist if both strings have unique characters mapped uniquely
    if len(s1) != len(s2):
        return False

    mapping_s1_to_s2 = {}
    mapping_s2_to_s1 = {}

    for char1, char2 in zip(s1, s2):
        if char1 in mapping_s1_to_s2:
            if mapping_s1_to_s2[char1] != char2:
                return False
        else:
            mapping_s1_to_s2[char1] = char2

        if char2 in mapping_s2_to_s1:
            if mapping_s2_to_s1[char2] != char1:
                return False
        else:
            mapping_s2_to_s1[char2] = char1

    return True

