import re
from collections import defaultdict

def countAtoms(formula):
    def multiply_counts(multi_dict, multiplier):
        return {k: v * multiplier for k, v in multi_dict.items()}

    def merge_counts(main_dict, temp_dict):
        for key, value in temp_dict.items():
            main_dict[key] += value

    def parse_formula(f):
        stack = []
        current_dict = defaultdict(int)
        i, n = 0, len(f)

        while i < n:
            if f[i] == '(':
                stack.append(current_dict)
                current_dict = defaultdict(int)
                i += 1
            elif f[i] == ')':
                i += 1
                i_start = i
                while i < n and f[i].isdigit():
                    i += 1
                multiplier = int(f[i_start:i] or 1)
                temp_dict = multiply_counts(current_dict, multiplier)
                current_dict = stack.pop()
                merge_counts(current_dict, temp_dict)
            else:
                i_start = i
                i += 1
                while i < n and f[i].islower():
                    i += 1
                element = f[i_start:i]
                i_start = i
                while i < n and f[i].isdigit():
                    i += 1
                count = int(f[i_start:i] or 1)
                current_dict[element] += count

        return current_dict

    return dict(parse_formula(formula))

class BuildingView:
    def __init__(self, heights):
        self.heights = heights
        self.max_from_left = self._calculate_max_from_left()

    def _calculate_max_from_left(self):
        max_heights = []
        current_max = float('-inf')
        for height in self.heights:
            if height > current_max:
                max_heights.append(height)
                current_max = height
        return max_heights

    def countVisible(self):
        return len(self.max_from_left)

    def update(self, index, newHeight):
        self.heights[index] = newHeight
        self.max_from_left = self._calculate_max_from_left()

def is_palindrome(word):
    """
    Helper function to check if a word is a palindrome.
    """
    return word == word[::-1]

def palindromePairs(words):
    """
    Returns the total number of pairs (i, j) where 0 <= i < j < words.length,
    and the concatenation of words[i] + words[j] or words[j] + words[i] forms a palindrome.
    """
    count = 0
    for i in range(len(words)):
        for j in range(i + 1, len(words)):
            if is_palindrome(words[i] + words[j]):
                count += 1
            if is_palindrome(words[j] + words[i]):
                count += 1
    return count

