def find_substring(s, words):
    """
    Given a string `s` and a list of words `words`, return all starting indices of 
    substring(s) in `s` that is a concatenation of each word in `words` exactly once 
    and without any intervening characters. The words in `words` are all of the same length.
    """
    from collections import defaultdict

    if not s or not words:
        return []

    word_length = len(words[0])
    word_count = len(words)
    total_length = word_length * word_count
    word_map = defaultdict(int)

    for word in words:
        word_map[word] += 1

    def check(start):
        seen = defaultdict(int)
        words_used = 0
        for i in range(start, start + total_length, word_length):
            current_word = s[i:i + word_length]
            if current_word in word_map:
                seen[current_word] += 1
                if seen[current_word] > word_map[current_word]:
                    return False
                words_used += 1
            else:
                return False
        return words_used == word_count

    result = []
    for i in range(len(s) - total_length + 1):
        if check(i):
            result.append(i)

    return result

