def longest_unique_sum_subarray(events, target):
    prefix_sum = 0
    prefix_index = {0: -1}
    last_seen = {}
    best = 0

    for i, x in enumerate(events):
        if x in last_seen:
            left = last_seen[x] + 1
        else:
            left = 0

        last_seen[x] = i
        prefix_sum += x

        # 현재 위치 i에서 끝나는 구간의 합이 target인 시작점 찾기
        need = prefix_sum - target
        if need in prefix_index:
            start = prefix_index[need] + 1
            if start >= left:
                best = max(best, i - start + 1)

        # prefix_sum의 가장 이른 위치만 유지
        if prefix_sum not in prefix_index:
            prefix_index[prefix_sum] = i

    return best

def palindrome_prefix_counts(s):
    result = []
    count = 0
    for i in range(len(s)):
        prefix = s[:i+1]
        if prefix == prefix[::-1]:
            count += 1
        result.append(count)
    return result

def min_max_gap(timestamps: list[int], k: int) -> int:
    if k <= 1:
        return 0
    arr = sorted(timestamps)
    lo, hi = 0, arr[-1] - arr[0]

    def can(gap: int) -> bool:
        count = 1
        last = arr[0]
        for x in arr[1:]:
            if x - last <= gap:
                count += 1
                last = x
                if count >= k:
                    return True
        return False

    while lo < hi:
        mid = (lo + hi) // 2
        if can(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

def find_matching_words(words, pattern):
    """
    Returns a list of words from `words` that match the `pattern`.

    A word matches the `pattern` if there is a one-to-one mapping between
    every letter of the `pattern` and every letter of the word.

    :param words: List of strings to be checked against the pattern.
    :param pattern: String pattern to match against the words.
    :return: List of strings from `words` that match the `pattern`.
    """
    def match(word, pattern):
        if len(word) != len(pattern):
            return False
        mapping = {}
        mapped_values = set()
        for w_char, p_char in zip(word, pattern):
            if p_char not in mapping:
                if w_char in mapped_values:
                    return False
                mapping[p_char] = w_char
                mapped_values.add(w_char)
            elif mapping[p_char] != w_char:
                return False
        return True

    return [word for word in words if match(word, pattern)]

class Matrix:
    def __init__(self, data):
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def add(self, other):
        """
        Adds two matrices and returns a new Matrix object.
        Raises ValueError if matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for addition")

        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtracts the second matrix from the first and returns a new Matrix object.
        Raises ValueError if matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for subtraction")

        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiplies two matrices and returns a new Matrix object.
        Raises ValueError if the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to number of rows in the second matrix")

        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __str__(self):
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

class TreeNode:
    def __init__(self, value):
        """
        Initializes a new TreeNode with the given value.

        :param value: The integer value to be stored in the node.
        """
        self.value = value
        self.left = None
        self.right = None

    def insert(self, value):
        """
        Inserts a new value into the BST.

        :param value: The integer value to be inserted.
        """
        if value < self.value:
            if self.left is None:
                self.left = TreeNode(value)
            else:
                self.left.insert(value)
        elif value > self.value:
            if self.right is None:
                self.right = TreeNode(value)
            else:
                self.right.insert(value)

    def find(self, value):
        """
        Searches for a value in the BST.

        :param value: The integer value to be searched.
        :return: True if the value is found, False otherwise.
        """
        if value < self.value:
            if self.left is None:
                return False
            return self.left.find(value)
        elif value > self.value:
            if self.right is None:
                return False
            return self.right.find(value)
        else:
            return True

    def delete(self, value):
        """
        Deletes a value from the BST.

        :param value: The integer value to be deleted.
        :return: The root node of the modified BST.
        """
        if value < self.value:
            if self.left is not None:
                self.left = self.left.delete(value)
        elif value > self.value:
            if self.right is not None:
                self.right = self.right.delete(value)
        else:
            if self.left is None:
                return self.right
            elif self.right is None:
                return self.left
            min_larger_node = self.right
            while min_larger_node.left is not None:
                min_larger_node = min_larger_node.left
            self.value = min_larger_node.value
            self.right = self.right.delete(min_larger_node.value)
        return self

    def inorder_traversal(self):
        """
        Performs an in-order traversal of the BST.

        :return: A list of integers representing the in-order traversal.
        """
        result = []
        if self.left is not None:
            result = self.left.inorder_traversal()
        result.append(self.value)
        if self.right is not None:
            result = result + self.right.inorder_traversal()
        return result

def generate_primes(start, end):
    """
    Generate a list of prime numbers within a given range [start, end].

    Parameters:
    start (int): The starting integer of the range.
    end (int): The ending integer of the range.

    Returns:
    list: A list of prime numbers within the specified range.
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    return [num for num in range(start, end + 1) if is_prime(num)]

