def find_and_replace_pattern(words, pattern):
    def match(word, pattern):
        if len(word) != len(pattern):
            return False
        char_map = {}
        used_chars = set()
        for w, p in zip(word, pattern):
            if p not in char_map:
                if w in used_chars:
                    return False
                char_map[p] = w
                used_chars.add(w)
            elif char_map[p] != w:
                return False
        return True

    return [word for word in words if match(word, pattern)]

