def leadsToTerminal(graph):
    """
    Determines if all paths starting from node 0 lead to terminal nodes.

    Parameters:
    graph (List[List[int]]): The DAG represented by an adjacency list.

    Returns:
    bool: True if all paths from node 0 lead to terminal nodes, False otherwise.
    """
    def dfs(node, visited):
        if visited[node] != 0:
            return visited[node] == 1
        if not graph[node]:
            visited[node] = 1
            return True
        visited[node] = -1
        for neighbor in graph[node]:
            if not dfs(neighbor, visited):
                return False
        visited[node] = 1
        return True

    visited = [0] * len(graph)
    return dfs(0, visited)

def max_profit(prices):
    """
    Calculate the maximum profit from a single buy and sell transaction.

    :param prices: List[int] - A list of integers representing the stock prices on consecutive days.
    :return: int - The maximum profit that can be achieved. If no profit is possible, returns 0.
    """
    if not prices:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

