def find_water_collection_grid(grid):
    """
    Find the minimum height of the final cell where the water can collect in the grid.
    """
    def dfs(x, y):
        if (x, y) in memo:
            return memo[(x, y)]

        min_height = grid[x][y]
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] < grid[x][y]:
                min_height = min(min_height, dfs(nx, ny))

        memo[(x, y)] = min_height
        return min_height

    if not grid or not grid[0]:
        return -1

    memo = {}
    result = float('inf')

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            result = min(result, dfs(i, j))

    return result

