def maxTwoEvents(events):
    """
    This function calculates the maximum sum of values by attending at most two non-overlapping events.
    """
    # Sort the events by their start times
    events.sort(key=lambda x: x[0])

    n = len(events)
    max_val = 0
    endval = [0] * n  # Array to store max value of one event till ith event

    # Fill the endval array
    for i in range(n-1, -1, -1):
        if i == n-1:
            endval[i] = events[i][2]
        else:
            endval[i] = max(endval[i+1], events[i][2])

    i = 0
    for j in range(n):
        # Find an event end time that does not overlap with the current start time
        while i < n and events[i][0] <= events[j][1]:
            i += 1

        if i < n:
            max_val = max(max_val, events[j][2] + endval[i])
        else:
            max_val = max(max_val, events[j][2])

    return max_val

