def are_similar(s, t, pairs):
    if len(s) != len(t):
        return False

    from collections import defaultdict

    parent = {}

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    for a, b in pairs:
        if a not in parent:
            parent[a] = a
        if b not in parent:
            parent[b] = b
        union(a, b)

    for char in set(s + t):
        if char not in parent:
            parent[char] = char

    for i in range(len(s)):
        if find(s[i]) != find(t[i]):
            return False

    return True

