def count_unique_substrings(s, k):
    """
    Returns the count of unique substrings of length `k` in string `s`.
    """
    if k > len(s):
        return 0

    substrings = set()
    for i in range(len(s) - k + 1):
        substr = s[i:i+k]
        substrings.add(substr)

    return len(substrings)

def rearrange_array(arr, k):
    """
    Rearranges the elements of the array such that the element at position `k` is
    the same as it would be if the array was sorted. The order of other elements
    is not important.

    :param arr: List[int] - The unsorted array of integers
    :param k: int - The position to ensure has the correct element
    :return: List[int] - The rearranged array
    """
    if not (0 <= k < len(arr)):
        raise IndexError("k is out of the bounds of the array length.")

    # Perform nth element (quickselect algorithm)
    def partition(left, right, pivot_index):
        pivot_value = arr[pivot_index]
        arr[pivot_index], arr[right] = arr[right], arr[pivot_index]
        store_index = left
        for i in range(left, right):
            if arr[i] < pivot_value:
                arr[store_index], arr[i] = arr[i], arr[store_index]
                store_index += 1
        arr[right], arr[store_index] = arr[store_index], arr[right]
        return store_index

    def quickselect(left, right, k):
        if left == right:
            return arr[left]

        pivot_index = (left + right) // 2
        pivot_index = partition(left, right, pivot_index)

        if k == pivot_index:
            return arr[k]
        elif k < pivot_index:
            return quickselect(left, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, right, k)

    quickselect(0, len(arr) - 1, k)
    return arr

class TwoSum:
    def __init__(self):
        self.numbers = {}

    def add(self, number):
        """
        Add the number to the internal data structure.
        """
        if number in self.numbers:
            self.numbers[number] += 1
        else:
            self.numbers[number] = 1

    def find(self, value):
        """
        Find if there are two numbers in the internal data structure 
        such that their sum is equal to the given value.
        """
        for num in self.numbers:
            complement = value - num
            if complement in self.numbers:
                if complement != num or self.numbers[num] > 1:
                    return True
        return False

