class FileSystem:
    def __init__(self):
        self.fs = {'/': {}}

    def mkdir(self, path: str) -> None:
        dirs = path.split('/')
        current = self.fs['/']
        for dir in dirs[1:]:
            if dir not in current:
                current[dir] = {}
            current = current[dir]

    def addContentToFile(self, filePath: str, content: str) -> None:
        dirs = filePath.split('/')
        current = self.fs['/']
        for dir in dirs[1:-1]:
            current = current[dir]
        if dirs[-1] not in current:
            current[dirs[-1]] = ''
        current[dirs[-1]] += content

    def readContentFromFile(self, filePath: str) -> str:
        dirs = filePath.split('/')
        current = self.fs['/']
        for dir in dirs[1:-1]:
            current = current[dir]
        return current.get(dirs[-1], '')

    def ls(self, path: str) -> list:
        if path == '/':
            return sorted(self.fs['/'].keys())
        dirs = path.split('/')
        current = self.fs['/']
        for dir in dirs[1:]:
            current = current[dir]
        if isinstance(current, str):
            return [dirs[-1]]
        else:
            return sorted(current.keys())

