from typing import List, Tuple

def process_events(events: List[str]) -> List[Tuple[int, int]]:
    result = []
    start_timestamp = None

    for event in events:
        event_type, timestamp = event.split()
        timestamp = int(timestamp)

        if event_type == "start":
            if start_timestamp is None:
                start_timestamp = timestamp
        elif event_type == "end":
            if start_timestamp is not None:
                result.append((start_timestamp, timestamp))
                start_timestamp = None

    return result

import heapq

def max_trapped_water(grid):
    if not grid or not grid[0]:
        return 0

    n, m = len(grid), len(grid[0])
    visited = [[False] * m for _ in range(n)]
    heap = []
    water = 0

    # Push all the border cells into the heap
    for i in range(n):
        for j in range(m):
            if i == 0 or i == n-1 or j == 0 or j == m-1:
                heapq.heappush(heap, (grid[i][j], i, j))
                visited[i][j] = True

    # 4 possible directions to move
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while heap:
        height, x, y = heapq.heappop(heap)

        # Traverse the adjacent cells
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                visited[nx][ny] = True
                water += max(0, height - grid[nx][ny])
                heapq.heappush(heap, (max(height, grid[nx][ny]), nx, ny))

    return water

