class ParkingSystem:
    def __init__(self, numSpaces):
        self.totalSpaces = numSpaces
        self.availableSpaces = numSpaces
        self.parkedVehicles = {}

    def parkVehicle(self, vehicleType, licensePlate):
        if self.availableSpaces > 0 and licensePlate not in self.parkedVehicles:
            self.parkedVehicles[licensePlate] = vehicleType
            self.availableSpaces -= 1
            return True
        return False

    def retrieveVehicle(self, licensePlate):
        if licensePlate in self.parkedVehicles:
            del self.parkedVehicles[licensePlate]
            self.availableSpaces += 1
            return True
        return False

    def getAvailableSpaces(self):
        return self.availableSpaces

