def contains_difference(nums, k):
    """
    Returns True if there are two distinct indices i and j such that nums[i] and nums[j] differ by exactly k.
    """
    seen = set()
    for num in nums:
        if (num + k) in seen or (num - k) in seen:
            return True
        seen.add(num)
    return False

