import json
import re

def extract_ip_addresses(config_json):
    """
    Extracts all unique IP addresses from a given JSON object.

    :param config_json: A JSON object or a JSON string representing the network device configuration.
    :return: A list of unique IP addresses found in the JSON object.
    """
    # Regular expression to match IP address
    ip_regex = re.compile(r'\b(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\b')

    # Function to recursively search for IP addresses
    def find_ips(obj):
        ips = set()
        if isinstance(obj, dict):
            for k, v in obj.items():
                ips.update(find_ips(v))
        elif isinstance(obj, list):
            for item in obj:
                ips.update(find_ips(item))
        elif isinstance(obj, str):
            ips.update(ip_regex.findall(obj))
        return ips

    # Convert JSON string to Python object if necessary
    if isinstance(config_json, str):
        config_json = json.loads(config_json)

    # Extract IPs
    ip_addresses = find_ips(config_json)

    # Return as a list
    return list(ip_addresses)

def length_of_lis(nums):
    """
    Returns the length of the longest increasing subsequence in the given list of integers.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def evaluate_expression(s: str) -> int:
    """
    Evaluates a given mathematical expression string and returns the result.

    :param s: A string representing a valid mathematical expression.
    :return: An integer representing the result of the evaluated expression.
    """
    def compute(operands, operators):
        right = operands.pop()
        left = operands.pop()
        op = operators.pop()
        if op == '+':
            operands.append(left + right)
        elif op == '-':
            operands.append(left - right)
        elif op == '*':
            operands.append(left * right)
        elif op == '/':
            operands.append(left // right)

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    operands = []
    operators = []
    i = 0
    while i < len(s):
        if s[i] == ' ':
            i += 1
            continue
        if s[i] in '0123456789':
            num = 0
            while i < len(s) and s[i] in '0123456789':
                num = num * 10 + int(s[i])
                i += 1
            operands.append(num)
            i -= 1
        elif s[i] == '(':
            operators.append(s[i])
        elif s[i] == ')':
            while operators and operators[-1] != '(':
                compute(operands, operators)
            operators.pop()  # Remove '(' from the stack
        else:
            while (operators and precedence(operators[-1]) >= precedence(s[i])):
                compute(operands, operators)
            operators.append(s[i])
        i += 1
    while operators:
        compute(operands, operators)
    return operands[0]

