class DuplicateSubtrees:
    def __init__(self, root: TreeNode):
        self.root = root
        self.serial_map = defaultdict(list)

    def findDuplicateSubtrees(self) -> List[TreeNode]:
        def serialize(node: Optional[TreeNode]) -> str:
            if not node:
                return "#"
            serial = f"{node.val},{serialize(node.left)},{serialize(node.right)}"
            self.serial_map[serial].append(node)
            return serial

        serialize(self.root)

        result = []
        for nodes in self.serial_map.values():
            if len(nodes) > 1:
                result.append(nodes[0])

        return result

