def findTargetSumWays(nums, target):
    """
    Returns the number of ways to add the elements of nums (using both addition and subtraction)
    to reach exactly target.
    """
    memo = {}

    def backtrack(i, current_sum):
        if i == len(nums):
            return 1 if current_sum == target else 0

        if (i, current_sum) in memo:
            return memo[(i, current_sum)]

        # Choose the number with a plus sign
        add = backtrack(i + 1, current_sum + nums[i])

        # Choose the number with a minus sign
        subtract = backtrack(i + 1, current_sum - nums[i])

        memo[(i, current_sum)] = add + subtract
        return memo[(i, current_sum)]

    return backtrack(0, 0)

