def pacific_atlantic(matrix):
    if not matrix or not matrix[0]:
        return []

    m, n = len(matrix), len(matrix[0])

    def bfs(starts):
        visited = set(starts)
        queue = list(starts)
        while queue:
            x, y = queue.pop(0)
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in visited and matrix[nx][ny] >= matrix[x][y]:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
        return visited

    pacific_starts = [(i, 0) for i in range(m)] + [(0, j) for j in range(n)]
    atlantic_starts = [(i, n-1) for i in range(m)] + [(m-1, j) for j in range(n)]

    pacific_reachable = bfs(pacific_starts)
    atlantic_reachable = bfs(atlantic_starts)

    return list(pacific_reachable & atlantic_reachable)

