def sum_of_subtree(tree, target):
    """
    Returns the sum of all nodes in the subtree rooted at the node with the given target value.
    If the target value does not exist in the tree, returns 0.

    :param tree: dict, adjacency list representing the tree
    :param target: int, value of the node to find the subtree for
    :return: int, the sum of all nodes in the subtree rooted at the target node
    """
    if target not in tree:
        return 0

    def dfs(node):
        total = node
        for child in tree.get(node, []):
            total += dfs(child)
        return total

    return dfs(target)

