class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def longestZigZag(root):
    def dfs(node, direction, length):
        if not node:
            return length - 1

        if direction == "left":
            left_result = dfs(node.left, "right", length + 1)
            right_result = dfs(node.right, "left", 1)
        else:
            left_result = dfs(node.left, "right", 1)
            right_result = dfs(node.right, "left", length + 1)

        return max(left_result, right_result)

    if not root:
        return 0

    return max(dfs(root.left, "right", 1), dfs(root.right, "left", 1))

