def first_missing_positive(nums):
    """
    Returns the smallest positive integer that is not present in nums.

    Uses a linear time algorithm with constant extra space.
    """
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

def find_and_replace_pattern(words, pattern):
    """
    Finds and returns the list of words that match the given pattern.

    A word matches the pattern if it can be transformed into the pattern
    by replacing each letter with a common letter.

    :param words: List[str], list of words to check
    :param pattern: Str, the pattern to match
    :return: List[str], list of words that match the pattern
    """
    def matches(word, pattern):
        if len(word) != len(pattern):
            return False

        char_map = {}
        used_chars = set()

        for w_char, p_char in zip(word, pattern):
            if p_char in char_map:
                if char_map[p_char] != w_char:
                    return False
            else:
                if w_char in used_chars:
                    return False
                char_map[p_char] = w_char
                used_chars.add(w_char)

        return True

    return [word for word in words if matches(word, pattern)]

