from collections import defaultdict
from math import gcd

def max_points_on_a_line(points):
    def normalize(dx, dy):
        if dx == 0:
            return (0, 1)
        if dy == 0:
            return (1, 0)
        g = gcd(dx, dy)
        return (dx // g, dy // g) if dx > 0 else (-dx // g, -dy // g)

    if not points:
        return 0

    max_points = 1
    n = len(points)

    for i in range(n):
        slopes = defaultdict(int)
        duplicate_points = 0
        for j in range(i + 1, n):
            dx = points[j][0] - points[i][0]
            dy = points[j][1] - points[i][1]
            if dx == 0 and dy == 0:
                duplicate_points += 1
                continue
            slope = normalize(dx, dy)
            slopes[slope] += 1

        max_points = max(max_points, (max(slopes.values()) if slopes else 0) + duplicate_points + 1)

    return max_points

def minInsertions(s):
    """
    Returns the minimum number of insertions needed to make the string balanced.
    """
    left = 0
    insertions_needed = 0

    for char in s:
        if char == '(':
            left += 1
        elif char == ')':
            if left > 0:
                left -= 1
            else:
                insertions_needed += 1

    # After processing the string, any unmatched `(` will need to be closed
    insertions_needed += left

