def third_max(nums):
    """
    Returns the third maximum number in the array. 
    If the third maximum does not exist, returns the maximum number.
    """
    max_nums = [float('-inf'), float('-inf'), float('-inf')]
    for num in nums:
        if num not in max_nums:
            if num > max_nums[0]:
                max_nums = [num, max_nums[0], max_nums[1]]
            elif num > max_nums[1]:
                max_nums = [max_nums[0], num, max_nums[1]]
            elif num > max_nums[2]:
                max_nums = [max_nums[0], max_nums[1], num]

    return max_nums[2] if max_nums[2] != float('-inf') else max_nums[0]

