from collections import deque

class WindowMax:
    def __init__(self, arr, k):
        self.arr = arr
        self.k = k

    def getMax(self):
        if self.k > len(self.arr):
            return []

        result = []
        deq = deque()

        for i in range(len(self.arr)):
            # Ensure the deque's elements remain relevant within the window
            if deq and deq[0] == i - self.k:
                deq.popleft()

            # Maintain the decreasing order in deque for max value tracking
            while deq and self.arr[deq[-1]] < self.arr[i]:
                deq.pop()

            deq.append(i)

            # Append to result only when we have a complete window of size k
            if i >= self.k - 1:
                result.append(self.arr[deq[0]])

        return result

class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self, elements):
        if not elements:
            self.root = None
            return

        self.root = TreeNode(elements[0])
        queue = [self.root]
        i = 1

        while i < len(elements):
            current = queue.pop(0)
            if elements[i] is not None:
                current.left = TreeNode(elements[i])
                queue.append(current.left)
            i += 1
            if i < len(elements) and elements[i] is not None:
                current.right = TreeNode(elements[i])
                queue.append(current.right)
            i += 1

    def insert(self, value):
        if not self.root:
            self.root = TreeNode(value)
            return

        queue = [self.root]
        while queue:
            current = queue.pop(0)
            if not current.left:
                current.left = TreeNode(value)
                return
            else:
                queue.append(current.left)

            if not current.right:
                current.right = TreeNode(value)
                return
            else:
                queue.append(current.right)

    def levelOrderTraversal(self):
        if not self.root:
            return []

        result = []
        queue = [self.root]
        while queue:
            current = queue.pop(0)
            result.append(current.value)
            if current.left:
                queue.append(current.left)
            if current.right:
                queue.append(current.right)
        return result

    def findMaxDepth(self):
        def depth(node):
            if not node:
                return 0
            return 1 + max(depth(node.left), depth(node.right))

        return depth(self.root)

    def sumOfLeafNodes(self):
        if not self.root:
            return 0

        sum_leaves = 0
        queue = [self.root]
        while queue:
            current = queue.pop(0)
            if not current.left and not current.right:
                sum_leaves += current.value
            if current.left:
                queue.append(current.left)
            if current.right:
                queue.append(current.right)
        return sum_leaves

