def calculate_fibonacci(n):
    """
    Calculate the nth Fibonacci number using recursion.

    :param n: Index of the Fibonacci number to calculate.
    :return: The nth Fibonacci number.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return calculate_fibonacci(n - 1) + calculate_fibonacci(n - 2)

# Sample input to test the function
print(calculate_fibonacci(10))  # Expected output: 55

def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_of_primes(start, end):
    """Calculate the sum of all prime numbers within a given range [start, end]."""
    total = 0
    for num in range(start, end + 1):
        if is_prime(num):
            total += num
    return total

# Example usage:
# print(sum_of_primes(10, 30))  # Output should be 129 (11 + 13 + 17 + 19 + 23 + 29)

def is_balanced(s: str) -> bool:
    """
    Determines if the input string s containing '(', ')', '[', ']', '{', and '}' is balanced.

    A string is balanced if every opening bracket has a corresponding closing bracket in the correct order.

    :param s: The input string containing brackets.
    :return: True if the string is balanced, False otherwise.
    """
    matching_bracket = {')': '(', ']': '[', '}': '{'}
    stack = []

    for char in s:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if not stack or matching_bracket[char] != stack.pop():
                return False

    return not stack

def fibonacci(n):
    """
    Computes the nth Fibonacci number using recursion.

    Args:
    n (int): The position in the Fibonacci sequence. Must be a non-negative integer.

    Returns:
    int: The nth Fibonacci number.

    Raises:
    ValueError: If the input n is negative.
    """
    if n < 0:
        raise ValueError("Input should be a non-negative integer")

    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

# Example usage:
# print(fibonacci(10))  # Output: 55

def unique_substrings(s):
    """
    Generate all unique substrings of the input string s and return them in lexicographical order.

    :param s: Input string
    :return: List of unique substrings sorted in lexicographical order
    """
    substrings = set()
    n = len(s)

    for i in range(n):
        for j in range(i + 1, n + 1):
            substrings.add(s[i:j])

    return sorted(substrings)

def unique_elements(input_list):
    """
    Returns a list of unique elements from the input list.

    :param input_list: List of integers
    :return: List of unique integers
    """
    unique_list = []

    for element in input_list:
        is_unique = True
        for unique in unique_list:
            if element == unique:
                is_unique = False
                break

        if is_unique:
            unique_list.append(element)

    return unique_list

