import heapq
from collections import defaultdict

def find_parent(parents, node):
    if parents[node] == node:
        return node
    parents[node] = find_parent(parents, parents[node])
    return parents[node]

def union(parents, ranks, node1, node2):
    root1 = find_parent(parents, node1)
    root2 = find_parent(parents, node2)

    if root1 != root2:
        if ranks[root1] > ranks[root2]:
            parents[root2] = root1
        elif ranks[root1] < ranks[root2]:
            parents[root1] = root2
        else:
            parents[root2] = root1
            ranks[root1] += 1

def kruskal(n, edges, skip_edge_index=-1):
    parents = [i for i in range(n)]
    ranks = [0] * n
    mst_weight = 0
    edge_count = 0

    for i, (u, v, w) in enumerate(edges):
        if i == skip_edge_index:
            continue
        if find_parent(parents, u) != find_parent(parents, v):
            mst_weight += w
            union(parents, ranks, u, v)
            edge_count += 1

    if edge_count == n - 1:
        return mst_weight
    else:
        return float('inf')

def second_minimum_spanning_tree(n, edges):
    edges.sort(key=lambda x: x[2])
    mst_weight = kruskal(n, edges)

    if mst_weight == float('inf'):
        return -1

    smst_weight = float('inf')

    for i in range(len(edges)):
        weight = kruskal(n, edges, skip_edge_index=i)
        if weight > mst_weight:
            smst_weight = min(smst_weight, weight)

    return smst_weight if smst_weight != float('inf') else -1

