def max_number_of_pairs(nums, k):
    """
    Given a list of `n` distinct integers representing participants' abilities and an integer `k`,
    returns the maximum number of pairs such that the sum of the abilities in each pair is equal to `k`.
    """
    num_counter = {}
    for num in nums:
        if num in num_counter:
            num_counter[num] += 1
        else:
            num_counter[num] = 1

    pairs = 0
    for num in list(num_counter):
        complement = k - num
        if complement in num_counter and num_counter[num] > 0 and num_counter[complement] > 0:
            if num == complement:
                pairs += num_counter[num] // 2
                num_counter[num] = 0
            else:
                min_count = min(num_counter[num], num_counter[complement])
                pairs += min_count
                num_counter[num] -= min_count
                num_counter[complement] -= min_count

    return pairs

