def minimize_array_lexicographically(arr, k):
    """
    Returns the lexicographically smallest array possible after exactly k reversals.
    """
    n = len(arr)

    # Not enough operations, sort the whole array
    if k >= n:
        return sorted(arr)

    # If k is at least 2, we can sort the entire array
    # Explanation: We can achieve any possible permutation of the array by reversing subarrays twice
    if k >= 2:
        return sorted(arr)

    # With k = 1, we must identify optimal single reversal
    min_array = arr[:]

    for i in range(n):
        for j in range(i, n):
            reversed_subarray = arr[:i] + arr[i:j+1][::-1] + arr[j+1:]
            if reversed_subarray < min_array:
                min_array = reversed_subarray

    return min_array

def numIslands(grid):
    """
    Return the number of islands in the given grid.
    """
    if not grid:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]

    def dfs(x, y):
        if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] == '0' or visited[x][y]:
            return
        visited[x][y] = True
        dfs(x+1, y)
        dfs(x-1, y)
        dfs(x, y+1)
        dfs(x, y-1)

    island_count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1' and not visited[i][j]:
                dfs(i, j)
                island_count += 1

    return island_count

