def longest_bitonic_subsequence(arr):
    n = len(arr)

    # Edge case when array is empty
    if n == 0:
        return 0

    # Create two arrays to store the longest increasing subsequence
    inc = [1] * n # Length of LIS ending at each index
    dec = [1] * n # Length of LDS starting at each index

    # Calculate LIS values
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + 1:
                inc[i] = inc[j] + 1

    # Calculate LDS values
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j] and dec[i] < dec[j] + 1:
                dec[i] = dec[j] + 1

    # Calculate the maximum value of (inc[i] + dec[i] - 1)
    max_len = 0
    for i in range(n):
        max_len = max(max_len, inc[i] + dec[i] - 1)

    return max_len

