def find_diagonal_order(mat):
    """
    Given a m x n matrix mat of integers, return the elements in all possible diagonal orders.
    """
    if not mat or not mat[0]:
        return []

    m, n = len(mat), len(mat[0])
    result = []
    diagonals = {}

    # Collect elements of each diagonal
    for i in range(m):
        for j in range(n):
            if i + j not in diagonals:
                diagonals[i + j] = []
            diagonals[i + j].append(mat[i][j])

    # Traverse collected diagonals and add to result
    for key in sorted(diagonals.keys()):
        result.extend(diagonals[key])

    return result

