def max_root_to_leaf_sum(root):
    """
    Returns the maximum sum of the values along any root-to-leaf path.
    """
    if not root:
        return 0
    if not root.left and not root.right:  # if the node is a leaf
        return root.val

    left_sum = max_root_to_leaf_sum(root.left)
    right_sum = max_root_to_leaf_sum(root.right)

    return root.val + max(left_sum, right_sum)

