def longest_subsequence(arr, k):
    """
    Returns the length of the longest subsequence such that the 
    difference between adjacent elements is at most k.
    """
    n = len(arr)
    if n == 0:
        return 0

    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if abs(arr[i] - arr[j]) <= k:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

