def can_partition_to_k_palindromes(s, k):
    def dfs(index, k):
        if index == len(s):
            return k == 0
        if k == 0:
            return False
        for i in range(index + 1, len(s) + 1):
            if is_palindrome(s[index:i]):
                if dfs(i, k - 1):
                    return True
        return False

    return dfs(0, k)

def generate_primes(n):
    """
    Generate a list of prime numbers up to and including n.

    Parameters:
    n (int): The upper limit integer (inclusive) for generating prime numbers.

    Returns:
    list: A list of prime numbers up to and including n.
    """

    if n < 2:
        return []

    primes = [2]
    for num in range(3, n + 1, 2):
        is_prime = True
        for divisor in range(3, int(num ** 0.5) + 1, 2):
            if num % divisor == 0:
