def findDeepestNode(root):
    if not root:
        return None

    queue = [(root, 0)]  # Each element is a tuple (node, depth)
    max_depth = -1
    deepest_node = None

    while queue:
        current, depth = queue.pop(0)

        if depth > max_depth:
            max_depth = depth
            deepest_node = current

        if current.left:
            queue.append((current.left, depth + 1))
        if current.right:
            queue.append((current.right, depth + 1))

    return deepest_node

