def min_concatenations(words, target):
    from collections import defaultdict, deque

    # Create a queue to track current strings and their concatenation counts
    queue = deque([(target, 0)])
    visited = set()  # to avoid re-processing the same substring

    while queue:
        current, count = queue.popleft()

        # If the current string is empty, we've successfully formed the target
        if not current:
            return count

        # Try to match any word and create a new substring
        for word in words:
            if current.startswith(word):
                new_substring = current[len(word):]
                if new_substring not in visited:
                    visited.add(new_substring)
                    queue.append((new_substring, count + 1))

    return -1  # Impossible to form the target string

class WordQuery:
    def __init__(self, words):
        self.words = words
        self.precomputed_max_lengths = self._precompute_max_lengths(words)

    def _precompute_max_lengths(self, words):
        n = len(words)
        max_lengths = [[0] * n for _ in range(n)]

        for i in range(n):
            current_max = 0
            for j in range(i, n):
                current_max = max(current_max, len(words[j]))
                max_lengths[i][j] = current_max

        return max_lengths

    def query(self, start, end):
        return self.precomputed_max_lengths[start][end]

