def lexicographically_smallest_string(s):
    """
    Returns the lexicographically smallest string possible by performing the described operations
    on the input string s any number of times.

    :param s: String consisting of characters 'a', 'b', and 'c'
    :return: Lexicographically smallest string after operations
    """
    smallest_string = []

    for char in s:
        if char == 'a':
            smallest_string.append('a')
        elif char == 'b':
            smallest_string.append('a')
        elif char == 'c':
            smallest_string.append('a')

    return ''.join(smallest_string)

