def max_energy_collected(energy):
    """
    Returns the maximum energy a player can collect by starting at any checkpoint
    and either moving to the next checkpoint or skipping one checkpoint at each step.
    """
    if not energy:
        return 0
    n = len(energy)
    if n == 1:
        return energy[0]

    # Initialize dp arrays
    dp = [0] * n
    dp[0] = energy[0]
    if n > 1:
        dp[1] = max(energy[0], energy[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + energy[i])

    return max(dp[-1], dp[-2])

