def min_path_sum(grid):
    """
    Returns the minimum sum of the values along a path from the top-left 
    to the bottom-right corner of the grid. Movement is restricted to right
    or down.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Initialize the first row
    for i in range(1, n):
        grid[0][i] += grid[0][i - 1]

    # Initialize the first column
    for i in range(1, m):
        grid[i][0] += grid[i - 1][0]

    # Populate the rest of the grid
    for i in range(1, m):
        for j in range(1, n):
            grid[i][j] += min(grid[i-1][j], grid[i][j-1])

    return grid[m-1][n-1]

def minimumInsertionsToBalance(s: str) -> int:
    """
    Returns the minimum number of insertions needed to make s a valid parentheses string.
    """
    left_needed = 0  # To count the needed '('
    insertions = 0  # To count the needed ')'

    for char in s:
        if char == '(':
            left_needed += 1
        elif char == ')':
            if left_needed > 0:
                left_needed -= 1
            else:
                insertions += 1

    # Any remaining needed '(' will require a ')' insertion
    return insertions + left_needed

def match(word, pattern):
    """
    Helper function to check if the word matches the pattern.
    """
    mapping = {}
    reverse_mapping = {}
    for w_char, p_char in zip(word, pattern):
        if w_char in mapping:
            if mapping[w_char] != p_char:
                return False
        else:
            mapping[w_char] = p_char
        if p_char in reverse_mapping:
            if reverse_mapping[p_char] != w_char:
                return False
        else:
            reverse_mapping[p_char] = w_char
    return True

def findAndReplacePattern(words, pattern):
    """
    Find and return the list of words matching the given pattern.
    """
    result = []
    for word in words:
        if match(word, pattern):
            result.append(word)
    return result

def min_number_of_moves(grid):
    """
    Returns the minimum number of moves to make all values in the grid equal to zero.
    """
    return sum(sum(row) for row in grid)

