def can_finish_courses(num_courses, prerequisites):
    """
    Determines if it is possible to finish all courses given the prerequisites.

    Parameters:
        num_courses (int): The total number of courses.
        prerequisites (List[List[int]]): The list of prerequisite pairs, 
                                         where each pair [a, b] indicates that course a depends on course b.

    Returns:
        bool: True if it is possible to finish all courses, False otherwise.
    """

    # Create an adjacency list from the prerequisites
    graph = {i: [] for i in range(num_courses)}
    for dest, src in prerequisites:
        graph[src].append(dest)

    # Track visited nodes to detect cycles
    visiting = set()
    visited = set()

    def has_cycle(node):
        if node in visiting:
            return True
        if node in visited:
            return False

        visiting.add(node)
        for neighbor in graph[node]:
            if has_cycle(neighbor):
                return True
        visiting.remove(node)
        visited.add(node)
        return False

    for course in range(num_courses):
        if has_cycle(course):
            return False

    return True

