def min_tower_height(heights):
    """
    Returns the minimum height needed for the new tower to satisfy the conditions.
    """
    if not heights:
        return 0

    max_left = 0
    max_right = 0

    for height in heights:
        if height > max_left:
            max_left = height

    for height in reversed(heights):
        if height > max_right:
            max_right = height

    return max(max_left, max_right)

