from collections import deque

def is_complete_binary_tree(data):
    """
    Determine if the binary tree represented in level-order traversal is a complete binary tree.
    """
    n = len(data)
    if n == 0:
        return True

    nodes = deque([(0, data[0])])
    seen_null = False

    while nodes:
        index, value = nodes.popleft()

        if value is None:
            seen_null = True
        else:
            if seen_null:
                return False
            left_index = 2 * index + 1
            right_index = 2 * index + 2
            if left_index < n:
                nodes.append((left_index, data[left_index]))
            if right_index < n:
                nodes.append((right_index, data[right_index]))

    return True

