def longest_palindrome(s: str) -> str:
    """
    Returns the longest palindromic substring in the given string s.

    :param s: Input string
    :return: Longest palindromic substring
    """
    if not s:
        return ""

    n = len(s)
    dp = [[False] * n for _ in range(n)]
    start = 0
    max_length = 1

    for i in range(n):
        dp[i][i] = True

    for i in range(n - 1):
        if s[i] == s[i + 1]:
            dp[i][i + 1] = True
            start = i
            max_length = 2

    for k in range(3, n + 1):
        for i in range(n - k + 1):
            j = i + k - 1

            if dp[i + 1][j - 1] and s[i] == s[j]:
                dp[i][j] = True

                if k > max_length:
                    start = i
                    max_length = k

    return s[start:start + max_length]

class Matrix:
    def __init__(self, data):
        """
        Initialize the Matrix with a 2D list.

        :param data: List of lists representing the matrix.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def add(self, other):
        """
        Add two matrices.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the sum.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for addition")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtract two matrices.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the difference.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for subtraction")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiply two matrices.

        :param other: Another Matrix object.
        :return: A new Matrix object representing the product.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns of first matrix must be equal to number of rows of second matrix for multiplication")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __str__(self):
        """
        String representation of the matrix.

        :return: A string representation of the matrix.
        """
        return '\n'.join(['\t'.join(map(str, row)) for row in self.data])

