import re

def replace_substring_preserving_case(text, old, new):
    """
    Replaces all instances of the substring `old` in `text` with `new`, preserving the case of `old`.

    :param text: The original string.
    :param old: The substring to be replaced.
    :param new: The substring to replace with.
    :return: A new string with the replacements made.
    """
    def replace(match):
        matched_text = match.group(0)
        if matched_text.islower():
            return new.lower()
        elif matched_text.isupper():
            return new.upper()
        elif matched_text.istitle():
            return new.capitalize()
        else:
            return new

    pattern = re.compile(re.escape(old), re.IGNORECASE)
    result = pattern.sub(replace, text)
    return result

