def flatten_json(y):
    """
    Flattens a nested dictionary into a single-level dictionary.

    Parameters:
    y (dict): The nested dictionary to flatten.

    Returns:
    dict: A single-level dictionary with flattened keys.
    """
    out = {}

    def flatten(x, name=''):
        if isinstance(x, dict):
            for a in x:
                flatten(x[a], name + a + '_')
        elif isinstance(x, list):
            for i, a in enumerate(x):
                flatten(a, name + str(i) + '_')
        else:
            out[name[:-1]] = x

    flatten(y)
    return out

