def evaluate_prefix(expression):
    """
    Evaluates a mathematical expression given in prefix notation.

    :param expression: A string representing the prefix expression.
    :return: An integer representing the result of the evaluated expression.
    """
    stack = []
    operators = {'+', '-', '*', '/'}

    tokens = expression.split()[::-1]

    for token in tokens:
        if token in operators:
            operand1 = stack.pop()
            operand2 = stack.pop()

            if token == '+':
                result = operand1 + operand2
            elif token == '-':
                result = operand1 - operand2
            elif token == '*':
                result = operand1 * operand2
            elif token == '/':
                result = operand1 // operand2

            stack.append(result)
        else:
            stack.append(int(token))

    return stack[0]

def count_chars_before(s, c):
    """
    Returns a dictionary with characters in the string `s` that appear before the first occurrence of `c` as keys,
    and their counts as values.

    :param s: The input string.
    :param c: The character to stop counting before.
    :return: A dictionary with character counts.
    """
    char_count = {}
    for char in s:
        if char == c:
            break
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    return char_count

