def find_repeated_substrings(s, n):
    """
    Given a string `s` and an integer `n`, returns a list of all unique substrings of length `n` 
    that occur more than once within the string `s`. The list is returned in lexicographical order.
    """
    if n <= 0 or n > len(s) or not s:
        return []

    substring_count = {}
    for i in range(len(s) - n + 1):
        substring = s[i:i + n]
        if substring in substring_count:
            substring_count[substring] += 1
        else:
            substring_count[substring] = 1

    repeated_substrings = [substr for substr, count in substring_count.items() if count > 1]
    return sorted(repeated_substrings)

