def findLongestPath(root):
    """
    Given the root of the k-ary tree, find the longest path from the root to a leaf.

    :param root: Node, the root of the k-ary tree
    :return: int, length of the longest path from the root to any leaf
    """
    if not root.children:
        return 0
    return 1 + max(findLongestPath(child) for child in root.children)

