def longest_word_chain(s):
    """
    Returns the length of the longest word chain in the given string `s`.
    """
    words = set(s.split())
    memo = {}

    def dfs(word):
        if word in memo:
            return memo[word]

        max_length = 1
        for i in range(len(word)):
            next_word = word[:i] + word[i+1:]
            if next_word in words:
                max_length = max(max_length, 1 + dfs(next_word))

        memo[word] = max_length
        return max_length

    return max(dfs(word) for word in words)

