def evaluate(expression):
    def helper(s, index):
        num = 0
        stack = []
        sign = '+'

        while index < len(s):
            char = s[index]

            if char.isdigit():
                num = num * 10 + int(char)

            if char == '(':
                num, index = helper(s, index + 1)

            if char in {'+', '-', '*', '/', ')'} or index == len(s) - 1:
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack[-1] *= num
                elif sign == '/':
                    stack[-1] = int(stack[-1] / num)

                if char == ')':
                    return sum(stack), index

                num = 0
                sign = char

            index += 1

        return sum(stack), index

    result, _ = helper(expression, 0)
    return result

