def longest_arith_subarray(nums):
    if len(nums) < 2:
        return len(nums)

    longest_length = 1
    current_length = 1
    current_diff = None

    for i in range(1, len(nums)):
        diff = nums[i] - nums[i-1]
        if diff == current_diff:
            current_length += 1
        else:
            current_diff = diff
            current_length = 2
        longest_length = max(longest_length, current_length)

    return longest_length

