def findAnagrams(s: str, p: str):
    from collections import Counter

    p_count = Counter(p)
    s_count = Counter()
    result = []
    p_len = len(p)

    for i in range(len(s)):
        # Add one more letter on the right side of the window
        s_count[s[i]] += 1
        # Remove one letter from the left side of the window
        if i >= p_len:
            if s_count[s[i - p_len]] == 1:
                del s_count[s[i - p_len]]
            else:
                s_count[s[i - p_len]] -= 1
        # Compare window with the word frequency
        if p_count == s_count:
            result.append(i - p_len + 1)

    return result

