class PalindromicChecker:
    def __init__(self, n, base):
        self.n = n
        self.base = base

    def isPalindromic(self):
        if self.n < 0:
            return False

        base_n_str = self.int_to_base(self.n, self.base)
        return base_n_str == base_n_str[::-1]

    @staticmethod
    def int_to_base(n, base):
        if n == 0:
            return "0"

        digits = []
        while n:
            digits.append(int(n % base))
            n //= base
        digits = digits[::-1]
        return "".join(str(digit) for digit in digits)

