def flatten_dict(d, parent_key='', sep='.'):
    """
    Flattens a nested dictionary into a flat dictionary with dot-separated keys.

    :param d: The nested dictionary to flatten.
    :param parent_key: The base key string for recursion (used internally).
    :param sep: The separator to use between keys.
    :return: A flat dictionary with dot-separated keys.
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

def find_key_value(data, key):
    """
    Recursively searches for a given key in a nested dictionary and returns its associated value.

    Parameters:
    data (dict): The nested dictionary to search within.
    key (str): The key to search for.

    Returns:
    The value associated with the key if found, otherwise None.
    """
    if isinstance(data, dict):
        for k, v in data.items():
            if k == key:
                return v
            elif isinstance(v, dict):
                result = find_key_value(v, key)
                if result is not None:
                    return result
    return None

