def evaluate_postfix(expression):
    """
    Evaluates a given postfix expression and returns the result as a floating-point number.

    :param expression: A string representing a mathematical expression in postfix notation.
    :return: The result of the postfix expression evaluation as a float.
    """
    tokens = expression.split()
    stack = []
    operators = {'+', '-', '*', '/'}

    for token in tokens:
        if token in operators:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)
        else:
            stack.append(float(token))

    return stack.pop()

