def find_primes_in_range(start, end):
    """
    Returns a list of all prime numbers between start and end (inclusive).

    :param start: An integer representing the start of the range.
    :param end: An integer representing the end of the range.
    :return: A list of integers representing all prime numbers in the range.
    """
    def is_prime(num):
        """
        Checks if a number is prime.

        :param num: An integer to check for primality.
        :return: True if the number is prime, False otherwise.
        """
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = []
    for num in range(start, end + 1):
        if is_prime(num):
            primes.append(num)
    return primes

