def find_min_max(tree: TreeNode) -> Tuple[int, int]:
    """
    Perform an in-order traversal to find the minimum and maximum values in a binary search tree.

    :param tree: The root node of the binary search tree.
    :return: A tuple containing the minimum and maximum values in the BST.
    """
    def in_order_traversal(node):
        if not node:
            return float('inf'), float('-inf')

        left_min, left_max = in_order_traversal(node.left)
        right_min, right_max = in_order_traversal(node.right)

        current_min = min(node.val, left_min, right_min)
        current_max = max(node.val, left_max, right_max)

        return current_min, current_max

    return in_order_traversal(tree)

class Polynomial:
    def __init__(self, coefficients):
        """
        Initialize a polynomial given a list of coefficients.
        Coefficients are in the order [a0, a1, a2, ..., an] representing
        a0 + a1*x + a2*x^2 + ... + an*x^n
        """
        self.coefficients = coefficients

    def __add__(self, other):
        """
        Add two polynomials together and return a new Polynomial object.
        """
        max_len = max(len(self.coefficients), len(other.coefficients))
        self_extended = self.coefficients + [0] * (max_len - len(self.coefficients))
        other_extended = other.coefficients + [0] * (max_len - len(other.coefficients))
        result_coeffs = [a + b for a, b in zip(self_extended, other_extended)]
        return Polynomial(result_coeffs)

    def evaluate(self, x):
        """
        Evaluate the polynomial at a given value of x and return the result.
        """
        return sum(a * (x ** i) for i, a in enumerate(self.coefficients))

    def __repr__(self):
        """
        Return a human-readable string representation of the polynomial.
        """
        terms = []
        for power, coeff in enumerate(self.coefficients):
            if coeff == 0:
                continue
            if power == 0:
                terms.append(f"{coeff}")
            elif power == 1:
                if coeff == 1:
                    terms.append("x")
                elif coeff == -1:
                    terms.append("-x")
                else:
                    terms.append(f"{coeff}x")
            else:
                if coeff == 1:
                    terms.append(f"x^{power}")
                elif coeff == -1:
                    terms.append(f"-x^{power}")
                else:
                    terms.append(f"{coeff}x^{power}")
        poly_str = " + ".join(terms)
        poly_str = poly_str.replace("+ -", "- ")
        return poly_str if poly_str else "0"

