class DatabaseConnection:
    def __init__(self, db_path):
        """Initialize the DatabaseConnection object with the path to the SQLite database."""
        self.db_path = db_path
        self.connection = None

    def create_connection(self):
        """Establish a connection to the SQLite database. Returns True if successful, False otherwise."""
        try:
            self.connection = sqlite3.connect(self.db_path)
            return True
        except sqlite3.Error:
            return False

    def execute_query(self, query):
        """Execute a given SQL query. Returns the result of the query if successful, None otherwise."""
        if self.connection is None:
            return None

        try:
            cursor = self.connection.cursor()
            cursor.execute(query)
            self.connection.commit()
            return cursor.fetchall()
        except sqlite3.Error:
            return None

    def close_connection(self):
        """Close the connection to the SQLite database. Returns True if successful, False otherwise."""
        if self.connection:
            try:
                self.connection.close()
                return True
            except sqlite3.Error:
                return False

def is_balanced_parentheses(s: str) -> bool:
    """
    Determines if the parentheses in the string are balanced.

    :param s: A string consisting of characters '(' and ')'.
    :return: True if the parentheses are balanced, False otherwise.
    """
    stack = []

    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()

