def findSubstring(s, words):
    """
    Returns the starting indices of all the words' concatenation in the string `s`.
    """
    if not s or not words:
        return []

    # Length of each word
    word_length = len(words[0])

    # Total length of all words when concatenated together
    total_length = word_length * len(words)

    # Result list to keep all starting indices of valid concatenations
    result = []

    # Dictionary to store the word count from words list
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    # Traverse the string to find valid concatenations
    for i in range(len(s) - total_length + 1):
        seen_words = {}
        for j in range(len(words)):
            # Starting index of the current word in the substring
            word_start_index = i + j * word_length
            # Extract the word from the string
            word = s[word_start_index:word_start_index + word_length]
            if word in word_count:
                if word in seen_words:
                    seen_words[word] += 1
                else:
                    seen_words[word] = 1
                # If word count exceeds the required count, break
                if seen_words[word] > word_count[word]:
                    break
            else:
                break
        # If all words are seen the required number of times, add index to result
        if seen_words == word_count:
            result.append(i)

    return result

def can_partition_k_subsets(nums, k):
    """
    Determines if it's possible to partition the nums array into k subsets with equal sums.
    """
    if not nums or k == 0:
        return False

    total_sum = sum(nums)
    if total_sum % k != 0:
        return False

    target = total_sum // k
    nums.sort(reverse=True)
    buckets = [0] * k

    def dfs(index):
        if index == len(nums):
            return all(b == target for b in buckets)

        for i in range(k):
            if buckets[i] + nums[index] > target:
                continue
            buckets[i] += nums[index]
            if dfs(index + 1):
                return True
            buckets[i] -= nums[index]
            if buckets[i] == 0:
                break
        return False

    return dfs(0)

