def can_be_non_decreasing(nums):
    """
    Returns true if it's possible to remove one element from the list
    to get a non-decreasing sequence, otherwise returns false.
    """
    def is_non_decreasing(arr):
        return all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1))

    for i in range(len(nums)):
        if is_non_decreasing(nums[:i] + nums[i+1:]):
            return True
    return False

