def is_possible_to_remove_edge(n, edges):
    """
    Determine if it is possible to remove exactly one edge to make the graph a tree.

    Parameters:
    n (int): The number of nodes in the graph.
    edges (List[List[int]]): The list of edges in the graph.

    Returns:
    bool: True if it's possible to remove exactly one edge to make the graph a tree, False otherwise.
    """
    if len(edges) != n:
        return False

    def find(parent, i):
        if parent[i] == i:
            return i
        else:
            return find(parent, parent[i])

    def union(parent, rank, x, y):
        xroot = find(parent, x)
        yroot = find(parent, y)

        if xroot != yroot:
            if rank[xroot] < rank[yroot]:
                parent[xroot] = yroot
            elif rank[xroot] > rank[yroot]:
                parent[yroot] = xroot
            else:
                parent[yroot] = xroot
                rank[xroot] += 1

    # Using Union-Find algorithm to detect a cycle
    parent = []
    rank = []

    for node in range(n):
        parent.append(node)
        rank.append(0)

    for u, v in edges:
        uroot = find(parent, u)
        vroot = find(parent, v)

        if uroot == vroot:  # Cycle detected
            return True
        else:
            union(parent, rank, uroot, vroot)

    return False

class ListNode:
