        self.next = next

def hasCycle(head):
    """
    Determines if the linked list contains a cycle.

    :param head: ListNode, the head of the linked list
    :return: bool, True if there is a cycle, False otherwise
    """
    if not head or not head.next:
        return False

    slow = head
    fast = head.next

    while slow != fast:
        if not fast or not fast.next:
            return False
        slow = slow.next
        fast = fast.next.next

    return True

def longest_subarray_with_sum_at_most_x(arr, x):
    max_length = 0
    current_sum = 0
    start_index = 0

    for end_index in range(len(arr)):
        current_sum += arr[end_index]

        while current_sum > x and start_index <= end_index:
            current_sum -= arr[start_index]
            start_index += 1

        if current_sum <= x:
            max_length = max(max_length, end_index - start_index + 1)

    return max_length

