def longest_unique_subsequence(s: str) -> int:
    """
    Returns the length of the longest unique subsequence with no consecutive repeating characters.
    """
    if not s:
        return 0

    result = []
    for char in s:
        if not result or result[-1] != char:
            result.append(char)

    return len(result)

