from collections import deque
from typing import List

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def levelOrder(root: TreeNode) -> List[List[int]]:
    """
    Returns the level order traversal of the nodes' values of a binary tree.
    """
    if not root:
        return []

    result = []
    queue = deque([root])

    while queue:
        level = []
        for _ in range(len(queue)):
            node = queue.popleft()
            level.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        result.append(level)

    return result

from collections import deque
from typing import Deque, Dict

class RateLimiter:
    def __init__(self, maxRequests: int, interval: int):
        """
        Initializes the RateLimiter object with a maximum number of allowed
        requests and an interval in seconds.
        """
        self.maxRequests = maxRequests
        self.interval = interval
        self.requestLogs: Dict[str, Deque[int]] = {}

    def allowRequest(self, key: str, timestamp: int) -> bool:
        """
        Returns true if the request for the given key at the specified timestamp
        is allowed, otherwise returns false.
        """
        if key not in self.requestLogs:
            self.requestLogs[key] = deque()

        self._cleanup_old_requests(key, timestamp)

        if len(self.requestLogs[key]) < self.maxRequests:
            self.requestLogs[key].append(timestamp)
            return True
        else:
            return False

    def _cleanup_old_requests(self, key: str, timestamp: int):
        """
        Remove timestamps that are outside of the interval.
        """
        while self.requestLogs[key] and self.requestLogs[key][0] <= timestamp - self.interval:
            self.requestLogs[key].popleft()

