from math import gcd
from functools import reduce

def lcm(a, b):
    """
    Returns the Least Common Multiple (LCM) of two integers a and b.
    """
    return a * b // gcd(a, b)

def smallest_multiple(start, end):
    """
    Returns the smallest integer that is evenly divisible by all integers in the range [start, end].
    """
    return reduce(lcm, range(start, end + 1))

