def matches_with_one_edit(s1, s2):
    """
    Helper function to determine if s1 can be transformed into s2 by at most one edit 
    (insert, delete, or replace one character).
    """
    m, n = len(s1), len(s2)
    if abs(m - n) > 1:
        return False

    edits = 0
    i, j = 0, 0

    while i < m and j < n:
        if s1[i] != s2[j]:
            if edits == 1:
                return False

            if m > n:
                i += 1
            elif m < n:
                j += 1
            else:
                i += 1
                j += 1

            edits += 1
        else:
            i += 1
            j += 1

    if i < m or j < n:
        edits += 1

    return edits <= 1

def index_of_query(strings, query):
    """
    Returns the index of the string in the list that matches the query after
    performing at most one string transformation on each string in the list.
    """
    for index, string in enumerate(strings):
        if string == query or matches_with_one_edit(string, query):
            return index
    return -1

def find_peak(matrix):
    """
    Find a peak element in the given matrix and return its indices.
    A peak is defined as an element that is greater than or equal to its adjacent elements.
    """
    def find_max_index(column, start_row, end_row):
        """
        Find the row index with the maximum value in the given column between start_row and end_row.
        """
        max_index = start_row
        for i in range(start_row + 1, end_row + 1):
            if matrix[i][column] > matrix[max_index][column]:
                max_index = i
        return max_index

    def find_peak_recursive(start_col, end_col):
        """
        Recursively find a peak element in the submatrix defined by columns start_col to end_col.
        """
        mid_col = (start_col + end_col) // 2
        max_row = find_max_index(mid_col, 0, len(matrix) - 1)

        if (mid_col > 0 and matrix[max_row][mid_col] < matrix[max_row][mid_col - 1]):
            return find_peak_recursive(start_col, mid_col - 1)
        elif (mid_col < len(matrix[0]) - 1 and matrix[max_row][mid_col] < matrix[max_row][mid_col + 1]):
            return find_peak_recursive(mid_col + 1, end_col)
        else:
            return max_row, mid_col

    return find_peak_recursive(0, len(matrix[0]) - 1)

