def count_characters(words, chars):
    """
    Returns the sum of the lengths of all words that can be formed using the characters in chars.
    Each character in chars can only be used once per word.
    """
    from collections import Counter

    def can_form_word(word, chars_count):
        word_count = Counter(word)
        for char, count in word_count.items():
            if count > chars_count.get(char, 0):
                return False
        return True

    chars_count = Counter(chars)
    total_length = 0

    for word in words:
        if can_form_word(word, chars_count):
            total_length += len(word)

    return total_length

def can_construct_target(words, target):
    """
    Determine if `target` can be constructed by concatenating words from `words`,
    each word can be used any number of times.
    """
    dp = [False] * (len(target) + 1)
    dp[0] = True

    for i in range(1, len(target) + 1):
        for word in words:
            if i >= len(word) and dp[i - len(word)] and target[i-len(word):i] == word:
                dp[i] = True
                break

    return dp[len(target)]

def isWellFormed(s: str) -> bool:
    """
    Determines if the input string is well-formed with respect to parentheses.

    Args:
    s (str): Input string containing only '(', ')', '{', '}', '[' and ']'.

    Returns:
    bool: True if the string is well-formed, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
