    def __init__(self):
        pass

    def isPalindrome(self, s: str) -> bool:
        def is_valid(sub_s: str) -> bool:
            return sub_s == sub_s[::-1]

        left, right = 0, len(s) - 1

        while left < right:
            if s[left] != s[right]:
                return is_valid(s[left+1:right+1]) or is_valid(s[left:right])
            left += 1
            right -= 1

        return True

