def min_reversals_to_balance(s):
    """
    Returns the minimum number of reversals required to make the string balanced, or -1 if impossible.
    """
    if len(s) % 2 != 0:
        return -1

    left_bracket_count = 0
    right_bracket_count = 0

    for bracket in s:
        if bracket == '{':
            left_bracket_count += 1
        else:
            if left_bracket_count > 0:
                left_bracket_count -= 1
            else:
                right_bracket_count += 1

    return (left_bracket_count + 1) // 2 + (right_bracket_count + 1) // 2

