def count_formable_words(s, words):
    """
    Returns the number of words that can be formed by a substring of s.
    """
    def can_form(word, s):
        s_idx = 0
        word_idx = 0
        while s_idx < len(s) and word_idx < len(word):
            if s[s_idx] == word[word_idx]:
                word_idx += 1
            s_idx += 1
        return word_idx == len(word)

    count = 0
    for word in words:
        if can_form(word, s):
            count += 1
    return count

