def count_employees(employees):
    """
    Counts the total number of employees in a hierarchical organization structure.

    :param employees: List of dictionaries representing the hierarchical structure of employees.
    :return: Integer representing the total number of employees.
    """
    total = 0
    for employee in employees:
        total += 1
        if employee['subordinates']:
            total += count_employees(employee['subordinates'])
    return total

