def find_second_largest(numbers):
    """
    Returns the second largest distinct integer in the list.
    Raises ValueError if the list contains fewer than two distinct integers.

    :param numbers: List of integers
    :return: Second largest distinct integer
    """
    if len(numbers) < 2:
        raise ValueError("List must contain at least two distinct numbers")

    first_largest = second_largest = None

    for number in numbers:
        if first_largest is None or number > first_largest:
            second_largest = first_largest
            first_largest = number
        elif number != first_largest:
            if second_largest is None or number > second_largest:
                second_largest = number

    if second_largest is None:
        raise ValueError("List must contain at least two distinct numbers")

    return second_largest

def is_valid_ipv4(ip):
    """
    Determines if the given string is a valid IPv4 address.

    :param ip: A string representing the IP address to be validated.
    :return: True if the string is a valid IPv4 address, False otherwise.
    """
    parts = ip.split('.')

    if len(parts) != 4:
        return False

    for part in parts:
        if not part.isdigit():
            return False

        num = int(part)

        if num < 0 or num > 255:
            return False

        if part != str(num):
            return False

    return True

class Graph:
    def __init__(self):
        # Initialize an empty dictionary to store the graph.
        # Keys will be vertices, and values will be sets of adjacent vertices.
        self.graph = {}

    def add_vertex(self, vertex):
        """Adds a new vertex to the graph."""
        if vertex not in self.graph:
            self.graph[vertex] = set()

    def add_edge(self, v1, v2):
        """Adds an edge between two vertices."""
        if v1 not in self.graph:
            self.add_vertex(v1)
        if v2 not in self.graph:
            self.add_vertex(v2)
        self.graph[v1].add(v2)
        self.graph[v2].add(v1)

    def remove_vertex(self, vertex):
        """Removes a vertex and all edges connected to it from the graph."""
        if vertex in self.graph:
            for neighbor in self.graph[vertex]:
                self.graph[neighbor].remove(vertex)
            del self.graph[vertex]

    def remove_edge(self, v1, v2):
        """Removes an edge between two vertices."""
        if v1 in self.graph and v2 in self.graph:
            if v2 in self.graph[v1]:
                self.graph[v1].remove(v2)
            if v1 in self.graph[v2]:
                self.graph[v2].remove(v1)

    def vertex_exists(self, vertex):
        """Checks if a vertex exists in the graph."""
        return vertex in self.graph

    def edge_exists(self, v1, v2):
        """Checks if an edge exists between two vertices."""
        return v1 in self.graph and v2 in self.graph[v1]

    def get_neighbors(self, vertex):
        """Returns the set of neighbors of a given vertex."""
        return self.graph.get(vertex, set())

