class Inventory:
    def __init__(self):
        """Initialize an empty inventory."""
        self.items = {}

    def add_item(self, name, price, quantity):
        """Add an item to the inventory or update its quantity if it already exists."""
        if name in self.items:
            _, existing_quantity = self.items[name]
            quantity += existing_quantity
        self.items[name] = (price, quantity)

    def remove_item(self, name):
        """Remove an item from the inventory if it exists."""
        if name in self.items:
            del self.items[name]

    def update_item(self, name, price, quantity):
        """Update the price and quantity of an existing item."""
        self.items[name] = (price, quantity)

