        return self.items.get(name, (0, 0))[1]

def gcd(a, b):
    """Calculate the Greatest Common Divisor of a and b using the Euclidean algorithm."""
    while b:
        a, b = b, a % b
    return a

def least_common_multiple(a, b):
    """Calculate the Least Common Multiple of a and b using the relationship between GCD and LCM."""
    return abs(a * b) // gcd(a, b)

