def sum_of_primes(n):
    """
    Computes the sum of all prime numbers less than a given integer n.

    Parameters:
    n (int): The upper limit (exclusive) for finding prime numbers.

    Returns:
    int: The sum of all prime numbers less than n.
    """
    if n <= 2:
        return 0
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            is_prime[i*i:n:i] = [False] * len(is_prime[i*i:n:i])
    return sum(index for index, prime in enumerate(is_prime) if prime)

