def max_non_adjacent_sum(arr):
    """
    Returns the maximum subarray sum such that no two elements of 
    the subarray are adjacent in the original array.
    """
    if not arr:
        return 0
    if len(arr) == 1:
        return max(0, arr[0])

    inclusive = 0  # Max sum including the current element
    exclusive = 0  # Max sum excluding the current element

    for num in arr:
        new_exclusive = max(inclusive, exclusive)
        inclusive = exclusive + num
        exclusive = new_exclusive

    return max(inclusive, exclusive)

