def is_valid(s: str) -> bool:
    """
    Returns True if the string s containing only the characters '(',')','{','}','[', and ']' 
    is valid according to the given rules, otherwise returns False.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            return False
    return stack == []

