def find_substrings(words):
    """
    Given a list of strings `words`, find all strings in `words` that are **substrings** of another string in `words`.
    Returns the list of these strings in any order.
    """
    substrings = set()

    for i in range(len(words)):
        for j in range(len(words)):
            if i != j and words[i] in words[j]:
                substrings.add(words[i])

    return list(substrings)

import math

def count_pairs_within_radius(coordinates, radius):
    """
    Returns the number of distinct pairs of points (a, b) such that the Euclidean distance 
    between point a and point b is less than or equal to radius.

    Parameters:
    coordinates (list of list of int): 2D array where coordinates[i] = [xi, yi]
    radius (int): Euclidean distance threshold

    Returns:
    int: number of distinct pairs within the given radius
    """
    def euclidean_distance(p1, p2):
        return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

    count = 0
    n = len(coordinates)
    for i in range(n):
        for j in range(i + 1, n):
            if euclidean_distance(coordinates[i], coordinates[j]) <= radius:
                count += 1
    return count

