def interleave(word1, word2):
    def interleave_helper(w1, w2, result, idx1, idx2):
        if idx1 == len(w1) and idx2 == len(w2):
            results.append(result)
            return
        if idx1 < len(w1):
            interleave_helper(w1, w2, result + w1[idx1], idx1 + 1, idx2)
        if idx2 < len(w2):
