def largestIntegerAfterKSwaps(num: str, k: int) -> str:
    """
    Returns the largest possible integer after performing at most k swaps on the string num.
    """
    def swap(num_list, i, j):
        num_list[i], num_list[j] = num_list[j], num_list[i]

    num_list = list(num)
    n = len(num_list)

    # Helper function to perform dfs to find the maximum number
    def dfs(num_list, k):
        nonlocal max_num
        if k == 0:
            return

        for i in range(n):
            for j in range(i + 1, n):
                if num_list[i] < num_list[j]:
                    swap(num_list, i, j)
                    current_num = ''.join(num_list)
                    if current_num > max_num:
                        max_num = current_num
                    dfs(num_list, k - 1)
                    swap(num_list, i, j)

    max_num = num
    dfs(num_list, k)

    return max_num

