from collections import Counter
from functools import lru_cache
from typing import List

def minStickers(stickers: List[str], target: str) -> int:
    # Preprocessing - calculate the frequency of characters in each sticker
    sticker_counts = [Counter(sticker) for sticker in stickers]

    # Define a helper function to backtrack and find the minimum stickers
    @lru_cache(None)
    def backtrack(remaining: str):
        if not remaining:
            return 0
        remaining_count = Counter(remaining)

        res = float('inf')
        for count in sticker_counts:
            if count[remaining[0]] == 0:
                continue

            new_remaining = []
            for ch, cnt in remaining_count.items():
                if cnt > count[ch]:
                    new_remaining.append(ch * (cnt - count[ch]))

            next_remaining = ''.join(new_remaining)
            res = min(res, 1 + backtrack(next_remaining))

        return res

    result = backtrack(target)
    return result if result != float('inf') else -1

