def flatten_dict(data, parent_key='', sep='_'):
    """
    Recursively flattens a nested dictionary into a single-level dictionary with compound keys.

    :param data: The dictionary to flatten.
    :param parent_key: The base key string for recursion (used internally).
    :param sep: The separator to use between keys.
    :return: A flattened dictionary with compound keys.
    """
    items = []
    for k, v in data.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

