def evaluate_expression(expression):
    """
    Evaluates a mathematical expression given as a string and returns the result as an integer.

    :param expression: A string representing a well-formed mathematical expression.
    :return: An integer representing the evaluated result of the expression.
    """
    def parse_expression(tokens):
        def parse_factor(tokens):
            token = tokens.pop(0)
            if token.isdigit():
                return int(token)
            elif token == '(':
                value = parse_expression(tokens)
                tokens.pop(0)  # Remove the closing ')'
                return value

        def parse_term(tokens):
            value = parse_factor(tokens)
            while tokens and tokens[0] in ('*', '/'):
                operator = tokens.pop(0)
                right = parse_factor(tokens)
                if operator == '*':
                    value *= right
                elif operator == '/':
                    value //= right  # Assume integer division
            return value

        value = parse_term(tokens)
        while tokens and tokens[0] in ('+', '-'):
            operator = tokens.pop(0)
            right = parse_term(tokens)
            if operator == '+':
                value += right
            elif operator == '-':
                value -= right
        return value

    # Tokenize the expression
    tokens = []
    current_number = ''
    for char in expression:
        if char.isdigit():
            current_number += char
        else:
            if current_number:
                tokens.append(current_number)
                current_number = ''
            if char in '+-*/()':
                tokens.append(char)
    if current_number:
        tokens.append(current_number)

    return parse_expression(tokens)

# Example usage:
