print(result)  # Output must be -17

def character_frequency(s):
    """
    Computes the frequency of each alphabetic character in the input string,
    treating uppercase and lowercase versions of the same letter as identical.

    Parameters:
    s (str): The input string.

    Returns:
    dict: A dictionary with lowercase alphabetic characters as keys and their frequencies as values.
    """
    frequency_dict = {}
    for char in s.lower():
        if char.isalpha():
            if char in frequency_dict:
                frequency_dict[char] += 1
            else:
                frequency_dict[char] = 1
    return frequency_dict

