def is_prime(num):
    """Check if a number is a prime number."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def find_max_prime_below(n):
    """Find the largest prime number less than n."""
    for candidate in range(n - 1, 1, -1):
        if is_prime(candidate):
            return candidate
    return None

def flatten_dict(d, parent_key='', sep='.'):
