Implement a data structure `MaxStack` that supports the following operations: `push(x)`, which pushes an element `x` onto the stack, `pop()`, which removes the element on top of the stack, `top()`, which gets the element on the top of the stack, `peekMax()`, which retrieves the maximum element in the stack, and `popMax()`, which removes the maximum element in the stack. If there is more than one maximum element, only remove the top-most one. Example usage of the `MaxStack` class is as follows:

- MaxStack maxStack = new MaxStack();
- maxStack.push(5);   
- maxStack.push(1);   
- maxStack.push(5);   
- maxStack.top();      // -> 5
- maxStack.popMax();   // -> 5
- maxStack.top();      // -> 1
- maxStack.peekMax();  // -> 5
- maxStack.pop();      // -> 1
- maxStack.top();      // -> 5

reference_solution:
class MaxStack:
    def __init__(self):
        self.stack = []
        self.max_stack = []

    def push(self, x):
        self.stack.append(x)
        if not self.max_stack or x >= self.max_stack[-1]:
            self.max_stack.append(x)

    def pop(self):
        top = self.stack.pop()
        if top == self.max_stack[-1]:
            self.max_stack.pop()
        return top

    def top(self):
        return self.stack[-1]

    def peekMax(self):
        return self.max_stack[-1]

    def popMax(self):
        max_val = self.peekMax()
        buffer = []
        while self.top() != max_val:
            buffer.append(self.pop())
        self.pop()  # pop the maximum element
        while buffer:
            self.push(buffer.pop())
        return max_val

