def has_pair_product_k(arr, k):
    """
    Checks if there exists at least one pair of integers in arr whose product is exactly k.
    """
    if k == 0:
        return False  # k=0 cannot be a product of two non-zero integers

    seen = set()

    for num in arr:
        if num != 0 and k % num == 0:  # check if num can pair with another number to make k
            if (k // num) in seen:
                return True
            seen.add(num)

    return False

