def flatten(head):
    if not head:
        return None

    stack = []
    current = head

    while current or stack:
        if current.child:
            if current.next:
                stack.append(current.next)
            current.next = current.child
            if current.next:
                current.next.prev = current
            current.child = None
        elif not current.next and stack:
            current.next = stack.pop()
            if current.next:
                current.next.prev = current

        current = current.next

    return head

