def number_of_boomerangs(points):
    def get_distance(p1, p2):
        return (p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2

    boomerangs = 0
    n = len(points)

    for i in range(n):
        distance_count = {}
        for j in range(n):
            if i != j:
                dist = get_distance(points[i], points[j])
                if dist in distance_count:
                    boomerangs += 2 * distance_count[dist]
                    distance_count[dist] += 1
                else:
                    distance_count[dist] = 1

    return boomerangs

class UndoableStack:
    def __init__(self):
        self.stack = []
        self.history = []

    def push(self, x):
        self.stack.append(x)
        self.history.append(('push', x))

    def pop(self):
        if not self.stack:
            return -1
        popped_element = self.stack.pop()
        self.history.append(('pop', popped_element))
        return popped_element

    def undo(self):
        if not self.history:
            return

        last_action, value = self.history.pop()
        if last_action == 'push':
            self.stack.pop()
        elif last_action == 'pop':
            self.stack.append(value)

