class SubscriptionManager:
    def __init__(self):
        self.subscriptions = {}  # key: user_id, value: list of [start, end) intervals

    def addSubscription(self, user_id, start, end):
        """
        Adds a subscription interval for a specific user.
        If the interval overlaps with any existing subscriptions of the same user,
        merge them to form a single continuous subscription.
        """
        if user_id not in self.subscriptions:
            self.subscriptions[user_id] = []

        # Add new interval and then merge all intervals
        self.subscriptions[user_id].append([start, end])
        self.subscriptions[user_id] = self._merge_intervals(self.subscriptions[user_id])

    def countUniqueUsers(self, t):
        """
        Returns the total number of unique users subscribed at the given time t.
        """
        count = 0
        for user_intervals in self.subscriptions.values():
            for interval in user_intervals:
                if interval[0] <= t < interval[1]:
                    count += 1
                    break
        return count

    def _merge_intervals(self, intervals):
        intervals.sort()
        merged = [intervals[0]]
        for current in intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                last[1] = max(last[1], current[1])
            else:
                merged.append(current)
        return merged

def longest_path_longest_path_with_exact_k_edges(n, edges, k):
    import sys
    # Initialize the dp array with -inf
    dp = [[-sys.maxsize] * (k + 1) for _ in range(n)]
    # The distance from a node to itself with 0 edges is 0
    for i in range(n):
        dp[i][0] = 0

    # Iterate for each edge count from 1 to k
    for e in range(1, k + 1):
        for u, v, weight in edges:
            if dp[u][e - 1] != -sys.maxsize:
                dp[v][e] = max(dp[v][e], dp[u][e - 1] + weight)

    # Find the maximum path length using exactly k edges
    longest_path_length = -1
    for i in range(n):
        longest_path_length = max(longest_path_length, dp[i][k])

    return longest_path_length if longest_path_length != -1 else -1

def min_new_edges(n, edges):
    from collections import defaultdict, deque

    def bfs(node, visited, adj_list):
        queue = deque([node])
        visited.add(node)
        while queue:
            current = queue.popleft()
            for neighbor in adj_list[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    adj_list = defaultdict(list)
    for a, b in edges:
        adj_list[a].append(b)
        adj_list[b].append(a)

    visited = set()
    components = 0

    for i in range(n):
        if i not in visited:
            components += 1
            bfs(i, visited, adj_list)

    if components == 1:
        return 0   # Already connected
    else:
        return components - 1   # Need (components - 1) edges to connect all components

def max_sum_subarray(nums, k):
    """
    Returns the maximum sum of a non-empty subarray of nums such that the sum does not exceed k.
    """
    n = len(nums)
    max_sum = float('-inf')

    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += nums[j]

            if current_sum <= k:
                max_sum = max(max_sum, current_sum)

    return max_sum if max_sum != float('-inf') else 0

