def longest_bitonic_subsequence(nums):
    n = len(nums)
    if n == 0:
        return 0

    inc_dp = [1] * n
    dec_dp = [1] * n

    # Compute the increasing subsequence lengths
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                inc_dp[i] = max(inc_dp[i], inc_dp[j] + 1)

    # Compute the decreasing subsequence lengths
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if nums[i] > nums[j]:
                dec_dp[i] = max(dec_dp[i], dec_dp[j] + 1)

    # Compute the longest bitonic subsequence length
    max_bitonic_length = 0
    for i in range(n):
        max_bitonic_length = max(max_bitonic_length, inc_dp[i] + dec_dp[i] - 1)

    return max_bitonic_length

def find_mode(numbers):
    """
    Determines the mode of a list of integers. Returns the smallest integer among
    the most frequent integers in case of a tie. Returns None if the list is empty.

    :param numbers: List of integers
    :return: The mode of the list or None if the list is empty
    """
    if not numbers:
        return None

    frequency = {}

    for number in numbers:
        if number in frequency:
            frequency[number] += 1
        else:
            frequency[number] = 1

    max_frequency = max(frequency.values())
    modes = [number for number, freq in frequency.items() if freq == max_frequency]

    return min(modes)

import json

def process_user_data(json_response):
    """
    Processes a JSON response containing user data and returns a dictionary mapping usernames to email addresses.

    Parameters:
    json_response (str): A JSON string representing a list of users.

    Returns:
    dict: A dictionary where keys are usernames and values are email addresses (or None if email is missing).
