def longest_increasing_subsequence(nums):
    """
    Finds and returns the longest increasing subsequence in the given list of integers.

    :param nums: List[int] - A list of integers.
    :return: List[int] - The longest increasing subsequence.
    """
    if not nums:
        return []

    dp = [[num] for num in nums]
    max_length = 1
    max_index = 0

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j] and len(dp[j]) + 1 > len(dp[i]):
                dp[i] = dp[j].copy()
                dp[i].append(nums[i])

        if len(dp[i]) > max_length:
            max_length = len(dp[i])
            max_index = i

    return dp[max_index]

def sum_even_numbers(nested_list):
    """
    Computes the sum of all even numbers in a nested list of integers.

    :param nested_list: A nested list of integers.
    :return: The sum of all even numbers in the nested list.
    """
    def flatten(lst):
        """
        Flattens a nested list into a single list of integers.

        :param lst: A nested list of integers.
        :yield: Each integer from the nested list.
        """
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    return sum(x for x in flatten(nested_list) if x % 2 == 0)

