def max_profit(prices):
    """
    Calculate the maximum profit from a single buy and sell of stock.

    :param prices: List[int] - A list of integers representing daily stock prices.
    :return: int - The maximum profit that can be achieved.
    """
    if not prices:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

def evaluate_expression(expression):
    """
    Evaluates a mathematical expression given as a string and returns the result.

    :param expression: A string representing a mathematical expression.
    :return: An integer representing the result of the evaluated expression.
    """
    def operate(a, b, operator):
        if operator == '+':
            return a + b
        elif operator == '-':
            return a - b
        elif operator == '*':
            return a * b
        elif operator == '/':
            return a // b

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        values.append(operate(left, right, operator))

    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    operators = []
    values = []
    i = 0

    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        elif expression[i] == '(':
            operators.append(expression[i])
        elif expression[i] == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()
        elif expression[i].isdigit():
            j = i
            while j < len(expression) and expression[j].isdigit():
                j += 1
            values.append(int(expression[i:j]))
            i = j - 1
        else:
            while (operators and operators[-1] != '(' and
                   precedence[operators[-1]] >= precedence[expression[i]]):
                apply_operator(operators, values)
            operators.append(expression[i])
        i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

