def minDistance(words, target):
    """
    Returns the minimum number of operations required to convert any string in `words` to the `target` string.
    """
    def edit_distance(word1, word2):
        """
        Helper function to compute the edit distance between two strings.
        """
        m = len(word1)
        n = len(word2)

        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(m + 1):
            for j in range(n + 1):
                if i == 0:
                    dp[i][j] = j
                elif j == 0:
                    dp[i][j] = i
                elif word1[i-1] == word2[j-1]:
                    dp[i][j] = dp[i-1][j-1]
                else:
                    dp[i][j] = 1 + min(dp[i-1][j],    # Insert
                                       dp[i][j-1],    # Remove
                                       dp[i-1][j-1])  # Replace
        return dp[m][n]

    minimal_distance = float('inf')
    for word in words:
        current_distance = edit_distance(word, target)
        if current_distance < minimal_distance:
            minimal_distance = current_distance

    return minimal_distance

def min_deletions_to_beautiful(s):
    """
    Returns the minimum number of deletions required to make the binary string `s` beautiful.
    """
    deletions = 0
    i = 0

    while i < len(s) - 2:
        if s[i:i+3] == '010':
            deletions += 1
            i += 3
        else:
            i += 1

    return deletions

