from collections import defaultdict

def count_paths_dag(edges, start, end):
    """
    Returns the number of distinct paths from start to end in a DAG.
    """
    graph = defaultdict(list)

    # Build the graph
    for u, v in edges:
        graph[u].append(v)

    # Memoization for storing number of paths from a node to end
    memo = {}

    def dfs(node):
        if node in memo:
            return memo[node]
        if node == end:
            return 1

        count = 0
        for neighbor in graph[node]:
            count += dfs(neighbor)

        memo[node] = count
        return count

    return dfs(start)

