def min_palindrome_partitions(s):
    """
    Returns the minimum number of palindrome partitions for the input string s.
    """
    n = len(s)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    is_palindrome = [[False] * n for _ in range(n)]

    for length in range(1, n + 1):
        for start in range(n - length + 1):
            end = start + length - 1
            if s[start] == s[end] and (length <= 2 or is_palindrome[start + 1][end - 1]):
                is_palindrome[start][end] = True

    for i in range(1, n + 1):
        for j in range(i):
            if is_palindrome[j][i - 1]:
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n] - 1  # Subtracting 1 as partition count is number of cuts

def is_valid_path(grid):
    """
    Determines if all filled cells ('1's) in the grid are connected horizontally or vertically.
    """
    if not grid:
        return True

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]

    def dfs(x, y):
        """ Depth-first search to mark all reachable '1's. """
        stack = [(x, y)]
        visited[x][y] = True
        while stack:
            i, j = stack.pop()
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1 and not visited[ni][nj]:
                    visited[ni][nj] = True
                    stack.append((ni, nj))

    # Find first '1' and start DFS from there
    first_filled_cell_found = False
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dfs(i, j)
                first_filled_cell_found = True
                break
        if first_filled_cell_found:
            break

    # Check if every '1' has been visited
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1 and not visited[i][j]:
                return False
    return True

