def can_convert_with_k_modifications(s1, s2, k):
    """
    Returns True if s1 can be converted to s2 using at most k modifications, False otherwise.
    """
    m = len(s1)
    n = len(s2)

    # Create a DP table to store results of subproblems
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill dp array in bottom-up manner
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i][j - 1],    # Insert
                                   dp[i - 1][j],    # Remove
                                   dp[i - 1][j - 1]) # Replace

    # dp[m][n] contains the number of operations required
    return dp[m][n] <= k

