def max_weight_progressive_subsequence(nums):
    """
    Finds the maximum weight of any progressive subsequence in the array nums.
    """
    if not nums:
        return 0

    n = len(nums)
    # dp[i] will store the maximum weight of a progressive subsequence that ends with nums[i]
    dp = nums[:]

    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + nums[i])

    return max(dp)

