def connect(root):
    if not root:
        return root

    # Initialize a queue for level order traversal
    queue = [root]

    while queue:
        size = len(queue)
        for i in range(size):
            node = queue.pop(0)

            # Connect node to the next node in the queue
            if i < size - 1:
                node.next = queue[0]
            else:
                node.next = None

            # Add children to the queue for the next level
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

    return root

