def min_workers(energy, m, L):
    """
    Find the minimum number of workers required to complete all tasks
    without any worker handling more than their limit L.
    """
    if not energy:
        return 0

    workers = 1
    current_energy = 0

    for e in energy:
        if e > L:
            return -1

        if current_energy + e <= L:
            current_energy += e
        else:
            workers += 1
            current_energy = e
            if workers > m:
                return -1

    return workers

