def find_keyword_in_files(file_paths, keyword):
    """
    Search for a keyword in each file within a list of file paths.

    Parameters:
    file_paths (list of str): List of file paths.
    keyword (str): The keyword to search for.

    Returns:
    list of tuples: A list of tuples (file_path, line_number) where the keyword is found.
    """
    results = []
    for file_path in file_paths:
        try:
            with open(file_path, 'r') as file:
                for line_number, line in enumerate(file, start=1):
                    if keyword in line:
                        results.append((file_path, line_number))
        except FileNotFoundError:
            print(f"Warning: The file {file_path} does not exist.")
        except Exception as e:
            print(f"An error occurred while reading {file_path}: {e}")

    return results

def sieve_of_eratosthenes(n):
    """
    Returns a list of all prime numbers up to a given integer n using the Sieve of Eratosthenes algorithm.

    :param n: The upper limit integer up to which prime numbers are to be found.
    :return: A list of prime numbers less than or equal to n.
    """
    if n < 2:
        return []

    prime = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if prime[p]:
            for i in range(p * p, n + 1, p):
                prime[i] = False
        p += 1

    return [p for p in range(2, n + 1) if prime[p]]

def flatten_list(nested_list):
    """
    Flattens a nested list of arbitrary depth into a flat list with all elements in the same order.

    :param nested_list: A nested list containing integers, strings, and other lists.
    :return: A flat list with all elements in the same order.
    """
    flat_list = []
    for item in nested_list:
        if isinstance(item, list):
            flat_list.extend(flatten_list(item))
        else:
            flat_list.append(item)
    return flat_list

def min_path_sum(triangle):
    """
    Finds the minimum path sum in a triangle of numbers.

    :param triangle: A 2D list of integers representing the triangle.
    :return: An integer representing the minimum path sum from the top to the bottom of the triangle.
    """
    if not triangle:
        return 0

    for row in range(len(triangle) - 2, -1, -1):
        for col in range(len(triangle[row])):
            triangle[row][col] += min(triangle[row + 1][col], triangle[row + 1][col + 1])

    return triangle[0][0]

