from collections import Counter
import math

def calculate_statistics(numbers):
    """
    Calculate statistical measures for a list of numbers.

    Parameters:
    numbers (list): A list of integers or floats.

    Returns:
    dict: A dictionary containing the mean, median, mode, variance, and standard deviation.
    """
    def mean(lst):
        """Calculate the mean of a list."""
        return sum(lst) / len(lst) if lst else None

    def median(lst):
        """Calculate the median of a list."""
        if not lst:
            return None
        sorted_lst = sorted(lst)
        n = len(sorted_lst)
        mid = n // 2
        if n % 2 == 0:
            return (sorted_lst[mid - 1] + sorted_lst[mid]) / 2
        else:
            return sorted_lst[mid]

    def mode(lst):
        """Calculate the mode(s) of a list."""
        if not lst:
            return None
        count = Counter(lst)
        max_count = max(count.values())
        modes = [k for k, v in count.items() if v == max_count]
        return modes if len(modes) > 1 else modes[0]

    def variance(lst):
        """Calculate the variance of a list."""
        if len(lst) < 2:
            return None
        avg = mean(lst)
        return sum((x - avg) ** 2 for x in lst) / len(lst)

    def standard_deviation(lst):
        """Calculate the standard deviation of a list."""
        var = variance(lst)
        return math.sqrt(var) if var is not None else None

    return {
        'mean': mean(numbers),
        'median': median(numbers),
        'mode': mode(numbers),
        'variance': variance(numbers),
        'standard_deviation': standard_deviation(numbers)
    }

