def cherryPickup(grid):
    """
    Given a grid where each cell represents the number of cherries,
    returns the maximum number of cherries both you and your friend can collect from the top row to the bottom row.
    """
    m, n = len(grid), len(grid[0])

    # Initialize a 3D array for dynamic programming, with dimensions [m][n][n]
    dp = [[[0] * n for _ in range(n)] for _ in range(m)]

    # Initialize the value at the starting positions
    dp[0][0][n-1] = grid[0][0] + grid[0][n-1] if 0 != n-1 else grid[0][0]

    # Iterate through each row
    for r in range(1, m):
        for c1 in range(n):
            for c2 in range(n):
                # Initialize the maximum cherries collected till now as 0
                max_cherries = 0

                # Check all possible movements for the previous step
                for pc1 in (c1-1, c1, c1+1):
                    for pc2 in (c2-1, c2, c2+1):
                        if 0 <= pc1 < n and 0 <= pc2 < n:
                            max_cherries = max(max_cherries, dp[r-1][pc1][pc2])

                dp[r][c1][c2] = max_cherries + grid[r][c1] + (grid[r][c2] if c1 != c2 else 0)

    # The result will be in the maximum value in the last row of dp array
    return max(dp[m-1][c1][c2] for c1 in range(n) for c2 in range(n))

def num_distinct_islands(grid):
    """
    Given a 2D grid of '0's and '1's, return the number of distinct islands.
    """
    def dfs(x, y, origin):
        stack = [(x, y)]
        shape = []
        while stack:
            r, c = stack.pop()
            if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == 1:
                grid[r][c] = 0
                shape.append((r - origin[0], c - origin[1]))
                neighbors = [(r+1, c), (r-1, c), (r, c+1), (r, c-1)]
                for nr, nc in neighbors:
                    stack.append((nr, nc))
        return tuple(shape)

    unique_islands = set()

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                island_shape = dfs(i, j, (i, j))
                if island_shape:
                    unique_islands.add(island_shape)

    return len(unique_islands)

