def evaluate_expression(expression):
    def operate(a, b, op):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return int(a / b)  # truncate toward zero

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operation(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        values.append(operate(left, right, operator))

    operators = []
    values = []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue

        if expression[i] == '(':
            operators.append(expression[i])
        elif expression[i].isdigit():
            val = 0
            while (i < len(expression) and expression[i].isdigit()):
                val = val * 10 + int(expression[i])
                i += 1
            values.append(val)
            i -= 1
        elif expression[i] == ')':
            while operators and operators[-1] != '(':
                apply_operation(operators, values)
            operators.pop()  # pop '('
        else:
            while (operators and precedence(operators[-1]) >= precedence(expression[i])):
                apply_operation(operators, values)
            operators.append(expression[i])
        i += 1

    while operators:
        apply_operation(operators, values)

    return values[0]

import heapq
from collections import defaultdict

class AutocompleteSystem:
    def __init__(self, sentences, times):
        self.trie = {}
        self.prefix = ""
        self.search_count = defaultdict(int)

        for i, sentence in enumerate(sentences):
            self.add_sentence(sentence, times[i])

    def add_sentence(self, sentence, times):
        self.search_count[sentence] += times
        node = self.trie

        for char in sentence:
            if char not in node:
                node[char] = {}
            node = node[char]
        node['#'] = sentence

    def input(self, c):
        if c == '#':
            self.add_sentence(self.prefix, 1)
            self.prefix = ""
            return []

        self.prefix += c
        node = self.trie

        for char in self.prefix:
            if char in node:
                node = node[char]
            else:
                return []

        # Get all sentences from the current trie node
        sentences = []
        self.dfs(node, sentences)

        # Get top 3 hot sentences
        top_sentences = heapq.nsmallest(3, sentences, key=lambda x: (-self.search_count[x], x))
        return top_sentences

    def dfs(self, node, sentences):
        for char in node:
            if char == '#':
                sentences.append(node[char])
            else:
                self.dfs(node[char], sentences)

