def min_moves_to_avoid_adjacent_duplicates(s, k):
    if len(s) == 0:
        return 0

    moves = 0
    i = 0

    while i < len(s) - 1:
        if s[i] == s[i + 1]:
            moves += 1
            i += 2  # Skip the next character because we need to change the current one
        else:
            i += 1

    return moves

