def remove_invalid_parentheses(s):
    """
    Removes the minimum number of parentheses to make the string valid.
    Returns all possible results.
    """
    level = {s}
    while True:
        valid = list(filter(is_valid, level))
        if valid:
            return valid
        # Generate all possible states
        level = {s[:i] + s[i+1:] for s in level for i in range(len(s))}

def is_valid(s):
    """
    Checks if the parentheses string is valid.
    """
    count = 0
    for char in s:
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
            if count < 0:
                return False
    return count == 0

