def summary_ranges(arr):
    """
    Given a list of unique integers sorted in ascending order, return the list of ranges that cover all the numbers in the array.
    """
    if not arr:
        return []

    ranges = []
    start = arr[0]
    end = arr[0]

    for num in arr[1:]:
        if num == end + 1:
            end = num
        else:
            if start == end:
                ranges.append(str(start))
            else:
                ranges.append(f"{start}->{end}")
            start = num
            end = num

    if start == end:
        ranges.append(str(start))
    else:
        ranges.append(f"{start}->{end}")

    return ranges

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def longestConsecutive(root):
    """
    Returns the length of the longest path with consecutive values in the binary tree.
    """
    def dfs(node, parent_val, length):
        if not node:
            return length
        if node.val == parent_val + 1:
            length += 1
        else:
            length = 1
        left_length = dfs(node.left, node.val, length)
        right_length = dfs(node.right, node.val, length)
        return max(length, left_length, right_length)

    return dfs(root, root.val - 1, 0) if root else 0

