def make_beautiful(arr, k):
    """
    Reorders elements of the array arr so that it becomes beautiful with respect to k.
    A beautiful array means for any pair i, j where 0 <= i < j < len(arr), arr[i] + arr[j] <= k.
    If it's not possible to make the array beautiful, returns an empty array.
    """
    arr.sort()
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[i] + arr[j] > k:
