    return arr

def top_survey_name(records):
    scores = {}
    for part in records.split(';'):
        part = part.strip()
        if not part:
            continue
        name, score = part.split('=')
        name = name.strip()
        score = int(score.strip())
        scores[name] = scores.get(name, 0) + score
    best_name = None
    best_score = None
    for name, score in scores.items():
        if best_name is None or score > best_score or (score == best_score and name < best_name):
