def longest_non_decreasing_run(daily_users):
    if not daily_users:
        return 0
    best = 1
    current = 1
    for i in range(1, len(daily_users)):
        if daily_users[i] >= daily_users[i - 1]:
            current += 1
        else:
            current = 1
        best = max(best, current)
    return best if best >= 2 else 1

def optimize_fibonacci(n, memo=None):
    """
    Calculate the nth Fibonacci number using memoization.

    Parameters:
    n (int): The position in the Fibonacci sequence (0-indexed).
    memo (dict, optional): A dictionary to store previously computed Fibonacci numbers.

    Returns:
    int: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        memo[n] = optimize_fibonacci(n-1, memo) + optimize_fibonacci(n-2, memo)
        return memo[n]

