def calculate_fibonacci(n):
    """
    Calculate the nth Fibonacci number using recursion.

    Parameters:
    n (int): The position in the Fibonacci sequence. Must be a non-negative integer.

    Returns:
    int: The nth Fibonacci number.

    Raises:
    ValueError: If n is negative.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return calculate_fibonacci(n - 1) + calculate_fibonacci(n - 2)

def find_duplicate_elements(input_list):
    """
    Identifies and returns a list of integers that appear more than once in the input list.

    :param input_list: List of integers
    :return: List of integers that are duplicates in the input list
    """
    element_counts = {}
    duplicates = []

    for element in input_list:
        if element in element_counts:
            element_counts[element] += 1
        else:
            element_counts[element] = 1

    for element, count in element_counts.items():
        if count > 1:
            duplicates.append(element)

