def is_balanced(s: str) -> bool:
    """
    Determines if a string of brackets is balanced.

    Args:
    s (str): A string containing only the characters '(', ')', '{', '}', '[' and ']'.

    Returns:
    bool: True if the string is balanced, False otherwise.
    """
    matching_bracket = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket:
            if not stack or stack[-1] != matching_bracket[char]:
                return False
            stack.pop()

    return not stack

def remove_consecutive_duplicates(s: str) -> str:
    """
    Removes all consecutive duplicate characters from the input string.

    :param s: A string consisting of lowercase English letters.
    :return: A string with all consecutive duplicate characters removed.
    """
    if not s:
        return s

    result = [s[0]]

    for i in range(1, len(s)):
        if s[i] != s[i - 1]:
            result.append(s[i])

    return ''.join(result)

