class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Inserts a new node with the given key into the tree."""
        new_node = TreeNode(key)
        if self.root is None:
            self.root = new_node
        else:
            self._insert_recursively(self.root, new_node)

    def _insert_recursively(self, node, new_node):
        """Recursively inserts a new node into the correct position in the tree."""
        if new_node.val < node.val:
            if node.left is None:
                node.left = new_node
            else:
                self._insert_recursively(node.left, new_node)
        else:
            if node.right is None:
                node.right = new_node
            else:
                self._insert_recursively(node.right, new_node)

    def delete(self, key):
        """Deletes the node with the given key from the tree."""
        self.root = self._delete_recursively(self.root, key)

    def _delete_recursively(self, node, key):
        """Recursively deletes the node with the given key from the tree."""
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete_recursively(node.left, key)
        elif key > node.val:
            node.right = self._delete_recursively(node.right, key)
        else:
            if node.left is None:
                temp = node.right
                node = None
                return temp
            elif node.right is None:
                temp = node.left
                node = None
                return temp

            temp = self._get_minimum(node.right)
            node.val = temp.val
            node.right = self._delete_recursively(node.right, temp.val)

        return node

    def _get_minimum(self, node):
        """Returns the node with the minimum value in the given subtree."""
        current = node
        while current.left is not None:
            current = current.left
        return current

    def inorder_traversal(self):
        """Returns a list of keys in the tree in in-order traversal order."""
        return self._inorder_traversal_recursively(self.root)

    def _inorder_traversal_recursively(self, node):
        """Recursively performs in-order traversal of the tree."""
        result = []
        if node is not None:
            result = self._inorder_traversal_recursively(node.left)
            result.append(node.val)
            result = result + self._inorder_traversal_recursively(node.right)
        return result

