def calculate_average_grades(grades):
    """
    Calculate the average grades for each student from a list of tuples.

    :param grades: List of tuples, where each tuple contains a student's name and their grades.
    :return: Dictionary with student names as keys and their average grades as values, rounded to two decimal places.
    """
    student_grades = {}

    for entry in grades:
        name = entry[0]
        grades_list = entry[1:]

        if name not in student_grades:
            student_grades[name] = {'total': sum(grades_list), 'count': len(grades_list)}
        else:
            student_grades[name]['total'] += sum(grades_list)
            student_grades[name]['count'] += len(grades_list)

    average_grades = {name: round(data['total'] / data['count'], 2) for name, data in student_grades.items()}

    return average_grades

