def can_reach_end_with_k_jumps(arr, k):
    """
    Determines if it is possible to reach the end of the array in exactly k jumps.

    :param arr: List[int] - array of integer jumps
    :param k: int - number of jumps required to reach the end
    :return: bool - True if possible, False otherwise
    """
    def dfs(index, remaining_jumps):
        if remaining_jumps < 0:
            return False
        if index >= len(arr) - 1:
            return remaining_jumps == 0

        jump_length = arr[index]
        for next_index in range(index + 1, min(index + jump_length + 1, len(arr))):
            if dfs(next_index, remaining_jumps - 1):
                return True

        return False

    return dfs(0, k)

