class EventScheduler:
    def __init__(self):
        self.events = []

    def addEvent(self, startTime, endTime):
        self.events.append((startTime, endTime))
        self.events.sort()

    def getNextEvent(self, currentTime):
        for startTime, endTime in self.events:
            if startTime > currentTime:
                return startTime
        return -1

    def getEventsInRange(self, startTime, endTime):
        result = []
        for eventStartTime, eventEndTime in self.events:
            if eventStartTime >= startTime and eventStartTime <= endTime:
                result.append(eventStartTime)
        return result

