def shortestBridge(grid):
    from collections import deque

    def get_islands():
        visited = [[False] * len(grid[0]) for _ in range(len(grid))]
        islands = []

        def dfs(r, c, island):
            if r < 0 or r >= len(grid) or c < 0 or c >= len(grid[0]) or visited[r][c] or grid[r][c] == 0:
                return
            visited[r][c] = True
            island.append((r, c))
            dfs(r + 1, c, island)
            dfs(r - 1, c, island)
            dfs(r, c + 1, island)
            dfs(r, c - 1, island)

        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == 1 and not visited[r][c]:
                    island = []
                    dfs(r, c, island)
                    islands.append(island)

        return islands

    islands = get_islands()
    queue = deque([(r, c, 0) for r, c in islands[0]])
    visited = set((r, c) for r, c in islands[0])

    while queue:
        r, c, d = queue.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and (nr, nc) not in visited:
                if grid[nr][nc] == 1:
                    return d
                queue.append((nr, nc, d + 1))
                visited.add((nr, nc))

    return -1  # In case there is no solution, though problem guarantees there will be one.

