def has_subarray_with_sum(arr, m, x):
    if len(arr) < m:
        return False

    current_sum = sum(arr[:m])

    if current_sum == x:
        return True

    for i in range(m, len(arr)):
        current_sum += arr[i] - arr[i - m]
        if current_sum == x:
            return True

    return False

