def max_tasks(tasks, deadline, rest):
    tasks.sort()
    time_spent = 0
    completed_tasks = 0

    for task in tasks:
        if time_spent + task <= deadline:
            time_spent += task
            completed_tasks += 1
            if time_spent + rest <= deadline:
                time_spent += rest
            else:
                break
        else:
            break

    return completed_tasks

def tree_height(pairs):
    """
    Calculate the height of an n-ary tree defined via a list of parent-child relationships.

    :param pairs: List of lists, where each sublist contains two elements [parent, child].
    :return: Height of the tree.
    """
    from collections import defaultdict, deque

    if not pairs:
        return 0

    # Build the adjacency list representation of the tree
    adjacency_list = defaultdict(list)
    for parent, child in pairs:
        adjacency_list[parent].append(child)

    # Function to perform DFS and find the height
    def dfs(node):
        if not adjacency_list[node]:
            return 1  # Leaf node
        else:
            return 1 + max(dfs(child) for child in adjacency_list[node])

    # The tree is rooted at node 0
    return dfs(0)

class FileSystem:
    def __init__(self):
        self.paths = {}

    def createPath(self, path, value):
        parts = path.split('/')
        current = self.paths

        for part in parts[1:-1]:
            if part not in current:
                return False
            current = current[part]

        if parts[-1] in current:
            return False

        current[parts[-1]] = {}
        current[parts[-1]]['value'] = value
        return True

    def getPath(self, path):
        parts = path.split('/')
        current = self.paths

        for part in parts[1:]:
            if part not in current:
                return ""
            current = current[part]

        return current.get('value', "")

class Excel:
    def __init__(self, H, W):
        """
        Initializes an Excel object with H rows and columns from 'A' to the given W column (inclusive), using 1-based indexing.
        """
        self.H = H
        self.W = ord(W) - ord('A') + 1
        self.grid = [[0] * self.W for _ in range(H)]
        self.formulas = {}

    def set(self, row, column, value):
        """
        Sets the value at the cell `(row, column)` to `value`.
        """
        self.grid[row-1][ord(column)-ord('A')] = value
        if (row, column) in self.formulas:
            del self.formulas[(row, column)]

    def get(self, row, column):
        """
        Returns the value at the cell `(row, column)`.
        """
        if (row, column) in self.formulas:
            return self.calculate_formula(row, column)
        return self.grid[row-1][ord(column)-ord('A')]

    def sum(self, row, column, numbers):
        """
        Returns the sum of the values of cells allocated within the range represented by `numbers` and updates the cell `(row, column)` to this sum.
        """
        self.formulas[(row, column)] = numbers
        return self.calculate_formula(row, column)

    def calculate_formula(self, row, column):
        total_sum = 0
        for part in self.formulas[(row, column)]:
            total_sum += self.evaluate_range(part)
        self.grid[row-1][ord(column)-ord('A')] = total_sum
        return total_sum

    def evaluate_range(self, part):
        if ':' in part:
            start, end = part.split(':')
            start_row, start_col = int(start[1:]), start[0]
            end_row, end_col = int(end[1:]), end[0]

            total_sum = 0
            for r in range(start_row, end_row+1):
                for c in range(ord(start_col), ord(end_col)+1):
                    total_sum += self.get(r, chr(c))
            return total_sum
        else:
            return self.get(int(part[1:]), part[0])

