def tickets_waiting_time(nums):
    """
    Returns the minimum number of minutes needed for everyone in the queue to get their ticket.
    """
    total_time = 0
    while nums:
        for i in range(len(nums)):
            if nums[i] > 0:
                nums[i] -= 1
                total_time += 1
                if nums[i] == 0:
                    break
        nums = [ticket for ticket in nums if ticket > 0]
    return total_time

