def maximum_consecutive_ones(s):
    """
    Returns the maximum number of consecutive '1's achievable by removing exactly one '0'.
    """
    max_ones = 0
    current_ones = 0
    left_ones = 0

    for i in range(len(s)):
        if s[i] == '1':
            current_ones += 1
        else:
            left_ones = current_ones
            current_ones = 0

        max_ones = max(max_ones, left_ones + current_ones)

    return max_ones if '0' in s else len(s)

