def min_remove_to_make_valid(s):
    """
    Removes the minimum number of parentheses to make the given string valid.
    """
    indices_to_remove = set()
    stack = []

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                indices_to_remove.add(i)

    indices_to_remove = indices_to_remove.union(set(stack))
    result = [char for i, char in enumerate(s) if i not in indices_to_remove]

    return "".join(result)

