def longest_consecutive_path(grid):
    if not grid or not grid[0]:
        return 0

    def dfs(x, y, prev_value):
        # If the coordinates are out of bounds or the current cell value is not consecutive, return 0
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or (grid[x][y] != prev_value + 1):
            return 0
        if (x, y) in memo:
            return memo[(x, y)]

        current_val = grid[x][y]

        # Explore all four directions: up, down, left, right
        up = dfs(x-1, y, current_val)
        down = dfs(x+1, y, current_val)
        left = dfs(x, y-1, current_val)
        right = dfs(x, y+1, current_val)

        # The longest path starting from this cell
        memo[(x, y)] = 1 + max(up, down, left, right)
        return memo[(x, y)]

    memo = {}
    longest_path = 0

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            longest_path = max(longest_path, dfs(i, j, grid[i][j]-1))

    return longest_path

def largest_island(grid):
    def dfs(x, y, index):
        stack = [(x, y)]
        grid[x][y] = index
        size = 1
        while stack:
            cx, cy = stack.pop()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 1:
                    grid[nx][ny] = index
                    stack.append((nx, ny))
                    size += 1
        return size

    n = len(grid)
    max_island = 0
    index = 2
    area = {}

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                area[index] = dfs(i, j, index)
                max_island = max(max_island, area[index])
                index += 1

    if max_island == n * n:
        return max_island

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                surrounding_islands = set()
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < n and 0 <= nj < n and grid[ni][nj] > 1:
                        surrounding_islands.add(grid[ni][nj])
                new_island_size = 1 + sum(area[idx] for idx in surrounding_islands)
                max_island = max(max_island, new_island_size)

    return max_island

