def flatten_json(data, parent_key='', sep='.'):
    """
    Flattens a nested dictionary into a single-level dictionary with concatenated keys.

    Parameters:
    data (dict): The dictionary to be flattened.
    parent_key (str): The base key string to which the current key will be appended. Defaults to an empty string.
    sep (str): The separator to use between keys. Defaults to a dot ('.').

    Returns:
    dict: A new dictionary with flattened keys.
    """
    flattened = {}
    for key, value in data.items():
        new_key = f"{parent_key}{sep}{key}" if parent_key else key
        if isinstance(value, dict):
            flattened.update(flatten_json(value, new_key, sep=sep))
        else:
            flattened[new_key] = value
    return flattened

