def islandPerimeter(grid):
    """
    Returns the perimeter of the island in the 2D binary matrix grid.
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    perimeter = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                # Each cell contributes initially 4 to perimeter
                perimeter += 4

                # Check the previous row
                if r > 0 and grid[r - 1][c] == 1:
                    perimeter -= 2
                # Check the previous column
                if c > 0 and grid[r][c - 1] == 1:
                    perimeter -= 2

    return perimeter

def lexicographically_smallest_string(s):
    """
    Returns the lexicographically smallest string that can be achieved
    by repeatedly reversing any two-character substring in the input string s.
    """
    # Convert string to list for in-place manipulation
    s = list(s)

    # We can use a simple greedy approach by continually sorting the string
    n = len(s)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if s[j] > s[j + 1]:
                # Swap adjacent characters if they are in wrong order
                s[j], s[j + 1] = s[j + 1], s[j]

    # Join the list back into a string
    return ''.join(s)

