def can_place_word(board, word, row, col, direction):
    if direction == "horizontal":
        if col + len(word) > len(board[0]):
            return False
        for i in range(len(word)):
            if board[row][col + i] not in (' ', word[i]):
                return False
        for i in range(len(word)):
            board[row][col + i] = word[i]
    else:  # vertical
        if row + len(word) > len(board):
            return False
        for i in range(len(word)):
            if board[row + i][col] not in (' ', word[i]):
                return False
        for i in range(len(word)):
            board[row + i][col] = word[i]
    return True

def place_words_on_board(board, words):
    for word in words:
        placed = False
        for row in range(len(board)):
            for col in range(len(board[0])):
                if (can_place_word(board, word, row, col, "horizontal") or
                   can_place_word(board, word, row, col, "vertical")):
                    placed = True
                    break
            if placed:
                break
        if not placed:
            return False
    return True

