def findFarmland(grid):
    """
    Finds and returns a list of coordinates representing each farmland in the grid.
    Each coordinate contains the top-left and bottom-right corners of the farmland.
    """
    m, n = len(grid), len(grid[0])
    farmlands = []

    def dfs(i, j):
        if 0 <= i < m and 0 <= j < n and grid[i][j] == 1:
            grid[i][j] = -1
            top_left[0] = min(top_left[0], i)
            top_left[1] = min(top_left[1], j)
            bottom_right[0] = max(bottom_right[0], i)
            bottom_right[1] = max(bottom_right[1], j)
            for x, y in [(i+1, j), (i, j+1), (i-1, j), (i, j-1)]:
                dfs(x, y)

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                top_left = [i, j]
                bottom_right = [i, j]
                dfs(i, j)
                farmlands.append([top_left[0], top_left[1], bottom_right[0], bottom_right[1]])

    return sorted(farmlands)

