from itertools import combinations

def count_subsets(nums, target):
    """
    Returns the number of subsets in nums that add up to the target.
    """
    count = 0
    n = len(nums)

    # Generate all possible subsets using combination logic
    for i in range(1, n+1):
        for combo in combinations(nums, i):
            if sum(combo) == target:
                count += 1
    return count

def cart_item_counts(events, queries):
    from collections import defaultdict

    user_items = defaultdict(set)
    ans = []
    i = 0
    n = len(events)
    for q_time, q_user in queries:
        while i < n and events[i][0] < q_time:
            _, user_id, action, item_id = events[i]
            if action == 'add':
                user_items[user_id].add(item_id)
            elif action == 'remove':
                user_items[user_id].discard(item_id)
            i += 1
        ans.append(len(user_items[q_user]))
    return ans

def max_subarray_sum_with_min_length(scores, min_len):
    n = len(scores)
    if n < min_len or min_len <= 0:
        return 0
    prefix = [0]
    for x in scores:
        prefix.append(prefix[-1] + x)
    min_prefix = 0
    best = None
    for i in range(min_len, n + 1):
        min_prefix = min(min_prefix, prefix[i - min_len])
        current = prefix[i] - min_prefix
        if best is None or current > best:
            best = current
    return best if best is not None else 0

def sum_tuples(input_list):
    """
    Processes a list of tuples and returns a dictionary where the keys are the first elements
    of the tuples and the values are the sums of the second elements of the tuples that share
    the same first element.

    :param input_list: List of tuples, where each tuple contains two integers.
    :return: Dictionary with integer keys and integer values representing the sums.
    """
    result_dict = {}
    for key, value in input_list:
        if key in result_dict:
            result_dict[key] += value
        else:
            result_dict[key] = value
    return result_dict

# Example usage:
print(sum_tuples([(1, 2), (2, 3), (1, 4), (3, 1)]))  # Output: {1: 6, 2: 3, 3: 1}

def calculate_factorial(n):
    """Calculate the factorial of a non-negative integer using recursion.

    :param n: The non-negative integer to calculate the factorial for.
    :return: The factorial of n.
    """
    if n == 0:
        return 1
    else:
        return n * calculate_factorial(n - 1)

# Example usage:
# print(calculate_factorial(5))  # Output: 120

def find_duplicates(input_list):
    """
    Identifies all integers that appear more than once in the input list.

    Parameters:
    input_list (list of int): A list of integers.

    Returns:
    list of int: A list of integers that appear more than once in the input list, without duplicates.
    """
    element_count = {}
    duplicates = []

    for number in input_list:
        if number in element_count:
            element_count[number] += 1
        else:
            element_count[number] = 1

    for number, count in element_count.items():
        if count > 1:
            duplicates.append(number)

    return duplicates

