class ShoppingCart:
    def __init__(self):
        """Initialize an empty dictionary to store the cart items."""
        self.items = {}

    def add_item(self, name, price, quantity=1):
        """
        Add or update the item in the cart.

        :param name: str, the name of the item
        :param price: float, the price of the item
        :param quantity: int, the quantity of the item to add (default is 1)
        """
        if name in self.items:
            self.items[name]['quantity'] += quantity
        else:
            self.items[name] = {'price': price, 'quantity': quantity}

    def remove_item(self, name, quantity=1):
        """
        Remove the specified quantity of the item from the cart.

        :param name: str, the name of the item
        :param quantity: int, the quantity of the item to remove (default is 1)
        """
        if name in self.items:
            if self.items[name]['quantity'] > quantity:
                self.items[name]['quantity'] -= quantity
            else:
                del self.items[name]

    def update_quantity(self, name, quantity):
        """
        Update the quantity of the item in the cart.

        :param name: str, the name of the item
        :param quantity: int, the new quantity of the item
        """
        if name in self.items:
            self.items[name]['quantity'] = quantity

    def calculate_total(self):
        """
        Calculate the total price of all items in the cart.

        :return: float, the total price
        """
        total = 0
        for item in self.items.values():
            total += item['price'] * item['quantity']
        return total

