def process_log(log):
    from collections import defaultdict

    def recursive_dict():
        return defaultdict(recursive_dict)

    def update_dict(d, keys, value=None):
        for key in keys[:-1]:
            d = d[key]
        if value:
            d[keys[-1]] = value
        else:
            d[keys[-1]]

    file_system = recursive_dict()
    current_path = ['/']

    commands = log.split('\n')

    for command in commands:
        parts = command.split()
        if parts[0] == 'cd':
            if parts[1] == '..':
                if len(current_path) > 1:
                    current_path.pop()
            else:
                current_path.append(parts[1])
        elif parts[0] == 'mkdir':
            update_dict(file_system, current_path + [parts[1]])
        elif parts[0] == 'touch':
            update_dict(file_system, current_path + [parts[1]], parts[1])
        elif parts[0] == 'ls':
            continue  # No state change required for `ls`

    return file_system['/']

import heapq
from collections import defaultdict, deque

def findCheapestPrice(n, flights, src, dst, k):
    graph = defaultdict(list)
    for u, v, w in flights:
        graph[u].append((v, w))

    # Use a priority queue to progressively explore the cheapest option
    pq = [(0, src, 0)]
    visited = defaultdict(lambda: float('inf'))

    while pq:
        cost, u, stops = heapq.heappop(pq)

        # If we reach the destination
        if u == dst:
            return cost

        # If we have more stops available
        if stops <= k:
            for v, w in graph[u]:
                new_cost = cost + w
                if new_cost < visited[(v, stops + 1)]:
                    visited[(v, stops + 1)] = new_cost
                    heapq.heappush(pq, (new_cost, v, stops + 1))

    return -1

