def longest_balanced_subarray(colors):
    """
    Returns the length of the longest contiguous subarray where each color appears an even number of times.
    """
    def is_balanced(subarray):
        color_count = {}
        for color in subarray:
            color_count[color] = color_count.get(color, 0) + 1
        return all(count % 2 == 0 for count in color_count.values())

    max_length = 0
    n = len(colors)

    for start in range(n):
        for end in range(start + 1, n + 1):
            subarray = colors[start:end]
            if is_balanced(subarray):
                max_length = max(max_length, end - start)

    return max_length

