def max_elevation_difference(grid):
    """
    Returns the maximum difference in elevation between any two connected cells in the grid.
    """
    def dfs(x, y):
        stack = [(x, y)]
        visited[x][y] = True
        min_val, max_val = grid[x][y], grid[x][y]
        while stack:
            cx, cy = stack.pop()
            for nx, ny in get_neighbors(cx, cy):
                if not visited[nx][ny]:
                    visited[nx][ny] = True
                    stack.append((nx, ny))
                    min_val = min(min_val, grid[nx][ny])
                    max_val = max(max_val, grid[nx][ny])
        return min_val, max_val

    def get_neighbors(x, y):
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
                yield nx, ny

    visited = [[False] * len(grid[0]) for _ in range(len(grid))]
    max_diff = 0

    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if not visited[i][j]:
                min_val, max_val = dfs(i, j)
                max_diff = max(max_diff, max_val - min_val)

    return max_diff

