def find_words(board, words):
    def dfs(board, word, i, j, k, visited):
        if k == len(word):
            return True
        if i < 0 or i >= len(board) or j < 0 or j >= len(board[0]):
            return False
        if visited[i][j] or board[i][j] != word[k]:
            return False
        visited[i][j] = True
        if dfs(board, word, i + 1, j, k + 1, visited) or dfs(board, word, i - 1, j, k + 1, visited) or dfs(board, word, i, j + 1, k + 1, visited) or dfs(board, word, i, j - 1, k + 1, visited):
            return True
        visited[i][j] = False
        return False

    found_words = []
    for word in words:
        found = False
        for i in range(len(board)):
            for j in range(len(board[0])):
                visited = [[False] * len(board[0]) for _ in range(len(board))]
                if dfs(board, word, i, j, 0, visited):
                    found_words.append(word)
                    found = True
                    break
            if found:
                break

    return found_words

