def can_make_bouquets(flowers, k, m):
    """
    Determine if it is possible to make m bouquets each consisting of k consecutive flowers.
    """
    def can_bloom(day):
        count = 0  # to keep track of consecutive blooming flowers
        bouquets = 0  # to keep track of bouquets made
        for bloom_day in flowers:
            if bloom_day <= day:
                count += 1
                if count == k:
                    bouquets += 1
                    count = 0
            else:
                count = 0
            if bouquets >= m:
                return True
        return False

    low, high = min(flowers), max(flowers)
    while low < high:
        mid = (low + high) // 2
        if can_bloom(mid):
            high = mid
        else:
            low = mid + 1

    return can_bloom(low)

