import math

def calculate_area(shape, **kwargs):
    """
    Calculates the area of the specified shape.

    Parameters:
    - shape (str): Type of the shape ('circle', 'rectangle', or 'triangle').
    - kwargs: Keyword arguments specific to the shape to calculate the area.

    Returns:
    - float: Area of the specified shape.

    Raises:
    - ValueError: If the shape type is unsupported or required dimensions are missing.
    """
    if shape == 'circle':
        if 'radius' in kwargs:
            return math.pi * kwargs['radius'] ** 2
        else:
            raise ValueError("Radius is required for a circle.")

    elif shape == 'rectangle':
        if 'width' in kwargs and 'height' in kwargs:
            return kwargs['width'] * kwargs['height']
        else:
            raise ValueError("Both width and height are required for a rectangle.")

    elif shape == 'triangle':
        if 'base' in kwargs and 'height' in kwargs:
            return 0.5 * kwargs['base'] * kwargs['height']
        else:
            raise ValueError("Both base and height are required for a triangle.")

    else:
        raise ValueError("Unsupported shape type. Supported types are: 'circle', 'rectangle', 'triangle'.")

def unique_servers(servers: str) -> list[str]:
    if servers == '':
        return []
    result = []
    seen = set()
    for server in servers.split(','):
        if server not in seen:
            seen.add(server)
            result.append(server)
    return result

import math

def euclidean_distance(point1, point2):
    """Calculate the Euclidean distance between two points in 2D space."""
    return math.sqrt((point1[0] - point2[0]) ** 2 + (point1[1] - point2[1]) ** 2)

def find_closest_pair(points):
    """Find and return the closest pair of points from a list of 2D points."""
    if len(points) < 2:
        raise ValueError("At least two points are required")

    closest_pair = (points[0], points[1])
    min_distance = euclidean_distance(points[0], points[1])

    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            distance = euclidean_distance(points[i], points[j])
            if distance < min_distance:
                min_distance = distance
                closest_pair = (points[i], points[j])

    return closest_pair

# Example usage:
points = [(1, 2), (3, 4), (5, 1)]
print(find_closest_pair(points))  # Output should be ((1, 2), (5, 1))

def generate_primes(n):
    """
    Returns a list of all prime numbers up to and including n using the Sieve of Eratosthenes algorithm.
    """
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n ** 0.5) + 1):
        if is_prime[start]:
            for multiple in range(start * start, n + 1, start):
                is_prime[multiple] = False

    return [num for num, prime in enumerate(is_prime) if prime]

import string

def word_count(sentence: str) -> dict:
    """
    Returns a dictionary with words as keys and their counts as values.
    The function is case-insensitive and ignores punctuation.

    :param sentence: A string containing words separated by spaces.
    :return: A dictionary with words as keys and their counts as values.
    """
    cleaned_sentence = sentence.translate(str.maketrans('', '', string.punctuation)).lower()
    words = cleaned_sentence.split()
    counts = {}

    for word in words:
        if word in counts:
            counts[word] += 1
        else:
            counts[word] = 1

    return counts

# Example usage
print(word_count("Hello, hello world!"))  # Output: {'hello': 2, 'world': 1}

def classify_sentences(sentences):
    """
    Classifies each sentence in the list into 'positive' or 'negative' based on the presence of specific positive and negative words.

    Parameters:
    sentences (list of str): A list of sentences to be classified.

    Returns:
    dict: A dictionary with sentences as keys and their sentiment as values.
    """
    positive_words = {"happy", "joy", "good", "wonderful", "great", "fantastic", "excellent", "positive", "love", "fortunate"}
    negative_words = {"sad", "pain", "hate", "terrible", "bad", "awful", "horrible", "negative", "worst", "unfortunate"}

    def classify(sentence):
        words = set(word.lower() for word in sentence.split())
        pos_count = sum(1 for word in words if word in positive_words)
        neg_count = sum(1 for word in words if word in negative_words)
        return "positive" if pos_count > neg_count else "negative"

    return {sentence: classify(sentence) for sentence in sentences}

def flatten_dict(d, parent_key='', sep='_'):
    """
    Flattens a nested dictionary into a single-level dictionary with compound keys.

    Parameters:
    d (dict): The nested dictionary to flatten.
    parent_key (str): The base key string for recursion (used internally).
    sep (str): The separator to use between keys.

    Returns:
    dict: A flattened dictionary with compound keys.
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

# Example usage:
nested_dict = {'a': {'b': 1, 'c': {'d': 2}}}
flattened_dict = flatten_dict(nested_dict)
print(flattened_dict)  # Output: {'a_b': 1, 'a_c_d': 2}

