def largest_island(grid):
    def dfs(x, y, index):
        area = 1
        grid[x][y] = index
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == 1:
                area += dfs(nx, ny, index)
        return area

    def neighbor_indices(x, y):
        indices = set()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] > 1:
                indices.add(grid[nx][ny])
        return indices

    if not grid:
        return 0

    m, n = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    index = 2
    area_map = {0: 0}

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                area_map[index] = dfs(i, j, index)
                index += 1

    max_area = max(area_map.values(), default=0)

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 0:
                neighbor_indices_set = neighbor_indices(i, j)
                new_area = 1 + sum(area_map[idx] for idx in neighbor_indices_set)
                max_area = max(max_area, new_area)

    return max_area

