def evaluate_expression(expression):
    """
    Evaluates an arithmetic expression containing addition and subtraction, with possible parentheses.

    Args:
    expression (str): A string representing the arithmetic expression.

    Returns:
    int: The result of the evaluated arithmetic expression.
    """
    def calculate(operators, operands):
        """Helper function to perform arithmetic operations."""
        if operators[-1] == '+':
            operands[-2] += operands[-1]
        elif operators[-1] == '-':
            operands[-2] -= operands[-1]
        operators.pop()
        operands.pop()

    operators, operands = [], []
    i, n = 0, len(expression)

    while i < n:
        if expression[i] == ' ':
            i += 1
            continue
        if expression[i] in '+-':
            while operators and operators[-1] in "+-":
                calculate(operators, operands)
            operators.append(expression[i])
        elif expression[i] == '(':
            operators.append(expression[i])
        elif expression[i] == ')':
            while operators[-1] != '(':
                calculate(operators, operands)
            operators.pop()
        else:
            num = 0
            while i < n and expression[i].isdigit():
                num = num * 10 + int(expression[i])
                i += 1
            operands.append(num)
            continue
        i += 1

    while operators:
        calculate(operators, operands)

    return operands[0]

def can_form_palindrome(s):
    """
    Determines if the characters of the string `s` can be rearranged to form a palindrome.

    :param s: A string consisting of lowercase English letters.
    :return: True if the characters can be rearranged to form a palindrome, False otherwise.
    """
    # Dictionary to store the frequency of each character
    char_count = {}

    # Count the frequency of each character in the string
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Count how many characters have an odd frequency
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    # A string can form a palindrome if at most one character has an odd frequency
    return odd_count <= 1

# Test the function with the provided example
print(can_form_palindrome("ivicc"))  # Output: True

def count_keys(json_obj, result=None):
    """
    Recursively counts the occurrences of each unique key in a JSON object.

    :param json_obj: The JSON object (Python dictionary or list) to analyze.
    :param result: A dictionary to store the count of each key (used internally for recursion).
    :return: A dictionary with keys as unique keys from the JSON object and values as their counts.
    """
    if result is None:
        result = {}

    if isinstance(json_obj, dict):
        for key, value in json_obj.items():
            result[key] = result.get(key, 0) + 1
            count_keys(value, result)
    elif isinstance(json_obj, list):
        for item in json_obj:
            count_keys(item, result)

    return result

