def rearrange_shrubs(arr, d):
    """
    Rearranges the shrubs such that the absolute difference in height between any two 
    adjacent shrubs does not exceed d. If it is not possible, returns an empty list.
    """
    arr_sorted = sorted(arr)
    for i in range(1, len(arr_sorted)):
        if abs(arr_sorted[i] - arr_sorted[i - 1]) > d:
            return []
    return arr_sorted

