MOD = 10**9 + 7

def count_subsets(nums, target):
    from collections import defaultdict

    dp = defaultdict(int)
    dp[0] = 1  # There is one way to get sum 0: pick no elements

    for num in nums:
        for cur_sum in list(dp.keys())[::-1]:
            new_sum = cur_sum + num
            dp[new_sum] = (dp[new_sum] + dp[cur_sum]) % MOD

    return dp[target]

