def min_deletions_to_subsequence(s, t):
    """
    Returns the minimum number of deletions required to make `s` a subsequence of `t`.
    """
    n = len(s)
    m = len(t)

    # Find the length of the Longest Common Subsequence (LCS)
    def lcs(s, t, n, m):
        # Create a 2D array to store lengths of longest common subsequence.
        dp = [[0] * (m + 1) for _ in range(n + 1)]

        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if s[i - 1] == t[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        return dp[n][m]

    lcs_length = lcs(s, t, n, m)

    # The minimum deletions needed is the length of `s` minus the length of LCS
    return n - lcs_length

def longestSubstring(s, k):
    """
    Returns the length of the longest substring where each character appears at least k times.
    """
    def longest_substring_util(s, k, start, end):
        if end - start < k:
            return 0

        char_count = {}
        for i in range(start, end):
            char_count[s[i]] = char_count.get(s[i], 0) + 1

        for mid in range(start, end):
            if char_count[s[mid]] < k:
                next_mid = mid + 1
                while next_mid < end and char_count[s[next_mid]] < k:
                    next_mid += 1
                return max(longest_substring_util(s, k, start, mid), longest_substring_util(s, k, next_mid, end))

        return end - start

    return longest_substring_util(s, k, 0, len(s))

