def evaluate_expression(s):
    """
    Evaluate a mathematical expression containing only non-negative integers and the operators +, -, *, and /.
    The integer division should truncate toward zero.
    """
    def apply_operator(operands, operator):
        b = operands.pop()
        a = operands.pop()
        if operator == '+':
            operands.append(a + b)
        elif operator == '-':
            operands.append(a - b)
        elif operator == '*':
            operands.append(a * b)
        elif operator == '/':
            operands.append(int(a / b))  # int() truncates toward zero

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    operands = []
    operators = []
    i = 0

    while i < len(s):
        if s[i].isdigit():
            num = 0
            while i < len(s) and s[i].isdigit():
                num = num * 10 + int(s[i])
                i += 1
            operands.append(num)
            i -= 1
        else:
            while (operators and precedence(operators[-1]) >= precedence(s[i])):
                apply_operator(operands, operators.pop())
            operators.append(s[i])
        i += 1

    while operators:
        apply_operator(operands, operators.pop())

    return operands[-1]

