        self.right = right

def level_order_traversal(root):
    """
    Returns a list of tree's values in level order traversal.
    """
    if not root:
        return []

    result = []
    queue = collections.deque([root])

    while queue:
        node = queue.popleft()
        result.append(node.value)

        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)

    return result

