def shortest_palindrome_length(s):
    """
    Returns the length of the shortest palindrome that can be done by adding characters 
    in front of the string s.
    """
    if s == s[::-1]:
        return len(s)

    # Find the longest palindromic prefix
    for i in range(len(s), -1, -1):
        if s[:i] == s[:i][::-1]:
            break

    # Number of characters that need to be added in the front to make it a palindrome
    return 2 * len(s) - i

