import heapq

def trapRainWater(heightMap):
    if not heightMap or not heightMap[0]:
        return 0

    m, n = len(heightMap), len(heightMap[0])
    visited = [[False]*n for _ in range(m)]
    min_heap = []

    # Initialize the heap with the boundary cells
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m-1 or j == 0 or j == n-1:
                heapq.heappush(min_heap, (heightMap[i][j], i, j))
                visited[i][j] = True

    direction_vectors = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    result = 0
    while min_heap:
        height, x, y = heapq.heappop(min_heap)
        for dx, dy in direction_vectors:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                result += max(0, height - heightMap[nx][ny])
                new_height = max(height, heightMap[nx][ny])
                heapq.heappush(min_heap, (new_height, nx, ny))

    return result

