def smallest_substring(s):
    """
    Returns the length of the smallest substring that contains at least one 'a', one 'b', and one 'c'.
    If no such substring exists, returns 0.
    """
    if not s or 'a' not in s or 'b' not in s or 'c' not in s:
        return 0

    min_length = float('inf')
    left = 0
    count = {'a': 0, 'b': 0, 'c': 0}

    for right in range(len(s)):
        if s[right] in count:
            count[s[right]] += 1

        while all(count[char] > 0 for char in 'abc'):
            min_length = min(min_length, right - left + 1)
            if s[left] in count:
                count[s[left]] -= 1
            left += 1

    return min_length if min_length != float('inf') else 0

import random

class RandomizedSet:
    def __init__(self):
        self.data = []
        self.val_to_index = {}

    def insert(self, val: int) -> bool:
        if val in self.val_to_index:
            return False
        self.val_to_index[val] = len(self.data)
        self.data.append(val)
        return True

    def delete(self, val: int) -> bool:
        if val not in self.val_to_index:
            return False
        index = self.val_to_index[val]
        last_val = self.data[-1]
        self.data[index] = last_val
        self.val_to_index[last_val] = index
        self.data.pop()
        del self.val_to_index[val]
        return True

    def getRandomElement(self) -> int:
        return random.choice(self.data)

