def combination_sum(nums, target):
    """
    Finds all unique combinations in nums where the sum is equal to the target.
    Each number in nums may be used only once in the combination.
    The solution set must not contain duplicate combinations.
    """
    nums.sort()
    result = []

    def backtrack(start, path, remaining):
        if remaining == 0:
            result.append(path)
            return
        for i in range(start, len(nums)):
            if i > start and nums[i] == nums[i - 1]:
                continue
            if nums[i] > remaining:
                break
            backtrack(i + 1, path + [nums[i]], remaining - nums[i])

    backtrack(0, [], target)
    return result

