def minimumTimeRequired(jobs, n):
    """
    Returns the minimum time required to complete all jobs with n workers.
    Greedy approach to balance the workloads among workers.
    """
    # Early exit for trivial cases
    if n >= len(jobs):
        return max(jobs)

    def can_finish(jobs, n, max_time):
        workloads = [0] * n

        def backtrack(idx):
            if idx == len(jobs):
                return True
            for i in range(n):
                if workloads[i] + jobs[idx] <= max_time:
                    workloads[i] += jobs[idx]
                    if backtrack(idx + 1):
                        return True
                    workloads[i] -= jobs[idx]
                if workloads[i] == 0:  # Skip this worker as it is redundant
                    break
            return False

        return backtrack(0)

    left, right = max(jobs), sum(jobs)
    while left < right:
        mid = (left + right) // 2
        if can_finish(jobs, n, mid):
            right = mid
        else:
            left = mid + 1

    return left

class TravelPlanner:
    def __init__(self, n):
        self.n = n
        self.graph = {i: set() for i in range(n)}

    def addRoad(self, city1, city2):
        self.graph[city1].add(city2)
        self.graph[city2].add(city1)

    def removeRoad(self, city1, city2):
        self.graph[city1].discard(city2)
        self.graph[city2].discard(city1)

    def isConnected(self, city1, city2):
        visited = set()
        return self._dfs(city1, city2, visited)

    def _dfs(self, current, target, visited):
        if current == target:
            return True
        visited.add(current)
        for neighbor in self.graph[current]:
            if neighbor not in visited and self._dfs(neighbor, target, visited):
                return True
        return False

