def can_make_palindrome(s, queries):
    def canFormPalindrome(s, left, right, k):
        changes_needed = 0
        l, r = left, right
        while l < r:
            if s[l] != s[r]:
                changes_needed += 1
            l += 1
            r -= 1
        return changes_needed <= k

    results = []
    for left, right, k in queries:
        results.append(canFormPalindrome(s, left, right, k))
    return results

