def longest_subarray_with_k_distinct(nums, k):
    if k <= 0:
        return 0

    freq = {}
    left = 0
    best = 0

    for right, value in enumerate(nums):
        freq[value] = freq.get(value, 0) + 1

        while len(freq) > k:
            left_value = nums[left]
            freq[left_value] -= 1
            if freq[left_value] == 0:
                del freq[left_value]
            left += 1

        if len(freq) == k:
            best = max(best, right - left + 1)

    return best

