def find_first_triplet_order(logs):
    order_customers = {}
    order_first_reach = {}

    for idx, (customer_id, order_id) in enumerate(logs):
        if order_id not in order_customers:
            order_customers[order_id] = set()
        customers = order_customers[order_id]
        before = len(customers)
        customers.add(customer_id)
        after = len(customers)
        if before < 3 and after >= 3 and order_id not in order_first_reach:
            order_first_reach[order_id] = idx

    if not order_first_reach:
        return -1

    best_order = None
    best_idx = None
    for order_id, idx in order_first_reach.items():
        if best_order is None or idx < best_idx or (idx == best_idx and order_id < best_order):
            best_order = order_id
            best_idx = idx
    return best_order

def min_completion_time(arrivals: list[int], k: int) -> int:
    n = len(arrivals)
    if k <= 0 or k > n:
        return -1
    return min(arrivals[k - 1:]) if k == 1 else min(arrivals[i + k - 1] for i in range(n - k + 1))

def min_length_subarray_sum(nums, target):
    left = 0
    current_sum = 0
    best = float('inf')

    for right, value in enumerate(nums):
        current_sum += value
        while current_sum >= target:
            if current_sum == target:
                best = min(best, right - left + 1)
            current_sum -= nums[left]
            left += 1

    return 0 if best == float('inf') else best

def find_triplets(nums, target):
    """
    Finds all unique triplets in the list `nums` that sum up to `target`.

    :param nums: List of integers.
    :param target: Target sum for the triplets.
    :return: List of lists, where each inner list contains three integers that sum up to `target`.
    """
    nums.sort()
    result = []
    n = len(nums)

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, n - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == target:
                result.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return result

def two_sum(numbers, target):
    """
    Finds the indices of the two numbers in the list that add up to the target.

    :param numbers: List of integers.
    :param target: Target integer.
    :return: List containing the indices of the two numbers.
    """
    num_indices = {}
    for index, number in enumerate(numbers):
        complement = target - number
        if complement in num_indices:
            return [num_indices[complement], index]
        num_indices[number] = index

def find_common_substring(s1, s2):
    """
    Finds the longest common substring between two strings.

    :param s1: First input string.
    :param s2: Second input string.
    :return: The longest common substring.
    """
    dp = [[0] * (len(s2) + 1) for _ in range(len(s1) + 1)]
    longest_length = 0
    end_index_s1 = 0

    for i in range(1, len(s1) + 1):
        for j in range(1, len(s2) + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > longest_length:
                    longest_length = dp[i][j]
                    end_index_s1 = i
            else:
                dp[i][j] = 0

    return s1[end_index_s1 - longest_length:end_index_s1]

def flatten_dict(d, parent_key='', sep='.'):
    """
    Flattens a nested dictionary and lists into a single-level dictionary.

    :param d: The dictionary to flatten.
    :param parent_key: The base key string to append to.
    :param sep: The separator between keys.
    :return: A flattened dictionary.
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        elif isinstance(v, list):
            for i, item in enumerate(v):
                items.extend(flatten_dict({f"{k}.{i}": item}, parent_key=new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

