def remove_duplicate_letters(s):
    """
    Remove duplicate letters from s to ensure every letter appears once and only once,
    and the result is the smallest in lexicographical order among all possible results.
    """
    stack = []
    seen = set()
    last_occurrence = {char: idx for idx, char in enumerate(s)}

    for idx, char in enumerate(s):
        if char not in seen:
            while stack and char < stack[-1] and idx < last_occurrence[stack[-1]]:
                seen.discard(stack.pop())
            seen.add(char)
            stack.append(char)

    return ''.join(stack)

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def incrementLinkedList(head):
    """
    Increment the number represented by the linked list by 1.
    The digits are stored in reverse order.

    :param head: Head node of the linked list
    :return: Head node of the updated linked list
    """
    if not head:
        return ListNode(1)

    carry = 1
    current = head
    prev = None

    while current and carry:
        current.val += carry
        if current.val == 10:
            current.val = 0
            carry = 1
        else:
            carry = 0
        prev = current
        current = current.next

    if carry:
        prev.next = ListNode(1)

    return head

from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def maxLevelSum(root):
    """
    Finds the level of the tree that has the maximum sum of node values.
    """
    if not root:
        return -1

    queue = deque([(root, 0)])
    level_sum = {}

    while queue:
        node, level = queue.popleft()

        if level not in level_sum:
            level_sum[level] = 0
        level_sum[level] += node.val

        if node.left:
            queue.append((node.left, level + 1))
        if node.right:
            queue.append((node.right, level + 1))

    max_level = max(level_sum, key=lambda k: (level_sum[k], -k))
    return max_level

