def num_similar_groups(words):
    """
    Calculates the number of similar groups in the provided list of words.

    :param words: List of strings
    :return: Number of similar groups
    """
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    n = len(words)
    parent = list(range(n))

    for i in range(n):
        for j in range(i + 1, n):
            if sorted(words[i]) == sorted(words[j]):
                union(i, j)

    return sum(parent[i] == i for i in range(n))

