        self.val = val
        self.parent = None

def build_tree(parents):
    nodes = [TreeNode(i + 1) for i in range(len(parents))]
    root = None
    for i, parent_index in enumerate(parents):
        if parent_index == -1:
            root = nodes[i]
        else:
            nodes[i].parent = nodes[parent_index - 1]
    return root, nodes

def find_path_to_root(node):
    path = []
    while node:
        path.append(node.val)
        node = node.parent
    return path

def lca(parents, p, q):
    _, nodes = build_tree(parents)
    node_p = nodes[p - 1]
    node_q = nodes[q - 1]

    path_p = find_path_to_root(node_p)
    path_q = find_path_to_root(node_q)

    path_p.reverse()
    path_q.reverse()

    i = 0
    while i < len(path_p) and i < len(path_q) and path_p[i] == path_q[i]:
        i += 1
    return path_p[i - 1]

