def longest_good_substring(s):
    """
    Returns the longest "good" substring of s.
    A substring is considered "good" if it contains both
    the lowercase and uppercase versions of each letter in the substring.
    """
    def is_good(sub):
        return all(c.lower() in sub and c.upper() in sub for c in sub)

    max_len = 0
    good_substring = ""

    n = len(s)
    for i in range(n):
        for j in range(i+1, n+1):
            sub = s[i:j]
            if is_good(sub) and (j - i) > max_len:
                max_len = j - i
                good_substring = sub

    return good_substring

