def longest_common_subsequence(s, t):
    """
    Returns the length of the longest common subsequence that is a substring in both s and t.
    """
    m, n = len(s), len(t)
    # Create a 2D array to store lengths of longest common suffixes of substrings.
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build dp array and keep track of the maximum length.
    result = 0
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                result = max(result, dp[i][j])
            else:
                dp[i][j] = 0

    return result

