def best_affordable_price(prices, budgets):
    def upper_bound(arr, x):
        left, right = 0, len(arr)
        while left < right:
            mid = (left + right) // 2
            if arr[mid] <= x:
                left = mid + 1
            else:
                right = mid
        return left

    result = []
    for b in budgets:
        idx = upper_bound(prices, b) - 1
        result.append(prices[idx] if idx >= 0 else 0)
    return result

def arrival_balance(eta, queries):
    def upper_bound(arr, x):
        left, right = 0, len(arr)
        while left < right:
            mid = (left + right) // 2
            if arr[mid] <= x:
                left = mid + 1
            else:
                right = mid
        return left

    n = len(eta)
    result = []
    for t in queries:
        leq = upper_bound(eta, t)
        gt = n - leq
        result.append(leq - gt)
    return result

def count_dicts_with_key(data, target_key):
    """
    Counts the number of dictionaries in a nested list that contain the target_key.

    :param data: List of dictionaries, possibly nested.
    :param target_key: The key to search for in the dictionaries.
    :return: Integer count of dictionaries containing the target_key.
    """
    def search_dict(d):
        count = 0
        if isinstance(d, dict):
            if target_key in d:
                count += 1
            for value in d.values():
                count += search_dict(value)
        elif isinstance(d, list):
            for item in d:
                count += search_dict(item)
        return count

    return search_dict(data)

def generate_palindromes(words):
    """
    Generate a list of unique palindromes that can be formed by concatenating
    any two different words from the input list.

    :param words: List of distinct words
    :return: List of unique palindromes
    """
    palindromes = set()
    words_set = set(words)

    for word in words:
        for i in range(len(word) + 1):
            prefix = word[:i]
            suffix = word[i:]

            if prefix[::-1] in words_set and suffix == suffix[::-1] and prefix != word:
                palindromes.add(word + prefix[::-1])

            if suffix[::-1] in words_set and prefix == prefix[::-1] and suffix != word:
                palindromes.add(suffix[::-1] + word)

    return list(palindromes)

