def visible_buildings(heights: List[int]) -> Tuple[int, int]:
    """
    Calculate the number of buildings visible from the left and the right.

    :param heights: List of integers representing the heights of buildings.
    :return: A tuple containing the number of visible buildings from the left and the right.
    """
    n = len(heights)
    if n == 0:
        return (0, 0)

    left_max = heights[0]
    visible_from_left = 1
    for i in range(1, n):
        if heights[i] > left_max:
            visible_from_left += 1
            left_max = heights[i]

    right_max = heights[-1]
    visible_from_right = 1
    for i in range(n-2, -1, -1):
        if heights[i] > right_max:
            visible_from_right += 1
            right_max = heights[i]

    return (visible_from_left, visible_from_right)

