class TaskManager:
    def __init__(self):
        """Initialize the TaskManager with an empty list of tasks."""
        self.tasks = []

    def time_to_minutes(self, time_str):
        """Convert time in HH:MM format to minutes."""
        hours, minutes = map(int, time_str.split(':'))
        return hours * 60 + minutes

    def check_overlap(self, new_task):
        """Check if the new task overlaps with any existing task."""
        new_start = self.time_to_minutes(new_task["start_time"])
        new_end = self.time_to_minutes(new_task["end_time"])

        for task in self.tasks:
            start = self.time_to_minutes(task["start_time"])
            end = self.time_to_minutes(task["end_time"])

            if not (new_end <= start or new_start >= end):
                return True  # Overlap found
        return False

    def add_task(self, task):
        """Add a task if it does not overlap with any existing tasks."""
        if self.check_overlap(task):
            print(f"Task '{task['task_name']}' overlaps with existing tasks and cannot be added.")
        else:
            self.tasks.append(task)
            print(f"Task '{task['task_name']}' added successfully.")

    def total_time_spent(self):
        """Calculate the total time spent on all tasks."""
        total_minutes = sum(self.time_to_minutes(task["end_time"]) - self.time_to_minutes(task["start_time"])
                            for task in self.tasks)
        hours = total_minutes // 60
        minutes = total_minutes % 60
        return f"{hours:02}:{minutes:02}"

