def laser_beam_area(heights):
    """
    Returns the total sum of the areas of all rectangular buildings intersected
    by a horizontal laser beam shot at the height of the maximum building height.
    """
    if not heights:
        return 0

    max_height = max(heights)
    total_area = 0

    for height in heights:
        if height == max_height:
            total_area += max_height

    return total_area

