def find_compound_words(words):
    """
    Returns all compound words in the array of words.
    A compound word is defined as a word that consists of at least two other words found in the array concatenated together.
    """
    word_set = set(words)
    compound_words = []

    def is_compound(word):
        n = len(word)
        dp = [False] * (n + 1)
        dp[0] = True

        for i in range(1, n + 1):
            for j in range(i):
                if dp[j] and word[j:i] in word_set and word[j:i] != word:
                    dp[i] = True
                    break
        return dp[-1]

    for word in words:
        if is_compound(word):
            compound_words.append(word)

    return compound_words

