def check_subarray_sum(arr, k):
    """
    Returns True if there is a continuous subarray of size at least k that sums up to a multiple of k, otherwise False.
    """
    if len(arr) < k:
        return False

    cum_sum = 0
    mod_dict = {0: -1}

    for i, num in enumerate(arr):
        cum_sum += num
        mod = cum_sum % k

        if mod in mod_dict:
            if i - mod_dict[mod] >= k:
                return True
        else:
            mod_dict[mod] = i

    return False

from collections import Counter

def find_anagrams(s, patterns):
    """
    Returns a list of all distinct patterns that are anagrams of any substring of s.
    """
    def is_anagram(sub, pat):
        return Counter(sub) == Counter(pat)

    s_len = len(s)
    results = set()

    for pattern in patterns:
        pat_len = len(pattern)
        for i in range(s_len - pat_len + 1):
            if is_anagram(s[i:i + pat_len], pattern):
                results.add(pattern)
                break # No need to check further substrings in `s` for this pattern

    return list(results)

