def count_unique_pairs(arr, k):
    """
    Returns the count of unique pairs (arr[i], arr[j]) such that i != j and arr[i] + arr[j] = k.
    """
    unique_pairs = set()
    seen = set()

    for num in arr:
        complement = k - num
        if complement in seen:
            unique_pairs.add(tuple(sorted((num, complement))))
        seen.add(num)

    return len(unique_pairs)

