def find_peaks(matrix):
    """
    Returns a list of coordinates (i, j) of all peaks in the matrix.
    """
    rows, cols = len(matrix), len(matrix[0])
    peaks = []

    for i in range(rows):
        for j in range(cols):
            is_peak = True
            if i > 0 and matrix[i][j] < matrix[i-1][j]:
                is_peak = False
            if i < rows-1 and matrix[i][j] < matrix[i+1][j]:
                is_peak = False
            if j > 0 and matrix[i][j] < matrix[i][j-1]:
                is_peak = False
            if j < cols-1 and matrix[i][j] < matrix[i][j+1]:
                is_peak = False
            if is_peak:
                peaks.append((i, j))

    return peaks

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def minCameraCover(root: TreeNode) -> int:
    def dfs(node):
        if not node:
            return 0, 0, float('inf')

        la, lb, lc = dfs(node.left)
        ra, rb, rc = dfs(node.right)

        a = lb + rb

        b = min(lc + min(rb, rc), rc + min(lb, lc))

        c = 1 + min(la, lb, lc) + min(ra, rb, rc)

        return a, b, c

    return min(dfs(root)[1:])

