def max_non_overlapping_substrings(s):
    """
    Returns the maximum number of non-overlapping substrings such that each substring 
    has an equal number of '0's and '1's.
    """
    count_0 = count_1 = 0
    max_substrings = 0
    for char in s:
        if char == '0':
            count_0 += 1
        elif char == '1':
            count_1 += 1

        if count_0 == count_1:
            max_substrings += 1
            count_0 = count_1 = 0

    return max_substrings

