def splitArray(nums, m):
    def can_split(nums, m, mid):
        count = 1
        total = 0
        for num in nums:
            total += num
            if total > mid:
                total = num
                count += 1
                if count > m:
                    return False
        return True

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if can_split(nums, m, mid):
            right = mid
        else:
            left = mid + 1
    return left

def exist(board, word):
    """
    Returns whether the word exists in the given 2D grid.
    """
    if not board or not board[0] or not word:
        return False

    rows, cols = len(board), len(board[0])

    def dfs(r, c, index):
        if index == len(word):
            return True
        if r < 0 or r >= rows or c < 0 or c >= cols or board[r][c] != word[index]:
            return False

        temp, board[r][c] = board[r][c], '#'
        found = (dfs(r+1, c, index+1) or dfs(r-1, c, index+1) or 
                 dfs(r, c+1, index+1) or dfs(r, c-1, index+1))
        board[r][c] = temp
        return found

    for i in range(rows):
        for j in range(cols):
            if board[i][j] == word[0] and dfs(i, j, 0):
                return True
    return False

