def evaluate_expression(expression: str) -> int:
    """
    Evaluates a mathematical expression given as a string and returns its integer result.
    """
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(int(left / right))  # Use int() for truncating towards zero

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    operators = []
    values = []
    i = 0

    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue

        if expression[i] == '(':
            operators.append(expression[i])

        elif expression[i] == ')':
            while operators and operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()

        elif expression[i].isdigit():
            val = 0
            while i < len(expression) and expression[i].isdigit():
                val = (val * 10) + int(expression[i])
                i += 1
            values.append(val)
            i -= 1

        elif expression[i] in '+-*/':
            while (operators and precedence(operators[-1]) >= precedence(expression[i])):
                apply_operator(operators, values)
            operators.append(expression[i])

        i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

