def evaluate_expression(expression):
    """
    Evaluates a mathematical expression composed of non-negative integers and operators (+, -, *, /).
    It follows the standard operator precedence without any parentheses.
    Integer division truncates toward zero.
    """
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(int(left / right))  # truncate toward zero

    operators, values = [], []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        if expression[i] in '0123456789':
            j = i
            while j < len(expression) and expression[j] in '0123456789':
                j += 1
            values.append(int(expression[i:j]))
            i = j
        else:
            while (operators and operators[-1] in "*/" and expression[i] in "+-") or \
                  (operators and operators[-1] in "*/" and expression[i] in "*/"):
                apply_operator(operators, values)
            operators.append(expression[i])
            i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

from collections import deque

def longest_subarray_within_limit(prices, limit):
    max_d = deque()
    min_d = deque()
    left = 0
    best = 0
    for right, x in enumerate(prices):
        while max_d and max_d[-1] < x:
            max_d.pop()
        max_d.append(x)
        while min_d and min_d[-1] > x:
            min_d.pop()
        min_d.append(x)
        while max_d[0] - min_d[0] > limit:
            if prices[left] == max_d[0]:
                max_d.popleft()
            if prices[left] == min_d[0]:
                min_d.popleft()
            left += 1
        best = max(best, right - left + 1)
    return best

def longest_subarray_at_most_k_distinct(counts, k):
    if k <= 0:
        return 0
    left = 0
    best = 0
    freq = {}
    distinct = 0
    for right, val in enumerate(counts):
        if freq.get(val, 0) == 0:
            distinct += 1
        freq[val] = freq.get(val, 0) + 1
        while distinct > k:
            lv = counts[left]
            freq[lv] -= 1
            if freq[lv] == 0:
                distinct -= 1
            left += 1
        best = max(best, right - left + 1)
    return best

def aggregate_inventory(raw):
    totals = {}
    for item in raw.split(';'):
        item = item.strip()
        if '|' not in item:
            continue
        name, qty_str = item.split('|', 1)
        name = name.strip()
        qty_str = qty_str.strip()
        if not name:
            continue
        try:
            qty = int(qty_str)
        except ValueError:
            continue
        if qty < 0:
            continue
        totals[name] = totals.get(name, 0) + qty
    return dict(sorted(totals.items()))

def max_budget_cap(budgets, target):
    if not budgets:
        return 0
    budgets = sorted(budgets)
    total = sum(budgets)
    if total <= target:
        return budgets[-1]

    low, high = 0, budgets[-1]
    answer = 0

    while low <= high:
        mid = (low + high) // 2
        capped_sum = 0
        for b in budgets:
            capped_sum += min(b, mid)
        if capped_sum <= target:
            answer = mid
            low = mid + 1
        else:
            high = mid - 1
    return answer

def sort_dicts_by_key(dicts, key):
    """
    Sorts a list of dictionaries based on the values associated with a given key.
    Dictionaries without the key are treated as having a value of None and are placed at the end.

    :param dicts: List of dictionaries to sort.
    :param key: The key to sort the dictionaries by.
    :return: A new list of dictionaries sorted by the specified key.
    """
    def get_sort_value(d):
        return d.get(key)

    return sorted(dicts, key=get_sort_value)

import csv

def filter_employees_by_department(filename, department_name):
    """
    Reads a CSV file and filters employees by the specified department.

    Args:
        filename (str): The path to the CSV file.
        department_name (str): The department to filter employees by.

    Returns:
        list: A list of dictionaries, each representing an employee in the specified department.
    """
    filtered_employees = []

    try:
        with open(filename, mode='r', newline='', encoding='utf-8') as file:
            reader = csv.DictReader(file)

            required_columns = {'employee_id', 'name', 'department', 'salary'}
            if not required_columns.issubset(reader.fieldnames):
                raise ValueError("CSV file is not in the expected format.")

            for row in reader:
                if row['department'] == department_name:
                    filtered_employees.append(row)

    except FileNotFoundError:
        print(f"Error: The file '{filename}' was not found.")
    except csv.Error as e:
        print(f"Error reading CSV file: {e}")
    except ValueError as ve:
        print(f"ValueError: {ve}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    return filtered_employees

def find_first_local_maximum(nums):
    """
    Finds the index of the first local maximum element in the list.

    Parameters:
    nums (list of int): The list of integers to search.

    Returns:
    int: The index of the first local maximum element, or -1 if no such element exists.
    """
    n = len(nums)
    if n == 0:
        return -1
    if n == 1 or nums[0] > nums[1]:
        return 0
    for i in range(1, n-1):
        if nums[i-1] < nums[i] > nums[i+1]:
            return i
    if nums[n-2] < nums[n-1]:
        return n-1
    return -1

def flatten_json(y):
    """
    Flattens a nested JSON object into a single-level dictionary with concatenated keys.

    :param y: The nested JSON object to be flattened.
    :return: A flat dictionary with concatenated keys.
    """
    out = {}

    def flatten(x, name=''):
        if isinstance(x, dict):
            for a in x:
                flatten(x[a], name + a + '.')
        elif isinstance(x, list):
            for i, a in enumerate(x):
                flatten(a, name + str(i) + '.')
        else:
            out[name[:-1]] = x

    flatten(y)
    return out

