def binary_search(arr, x):
    """
    Perform a binary search on a sorted list to find the index of a target value.

    Parameters:
    arr (list of int): The sorted list to search.
    x (int): The target value to find.

    Returns:
    int: The index of the target value in the list if found, otherwise -1.
    """
    def recursive_search(low, high):
        if low > high:
            return -1

        mid = (low + high) // 2

        if arr[mid] == x:
            return mid
        elif arr[mid] < x:
            return recursive_search(mid + 1, high)
        else:
            return recursive_search(low, mid - 1)

    return recursive_search(0, len(arr) - 1)

