from collections import Counter, deque
import heapq

def rearrange_string(s, k):
    if k == 0:
        return s

    count = Counter(s)
    max_heap = [(-value, key) for key, value in count.items()]
    heapq.heapify(max_heap)

    queue = deque()

    result = []

    while max_heap:
        freq, char = heapq.heappop(max_heap)
        result.append(char)

        queue.append((char, freq + 1))

        if len(queue) >= k:
            front_char, front_freq = queue.popleft()
            if front_freq < 0:
                heapq.heappush(max_heap, (front_freq, front_char))

    if len(result) == len(s):
        return ''.join(result)
    else:
        return ""

class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

class BinaryTreeDiameter:
    def __init__(self, root):
        self.root = root
        self.diameter = 0

    def getDiameter(self):
        self.calculateDiameter(self.root)
        return self.diameter

    def calculateDiameter(self, node):
        if not node:
            return 0

        left_height = self.calculateDiameter(node.left)
        right_height = self.calculateDiameter(node.right)

        # The diameter at the current node will be the sum of the heights of its left and right subtrees
        self.diameter = max(self.diameter, left_height + right_height)

        # The height of the current node will be the max height of its left or right subtree plus 1 (for the current node)
        return max(left_height, right_height) + 1

