def longest_alphabetical_subsequence(s):
    """
    Returns the length of the longest subsequence in s such that every letter in the subsequence
    appears in alphabetical order.
    """
    if not s:
        return 0

    dp = [1] * len(s)

    for i in range(1, len(s)):
        for j in range(i):
            if s[i] >= s[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

