def find_unique_pairs(nums, k):
    """
    Returns the number of unique pairs (i, j) where i < j and nums[j] - nums[i] == k.
    """
    if not nums or k < 0:
        return 0

    left, right = 0, 1
    unique_pairs = set()
    nums_len = len(nums)

    while right < nums_len:
        diff = nums[right] - nums[left]
        if diff == k:
            unique_pairs.add((nums[left], nums[right]))
            left += 1
            right += 1
        elif diff < k:
            right += 1
        else:
            left += 1
            if left == right:
                right += 1

    return len(unique_pairs)

