def calculate(expression):
    """
    Evaluate the given mathematical expression and return the result as an integer.
    """
    if not expression:
        return 0

    stack = []
    num = 0
    sign = "+"  # The initial sign is positive
    n = len(expression)

    for i in range(n):
        char = expression[i]
        if char.isdigit():
            num = num * 10 + int(char)
        if char in "+-*/" or i == n - 1:
            if sign == "+":
                stack.append(num)
            elif sign == "-":
                stack.append(-num)
            elif sign == "*":
                stack.append(stack.pop() * num)
            elif sign == "/":
                stack.append(int(stack.pop() / num))  # Python 2 division ensures truncation towards zero
            sign = char
            num = 0

    return sum(stack)

def maxSideLength(grid, threshold):
    """
    Returns the maximum side length of a square sub-matrix such that the sum
    of all the elements within this square is less than or equal to the given threshold.
    """
    m, n = len(grid), len(grid[0])

    # Compute prefix sums
    prefix = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m):
        for j in range(n):
            prefix[i+1][j+1] = grid[i][j] + prefix[i][j+1] + prefix[i+1][j] - prefix[i][j]

    def square_sum(x1, y1, x2, y2):
        return prefix[x2][y2] - prefix[x1][y2] - prefix[x2][y1] + prefix[x1][y1]

    # Binary search on the side length of the square sub-matrix
    left, right, max_side = 1, min(m, n), 0

    while left <= right:
        mid = (left + right) // 2
        found = False
        for i in range(m - mid + 1):
            for j in range(n - mid + 1):
                if square_sum(i, j, i + mid, j + mid) <= threshold:
                    found = True
                    break
            if found:
                break

        if found:
            max_side = mid
            left = mid + 1
        else:
            right = mid - 1

    return max_side

def generate_phone_numbers(num):
    """
    Returns all possible combinations of `num` digits such that no consecutive digits are the same.
    Sorted in lexicographical order.
    """
    if num <= 0:
        return []

    def dfs(path):
        if len(path) == num:
            result.append("".join(path))
            return
        for digit in map(str, range(10)):
            if not path or path[-1] != digit:
                dfs(path + [digit])

    result = []
    for start_digit in map(str, range(10)):
        dfs([start_digit])

    result.sort()
    return result

