def distinct_contiguous_subarrays(arr):
    def is_valid_subarray(subarray):
        max_element = max(subarray)
        min_element = min(subarray)
        return max_element >= 2 * min_element

    all_subarrays = set()

    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n + 1):
            subarray = tuple(arr[i:j])
            if subarray not in all_subarrays and is_valid_subarray(subarray):
                all_subarrays.add(subarray)

    return [list(subarray) for subarray in all_subarrays]

def maxJumps(arr, d):
    n = len(arr)
    dp = [0] * n

    def dfs(i):
        if dp[i] != 0:
            return dp[i]
        max_jump = 1
        # move to the right
        for j in range(i + 1, min(i + d + 1, n)):
            if arr[j] >= arr[i]:
                break
            max_jump = max(max_jump, 1 + dfs(j))

        # move to the left
        for j in range(i - 1, max(i - d - 1, -1), -1):
            if arr[j] >= arr[i]:
                break
            max_jump = max(max_jump, 1 + dfs(j))

        dp[i] = max_jump
        return dp[i]

    return max(dfs(i) for i in range(n))

