def perform_operations(operations):
    stack = []
    for operation in operations:
        if operation.startswith("PUSH "):
            _, x = operation.split()
            stack.append(int(x))
        elif operation == "POP" and stack:
            stack.pop()
        elif operation == "PUSH_WITH_MIN" and stack:
            stack.append(min(stack))
    return stack

def exist(grid, word):
    rows, cols = len(grid), len(grid[0])

    def dfs(r, c, idx):
        if idx == len(word):
            return True
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] != word[idx]:
            return False
        temp = grid[r][c]
        grid[r][c] = '#'
        found = (dfs(r + 1, c, idx + 1) or
                 dfs(r - 1, c, idx + 1) or
                 dfs(r, c + 1, idx + 1) or
                 dfs(r, c - 1, idx + 1))
        grid[r][c] = temp
        return found

    for i in range(rows):
        for j in range(cols):
            if dfs(i, j, 0):
                return True
    return False

from typing import List
import heapq

def minHeightDifference(grid: List[List[int]]) -> int:
    n, m = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    min_diff = [[float('inf')] * m for _ in range(n)]
    pq = [(0, 0, 0)]  # (difference, row, column)
    min_diff[0][0] = 0

    while pq:
        diff, x, y = heapq.heappop(pq)

        if (x, y) == (n - 1, m - 1):
            return diff

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                new_diff = max(diff, abs(grid[nx][ny] - grid[x][y]))
                if new_diff < min_diff[nx][ny]:
                    min_diff[nx][ny] = new_diff
                    heapq.heappush(pq, (new_diff, nx, ny))

    return -1

from typing import List

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def generateTrees(n: int) -> List[TreeNode]:
    if n == 0:
        return []

    def generate_trees(start, end):
        if start > end:
            return [None]

        all_trees = []
        for i in range(start, end + 1):
            # Generate all left and right subtrees recursively
            left_trees = generate_trees(start, i - 1)
            right_trees = generate_trees(i + 1, end)

            # Connect left and right subtrees to the root `i`
            for left in left_trees:
                for right in right_trees:
                    current_tree = TreeNode(i)
                    current_tree.left = left
                    current_tree.right = right
                    all_trees.append(current_tree)
        return all_trees

    return generate_trees(1, n)

