def min_repaints(colors):
    """
    Returns the minimum number of repaints required such that no two
    adjacent houses have the same color, given a string colors.
    """
    if not colors:
        return 0

    n = len(colors)
    repaint_count1 = 0  # start with first house as 'R'
    repaint_count2 = 0  # start with first house as 'G'
    previous_color1 = 'R'
    previous_color2 = 'G'

    for i in range(n):
        if colors[i] == previous_color1:
            repaint_count1 += 1
            previous_color1 = get_next_color(previous_color1, colors, i)
        else:
            previous_color1 = colors[i]

        if colors[i] == previous_color2:
            repaint_count2 += 1
            previous_color2 = get_next_color(previous_color2, colors, i)
        else:
            previous_color2 = colors[i]

    return min(repaint_count1, repaint_count2)


def get_next_color(previous, colors, i):
    """
    Get the next color different from the previous one and the next one in the list.
    """
    if previous == 'R':
        return 'G' if i+1 >= len(colors) or colors[i+1] != 'G' else 'B'
    elif previous == 'G':
        return 'R' if i+1 >= len(colors) or colors[i+1] != 'R' else 'B'
    else:  # previous == 'B'
        return 'R' if i+1 >= len(colors) or colors[i+1] != 'R' else 'G'

from collections import Counter

def can_construct_from_target(word, target_counter):
    word_counter = Counter(word)
    for letter in word_counter:
        if word_counter[letter] > target_counter.get(letter, 0):
            return False
    return True

def longest_constructible_word(words, target):
    target_counter = Counter(target)
    longest_word = ""

    for word in words:
        if can_construct_from_target(word, target_counter):
            if len(word) > len(longest_word):
                longest_word = word

    return longest_word

