def longest_increasing_subsequence_with_difference(arr, d):
    """
    Returns the length of the longest subsequence of increasing sea levels
    such that the difference between consecutive elements is at most d.
    """
    if not arr:
        return 0

    n = len(arr)
    dp = [1] * n  # Initialize dp array

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and arr[i] - arr[j] <= d:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def num_matching_subseq(s, words):
    def is_subsequence(word, s):
        it = iter(s)
        return all(char in it for char in word)

    count = 0
    for word in words:
        if is_subsequence(word, s):
            count += 1
    return count

def check_subarray_sum(nums, k):
    """
    Returns True if there is a subarray of length at least 2 that sums 
    up to a multiple of k, otherwise returns False.
    """
    if len(nums) < 2:
        return False

    mod_map = {0: -1}  # Dictionary to store the remainder and its index
    total_sum = 0  

    for i, num in enumerate(nums):
        total_sum += num
        mod = total_sum % k if k != 0 else total_sum

        if mod in mod_map:
            if i - mod_map[mod] > 1:
                return True
        else:
            mod_map[mod] = i

    return False

