def max_stable_warehouse_value(inventory, threshold):
    inventory = sorted(inventory)
    n = len(inventory)

    def count_ge(x):
        # first index with value >= x
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if inventory[mid] >= x:
                hi = mid
            else:
                lo = mid + 1
        return n - lo

    lo, hi = 0, max(inventory, default=0)
    ans = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if count_ge(mid) >= mid:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

def minimax_session_length(durations):
    if not durations:
        return 0
    arr = sorted(durations)
    n = len(arr)
    candidates = sorted(set(arr))

    def lower_bound(x):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def upper_bound(x):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] <= x:
                lo = mid + 1
            else:
                hi = mid
        return lo

    best_l = candidates[0]
    best_score = None
    for l in candidates:
        ge = n - lower_bound(l)
        le = upper_bound(l)
        score = max(ge, le)
        if best_score is None or score < best_score or (score == best_score and l < best_l):
            best_score = score
            best_l = l
    return best_l

def find_path(grid):
    """
    Finds a path from the top-left corner to the bottom-right corner of a grid.
    The path can only move in the right or down directions.

    :param grid: List[List[str]] - A 2D list representing the grid where '.' is an empty cell and '#' is an obstacle.
    :return: List[Tuple[int, int]] - A list of coordinates representing the path, or an empty list if no path exists.
    """
    def dfs(x, y, path):
        if x < 0 or y < 0 or x >= len(grid) or y >= len(grid[0]) or grid[x][y] == '#':
            return False
        if x == len(grid) - 1 and y == len(grid[0]) - 1:
            path.append((x, y))
            return True
        path.append((x, y))
        if dfs(x, y + 1, path):
            return True
        if dfs(x + 1, y, path):
            return True
        path.pop()
        return False

    path = []
    if dfs(0, 0, path):
        return path
    else:
        return []

import sqlite3

class DatabaseConnection:
    def __init__(self):
        self.connection = None

    def connect(self, database_path):
        """
        Establishes a connection to the SQLite database located at `database_path`.
        Prints a success message if successful, or an error message if an exception occurs.
        """
        try:
            self.connection = sqlite3.connect(database_path)
            print(f"Successfully connected to the database: {database_path}")
        except sqlite3.Error as e:
            print(f"An error occurred while connecting to the database: {e}")

    def execute_query(self, query):
        """
        Executes a given SQL query and returns the results as a list of tuples.
        If no connection is established, prints a message and returns an empty list.
        If an error occurs during query execution, prints a message and returns an empty list.
        """
        if self.connection is None:
            print("No database connection found. Please connect first.")
            return []

        try:
            cursor = self.connection.cursor()
            cursor.execute(query)
            self.connection.commit()
            return cursor.fetchall()
        except sqlite3.Error as e:
            print(f"An error occurred while executing the query: {e}")
            return []

    def close(self):
        """
        Closes the database connection.
        Prints a success message if successful, or an error message if an exception occurs.
        """
        if self.connection:
            try:
                self.connection.close()
                print("Database connection closed.")
            except sqlite3.Error as e:
                print(f"An error occurred while closing the database connection: {e}")
            finally:
                self.connection = None

def replace_repeated_chars(s):
    """
    Replaces all sequences of repeated characters in the string with a single instance of that character.

    :param s: A string consisting of lowercase English letters.
    :return: A string with consecutive duplicate characters removed.
    """
    if not s:
        return ""

    result = [s[0]]

    for char in s[1:]:
        if char != result[-1]:
            result.append(char)

    return ''.join(result)

