    """
    Calculate the factorial of a given non-negative integer n using recursion.

    :param n: Integer, the number for which the factorial is to be calculated.
    :return: Integer, the factorial of the given number.
    :raises ValueError: If the input n is negative.
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    elif n == 0:
        return 1
    else:
        return n * calculate_factorial(n - 1)

def encode_message(message):
    """
    Encodes a given string using a Caesar cipher with a shift of 3.
    Only alphabetic characters are encoded, while other characters remain unchanged.

    :param message: The input string to be encoded.
    :return: The encoded string.
    """
    def shift_char(c):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + 3) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + 3) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c) for c in message)

def shunting_yard(expression):
    """
    Convert an infix expression to a postfix expression using the Shunting Yard algorithm.

    :param expression: A string representing the infix expression.
    :return: A list representing the postfix expression.
    """
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output_queue = []
    operator_stack = []
    i = 0
    while i < len(expression):
        if expression[i].isdigit() or expression[i] == '.':
            num = expression[i]
            while i + 1 < len(expression) and (expression[i + 1].isdigit() or expression[i + 1] == '.'):
                i += 1
                num += expression[i]
            output_queue.append(float(num))
        elif expression[i] in '+-*/':
            while (operator_stack and operator_stack[-1] in '+-*/' and
                   precedence[operator_stack[-1]] >= precedence[expression[i]]):
                output_queue.append(operator_stack.pop())
            operator_stack.append(expression[i])
        elif expression[i] == '(':
            operator_stack.append(expression[i])
        elif expression[i] == ')':
            while operator_stack and operator_stack[-1] != '(':
                output_queue.append(operator_stack.pop())
            if operator_stack and operator_stack[-1] == '(':
                operator_stack.pop()
        i += 1
    while operator_stack:
        output_queue.append(operator_stack.pop())
    return output_queue

def evaluate_postfix(postfix):
    """
    Evaluate a postfix expression.

    :param postfix: A list representing the postfix expression.
    :return: A float representing the evaluated result.
    """
    stack = []
    for token in postfix:
        if isinstance(token, float):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)
    return stack[0]

def evaluate_expression(expression):
    """
    Evaluate a mathematical expression given as a string.

    :param expression: A string representing the mathematical expression.
    :return: A float representing the evaluated result.
    """
    postfix = shunting_yard(expression)
    return evaluate_postfix(postfix)

