class Inventory:
    def __init__(self):
        self.items = {}

    def add_item(self, item_name: str, quantity: int):
        """
        Adds the specified quantity of the item to the inventory.
        If the item already exists, update its quantity.
        """
        if item_name in self.items:
            self.items[item_name] += quantity
        else:
            self.items[item_name] = quantity

    def remove_item(self, item_name: str, quantity: int):
        """
        Removes the specified quantity of the item from the inventory.
        Raises ValueError if the item does not exist or the quantity to be removed exceeds the available quantity.
        """
        if item_name not in self.items:
            raise ValueError(f"Item '{item_name}' not found in inventory.")
        if self.items[item_name] < quantity:
            raise ValueError(f"Cannot remove {quantity} of '{item_name}'. Only {self.items[item_name]} available.")
        self.items[item_name] -= quantity
        if self.items[item_name] == 0:
            del self.items[item_name]

    def get_item_quantity(self, item_name: str) -> int:
        """
        Returns the current quantity of the specified item.
        Returns 0 if the item does not exist.
        """
        return self.items.get(item_name, 0)

    def list_items(self) -> list:
        """
        Returns a list of tuples, each containing an item name and its quantity,
        representing all items in the inventory.
        """
        return list(self.items.items())

def sum_of_primes(n):
    """
    Calculate the sum of all prime numbers up to and including n using the Sieve of Eratosthenes.

    :param n: The upper limit integer up to which primes are summed.
    :return: The sum of all prime numbers up to and including n.
    """
    if n < 2:
        return 0
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    p = 2
    while p * p <= n:
        if is_prime[p]:
            for multiple in range(p * p, n + 1, p):
                is_prime[multiple] = False
        p += 1
    return sum(index for index, prime in enumerate(is_prime) if prime)

class BankAccount:
    def __init__(self, initial_balance=0.0):
        """Initialize the bank account with an optional initial balance."""
        self.balance = initial_balance

    def deposit(self, amount):
        """Deposit a specified amount into the account. Return True if successful, otherwise False."""
        if amount > 0:
            self.balance += amount
            return True
        return False

    def withdraw(self, amount):
        """Withdraw a specified amount from the account if funds are available. Return True if successful, otherwise False."""
        if amount > 0 and self.balance >= amount:
            self.balance -= amount
            return True
        return False

    def check_balance(self):
        """Check the current balance of the account."""
        return self.balance

    def apply_annual_interest(self, annual_interest_rate):
        """Apply an annual interest rate to the account balance, compounded annually. Return True if successful, otherwise False."""
        if annual_interest_rate >= 0:
            self.balance += self.balance * (annual_interest_rate / 100)
            return True
        return False

def sum_of_primes(n):
    """
    Calculate the sum of all prime numbers less than a given number n.

    Parameters:
    n (int): The upper limit (exclusive) for calculating the sum of primes.

    Returns:
    int: The sum of all prime numbers less than n.
    """
    if n <= 2:
        return 0
    primes = [True] * n
    primes[0], primes[1] = False, False

    for i in range(2, int(n**0.5) + 1):
        if primes[i]:
            for j in range(i*i, n, i):
                primes[j] = False

    return sum(index for index, value in enumerate(primes) if value)

