def min_operations_to_form_target(nums, target):
    """
    Return the minimum number of operations required to form the target 
    by adding elements of nums any number of times. If it is not possible, return -1.
    """
    if target == 0:
        return 0
    if not nums:
        return -1

    dp = [float('inf')] * (target + 1)
    dp[0] = 0

    for num in nums:
        for i in range(num, target + 1):
            dp[i] = min(dp[i], dp[i - num] + 1)

    return dp[target] if dp[target] != float('inf') else -1

