def can_visit_all_rooms(rooms):
    """
    Determine if all rooms can be visited starting from room 0.

    Args:
    rooms (List[List[int]]): A 2D list where the i-th element is a list of keys found in the i-th room.

    Returns:
    bool: True if all rooms can be visited, otherwise False.
    """
    def dfs(room, visited):
        visited.add(room)
        for key in rooms[room]:
            if key not in visited:
                dfs(key, visited)

    visited = set()
    dfs(0, visited)
    return len(visited) == len(rooms)

