from collections import deque

def shortest_path(grid):
    """
    Finds the shortest path from start 'S' to destination 'D' in the grid.
    The robot can move in 4 directions: up, down, left, right.
    If there is no path, returns -1.
    """
    def bfs(start):
        q = deque([start])
        visited = set()
        visited.add(start)
        steps = 0

        while q:
            for _ in range(len(q)):
                x, y = q.popleft()
                if grid[x][y] == 'D':
                    return steps

                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and (nx, ny) not in visited and grid[nx][ny] != '#':
                        visited.add((nx, ny))
                        q.append((nx, ny))
            steps += 1
        return -1

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 'S':
                return bfs((i, j))
    return -1

