def minimum_operations_to_connect_network(n, connections):
    """
    Returns the minimum number of operations needed to make the entire network connected,
    or -1 if it is not possible.
    """
    if len(connections) < n - 1:
        return -1

    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX
            return True
        return False

    operations = 0

    for city1, city2 in connections:
        if union(city1, city2):
            operations += 1

    components = len({find(x) for x in range(n)})

    return components - 1 if components == 1 else operations + (components - 1) if operations >= n - 1 else -1

