def evaluate_expression(expression):
    """
    Evaluate the arithmetic expression provided and return the result as an integer.
    """
    # We use stack to handle multiplication and division correctly
    num, stack, sign = 0, [], '+'
    for i, s in enumerate(expression):
        if s.isdigit():
            num = num * 10 + int(s)
        if s in '+-*/' or i == len(expression) - 1:
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack.append(stack.pop() * num)
            elif sign == '/':
                stack.append(int(stack.pop() / num))
            sign = s
            num = 0
    return sum(stack)

