def count_substrings_with_3_unique_chars(s):
    """
    Returns the number of substrings that contain exactly 3 unique characters.
    """
    n = len(s)
    if n < 3:
        return 0

    count = 0
    for i in range(n - 2):
        unique_chars = set()
        for j in range(i, min(i + 3, n)):
            unique_chars.add(s[j])
            if len(unique_chars) == 3 and j == i + 2:
                count += 1
                break

    return count

