        self.val = val
        self.next = next

def group_by_remainder(head, k):
    if not head or k == 0:
        return head

    remainders_buckets = [[] for _ in range(k)]
    current = head

    while current:
        remainder = current.val % k
        remainders_buckets[remainder].append(current)
        current = current.next

    new_head = None
    prev = None

    for bucket in remainders_buckets:
        if bucket:
            for node in bucket:
                if new_head is None:
                    new_head = node
                if prev:
                    prev.next = node
                prev = node

    if prev:
        prev.next = None

    return new_head

