class WordChain:
    def __init__(self, words):
        self.words = words

    def is_predecessor(self, w1, w2):
        if len(w2) != len(w1) + 1:
            return False
        i, j = 0, 0  # Pointers for w1 and w2

        while i < len(w1) and j < len(w2):
            if w1[i] == w2[j]:
                i += 1
            j += 1

        return i == len(w1)

    def longestChain(self):
        if not self.words:
            return []

        self.words.sort(key=len)  # Sort words by their lengths
        chains = {word: [word] for word in self.words}

        for i in range(len(self.words)):
            for j in range(i):
                if self.is_predecessor(self.words[j], self.words[i]):
                    if len(chains[self.words[j]]) + 1 > len(chains[self.words[i]]):
                        chains[self.words[i]] = chains[self.words[j]] + [self.words[i]]

        longest = []
        for chain in chains.values():
            if len(chain) > len(longest):
                longest = chain

        return longest

