def minimize_square_diff_cost(nums: list[int]) -> int:
    n = len(nums)
    if n <= 1:
        return 0

    def base_cost(arr):
        return sum((arr[i] - arr[i - 1]) ** 2 for i in range(1, len(arr)))

    best = base_cost(nums)

    for l in range(n):
        for r in range(l, n):
            arr = nums[:l] + nums[l:r + 1][::-1] + nums[r + 1:]
            best = min(best, base_cost(arr))

    return best

def evaluate_expression(s):
    """
    Evaluates a given mathematical expression string and returns the result as a floating-point number.

    :param s: A string representing the mathematical expression.
    :return: A floating-point number representing the result of the evaluated expression.
    """
    def calc(a, b, op):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a / b

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        values.append(calc(left, right, operator))

    def greater_precedence(op1, op2):
        return precedence(op1) > precedence(op2)

    values = []
    operators = []
    i = 0
    while i < len(s):
        if s[i] == ' ':
            i += 1
            continue
        if s[i].isdigit() or s[i] == '.':
            val = 0.0
            decimal = False
            decimal_places = 0
            while i < len(s) and (s[i].isdigit() or s[i] == '.'):
                if s[i] == '.':
                    decimal = True
                else:
                    if decimal:
                        decimal_places += 1
                    val = val * 10 + int(s[i])
                i += 1
            if decimal:
                val /= 10 ** decimal_places
            values.append(val)
            i -= 1
        elif s[i] == '(':
            operators.append(s[i])
        elif s[i] == ')':
            while operators and operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()
        else:
            while (operators and operators[-1] != '(' and
                   greater_precedence(operators[-1], s[i])):
                apply_operator(operators, values)
            operators.append(s[i])
        i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

