def find_mode(numbers):
    """
    Finds the mode(s) of a list of integers.

    Parameters:
    numbers (list): A list of integers.

    Returns:
    list: A list containing the mode(s) of the input list.
    """
    if not numbers:
        return []

    frequency = {}
    for num in numbers:
        if num in frequency:
