def check_prime(n):
    """
    Determines if the given integer n is a prime number.

    Parameters:
    n (int): The integer to check for primality.

    Returns:
    bool: True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def can_partition(numbers):
    """
    Determines if a list of integers can be partitioned into two subsets with equal sum.

    :param numbers: List of integers
    :return: True if such a partition exists, False otherwise
    """
    total_sum = sum(numbers)

    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    n = len(numbers)

    dp = [[False] * (target + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if numbers[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - numbers[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][target]

