def longest_increasing_subsequence(nums):
    """
    Finds the longest increasing subsequence in a list of integers.

    :param nums: List[int] - A list of integers.
    :return: List[int] - The longest increasing subsequence.
    """
    if not nums:
        return []

    tails = []
    predecessors = [-1] * len(nums)
    indices = [-1] * len(nums)

    for i, num in enumerate(nums):
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        if left == len(tails):
            if tails:
                predecessors[i] = indices[len(tails) - 1]
            tails.append(num)
            indices[len(tails) - 1] = i
        else:
            tails[left] = num
            indices[left] = i
            if left > 0:
                predecessors[i] = indices[left - 1]

    lis = []
    k = indices[len(tails) - 1]
    while k >= 0:
        lis.append(nums[k])
        k = predecessors[k]

    lis.reverse()
    return lis

