def count_palindromic_subsequences(s):
    """
    Returns the number of valid subsequences that are palindromes.
    """
    MOD = 10**9 + 7
    n = len(s)

    # dp[l][r] will be the number of palindromic subsequences in substring s[l:r+1]
    dp = [[0] * n for _ in range(n)]

    for length in range(1, n + 1):  # length of substring
        for l in range(n - length + 1):
            r = l + length - 1
            if length == 1:
                dp[l][r] = 1
            else:
                if s[l] != s[r]:
                    dp[l][r] = dp[l + 1][r] + dp[l][r - 1] - dp[l + 1][r - 1]
                else:
                    dp[l][r] = dp[l + 1][r] + dp[l][r - 1] + 1

            dp[l][r] = (dp[l][r] + MOD) % MOD

    return dp[0][n - 1]

