def findKthElement(arr1, arr2, k):
    """
    Finds the k-th smallest element in the combined sorted array of arr1 and arr2
    without merging the arrays.
    """
    def kth_helper(arr1, start1, end1, arr2, start2, end2, k):
        # If arr1 is exhausted, return the k-th element from arr2
        if start1 > end1:
            return arr2[start2 + k - 1]

        # If arr2 is exhausted, return the k-th element from arr1
        if start2 > end2:
            return arr1[start1 + k - 1]

        # If k equals 1, return the smallest element between two arrays
        if k == 1:
            return min(arr1[start1], arr2[start2])

        # Calculate mid points for both arrays
        mid1 = start1 + k // 2 - 1
        mid2 = start2 + k // 2 - 1

        elem1 = arr1[mid1] if mid1 <= end1 else float('inf')
        elem2 = arr2[mid2] if mid2 <= end2 else float('inf')

        # If element from arr1 is smaller, that means we'll discard first k // 2 elements of arr1
        if elem1 < elem2:
            return kth_helper(arr1, mid1 + 1, end1, arr2, start2, end2, k - k // 2)
        else:
            # If element from arr2 is smaller or equal, we'll discard first k // 2 elements of arr2
            return kth_helper(arr1, start1, end1, arr2, mid2 + 1, end2, k - k // 2)

    # Main call to helper function
    return kth_helper(arr1, 0, len(arr1) - 1, arr2, 0, len(arr2) - 1, k)

class Node:
    def __init__(self, x, next=None, random=None):
        self.val = x
        self.next = next
        self.random = random

class DeepCopyList:
    def copyRandomList(self, head):
        if not head:
            return None

        # Create a mapping from original nodes to their copies
        old_to_new = {}

        # First pass: Copy all the nodes and store the copies in the map
        current = head
        while current:
            copy = Node(current.val)
            old_to_new[current] = copy
            current = current.next

        # Second pass: Set the next and random pointers for the copied nodes
        current = head
        while current:
            copy = old_to_new[current]
            copy.next = old_to_new.get(current.next)
            copy.random = old_to_new.get(current.random)
            current = current.next

        return old_to_new[head]

