def longest_non_repeating_substring(s):
    """
    Returns the length of the longest possible remaining string after deleting characters
    to ensure no consecutive characters are the same.
    """
    if not s:
        return 0

    max_length = 1  # A single character is always non-repeating
    for i in range(1, len(s)):
        if s[i] != s[i - 1]:
            max_length += 1

    return max_length

