def score_of_parentheses(s):
    """
    Calculate the score of a valid parentheses string.
    """
    stack = [0]  # Start with a base score of zero

    for char in s:
        if char == '(':
            stack.append(0)
        else:
            v = stack.pop()
            stack[-1] += max(2 * v, 1)
    return stack.pop()

