def has_cycle(graph, n):
    """
    Determines if the directed graph has a cycle.

    :param graph: List of edges where each edge is represented as a pair of nodes [u, v]
    :param n: Number of nodes in the graph
    :return: True if the graph contains a cycle, False otherwise
    """
    def dfs(node):
        if node in visiting:
            return True
        if node in visited:
            return False

        visiting.add(node)
        for neighbor in adj_list[node]:
            if dfs(neighbor):
                return True
        visiting.remove(node)
        visited.add(node)

        return False

    from collections import defaultdict

    adj_list = defaultdict(list)
    for u, v in graph:
        adj_list[u].append(v)

    visited = set()
    visiting = set()

    for node in range(n):
        if dfs(node):
            return True

    return False

class MinStack:
    def __init__(self):
        self.stack = []
        self.min_stack = []

    def push(self, val: int) -> None:
        self.stack.append(val)
        if not self.min_stack or val <= self.min_stack[-1]:
            self.min_stack.append(val)

    def pop(self) -> None:
        if self.stack:
            val = self.stack.pop()
            if val == self.min_stack[-1]:
                self.min_stack.pop()

    def top(self) -> int:
        if self.stack:
            return self.stack[-1]
        return None

    def getMin(self) -> int:
        if self.min_stack:
            return self.min_stack[-1]
        return None

