def can_form_valid_bst(nums):
    """
    Determines if the given list of integers can form a valid binary search tree (BST).
    Args:
    nums (list): List of integers representing the values to be inserted in BST.

    Returns:
    bool: True if the values can form a valid BST, False otherwise.
    """
    def is_valid_bst_sequence(start, end):
        if start >= end:
            return True
        root_val = nums[start]
        right_subtree_start = start + 1
        while right_subtree_start <= end and nums[right_subtree_start] < root_val:
            right_subtree_start += 1
        for i in range(right_subtree_start, end + 1):
            if nums[i] < root_val:
                return False
        return is_valid_bst_sequence(start + 1, right_subtree_start - 1) and is_valid_bst_sequence(right_subtree_start, end)

    return is_valid_bst_sequence(0, len(nums) - 1)

