def smallest_substring(document, keywords):
    from collections import Counter, defaultdict

    if not document or not keywords:
        return ""

    keyword_count = Counter(keywords)
    required_keywords = len(keyword_count)
    current_count = defaultdict(int)
    formed_keywords = 0

    left = 0
    min_len = float('inf')
    min_substr = ""

    for right in range(len(document)):
        char = document[right]
        if char in keyword_count:
            current_count[char] += 1
            if current_count[char] == keyword_count[char]:
                formed_keywords += 1

        while formed_keywords == required_keywords:
            if right - left + 1 < min_len:
                min_len = right - left + 1
                min_substr = document[left:right+1]

            char = document[left]
            if char in keyword_count:
                current_count[char] -= 1
                if current_count[char] < keyword_count[char]:
                    formed_keywords -= 1
            left += 1

    return min_substr

