def two_sum(nums, target):
    """
    Find indices i, j such that nums[i] + nums[j] = target, where i and j are distinct.

    Args:
    nums: List of integers
    target: Integer target sum

    Returns:
    Tuple of integers (i, j)
    """
    index_map = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in index_map:
            return (index_map[complement], i)
        index_map[num] = i

def can_form_target(words, target):
    """
    Determines if the target can be formed by concatenating exactly two distinct strings from words.
    """
    word_set = set(words)

    for word in words:
        remainder = target[len(word):] if target.startswith(word) else None
        if remainder and remainder in word_set and remainder != word:
            return True
    return False

