def longest_harmonious_window(durations):
    from collections import deque
    maxdq = deque()
    mindq = deque()
    left = 0
    best = 0
    for right, x in enumerate(durations):
        while maxdq and maxdq[-1] < x:
            maxdq.pop()
        maxdq.append(x)
        while mindq and mindq[-1] > x:
            mindq.pop()
        mindq.append(x)
        while maxdq[0] - mindq[0] > 1:
            if durations[left] == maxdq[0]:
                maxdq.popleft()
            if durations[left] == mindq[0]:
                mindq.popleft()
            left += 1
        best = max(best, right - left + 1)
    return best

