def calculate_grade_distribution(scores):
    """
    Calculate the percentage distribution of grades for a list of student scores.

    Args:
    scores (list of int): A list of integers representing student test scores.

    Returns:
    dict: A dictionary with grade letters ('A', 'B', 'C', 'D', 'F') as keys and their respective percentages as values.
    """
    total_students = len(scores)
    grade_counts = {'A': 0, 'B': 0, 'C': 0, 'D': 0, 'F': 0}

    for score in scores:
        if 90 <= score <= 100:
            grade_counts['A'] += 1
        elif 80 <= score < 90:
            grade_counts['B'] += 1
        elif 70 <= score < 80:
            grade_counts['C'] += 1
        elif 60 <= score < 70:
            grade_counts['D'] += 1
        else:
            grade_counts['F'] += 1

    grade_percentages = {grade: round((count / total_students) * 100, 2) for grade, count in grade_counts.items()}

    return grade_percentages

