class Matrix:
    def __init__(self, data):
        """
        Initializes the Matrix with a 2D list.
        :param data: 2D list representing the matrix.
        """
        if not all(isinstance(row, list) and len(row) == len(data[0]) for row in data):
            raise ValueError("Input data should be a 2D list with equal length rows.")
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def add(self, other):
        """
        Adds two matrices of the same dimensions.
        :param other: Another Matrix object.
        :return: A new Matrix object representing the sum.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be the same size to add.")
        result = [[self.data[i][j] + other.data[i][j] for j in range(self.cols)] for i in range(self.rows)]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtracts the second matrix from the first.
        :param other: Another Matrix object.
        :return: A new Matrix object representing the difference.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be the same size to subtract.")
        result = [[self.data[i][j] - other.data[i][j] for j in range(self.cols)] for i in range(self.rows)]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiplies two matrices.
        :param other: Another Matrix object.
        :return: A new Matrix object representing the product.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in first matrix must be equal to number of rows in second matrix.")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def transpose(self):
        """
        Returns the transpose of the matrix.
        :return: A new Matrix object representing the transpose.
        """
        result = [[self.data[j][i] for j in range(self.rows)] for i in range(self.cols)]
        return Matrix(result)

    def __str__(self):
        """
        Returns a string representation of the matrix.
        :return: A string representing the matrix.
        """
        return '\n'.join(['\t'.join(map(str, row)) for row in self.data])

def max_profit(prices):
    """
    Calculate the maximum profit from a single buy and sell transaction.

    :param prices: List of integers representing stock prices on different days.
    :return: Integer representing the maximum profit that can be achieved.
    """
    if not prices:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

