def max_length_subarray_with_k_distinct(arr, k):
    from collections import defaultdict

    n = len(arr)
    if n == 0 or k == 0:
        return 0

    left = 0
    right = 0
    max_length = 0
    unique_count = 0
    freq_map = defaultdict(int)

    while right < n:
        if freq_map[arr[right]] == 0:
            unique_count += 1
        freq_map[arr[right]] += 1
        right += 1

        while unique_count > k:
            freq_map[arr[left]] -= 1
            if freq_map[arr[left]] == 0:
                unique_count -= 1
            left += 1

        if unique_count == k:
            max_length = max(max_length, right - left)

    return max_length

