def maxProfit(k, prices):
    """
    Calculates the maximum profit with at most k transactions.
    :param k: int, maximum number of allowed transactions
    :param prices: List[int], list of prices where prices[i] is the price of a item on day i
    :return: int, maximum profit
    """
    if not prices or k == 0:
        return 0

    n = len(prices)

    if k >= n // 2:
        return sum(max(prices[i] - prices[i - 1], 0) for i in range(1, n))

    dp = [[0] * n for _ in range(k + 1)]

    for i in range(1, k + 1):
        max_diff = -prices[0]
        for j in range(1, n):
            dp[i][j] = max(dp[i][j - 1], prices[j] + max_diff)
            max_diff = max(max_diff, dp[i - 1][j] - prices[j])

    return dp[k][n - 1]

def num_lakes(grid):
    """
    Returns the number of lakes in the given 2D grid.
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    def dfs(x, y):
        if not is_valid(x, y) or visited[x][y] or grid[x][y] == 1:
            return
        visited[x][y] = True
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        for dx, dy in directions:
            dfs(x + dx, y + dy)

    def is_surrounded_by_land(x, y):
        queue = [(x, y)]
        surrounded = True
        while queue:
            cx, cy = queue.pop(0)
            if not is_valid(cx, cy):
                surrounded = False
                continue
            if grid[cx][cy] == 1 or visited[cx][cy]:
                continue
            visited[cx][cy] = True
            directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
            for dx, dy in directions:
                queue.append((cx + dx, cy + dy))
        return surrounded

    lakes_count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 0 and not visited[i][j]:
                if is_surrounded_by_land(i, j):
                    lakes_count += 1
    return lakes_count

def four_sum(nums, target):
    from collections import defaultdict

    # This will hold pairs of summed values and their respective indices.
    two_sum_dict = defaultdict(list)

    # Save all pairs of two-sum values in a dictionary with their indices
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            two_sum_dict[nums[i] + nums[j]].append((i, j))

    # Try to find four indices such that their summed values equal the target
    for k in range(len(nums)):
        for l in range(k + 1, len(nums)):
            current_sum = nums[k] + nums[l]
            remaining_sum = target - current_sum
            if remaining_sum in two_sum_dict:
                for pair in two_sum_dict[remaining_sum]:
                    i, j = pair
                    # Check if the pairs are distinct
                    if len(set([i, j, k, l])) == 4:
                        return [i, j, k, l]
    return []

