def longest_palindromic_substring(s: str) -> str:
    """
    Finds and returns the longest palindromic substring within the given string.
    If there are multiple substrings of the same maximum length, returns the first one encountered.

    :param s: Input string
    :return: Longest palindromic substring
    """
    n = len(s)
    if n == 0:
        return ""

    dp = [[False] * n for _ in range(n)]
    start = 0
    max_length = 1

    for i in range(n):
        dp[i][i] = True

    for i in range(n - 1):
        if s[i] == s[i + 1]:
            dp[i][i + 1] = True
            start = i
            max_length = 2

    for k in range(3, n + 1):
        for i in range(n - k + 1):
            j = i + k - 1
            if dp[i + 1][j - 1] and s[i] == s[j]:
                dp[i][j] = True
                if k > max_length:
                    start = i
                    max_length = k

    return s[start:start + max_length]

class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def count_leaves(root):
    """
    Counts the number of leaf nodes in a binary tree.

    :param root: TreeNode, the root of the binary tree
    :return: int, the number of leaf nodes in the tree
    """
    if root is None:
        return 0
    if root.left is None and root.right is None:
        return 1
    return count_leaves(root.left) + count_leaves(root.right)

class Polynomial:
    def __init__(self, coefficients):
        """
        Initializes the polynomial with the given coefficients.
        :param coefficients: List of integers representing the coefficients of the polynomial.
        """
        self.coefficients = coefficients
        while len(self.coefficients) > 1 and self.coefficients[0] == 0:
            self.coefficients.pop(0)

    def __str__(self):
        """
        Returns a string representation of the polynomial.
        :return: String representation of the polynomial.
        """
        terms = []
        degree = len(self.coefficients) - 1
        for coeff in self.coefficients:
            if coeff == 0:
                continue
            elif coeff > 0 and terms:
                sign = " + "
            elif coeff < 0:
                sign = " - " if terms else "-"
                coeff = -coeff
            else:
                sign = ""

            if degree == 0:
                term = f"{coeff}"
            elif degree == 1:
                term = f"{coeff}x"
            else:
                term = f"{coeff}x^{degree}"

            terms.append(sign + term)
            degree -= 1

        return "".join(terms) if terms else "0"

    def evaluate(self, x):
        """
        Evaluates the polynomial at a given value of x.
        :param x: Integer value at which to evaluate the polynomial.
        :return: Integer result of the polynomial evaluation.
        """
        result = 0
        for power, coeff in enumerate(reversed(self.coefficients)):
            result += coeff * (x ** power)
        return result

    def add(self, other):
        """
        Adds two polynomials and returns a new polynomial representing the sum.
        :param other: Another Polynomial object to add to this polynomial.
        :return: New Polynomial object representing the sum.
        """
        degree_self = len(self.coefficients) - 1
        degree_other = len(other.coefficients) - 1
        max_degree = max(degree_self, degree_other)
        new_coefficients = [0] * (max_degree + 1)

        for i in range(degree_self + 1):
            new_coefficients[i] += self.coefficients[i]
        for i in range(degree_other + 1):
            new_coefficients[i] += other.coefficients[i]

        while len(new_coefficients) > 1 and new_coefficients[0] == 0:
            new_coefficients.pop(0)

        return Polynomial(new_coefficients)

def sum_of_primes(start, end):
    """
    Computes the sum of all prime numbers within the range [start, end].
    If start is greater than end, returns 0.

    :param start: The starting integer of the range.
    :param end: The ending integer of the range.
    :return: The sum of all prime numbers within the range [start, end].
    """
    def is_prime(n):
        """
        Determines if a number is prime.

        :param n: The number to check.
        :return: True if n is prime, False otherwise.
        """
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    if start > end:
        return 0

    prime_sum = 0
    for num in range(start, end + 1):
        if is_prime(num):
            prime_sum += num

    return prime_sum

def longest_increasing_subsequence(nums):
    """
    Finds the length of the longest increasing subsequence in a list of integers.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def is_valid(s: str) -> bool:
    """
    Determines if the given string of brackets is valid.

    :param s: A string consisting of '(', ')', '{', '}', '[' and ']'.
    :return: True if the sequence is valid, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            top_element = stack.pop() if stack else '#'
            if bracket_map[char] != top_element:
                return False

    return not stack

from urllib.parse import urlparse

def parse_url(url):
    """
    Parses a given URL and returns a dictionary containing the components: scheme, netloc, path, params, query, and fragment.
    Only includes components that are present in the URL.

    :param url: A string representing the URL to be parsed.
    :return: A dictionary with keys corresponding to the URL components that are present in the input URL.
    """
    parsed = urlparse(url)
    url_dict = {}

    if parsed.scheme:
        url_dict['scheme'] = parsed.scheme
    if parsed.netloc:
        url_dict['netloc'] = parsed.netloc
    if parsed.path:
        url_dict['path'] = parsed.path
    if parsed.params:
        url_dict['params'] = parsed.params
    if parsed.query:
        url_dict['query'] = parsed.query
    if parsed.fragment:
        url_dict['fragment'] = parsed.fragment

    return url_dict

