def shortest_palindrome_length(s):
    """
    Returns the length of the shortest palindrome that can be created by appending characters to the end of the string.
    """
    # Find the longest palindromic prefix
    n = len(s)
    rev_s = s[::-1]

    for i in range(n):
        if s.startswith(rev_s[i:]):
            # If s starts with the suffix of the reversed string, 
            # then the remaining part needs to be appended to make it a palindrome
            return 2 * n - len(rev_s[i:])

    return n  # For an empty input

# Adding function to get the length of the shortest palindrome
def make_shortest_palindrome(s):
    """
    Returns the length of the shortest palindrome that can be created by appending characters to the end of the string.
    """
    return shortest_palindrome_length(s)

