def min_moves_to_non_decreasing(heights):
    """
    Returns the minimum number of moves required to arrange the array
    of heights in non-decreasing order.
    """
    if not heights:
        return 0

    n = len(heights)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if heights[i] >= heights[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    longest_increasing_subsequence = max(dp)
    return n - longest_increasing_subsequence

def numDistinctIslands(grid):
    """
    Returns the number of distinct islands in the grid.
    """
    def dfs(x, y, baseX, baseY, shape):
        if (0 <= x < len(grid)) and (0 <= y < len(grid[0])) and grid[x][y] == 1:
            grid[x][y] = 0
            shape.append((x - baseX, y - baseY))
            dfs(x + 1, y, baseX, baseY, shape)
            dfs(x - 1, y, baseX, baseY, shape)
            dfs(x, y + 1, baseX, baseY, shape)
            dfs(x, y - 1, baseX, baseY, shape)

    shapes = set()
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                shape = []
                dfs(i, j, i, j, shape)
                shapes.add(tuple(shape))
    return len(shapes)

