def partition_labels(s: str, k: int):
    """
    Partitions the string s into as many parts as possible such that each letter appears in at most one part, 
    and the length of the longest part is minimized. Returns the lengths of the parts.
    """
    last_occurrence = {ch: ix for ix, ch in enumerate(s)}
    partitions = []
    start, end = 0, 0

    for ix, ch in enumerate(s):
        end = max(end, last_occurrence[ch])
        if ix == end:
            partitions.append(end - start + 1)
            start = ix + 1

    return partitions

