from collections import deque

def walls_and_gates(rooms):
    if not rooms:
        return

    m, n = len(rooms), len(rooms[0])
    INF = float('inf')
    queue = deque()

    # Initially, add all gates to the queue
    for i in range(m):
        for j in range(n):
            if rooms[i][j] == 0:
                queue.append((i, j))

    # Perform BFS from all gates simultaneously
    while queue:
        x, y = queue.popleft()
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and rooms[nx][ny] == INF:
                rooms[nx][ny] = rooms[x][y] + 1
                queue.append((nx, ny))

