def shortest_unsorted_block(records):
    n = len(records)
    left = n
    right = -1
    max_seen = records[0]
    for i in range(n):
        if records[i] < max_seen:
            right = i
        else:
            max_seen = records[i]
    min_seen = records[-1]
    for i in range(n - 1, -1, -1):
        if records[i] > min_seen:
            left = i
        else:
            min_seen = records[i]
    if right == -1:
        return 0
    return right - left + 1

