def count_characters(s):
    """
    Returns a list of tuples containing each unique character from the string
    and its corresponding count, ordered by the first appearance of the character.

    :param s: Input string
    :return: List of tuples (character, count)
    """
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    return list(char_count.items())

