def find_primes(start, end):
    """
    Finds all prime numbers within the given range [start, end].

    Args:
    start (int): The start of the range.
    end (int): The end of the range.

    Returns:
    list: A list of all prime numbers within the specified range.
    """
    if end < 2:
        return []

    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    return [n for n in range(max(2, start), end + 1) if is_prime(n)]

