reference_solution:
from collections import defaultdict

class SubarraySumDivisibleByK:
    def __init__(self, arr, k):
        self.arr = arr
        self.k = k

    def countSubarrays(self):
        count = 0
        cum_sum = 0
        remainder_map = defaultdict(int)
        remainder_map[0] = 1

        for num in self.arr:
            cum_sum += num
            remainder = cum_sum % self.k
            if remainder < 0: 
                remainder += self.k

            if remainder in remainder_map:
                count += remainder_map[remainder]

            remainder_map[remainder] += 1

        return count

class FileSystem:
    def __init__(self):
        self.fs = {}

    def mkdir(self, path):
        dirs = path.split('/')
        current = self.fs

        for d in dirs:
            if not d:
                continue
            if d not in current:
                current[d] = {"__metadata__": {}}
            current = current[d]

    def write(self, path, key, value):
        dirs = path.split('/')
        current = self.fs

        for d in dirs:
            if not d:
                continue
            if d not in current:
                return
            current = current[d]

        current["__metadata__"][key] = value

    def read(self, path, key):
        dirs = path.split('/')
        current = self.fs

        for d in dirs:
            if not d:
                continue
            if d not in current:
                return f"{path} {key} not found"
            current = current[d]

        if key in current["__metadata__"]:
            return f"{path} {key} {current['__metadata__'][key]}"
        else:
            return f"{path} {key} not found"

def process_operations(operations):
    fs = FileSystem()
    output = []

    for op in operations:
        tokens = op.split()
        if tokens[0] == "mkdir":
            fs.mkdir(tokens[1])
        elif tokens[0] == "write":
            fs.write(tokens[1], tokens[2], tokens[3])
        elif tokens[0] == "read":
            result = fs.read(tokens[1], tokens[2])
            output.append(result)

    return output

def count_trinucleotides(dna_sequences):
    """
    Counts the occurrences of each unique trinucleotide in a list of DNA sequences.

    Parameters:
    dna_sequences (list of str): A list of DNA sequences.

    Returns:
    dict: A dictionary with trinucleotides as keys and their counts as values.
    """
    trinucleotide_count = {}

    for sequence in dna_sequences:
        if len(sequence) >= 3:
            for i in range(len(sequence) - 2):
                trinucleotide = sequence[i:i+3]
                if trinucleotide in trinucleotide_count:
                    trinucleotide_count[trinucleotide] += 1
                else:
                    trinucleotide_count[trinucleotide] = 1

    return trinucleotide_count

