def min_operations_to_ensure_no_adjacent_duplicates(s, k):
    """
    Returns the minimum number of operations needed to ensure that there are no 
    two adjacent characters that are the same in the given string `s`.
    """
    if not s:
        return 0

    n = len(s)
    operations = 0
    i = 0

    while i < n - 1:
        if s[i] == s[i + 1]:
            # Find a non-conflicting character
            for ch in 'abcdefghijklmnopqrstuvwxyz':
                if ch != s[i] and (i + 2 >= n or ch != s[i + 2]):
                    s = s[:i + 1] + ch + s[i + 2:]
                    break
            operations += 1
        i += 1

    return operations

