def follows_pattern(pattern, string):
    def match(string, i, pattern, j, map_char_index, set_substrings):
        if i == len(string) and j == len(pattern):
            return True
        if i == len(string) or j == len(pattern):
            return False

        p_char = pattern[j]

        if p_char in map_char_index:
            mapped_str = map_char_index[p_char]
            if string.startswith(mapped_str, i):
                return match(string, i + len(mapped_str), pattern, j + 1, map_char_index, set_substrings)
            return False
        else:
            for k in range(i, len(string)):
                candidate_str = string[i:k + 1]

                if candidate_str in set_substrings:
                    continue

                map_char_index[p_char] = candidate_str
                set_substrings.add(candidate_str)

                if match(string, k + 1, pattern, j + 1, map_char_index, set_substrings):
                    return True

                del map_char_index[p_char]
                set_substrings.remove(candidate_str)

        return False

    return match(string, 0, pattern, 0, {}, set())

