class EmailQueue:
    def __init__(self, capacity):
        self.capacity = capacity
        self.queue = []

    def enqueue(self, email, message):
        if len(self.queue) >= self.capacity:
            self.queue.pop(0)
        self.queue.append((email, message))

    def dequeue(self):
        if not self.queue:
            return []
        return list(self.queue.pop(0))

