def find_peak_element(nums):
    """
    Finds the index of any peak element in the array 'nums'.
    A peak element is an element that is strictly greater than its neighbors.
    """
    n = len(nums)
    if n == 1:
        return 0  # If there's only one element, it is the peak element

    left, right = 0, n - 1

    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[mid + 1]:
            right = mid
        else:
            left = mid + 1

    return left

