from typing import List
from collections import Counter

def count_pairs(nums: List[int], k: int) -> int:
    """
    Counts the number of unique pairs (i, j) in the list nums such that nums[i] * nums[j] = k.

    :param nums: List of integers.
    :param k: Integer representing the product to find.
    :return: Integer count of pairs.
    """
    if not nums:
        return 0

    num_counter = Counter(nums)
    count = 0
    seen = set()

    for num in nums:
        if num == 0:
            if k == 0:
                count += num_counter[0] * (num_counter[0] - 1) // 2
            continue

        if k % num != 0:
            continue

        complement = k // num

        if complement in num_counter and complement not in seen:
            if complement == num:
                count += num_counter[num] * (num_counter[num] - 1) // 2
            else:
                count += num_counter[num] * num_counter[complement]
            seen.add(num)
            seen.add(complement)

    return count

class ContactManager:
    def __init__(self):
        """Initialize an empty list to store contacts."""
        self.contacts = []

    def add_contact(self, name, phone_number):
        """Add a new contact with the given name and phone number."""
        contact = {'name': name, 'phone_number': phone_number}
        self.contacts.append(contact)
        print(f"Contact {name} added successfully.")

    def remove_contact(self, name):
        """Remove the contact with the specified name."""
        initial_count = len(self.contacts)
        self.contacts = [contact for contact in self.contacts if contact['name'] != name]
        if len(self.contacts) < initial_count:
            print(f"Contact {name} removed successfully.")
        else:
            print(f"Contact {name} not found.")

    def update_contact(self, name, new_phone_number):
        """Update the phone number of the contact with the specified name."""
        for contact in self.contacts:
            if contact['name'] == name:
                contact['phone_number'] = new_phone_number
                print(f"Contact {name} updated successfully.")
                return
        print(f"Contact {name} not found.")

    def display_contacts(self):
        """Display all contacts."""
        if not self.contacts:
            print("No contacts found.")
        else:
