def count_occurrences(strings):
    """
    Counts the occurrences of each string in a list, treating strings as case-insensitive.

    :param strings: List of strings to count occurrences for.
    :return: Dictionary with strings as keys and their occurrence counts as values.
    """
    occurrences = {}
    for string in strings:
        string = string.lower()
        if string in occurrences:
            occurrences[string] += 1
        else:
            occurrences[string] = 1
    return occurrences

