def max_profit(prices):
    """
    Calculate the maximum profit from a single buy and sell transaction.

    :param prices: List of stock prices where prices[i] is the price of the stock on the i-th day.
    :return: Maximum profit that can be achieved from a single transaction. If no profit is possible, return 0.
    """
    if not prices:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

def json_compress(data):
    """
    Recursively removes all keys with None values from the dictionary and returns the compressed dictionary.

    :param data: A dictionary that may contain nested dictionaries and lists.
    :return: A dictionary with all keys containing None values removed.
    """
    if isinstance(data, dict):
        return {k: json_compress(v) for k, v in data.items() if v is not None and json_compress(v) != {}}
    elif isinstance(data, list):
        return [json_compress(item) for item in data if json_compress(item) != {}]
    else:
        return data

