def get_max_gold(matrix):
    def dfs(x, y, visited):
        if (x < 0 or x >= len(matrix) or y < 0 or y >= len(matrix[0]) or 
            (x, y) in visited or matrix[x][y] == 0):
            return 0
        visited.add((x, y))
        up = dfs(x - 1, y, visited)
        down = dfs(x + 1, y, visited)
        left = dfs(x, y - 1, visited)
        right = dfs(x, y + 1, visited)
        visited.remove((x, y))
        return matrix[x][y] + max(up, down, left, right)

    max_gold = 0
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j] != 0:
                max_gold = max(max_gold, dfs(i, j, set()))

    return max_gold

