class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """Insert a new value into the binary tree."""
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        """Helper method to insert a value recursively."""
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert_recursively(node.left, value)
        else:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_recursively(node.right, value)

    def inorder_traversal(self):
        """Return a list of values in inorder traversal order."""
        return self._inorder_traversal_recursively(self.root)

    def _inorder_traversal_recursively(self, node):
        """Helper method to perform inorder traversal recursively."""
        result = []
        if node is not None:
            result += self._inorder_traversal_recursively(node.left)
            result.append(node.value)
            result += self._inorder_traversal_recursively(node.right)
        return result

    def preorder_traversal(self):
        """Return a list of values in preorder traversal order."""
        return self._preorder_traversal_recursively(self.root)

    def _preorder_traversal_recursively(self, node):
        """Helper method to perform preorder traversal recursively."""
        result = []
        if node is not None:
            result.append(node.value)
            result += self._preorder_traversal_recursively(node.left)
            result += self._preorder_traversal_recursively(node.right)
        return result

    def postorder_traversal(self):
        """Return a list of values in postorder traversal order."""
        return self._postorder_traversal_recursively(self.root)

    def _postorder_traversal_recursively(self, node):
        """Helper method to perform postorder traversal recursively."""
        result = []
        if node is not None:
            result += self._postorder_traversal_recursively(node.left)
            result += self._postorder_traversal_recursively(node.right)
            result.append(node.value)
        return result

    def level_order_traversal(self):
        """Return a list of values in level order traversal (breadth-first)."""
        result = []
        if self.root is None:
            return result
        queue = [self.root]
        while queue:
            current_node = queue.pop(0)
            result.append(current_node.value)
            if current_node.left is not None:
                queue.append(current_node.left)
            if current_node.right is not None:
                queue.append(current_node.right)
        return result

    def height(self):
        """Return the height of the tree."""
        return self._height_recursively(self.root)

    def _height_recursively(self, node):
        """Helper method to calculate the height of the tree recursively."""
        if node is None:
            return -1
        left_height = self._height_recursively(node.left)
        right_height = self._height_recursively(node.right)
        return max(left_height, right_height) + 1

