def evaluate_expression(s: str) -> int:
    """
    Evaluates a mathematical expression containing digits and the operators +, -, *, and /.
    The expression may contain white spaces, and the division between integers should truncate toward zero.
    """
    def operate(op, second, first):
        if op == '+':
            return first + second
        elif op == '-':
            return first - second
        elif op == '*':
            return first * second
        elif op == '/':
            # Integer division truncating toward zero
            return int(first / second)

    s = s.replace(' ', '')
    n = len(s)
    stack = []
    num = 0
    last_op = '+'

    for i, char in enumerate(s):
        if char.isdigit():
            num = num * 10 + int(char)
        if char in '+-*/' or i == n - 1:
            if last_op in '+-':
                stack.append(num if last_op == '+' else -num)
            elif last_op in '*/':
                prev = stack.pop()
                stack.append(operate(last_op, num, prev))
            last_op = char
            num = 0

    return sum(stack)

