def is_balanced_parentheses(expression):
    """
    Determines if the parentheses in the given expression are balanced.

    :param expression: A string containing only the characters '(', ')', '{', '}', '[' and ']'.
    :return: True if the parentheses are balanced, False otherwise.
    """
    matching_parentheses = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in expression:
        if char in matching_parentheses:
            top_element = stack.pop() if stack else '#'
            if matching_parentheses[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def collect_notices(messages):
    result = []
    for message in messages:
        stripped = message.strip()
        if stripped.startswith('공지:'):
            result.append(stripped[len('공지:'):].strip())
    return result

def swap_keys_values(original_dict):
    """
    Returns a new dictionary with keys and values swapped from the original dictionary.

    :param original_dict: A dictionary with unique values.
    :return: A dictionary with keys and values swapped.
    """
    swapped_dict = {}
    for key, value in original_dict.items():
        swapped_dict[value] = key
    return swapped_dict

