def replace_word(sentence, target_word, replacement_word):
    """
    Replaces all occurrences of target_word in sentence with replacement_word,
    preserving the case of target_word in the replacement.

    :param sentence: str, the original sentence
    :param target_word: str, the word to be replaced
    :param replacement_word: str, the word to replace target_word with
    :return: str, the modified sentence
    """
    def match_case(word, target):
        if target.istitle() and not word.istitle():
            return word.capitalize()
        elif target.isupper() and not word.isupper():
            return word.upper()
        elif target.islower() and not word.islower():
            return word.lower()
        return word

    words = sentence.split()
    modified_words = [
        match_case(replacement_word, word) if word.lower() == target_word.lower() else word
        for word in words
    ]
    return ' '.join(modified_words)

def evaluate_expression(expression):
    """
    Evaluates a mathematical expression given as a string without using the eval function.

    :param expression: A string representing the mathematical expression.
    :return: A float representing the result of the evaluated expression.
    """
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    operators = []
    values = []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        if expression[i] in '0123456789':
            j = i
            while j < len(expression) and expression[j] in '0123456789':
                j += 1
            values.append(float(expression[i:j]))
            i = j
        elif expression[i] == '(':
            operators.append(expression[i])
            i += 1
        elif expression[i] == ')':
            while len(operators) != 0 and operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Pop '('
            i += 1
        else:
            while (len(operators) != 0 and precedence(operators[-1]) >= precedence(expression[i])):
                apply_operator(operators, values)
            operators.append(expression[i])
            i += 1

    while len(operators) != 0:
        apply_operator(operators, values)

    return values[0]

def detect_cycle(graph):
    """
    Detects if there is a cycle in a directed graph represented as an adjacency list.

    :param graph: A dictionary where keys are nodes and values are lists of adjacent nodes.
    :return: True if the graph contains a cycle, False otherwise.
    """
    def is_cyclic_util(node, visited, rec_stack):
        visited[node] = True
        rec_stack[node] = True

        for neighbour in graph.get(node, []):
            if not visited[neighbour]:
                if is_cyclic_util(neighbour, visited, rec_stack):
                    return True
            elif rec_stack[neighbour]:
                return True

        rec_stack[node] = False
        return False

    visited = {node: False for node in graph}
    rec_stack = {node: False for node in graph}

    for node in graph:
        if not visited[node]:
            if is_cyclic_util(node, visited, rec_stack):
                return True
    return False

def get_fibonacci(n):
    """
    Computes the nth Fibonacci number using a recursive approach.

    Parameters:
    n (int): The position in the Fibonacci sequence (0-indexed).

    Returns:
    int: The nth Fibonacci number.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return get_fibonacci(n - 1) + get_fibonacci(n - 2)

import collections

def flatten_json(y):
    """Flatten a nested dictionary or list into a single-level dictionary with concatenated keys.

    Args:
        y (dict or list): The JSON object to flatten.

    Returns:
        dict: A dictionary with flattened keys.
    """
    out = {}

    def flatten(x, name=''):
        if isinstance(x, dict):
            for a in x:
                flatten(x[a], name + a + '.')
        elif isinstance(x, list):
            for i, a in enumerate(x):
                flatten(a, name + str(i) + '.')
        else:
            out[name[:-1]] = x

    flatten(y)
    return out

