def binary_search(events, end_time):
    left, right = 0, len(events) - 1
    while left <= right:
        mid = (left + right) // 2
        if events[mid][1] <= end_time:
            left = mid + 1
        else:
            right = mid - 1
    return right

def max_value_events(events):
    events.sort(key=lambda x: x[1])
    dp = [0] * len(events)

    def find_max_value(index):
        if index == -1:
            return 0
        if dp[index] > 0:
            return dp[index]

        current_value = events[index][2]
        previous_index = binary_search(events, events[index][0])
        if previous_index != -1:
            current_value += find_max_value(previous_index)

        dp[index] = max(find_max_value(index - 1), current_value)
        return dp[index]

    return find_max_value(len(events) - 1)

