def maxDistToClosest(nums):
    """
    Returns the maximum distance to the nearest person for any empty seat.
    """
    max_dist = 0
    last_person = -1
    n = len(nums)

    for i in range(n):
        if nums[i] == 1:
            if last_person == -1:
                # All seats from the start are empty
                max_dist = max(max_dist, i)
            else:
                # The distance to the nearest person for seats between two people
                max_dist = max(max_dist, (i - last_person) // 2)
            last_person = i

    # All seats from the last person to the end are empty
    if nums[-1] == 0:
        max_dist = max(max_dist, n - last_person - 1)

    return max_dist

def average_of_k_highest(grades, k):
    """
    Returns the average of the k highest grades.
    If k is greater than or equal to the number of students, returns the average of all grades.
    """
    if not grades:
        return 0

    grades_sorted = sorted(grades, reverse=True)
    if k >= len(grades_sorted):
        return sum(grades_sorted) / len(grades_sorted)

    return sum(grades_sorted[:k]) / k

