def can_partition_k_subsets(nums, k):
    def can_partition_from(start_index, k, current_sum, target, visited):
        if k == 1:
            return True
        if current_sum == target:
            return can_partition_from(0, k - 1, 0, target, visited)

        for i in range(start_index, len(nums)):
            if not visited[i] and current_sum + nums[i] <= target:
                visited[i] = True
                if can_partition_from(i + 1, k, current_sum + nums[i], target, visited):
                    return True
                visited[i] = False
        return False

    total_sum = sum(nums)
    if total_sum % k != 0:
        return False

    target = total_sum // k
    visited = [False] * len(nums)
    nums.sort(reverse=True)

    return can_partition_from(0, k, 0, target, visited)

