def minHeightBillboard(heights):
    """
    This function returns the minimum height of a billboard of width 2 placed across any two consecutive buildings.
    """
    if not heights or len(heights) < 2:
        return 0  # If there are fewer than 2 buildings, no billboard can be placed.

    min_height = float('inf')

    for i in range(len(heights) - 1):
        # The height of the billboard will be determined by the taller of the two buildings.
        max_height = max(heights[i], heights[i+1])
        if max_height < min_height:
            min_height = max_height

    return min_height

