from collections import Counter

def concatenate_unique_first_chars(words):
    """
    Concatenates words ensuring no two adjacent words share the same first character.
    Returns the final string or an empty string if such a concatenation is not possible.
    """
    if not words:
        return ""

    # Helper function to check if the given words can be arranged
    def can_arrange(words):
        count = Counter(words)
        sorted_by_frequency = sorted(count.items(), key=lambda x: -x[1])
        most_common_char, max_count = sorted_by_frequency[0]
        return max_count <= (len(words) + 1) // 2

    # Check if it's possible to arrange 
    if not can_arrange([word[0] for word in words]):
        return ""

    words.sort(key=lambda word: words.count(word), reverse=True)

    result = []
    prev_word = None

    while words:
        for i, word in enumerate(words):
            if not result or result[-1][0] != word[0]:
                result.append(word)
                prev_word = words.pop(i)
                break
        else:
            return ""

    return ''.join(result)

def normalize_memo(memo):
    data = {}
    for part in memo.split(';'):
        part = part.strip()
        if not part:
            continue
        key, value = part.split('=', 1)
        data[key.strip()] = value.strip()
    return [f'{key}={data[key]}' for key in sorted(data)]

def parse_city_map(s):
    result = {}
    for part in s.split(';'):
        part = part.strip()
        if not part:
            continue
        city, district = part.split('=', 1)
        result[city.strip()] = district.strip()
    return result

def shortest_cover_window_for_pair(messages):
    distinct = sorted(set(messages))
    if len(distinct) < 2:
        return ["", "", 0]

    positions = {}
    for idx, msg in enumerate(messages):
        positions.setdefault(msg, []).append(idx)

    best = ("", "", float('inf'))
    for i in range(len(distinct)):
        for j in range(i + 1, len(distinct)):
            a, b = distinct[i], distinct[j]
            pa, pb = positions[a], positions[b]
            x = y = 0
            local_best = float('inf')
            while x < len(pa) and y < len(pb):
                left = min(pa[x], pb[y])
                right = max(pa[x], pb[y])
                local_best = min(local_best, right - left + 1)
                if pa[x] < pb[y]:
                    x += 1
                else:
                    y += 1
            cand = (a, b, local_best)
            if local_best < best[2] or (local_best == best[2] and (a, b) < (best[0], best[1])):
                best = cand

    return [best[0], best[1], best[2]]

def count_subarrays_with_k_distinct(k, events):
    if k <= 0 or not events:
        return 0

    def at_most(m):
        freq = {}
        left = 0
        total = 0
        distinct = 0
        for right, x in enumerate(events):
            if freq.get(x, 0) == 0:
                distinct += 1
            freq[x] = freq.get(x, 0) + 1
            while distinct > m:
                y = events[left]
                freq[y] -= 1
                if freq[y] == 0:
                    distinct -= 1
                    del freq[y]
                left += 1
            total += right - left + 1
        return total

    return at_most(k) - at_most(k - 1)

def factorial(n):
    """
    Calculate the factorial of a non-negative integer n using recursion.

    Parameters:
    n (int): A non-negative integer whose factorial is to be computed.

    Returns:
    int: The factorial of the integer n.
    """
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def filter_primes(numbers):
    """Return a list of prime numbers from the input list."""
    return [num for num in numbers if is_prime(num)]

