class TextEditor:
    def __init__(self):
        self.text = []
        self.cursor = 0

    def insert(self, text):
        """Inserts the string `text` at the current cursor position."""
        self.text = self.text[:self.cursor] + list(text) + self.text[self.cursor:]
        self.cursor += len(text)

    def delete(self):
        """Deletes the character to the left of the cursor, if possible."""
        if self.cursor > 0:
            self.text = self.text[:self.cursor-1] + self.text[self.cursor:]
            self.cursor -= 1

    def left(self):
        """Moves the cursor one position to the left, if possible."""
        if self.cursor > 0:
            self.cursor -= 1

    def right(self):
        """Moves the cursor one position to the right, if possible."""
        if self.cursor < len(self.text):
            self.cursor += 1

    def print_text(self):
        """Prints the current state of the text."""
        print(''.join(self.text))

def process_operations(operations):
    """Processes a list of operations on a TextEditor instance."""
    editor = TextEditor()
    for operation in operations:
        if operation.startswith('insert '):
            _, text = operation.split(' ', 1)
            editor.insert(text)
        elif operation == 'delete':
            editor.delete()
        elif operation == 'left':
            editor.left()
        elif operation == 'right':
            editor.right()
        elif operation == 'print':
            editor.print_text()

