def find_two_sum(numbers, target):
    """
    Finds two distinct indices in the list 'numbers' such that the elements at these indices add up to 'target'.

    :param numbers: List of integers.
    :param target: Integer representing the target sum.
    :return: Tuple of two indices if a pair is found, otherwise None.
    """
    seen = {}
    for i, number in enumerate(numbers):
        complement = target - number
        if complement in seen:
            return (seen[complement], i)
        seen[number] = i
    return None

def evaluate_expression(expression):
    """
    Evaluates a mathematical expression given as a string.

    :param expression: A string representing the mathematical expression.
    :return: An integer representing the result of the evaluated expression.
    """
    def perform_operation(op, b, a):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a // b

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        values.append(perform_operation(operator, right, left))

    def greater_precedence(op1, op2):
        return precedence(op1) > precedence(op2)

    operators = []
    values = []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        if expression[i] == '(':
            operators.append(expression[i])
        elif expression[i].isdigit():
            val = 0
            while i < len(expression) and expression[i].isdigit():
                val = (val * 10) + int(expression[i])
                i += 1
            values.append(val)
            i -= 1
        elif expression[i] == ')':
            while operators and operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()
        else:
            while (operators and operators[-1] != '(' and
                   greater_precedence(operators[-1], expression[i])):
                apply_operator(operators, values)
            operators.append(expression[i])
        i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

