def addBoldTag(s, dict):
    """
    Adds bold tags to substrings of s that exist in dict.
    Handles overlapping substrings by merging them.
    """
    n = len(s)
    mask = [False] * n

    # Mark the substrings that need to be bolded
    for word in dict:
        start = s.find(word)
        while start != -1:
            for i in range(start, start + len(word)):
                mask[i] = True
            start = s.find(word, start + 1)

    # Build the resulting string with bold tags
    result = []
    i = 0
    while i < n:
        if mask[i]:
            result.append('<b>')
            while i < n and mask[i]:
                result.append(s[i])
                i += 1
            result.append('</b>')
        else:
            result.append(s[i])
            i += 1

    return ''.join(result)

def longest_special_substring(s):
    """
    Finds the length of the longest special substring containing equal number of 'a's and 'b's.
    """
    max_length = 0
    balance = 0
    balance_map = {0: -1}

    for i, char in enumerate(s):
        if char == 'a':
            balance += 1
        else:
            balance -= 1

        if balance in balance_map:
            max_length = max(max_length, i - balance_map[balance])
        else:
            balance_map[balance] = i

    return max_length

