def process_commands(commands):
    """
    Processes a list of commands to modify a string, initially empty,
    and returns the final string after executing all the commands.

    Args:
    commands (list): List of strings representing commands.

    Returns:
    str: The resulting string after processing all commands.
    """
    result = []
    history = []

    for command in commands:
        if command.startswith('add_'):
            char = command[4:]
            if len(char) == 1:
                result.append(char)
                history.append(('add', char))
        elif command == 'remove':
            if result:
                last_char = result.pop()
                history.append(('remove', last_char))
        elif command == 'undo':
            if history:
                last_command = history.pop()
                action, char = last_command
                if action == 'add':
                    result.pop()
                elif action == 'remove':
                    result.append(char)

    return ''.join(result)

