def count_color_paths(root):
    def dfs(node, has_red, has_blue):
        if node is None:
            return 0, 0

        new_has_red = has_red or node.color == 'red'
        new_has_blue = has_blue or node.color == 'blue'

        if node.left is None and node.right is None:
            return (1 if new_has_red else 0, 1 if new_has_blue else 0)

        left_red_paths, left_blue_paths = dfs(node.left, new_has_red, new_has_blue)
        right_red_paths, right_blue_paths = dfs(node.right, new_has_red, new_has_blue)

        return (left_red_paths + right_red_paths, left_blue_paths + right_blue_paths)

    return dfs(root, False, False)

