class BinaryTree:
    def __init__(self, values):
        self.root = self._build_tree(values)

    def _build_tree(self, values):
        if not values:
            return None
        nodes = [None if val is None else TreeNode(val) for val in values]
        kids = nodes[::-1]
        root = kids.pop()
        for node in nodes:
            if node:
                if kids: 
                    node.left = kids.pop()
                if kids: 
                    node.right = kids.pop()
        return root

    def findDeepestNode(self):
        if not self.root:
            return None
        q = [self.root]
        node = None
        while q:
            node = q.pop(0)
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)
        return node.val if node else None

    def getLeafCount(self):
        if not self.root:
            return 0
        leaf_count = 0
        q = [self.root]
        while q:
            node = q.pop(0)
            if not node.left and not node.right:
                leaf_count += 1
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)
        return leaf_count

    def isBalanced(self):
        def check(root):
            if not root:
                return 0, True
            left_height, left_balanced = check(root.left)
            right_height, right_balanced = check(root.right)
            balanced = left_balanced and right_balanced and abs(left_height - right_height) <= 1
            return max(left_height, right_height) + 1, balanced

        _, balanced = check(self.root)
        return balanced

import json

class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

class Codec:

    def serialize(self, root):
        """Encodes a tree to a single string.
        """
        def rserialize(node):
            if node is None:
                return ["null"]
            return [str(node.val)] + rserialize(node.left) + rserialize(node.right)

        return json.dumps(rserialize(root))

    def deserialize(self, data):
        """Decodes your encoded data to tree.
        """
        def rdeserialize(data_list):
            if data_list[0] == "null":
                data_list.pop(0)
                return None

            root = TreeNode(int(data_list.pop(0)))
            root.left = rdeserialize(data_list)
            root.right = rdeserialize(data_list)
            return root

        data_list = json.loads(data)
        return rdeserialize(data_list)

