def find_top_manager(n, reportPairs):
    if n == 0:
        return -1

    # a set of all employee IDs
    all_employees = set(range(1, n+1))

    # a set of employees who report to someone
    has_manager = set(e for _, e in reportPairs)

    # find the set of employees who do not report to anyone
    top_managers = all_employees - has_manager

    if not top_managers:
        return -1

    # return the smallest ID among the top managers
    return min(top_managers)

import heapq

class MedianFinder:
    def __init__(self):
        self.small = []  # max heap (inverted min heap)
        self.large = []  # min heap

    def addNum(self, num: int) -> None:
        heapq.heappush(self.small, -num)

        if (self.small and self.large and (-self.small[0] > self.large[0])):
            heapq.heappush(self.large, -heapq.heappop(self.small))

        if len(self.small) > len(self.large) + 1:
            heapq.heappush(self.large, -heapq.heappop(self.small))

        if len(self.large) > len(self.small):
            heapq.heappush(self.small, -heapq.heappop(self.large))

    def findMedian(self) -> float:
        if len(self.small) > len(self.large):
            return float(-self.small[0])
        return (-self.small[0] + self.large[0]) / 2.0

