def find_largest_prime_factor(n):
    """
    Returns the largest prime factor of a given integer n.

    :param n: Integer, the number to find the largest prime factor of.
    :return: Integer, the largest prime factor of n.
    """
    def is_prime(num):
        """
        Checks if a number is prime.

        :param num: Integer, the number to check for primality.
        :return: Boolean, True if num is prime, False otherwise.
        """
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    largest_prime = -1
    while n % 2 == 0:
        largest_prime = 2
        n //= 2

    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            if is_prime(i):
                largest_prime = i
            n //= i

    if n > 2 and is_prime(n):
        largest_prime = n

    return largest_prime

def find_largest_prime(n):
    """
    Finds the largest prime number less than or equal to n using the Sieve of Eratosthenes algorithm.

    Parameters:
    n (int): The upper limit to search for the largest prime number.

    Returns:
    int: The largest prime number less than or equal to n, or None if no prime number exists.
    """
    if n < 2:
        return None

    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False

    p = 2
    while p * p <= n:
        if sieve[p]:
            for i in range(p * p, n + 1, p):
                sieve[i] = False
        p += 1

    for prime in range(n, 1, -1):
        if sieve[prime]:
            return prime

