import xml.etree.ElementTree as ET

def dict_to_xml(tag, d):
    '''Recursively convert a dictionary to an XML element.'''
    elem = ET.Element(tag)
    for key, val in d.items():
        if isinstance(val, dict):
            child_elem = dict_to_xml(key, val)
            elem.append(child_elem)
        elif isinstance(val, list):
            for item in val:
                if isinstance(item, dict):
                    child_elem = dict_to_xml(key, item)
                    elem.append(child_elem)
                else:
                    child_elem = ET.Element(key)
                    child_elem.text = str(item)
                    elem.append(child_elem)
        else:
            child_elem = ET.Element(key)
            child_elem.text = str(val)
            elem.append(child_elem)
    return elem

def convert_to_xml(data_dict):
    '''Convert a nested dictionary to an XML string with root element <root>.'''
    root_elem = dict_to_xml('root', data_dict)
    return ET.tostring(root_elem, encoding='unicode')

def generate_report(employee_data):
    """
    Generates a formatted report from a list of employee records.

    Parameters:
    employee_data (list of dict): A list where each dictionary contains employee data with keys 'name', 'position', 'department', and 'salary'.

    Returns:
    str: A formatted report string containing the total number of employees, average salary per department, and the highest and lowest salaries in the company.
    """
    total_employees = len(employee_data)
    total_salaries = {}
    count_employees = {}
    highest_salary = None
    lowest_salary = None

    for emp in employee_data:
        dept = emp['department']
        salary = emp['salary']

        if dept not in total_salaries:
            total_salaries[dept] = 0
            count_employees[dept] = 0

        total_salaries[dept] += salary
        count_employees[dept] += 1

        if highest_salary is None or salary > highest_salary:
            highest_salary = salary

        if lowest_salary is None or salary < lowest_salary:
            lowest_salary = salary

    average_salary = {dept: total_salaries[dept] / count_employees[dept] for dept in total_salaries}

    report = [
        f"Total number of employees: {total_employees}",
        f"Average salary per department: {average_salary}",
        f"Highest salary in the company: {highest_salary}",
        f"Lowest salary in the company: {lowest_salary}"
    ]

    return "\n".join(report)

def flatten_json(json_obj, parent_key='', sep='.'):
    """
    Flattens a nested JSON object into a single-level dictionary with dot-separated keys.

    :param json_obj: The JSON object to flatten.
    :param parent_key: The base key string for recursion (used internally).
    :param sep: The separator between keys.
    :return: A flattened dictionary.
    """
    items = {}
    for k, v in json_obj.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.update(flatten_json(v, new_key, sep=sep))
        else:
            items[new_key] = v
    return items

