def find_magic_index(nums):
    """
    Finds the index of the first magic index in an array, if it exists.
    """
    def binary_search(left, right):
        if left > right:
            return -1
        mid = (left + right) // 2
        if nums[mid] == mid:
            # Check if there is an earlier magic index on the left side
            left_magic = binary_search(left, mid - 1)
            return mid if left_magic == -1 else left_magic
        elif nums[mid] > mid:
            return binary_search(left, mid - 1)
        else:
            return binary_search(mid + 1, right)

    return binary_search(0, len(nums) - 1)

