def min_time_to_complete_tasks(arr, k):
    """
    Calculate the minimum possible time required to complete all tasks
    with k workers available.

    :param arr: List[int] - List of times for each task
    :param k: int - Number of workers
    :return: int - Minimum possible time to complete all tasks
    """
    left, right = max(arr), sum(arr)

    def can_complete_in_time(mid):
        """Helper function to check if tasks can be done in `mid` time with `k` workers"""
        current_time = 0
        workers_needed = 1

        for time in arr:
            if current_time + time > mid:
                workers_needed += 1
                current_time = time
                if workers_needed > k:
                    return False
            else:
                current_time += time
        return True

    while left < right:
        mid = (left + right) // 2
        if can_complete_in_time(mid):
            right = mid
        else:
            left = mid + 1

    return left

