def count_subarrays_with_sum_k(arr, k):
    """
    Returns the number of subarrays in arr whose elements have a sum exactly equal to k.
    """
    count = 0
    current_sum = 0
    sum_dict = {0: 1}  # Sum dictionary to store the frequency of prefix sums.

    for num in arr:
        current_sum += num
        if (current_sum - k) in sum_dict:
            count += sum_dict[current_sum - k]
        if current_sum in sum_dict:
            sum_dict[current_sum] += 1
        else:
            sum_dict[current_sum] = 1

    return count

from collections import deque

def shortest_bridge(grid):
    def bfs_find_island(x, y):
        queue = deque([(x, y)])
        island = set([(x, y)])
        grid[x][y] = -1
        while queue:
            cx, cy = queue.popleft()
            for nx, ny in [(cx-1, cy), (cx+1, cy), (cx, cy-1), (cx, cy+1)]:
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == 1:
                    queue.append((nx, ny))
                    grid[nx][ny] = -1
                    island.add((nx, ny))
        return island

    def bfs_expand_island():
        steps = 0
        while queue:
            for _ in range(len(queue)):
                cx, cy = queue.popleft()
                for nx, ny in [(cx-1, cy), (cx+1, cy), (cx, cy-1), (cx, cy+1)]:
                    if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
                        if grid[nx][ny] == 1:
                            return steps
                        if grid[nx][ny] == 0:
                            grid[nx][ny] = -1
                            queue.append((nx, ny))
            steps += 1
        return -1

    # Find the first island
    found_island = False
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                island1 = bfs_find_island(i, j)
                found_island = True
                break
        if found_island:
            break

    # Expand the first island to find the shortest bridge to the second island
    queue = deque(island1)
    return bfs_expand_island()

