reference_solution:
def highest_peak(heights):
    from collections import deque

    m, n = len(heights), len(heights[0])
    queue = deque()
    visited = [[False] * n for _ in range(m)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Initialize the queue with all border cells
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                queue.append((i, j))
                visited[i][j] = True

    # Process the queue and perform BFS to find the highest peak
    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                heights[nx][ny] = max(heights[nx][ny], heights[x][y])
                visited[nx][ny] = True
                queue.append((nx, ny))

    return max(max(row) for row in heights)

