def max_good_subsequence_length(nums, k):
    from itertools import combinations

    def is_good_subsequence(subsequence):
        return sum(subsequence) % k == 0

    max_length = 0
    n = len(nums)

    for length in range(1, n + 1):
        for subseq in combinations(nums, length):
            if is_good_subsequence(subseq):
                max_length = max(max_length, length)

    return max_length

def checkPossibility(nums):
    """
    Returns True if it is possible to make the array non-decreasing with at most one modification,
    otherwise returns False.
    """
    n = len(nums)
    count = 0

    for i in range(1, n):
        if nums[i] < nums[i - 1]:
            if count == 1:
                return False
            count += 1
            if i == 1 or nums[i - 2] <= nums[i]:
                nums[i - 1] = nums[i]
            else:
                nums[i] = nums[i - 1]

    return True

def find_primes_in_range(start, end):
    """
    Finds all prime numbers in the inclusive range [start, end].

    Parameters:
    start (int): The starting integer of the range.
    end (int): The ending integer of the range.

    Returns:
    list: A list of prime numbers within the specified range.
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = []
    for num in range(start, end + 1):
        if is_prime(num):
            primes.append(num)
    return primes

