def maxProfitAssignment(difficulty, profit, worker):
    jobs = sorted(zip(difficulty, profit))
    worker.sort()
    max_profit = i = best = 0
    for ability in worker:
        while i < len(jobs) and ability >= jobs[i][0]:
            best = max(best, jobs[i][1])
            i += 1
        max_profit += best
    return max_profit

