def shift_string(word, k):
    """
    Shifts the characters in the word k times.
    """
    shifted = []
    for char in word:
        shifted.append(chr((ord(char) - ord('a') + k) % 26 + ord('a')))
    return ''.join(shifted)

def shift_strings(words, k):
    """
    Returns an array of strings where each string is shifted from 1 to k times.
    """
    result = []
    for word in words:
        for shift in range(1, k + 1):
            result.append(shift_string(word, shift))
    return result

from datetime import datetime

def clean_transactions(transactions):
    """
    Cleans a list of financial transactions by converting amounts to floats, standardizing dates,
    trimming descriptions and categories, converting categories to lowercase, and removing duplicates.

    :param transactions: List of dictionaries, each representing a financial transaction.
    :return: List of cleaned-up dictionaries.
    """
    cleaned_transactions = []
    seen_ids = set()

    for transaction in transactions:
        if transaction['id'] in seen_ids:
            continue
        seen_ids.add(transaction['id'])

        amount = transaction['amount'].replace('$', '').replace(',', '')
        try:
            amount = float(amount)
        except ValueError:
            amount = None

        try:
            date = datetime.strptime(transaction['date'], '%Y-%m-%d').strftime('%Y-%m-%d')
        except ValueError:
            try:
                date = datetime.strptime(transaction['date'], '%d/%m/%Y').strftime('%Y-%m-%d')
            except ValueError:
                date = None

        description = transaction['description'].strip()
        category = transaction['category'].strip().lower()

        cleaned_transactions.append({
            'id': transaction['id'],
            'amount': amount,
            'date': date,
            'description': description,
            'category': category,
        })

    return cleaned_transactions

class TreeNode:
