        self.val = val
        self.left = left
        self.right = right

def find_lowest_common_ancestor(root, value1, value2):
    """
    Finds the lowest common ancestor of two nodes in a binary search tree.

    :param root: TreeNode, the root of the BST.
    :param value1: int, the value of the first node.
    :param value2: int, the value of the second node.
    :return: int or None, the value of the LCA or None if either value does not exist.
    """
    if not root:
        return None

    # Ensure value1 is less than or equal to value2
    if value1 > value2:
        value1, value2 = value2, value1

    current = root
    while current:
        if current.val < value1:
            current = current.right
        elif current.val > value2:
            current = current.left
        else:
            return current.val

    return None

def longest_common_subsequence(str1, str2):
    """
    Returns the length of the longest common subsequence between two strings.

    :param str1: First input string
    :param str2: Second input string
    :return: Length of the longest common subsequence
    """
    m, n = len(str1), len(str2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

def find_pair(nums, target):
    """
    Finds and returns a pair of integers from the list whose sum equals the target.

    :param nums: List[int] - A list of integers.
    :param target: int - The target sum.
    :return: Tuple[int, int] or None - A tuple of two integers whose sum is target, or None if no such pair exists.
    """
    num_map = {}
    for num in nums:
        complement = target - num
        if complement in num_map:
            return (complement, num)
        num_map[num] = True
    return None

def find_duplicate_emails(email_list):
    """
    Identifies duplicate email addresses in a list, ignoring case sensitivity.

    Parameters:
    email_list (list of str): A list of email addresses.

    Returns:
    dict: A dictionary with duplicate email addresses (in lowercase) as keys and lists of indices as values.
    """
    email_index_map = {}
    duplicates = {}

    for index, email in enumerate(email_list):
        normalized_email = email.lower()

        if normalized_email in email_index_map:
            if normalized_email not in duplicates:
                duplicates[normalized_email] = [email_index_map[normalized_email]]
            duplicates[normalized_email].append(index)
        else:
            email_index_map[normalized_email] = index

    return duplicates

