        self.val = val
        self.left = left
        self.right = right

def closest_value(root, target):
    """
    Finds the value in the BST that is closest to the target.

    :param root: TreeNode, the root of the binary search tree.
    :param target: float, the target value.
    :return: int, the value in the BST closest to the target.
    """
    closest = root.val
    while root:
        if abs(target - root.val) < abs(target - closest):
            closest = root.val
        if target < root.val:
            root = root.left
        else:
            root = root.right
    return closest

def character_frequency(s):
    """
    Computes the frequency of each character in the given string.

    Parameters:
    s (str): The input string.

    Returns:
    dict: A dictionary with characters as keys and their frequencies as values.
    """
    frequency_dict = {}
    for char in s:
        if char in frequency_dict:
            frequency_dict[char] += 1
        else:
            frequency_dict[char] = 1
    return frequency_dict

