def is_valid_bst(root):
    """
    Determines if a binary tree is a valid binary search tree (BST).

    :param root: TreeNode, the root of the binary tree
    :return: bool, True if the tree is a valid BST, False otherwise
    """
    def validate(node, low=-float('inf'), high=float('inf')):
        if not node:
            return True
        if node.val <= low or node.val >= high:
            return False
        return (validate(node.right, node.val, high) and
                validate(node.left, low, node.val))

    return validate(root)

def shift_string(s):
    """
    Shifts each alphabetic character in the string two positions forward in the alphabet.
    Characters at the end of the alphabet wrap around to the beginning.
    Non-alphabetic characters remain unchanged.

    :param s: Input string consisting of alphabetic and possibly non-alphabetic characters.
    :return: A new string with each alphabetic character shifted two positions forward.
    """
    def shift_char(c):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + 2) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + 2) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c) for c in s)

