def longest_increasing_subsequence(nums):
    """
    Finds the longest increasing subsequence in a list of integers.

    :param nums: List of integers.
    :return: List of integers representing the longest increasing subsequence.
    """
    if not nums:
        return []

    tails = [0] * len(nums)
    size = 0

    for num in nums:
        left, right = 0, size
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        tails[left] = num
        if left == size:
            size += 1

    lis = []
    current_tail = tails[size - 1]
    for i in range(len(nums) - 1, -1, -1):
        if nums[i] == current_tail:
            lis.append(nums[i])
            if size > 1:
                current_tail = tails[size - 2]
            size -= 1

    return lis[::-1]

