from itertools import permutations

def num_topological_sorts(n, edges):
    """
    Returns the number of possible topological sorts for a given DAG.

    Parameters:
    n (int): Number of nodes in the DAG.
    edges (list): List of directed edges represented as pairs [u, v].

    Returns:
    int: Number of possible topological sorts.
    """
    def is_topological(permutation, edges):
        index = {node: i for i, node in enumerate(permutation)}
        for u, v in edges:
            if index[u] > index[v]:
                return False
        return True

    nodes = [i for i in range(n)]
    count = 0

    for perm in permutations(nodes):
        if is_topological(perm, edges):
            count += 1

    return count

