def palindromic_substring_indices(s):
    """
    Returns the starting indices of all palindromic substrings of s.
    """
    n = len(s)
    result = []

    def is_palindrome(substr):
        return substr == substr[::-1]

    for i in range(n):
        for j in range(i+1, n+1):
            if is_palindrome(s[i:j]):
                result.append(i)
    return sorted(set(result))

def shortest_bridge(grid):
    from collections import deque

    def get_neighbors(x, y, n):
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                yield nx, ny

    def bfs(queue, visited, mark_lookup):
        while queue:
            x, y = queue.popleft()
            for nx, ny in get_neighbors(x, y, n):
                if (nx, ny) not in visited and grid[nx][ny] == 1:
                    queue.append((nx, ny))
                    visited.add((nx, ny))
                    mark_lookup.append((nx, ny))

    # Find and mark all cells of the first island.
    n = len(grid)
    first_island = []
    visited = set()

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                first_island.append((i, j))
                visited.add((i, j))
                break
        if first_island:
            break

    queue = deque(first_island)
    bfs(queue, visited, first_island)

    # Use BFS to find the shortest path from the first island to the second island.
    queue = deque([(x, y, 0) for x, y in first_island])
    visited = set(first_island)

    while queue:
        x, y, dist = queue.popleft()
        for nx, ny in get_neighbors(x, y, n):
            if (nx, ny) not in visited:
                if grid[nx][ny] == 1:
                    return dist
                queue.append((nx, ny, dist + 1))
                visited.add((nx, ny))

    return -1

