from collections import Counter

def shortest_completing_word(licensePlate, words):
    def letter_count(word):
        return Counter([char.lower() for char in word if char.isalpha()])

    plate_count = letter_count(licensePlate)
    shortest_word = None

    for word in words:
        word_count = letter_count(word)
        if all(word_count[char] >= plate_count[char] for char in plate_count):
            if shortest_word is None or len(word) < len(shortest_word):
                shortest_word = word

    return shortest_word

class Node:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """
        Inserts a new key into the BST.
        """
        if self.root is None:
            self.root = Node(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        if key < node.val:
            if node.left is None:
                node.left = Node(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = Node(key)
            else:
                self._insert(node.right, key)

    def delete(self, key):
        """
        Deletes a key from the BST.
        """
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.val = self._min_value_node(node.right).val
            node.right = self._delete(node.right, node.val)

        return node

    def find_min(self):
        """
        Returns the minimum key in the BST.
        """
        return self._min_value_node(self.root).val if self.root else None

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

