def removeKchars(s, k):
    """
    Returns the lexicographically smallest string by removing exactly k characters from the input string 's'.
    """
    stack = []
    for char in s:
        while k > 0 and stack and stack[-1] > char:
            stack.pop()
            k -= 1
        stack.append(char)

    # If k characters are not removed
    while k > 0:
        stack.pop()
        k -= 1

    return "".join(stack)

class Library:
    def __init__(self):
        self.books = []  # List of dictionaries: {'title': ..., 'author': ..., 'available': ...}

    def add_book(self, title, author):
        """
        Adds a new book to the library.

        :param title: The title of the book.
        :param author: The author of the book.
        """
        new_book = {'title': title, 'author': author, 'available': True}
        self.books.append(new_book)
        print(f"Book '{title}' by {author} has been added to the library.")

    def remove_book(self, title, author):
        """
        Removes a book from the library.

        :param title: The title of the book.
        :param author: The author of the book.
        """
        for book in self.books:
            if book['title'] == title and book['author'] == author:
                self.books.remove(book)
                print(f"Book '{title}' by {author} has been removed from the library.")
                return
        print(f"Book '{title}' by {author} not found in the library.")

    def borrow_book(self, title, author):
        """
        Borrows a book from the library if it is available.

        :param title: The title of the book.
        :param author: The author of the book.
        """
        for book in self.books:
            if book['title'] == title and book['author'] == author:
                if book['available']:
                    book['available'] = False
                    print(f"Book '{title}' by {author} is borrowed successfully.")
                    return
                else:
                    print(f"Book '{title}' by {author} is currently not available.")
                    return
        print(f"Book '{title}' by {author} not found in the library.")

    def return_book(self, title, author):
        """
        Returns a book to the library.

        :param title: The title of the book.
        :param author: The author of the book.
        """
        for book in self.books:
            if book['title'] == title and book['author'] == author:
                if not book['available']:
                    book['available'] = True
                    print(f"Book '{title}' by {author} has been returned successfully.")
                    return
                else:
                    print(f"Error: Book '{title}' by {author} cannot be returned as it was not borrowed.")
                    return
        print(f"Book '{title}' by {author} not found in the library.")

    def list_available_books(self):
        """
        Lists all available books in the library.
        """
        available_books = [book for book in self.books if book['available']]
        if available_books:
            print("Available books:")
            for book in available_books:
                print(f"Title: '{book['title']}', Author: {book['author']}")
        else:
            print("No books are available in the library at the moment.")

