import heapq

def shortest_path(n, edges, start, end):
    """
    Computes the shortest transmission time from start to end in a weighted, directed graph.

    :param n: Number of nodes (servers)
    :param edges: List of edges where each edge is represented as [ui, vi, weighti]
    :param start: Starting node
    :param end: Destination node
    :return: Shortest transmission time from start to end, or -1 if no such path exists
    """
    graph = {i: [] for i in range(n)}
    for ui, vi, weight in edges:
        graph[ui].append((vi, weight))

    pq = [(0, start)]  # Priority queue to hold (current_time, current_node)
    dist = {i: float('inf') for i in range(n)}
    dist[start] = 0

    while pq:
        current_time, current_node = heapq.heappop(pq)

        if current_node == end:
            return current_time

        if current_time > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            time = current_time + weight
            if time < dist[neighbor]:
                dist[neighbor] = time
                heapq.heappush(pq, (time, neighbor))

    return -1

def evaluate_expression(expression):
    """
    Evaluates a mathematical expression containing +, -, *, and / (integer division).

    Parameters:
    expression (str): The expression string to be evaluated.

    Returns:
    int: The result of the evaluated expression.
    """
    # Initialize the variables
    stack = []
    current_number = 0
    operation = '+'

    # Iterate through each character in the string
    for i, char in enumerate(expression):
        if char.isdigit():
            current_number = current_number * 10 + int(char)

        if char in "+-*/" or i == len(expression) - 1:
            if operation == '+':
                stack.append(current_number)
            elif operation == '-':
                stack.append(-current_number)
            elif operation == '*':
                stack.append(stack.pop() * current_number)
            elif operation == '/':
                stack.append(int(stack.pop() / current_number))

            operation = char
            current_number = 0

    # Sum up values in the stack
    return sum(stack)

