from collections import Counter
from heapq import heapify, heappop, heappush

def can_rearrange_string(s: str, k: int) -> bool:
    if k == 0:
        return True

    counter = Counter(s)
    max_heap = [(-freq, char) for char, freq in counter.items()]
    heapify(max_heap)

    queue = []
    result = []

    while max_heap:
        freq, char = heappop(max_heap)
        result.append(char)
        queue.append((freq + 1, char)) # decrement the frequency

        if len(queue) >= k:
            popped = queue.pop(0)
            if popped[0] < 0:
                heappush(max_heap, popped)

    return len(result) == len(s)

