def min_max_diff(arr, k):
    '''
    This function finds the minimum possible value of the maximum difference between k subarrays formed
    by partitioning the original array arr.
    '''
    def feasible(mid, k):
        current_min = current_max = arr[0]
        partitions = 1

        for num in arr[1:]:
            current_min = min(current_min, num)
            current_max = max(current_max, num)

            if current_max - current_min > mid:
                partitions += 1
                current_min = current_max = num

        return partitions <= k

    low, high = 0, max(arr) - min(arr)

    while low < high:
        mid = (low + high) // 2
        if feasible(mid, k):
            high = mid
        else:
            low = mid + 1

    return low

def longest_bounded_range_subarray(tasks, limit):
    best = 0
    left = 0
    for right in range(len(tasks)):
        while left <= right:
            window = tasks[left:right + 1]
            if max(window) - min(window) <= limit:
                break
            left += 1
        if right - left + 1 > best:
            best = right - left + 1
    return best

