def min_batches(orders, k):
    from collections import defaultdict
    total = defaultdict(int)
    for product_id, quantity in orders:
        total[product_id] += quantity

    batches = 0
    for quantity_sum in total.values():
        batches += (quantity_sum + k - 1) // k
    return batches

def max_frequency_in_recent_window(names, k):
    from collections import defaultdict
    count = defaultdict(int)
    result = []
    current_max = 0

    for i, name in enumerate(names):
        count[name] += 1
        if count[name] > current_max:
            current_max = count[name]

        if i >= k:
            old = names[i - k]
            count[old] -= 1
            if count[old] == 0:
                del count[old]

        if i >= k - 1:
            current_max = max(count.values())
        else:
            current_max = max(count.values())
        result.append(current_max)

    return result

