def evaluate_expression(expression):
    """
    Evaluates a mathematical expression given as a string and returns the result.

    :param expression: A string representing the mathematical expression.
    :return: An integer representing the result of the evaluated expression.
    """
    operators = {
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
        '*': lambda x, y: x * y,
        '/': lambda x, y: x / y
    }

    def shunting_yard(expression):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        output_queue = []
        operator_stack = []
        tokens = []
        i = 0
        while i < len(expression):
            if expression[i].isdigit():
                num = []
                while i < len(expression) and expression[i].isdigit():
                    num.append(expression[i])
                    i += 1
                tokens.append(''.join(num))
                i -= 1
            elif expression[i] in operators or expression[i] == '(' or expression[i] == ')':
                tokens.append(expression[i])
            i += 1

        for token in tokens:
            if token.isdigit():
                output_queue.append(int(token))
            elif token in operators:
                while (operator_stack and operator_stack[-1] in operators and
                       precedence[operator_stack[-1]] >= precedence[token]):
                    output_queue.append(operator_stack.pop())
                operator_stack.append(token)
            elif token == '(':
                operator_stack.append(token)
            elif token == ')':
                while operator_stack and operator_stack[-1] != '(':
                    output_queue.append(operator_stack.pop())
                operator_stack.pop()

        while operator_stack:
            output_queue.append(operator_stack.pop())

        return output_queue

    def evaluate_postfix(postfix):
        stack = []
        for token in postfix:
            if token in operators:
                b = stack.pop()
                a = stack.pop()
                result = operators[token](a, b)
                stack.append(result)
            else:
                stack.append(token)
        return stack[0]

    postfix = shunting_yard(expression)
    result = evaluate_postfix(postfix)
    return result

