def find_prime_pairs(numbers):
    """Find pairs of prime numbers whose sum is also prime."""
    primes = [num for num in numbers if is_prime(num)]
    prime_pairs = []
    length = len(primes)

    for i in range(length):
        for j in range(i + 1, length):
            if is_prime(primes[i] + primes[j]):
                prime_pairs.append((primes[i], primes[j]))

    return prime_pairs

