def word_frequency(strings):
    """
    Computes the frequency of each unique word in a list of strings.

    Parameters:
    strings (list of str): A list of strings, where each string consists of words separated by spaces.

    Returns:
    dict: A dictionary with words as keys and their frequencies as values.
    """
    frequency = {}
    for string in strings:
        words = string.split()
        for word in words:
            if word in frequency:
                frequency[word] += 1
            else:
                frequency[word] = 1
    return frequency

