def max_product(nums):
    """
    Computes the maximum product of any two distinct integers in the list.
    If the list contains fewer than two integers, returns None.

    :param nums: List of integers
    :return: Maximum product of two distinct integers or None
    """
    if len(nums) < 2:
        return None

    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    for num in nums:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    return max(max1 * max2, min1 * min2)

def group_strings_by_length(strings):
    """
    Organizes a list of strings into a dictionary where keys are the lengths of the strings,
    and values are lists of strings of that length, sorted alphabetically.

    :param strings: List of strings to be organized.
    :return: Dictionary with string lengths as keys and sorted lists of strings as values.
    """
    length_dict = {}
    for string in strings:
        length = len(string)
        if length not in length_dict:
            length_dict[length] = []
        length_dict[length].append(string)

    for length in length_dict:
        length_dict[length].sort()

    return length_dict

def calculate_sentiment_scores(product_reviews):
    """
    Calculate the average sentiment score for each product based on a list of reviews.

    :param product_reviews: A dictionary with product names as keys and lists of reviews as values.
    :return: A dictionary with product names as keys and average sentiment scores as values.
    """
    positive_words = ['good', 'great', 'excellent', 'fantastic', 'perfect', 'amazing']
    negative_words = ['bad', 'terrible', 'poor', 'worst', 'awful', 'horrible']

    sentiment_scores = {}

    for product, reviews in product_reviews.items():
        total_score = 0

        for review in reviews:
            words = review.lower().split()
            review_score = 0

            for word in words:
                if word in positive_words:
                    review_score += 1
                elif word in negative_words:
                    review_score -= 1

            total_score += review_score

        average_score = total_score / len(reviews) if reviews else 0
        sentiment_scores[product] = average_score

    return sentiment_scores

