def longest_consecutive(root):
    """
    Returns the length of the longest path in the binary tree such that the node values
    form a sequence where each node's value is exactly one more than its parent.
    """
    def helper(node, parent_val, length):
        if not node:
            return length
        if node.val == parent_val + 1:
            length += 1
        else:
            length = 1
        left_length = helper(node.left, node.val, length)
        right_length = helper(node.right, node.val, length)
        return max(length, left_length, right_length)

    if not root:
        return 0
    return max(helper(root, root.val - 1, 0), helper(root.left, root.val, 0), helper(root.right, root.val, 0))

