def findKthSmallest(nums, k):
    """
    Returns the k-th smallest element in the list nums.
    """
    def quickselect(l, r, k):
        """
        Helper function to perform the quickselect algorithm.
        """
        if l == r:
            return nums[l]

        pivot_index = partition(l, r)

        if k == pivot_index:
            return nums[k]
        elif k < pivot_index:
            return quickselect(l, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, r, k)

    def partition(l, r):
        """
        Helper function to partition the array into elements less than
        and greater than the pivot.
        """
        pivot = nums[r]
        i = l
        for j in range(l, r):
            if nums[j] < pivot:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
        nums[i], nums[r] = nums[r], nums[i]
        return i

    return quickselect(0, len(nums) - 1, k - 1)

