def find_cut_index(arr):
    def is_valid(arr):
        for i in range(1, len(arr)):
            if arr[i] <= arr[i-1]:
                return False
        return True

    n = len(arr)
    if is_valid(arr):
        return -1

    for i in range(n):
        if is_valid(arr[:i] + arr[i+1:]):
            return i

    return -1

