def min_remove_to_make_valid(s):
    """
    Remove the minimum number of parentheses to make the string valid.
    """
    stack = []
    to_remove = set()

    # First pass: Identify positions of invalid parentheses
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if not stack:
                to_remove.add(i)
            else:
                stack.pop()

    # Add remaining unmatched '(' to the set to be removed
    to_remove = to_remove.union(set(stack))

    # Build the result string excluding characters marked for removal
    result = ''.join([char for i, char in enumerate(s) if i not in to_remove])

    return result

def min_window(s, t):
    def find_sub_sequence(s, t):
        i, j = 0, 0
        while i < len(s) and j < len(t):
            if s[i] == t[j]:
                j += 1
            i += 1
        return j == len(t)

    if not t:
        return ""

    min_len = float("inf")
    result = ""

    for i in range(len(s)):
        if s[i] == t[0]:
            for j in range(i, len(s)):
                if find_sub_sequence(s[i:j+1], t):
                    if j - i + 1 < min_len:
                        min_len = j - i + 1
                        result = s[i:j+1]
                    break

    return result

def has_path_with_target_sum(matrix, target):
    """
    Determines if there is a path from the top-left to bottom-right of the matrix
    such that the sum of the values along the path is exactly target. The path
    can only move either down or right at any point in time.

    :param matrix: List[List[int]], the m x n matrix with non-negative integers.
    :param target: int, the target sum to find.
    :return: bool, True if such a path exists, otherwise False.
    """
    if not matrix or not matrix[0]:
        return False

    m, n = len(matrix), len(matrix[0])
    memo = {}

    def dfs(x, y, current_sum):
        if (x, y, current_sum) in memo:
            return memo[(x, y, current_sum)]

        if x >= m or y >= n:
            return False

        current_sum += matrix[x][y]

        if current_sum > target:
            return False

        if x == m - 1 and y == n - 1:
            return current_sum == target

        down = dfs(x + 1, y, current_sum)
        right = dfs(x, y + 1, current_sum)

        memo[(x, y, current_sum)] = down or right
        return memo[(x, y, current_sum)]

    return dfs(0, 0, 0)

def can_split_into_k_palindromes(s, k):
    def is_palindrome(sub):
        return sub == sub[::-1]

    n = len(s)

    # If k is greater than the length of s, we cannot split it into k non-empty substrings
    if k > n:
        return False

    dp = [[False] * n for _ in range(n)]

    # Fill dp array: dp[i][j] will be True if s[i:j+1] is a palindrome
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if length == 1:
                dp[i][j] = True
            elif length == 2:
                dp[i][j] = (s[i] == s[j])
            else:
                dp[i][j] = (s[i] == s[j]) and dp[i + 1][j - 1]

    def can_partition(start, k):
        if k == 0:
            return start == n
        if k < 0:
            return False

        for end in range(start, n):
            if dp[start][end]:
                if can_partition(end + 1, k - 1):
                    return True

        return False

    return can_partition(0, k)

