class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

def build_tree(relations):
    if not relations:
        return None

    nodes = {}
    for parent, child, is_left in relations:
        if parent not in nodes:
            nodes[parent] = TreeNode(parent)
        if child not in nodes:
            nodes[child] = TreeNode(child)
        if is_left:
            nodes[parent].left = nodes[child]
        else:
            nodes[parent].right = nodes[child]

    # The root is the only node without a parent
    child_nodes = {child for _, child, _ in relations}
    all_nodes = set(nodes.keys())
    root_val = (all_nodes - child_nodes).pop()

    return nodes[root_val]

def is_balanced_binary_tree(relations):
    def check_balance(node):
        if not node:
            return 0, True

        left_height, is_left_balanced = check_balance(node.left)
        right_height, is_right_balanced = check_balance(node.right)

        height = max(left_height, right_height) + 1
        is_balanced = is_left_balanced and is_right_balanced and abs(left_height - right_height) <= 1

        return height, is_balanced

    root = build_tree(relations)
    _, is_balanced = check_balance(root)
    return is_balanced

def min_click_balance_gap(clicks):
    n = len(clicks)
    best = n
    for i in range(n):
        ones = zeros = 0
        for j in range(i, n):
            if clicks[j] == 1:
                ones += 1
            else:
                zeros += 1
            best = min(best, abs(ones - zeros))
    return best if n > 0 else 0

def min_drone_capacity(distances, k):
    arr = sorted(distances)
    lo, hi = max(arr), sum(arr)
    ans = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        bins = 1
        cur = 0
        for x in arr:
            if cur + x <= mid:
                cur += x
            else:
                bins += 1
                cur = x
        if bins <= k:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

def evaluate_postfix(expression: str) -> int:
    """
    Evaluates a given postfix expression and returns the result.

    :param expression: A string representing a mathematical expression in postfix notation.
    :return: The result of the postfix expression evaluation.
    :raises ValueError: If the expression contains invalid tokens or is malformed.
    """
    stack = []
    operators = {'+', '-', '*', '/'}

    tokens = expression.split()

    for token in tokens:
        if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            stack.append(int(token))
        elif token in operators:
            operand2 = stack.pop()
            operand1 = stack.pop()

            if token == '+':
                result = operand1 + operand2
            elif token == '-':
                result = operand1 - operand2
            elif token == '*':
                result = operand1 * operand2
            elif token == '/':
                result = operand1 // operand2

            stack.append(result)
        else:
            raise ValueError(f"Invalid token: {token}")

    if len(stack) != 1:
        raise ValueError("The postfix expression is invalid")

    return stack.pop()

def divide_numbers(a, b):
    """
    Divides two numbers and handles potential exceptions.

    Parameters:
    a (int, float): The numerator.
    b (int, float): The denominator.

    Returns:
    float: The result of the division if successful.
    str: An error message if an exception occurs.
    """
    try:
        result = a / b
    except ZeroDivisionError:
        return "Error: Division by zero is not allowed."
    except TypeError:
        return "Error: Invalid input type. Please provide numbers."
    except Exception as e:
        return f"An unexpected error occurred: {str(e)}"
    else:
        return result

def classify_characters(s):
    """
    Classifies characters in the input string into letters, digits, whitespace, and others.

    Parameters:
    s (str): The input string to classify.

    Returns:
    dict: A dictionary with counts of each character category.
    """
    classification = {"letters": 0, "digits": 0, "whitespace": 0, "others": 0}

    for char in s:
        if char.isalpha():
            classification["letters"] += 1
        elif char.isdigit():
            classification["digits"] += 1
        elif char.isspace():
            classification["whitespace"] += 1
        else:
            classification["others"] += 1

    return classification

