class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """Inserts a new node with the given value into the BST."""
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert_recursively(node.left, value)
        else:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_recursively(node.right, value)

    def delete(self, value):
        """Deletes the node with the given value from the BST."""
        self.root = self._delete_recursively(self.root, value)

    def _delete_recursively(self, node, value):
        if node is None:
            return node
        if value < node.value:
            node.left = self._delete_recursively(node.left, value)
        elif value > node.value:
            node.right = self._delete_recursively(node.right, value)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            temp = self._min_value_node(node.right)
            node.value = temp.value
            node.right = self._delete_recursively(node.right, temp.value)

        return node

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def inorder_traversal(self):
        """Returns a list of values obtained by performing an in-order traversal of the BST."""
        return self._inorder_traversal_recursively(self.root)

    def _inorder_traversal_recursively(self, node):
        res = []
        if node:
            res = self._inorder_traversal_recursively(node.left)
            res.append(node.value)
            res = res + self._inorder_traversal_recursively(node.right)
        return res

    def preorder_traversal(self):
        """Returns a list of values obtained by performing a pre-order traversal of the BST."""
        return self._preorder_traversal_recursively(self.root)

    def _preorder_traversal_recursively(self, node):
        res = []
        if node:
            res.append(node.value)
            res = res + self._preorder_traversal_recursively(node.left)
            res = res + self._preorder_traversal_recursively(node.right)
        return res

    def postorder_traversal(self):
        """Returns a list of values obtained by performing a post-order traversal of the BST."""
        return self._postorder_traversal_recursively(self.root)

    def _postorder_traversal_recursively(self, node):
        res = []
        if node:
            res = self._postorder_traversal_recursively(node.left)
            res = res + self._postorder_traversal_recursively(node.right)
            res.append(node.value)
        return res

