import random

def partition(arr, low, high):
    """
    Partitions the array around a pivot element and returns the index of the pivot.
    """
    pivot_index = random.randint(low, high)
    pivot_value = arr[pivot_index]
    arr[pivot_index], arr[high] = arr[high], arr[pivot_index]
    store_index = low

    for i in range(low, high):
        if arr[i] < pivot_value:
            arr[i], arr[store_index] = arr[store_index], arr[i]
            store_index += 1

    arr[store_index], arr[high] = arr[high], arr[store_index]
    return store_index

def quickselect(arr, low, high, k):
    """
    Selects the k-th smallest element in the array using the Quickselect algorithm.
    """
    if low == high:
        return arr[low]

    pivot_index = partition(arr, low, high)

    if k == pivot_index:
        return arr[k]
    elif k < pivot_index:
        return quickselect(arr, low, pivot_index - 1, k)
    else:
        return quickselect(arr, pivot_index + 1, high, k)

def find_kth_smallest(arr, k):
    """
    Finds the k-th smallest element in the array.
    """
    if k < 1 or k > len(arr):
        raise ValueError("k is out of the bounds of the array")
    return quickselect(arr, 0, len(arr) - 1, k - 1)

import queue

class QueueManager:
    def __init__(self):
        """Initialize the QueueManager with an empty dictionary to store queues."""
        self.queues = {}

    def add_queue(self, name):
        """Add a new queue with the given name. Raise KeyError if the queue already exists."""
        if name in self.queues:
            raise KeyError(f"Queue with name '{name}' already exists.")
        self.queues[name] = queue.Queue()

    def remove_queue(self, name):
        """Remove the queue with the given name. Raise KeyError if no such queue exists."""
        if name not in self.queues:
            raise KeyError(f"No queue with name '{name}' found.")
        del self.queues[name]

    def enqueue(self, name, item):
        """Enqueue an item to the queue with the given name. Raise KeyError if no such queue exists."""
        if name not in self.queues:
            raise KeyError(f"No queue with name '{name}' found.")
        self.queues[name].put(item)

    def dequeue(self, name):
        """Dequeue an item from the queue with the given name. Raise KeyError if no such queue exists.
        Raise IndexError if the queue is empty."""
        if name not in self.queues:
            raise KeyError(f"No queue with name '{name}' found.")
        if self.queues[name].empty():
            raise IndexError(f"Queue with name '{name}' is empty.")
        return self.queues[name].get()

    def is_empty(self, name):
        """Check if the queue with the given name is empty. Raise KeyError if no such queue exists."""
        if name not in self.queues:
            raise KeyError(f"No queue with name '{name}' found.")
        return self.queues[name].empty()

    def get_size(self, name):
        """Get the size of the queue with the given name. Raise KeyError if no such queue exists."""
        if name not in self.queues:
            raise KeyError(f"No queue with name '{name}' found.")
        return self.queues[name].qsize()

class DictionarySearch:
    def __init__(self, words):
        """
        Initializes the DictionarySearch with a list of words.

        :param words: List of words to be stored in the dictionary.
        """
        self.dictionary = {word: True for word in words}

    def find_longest_prefix(self, prefix):
        """
        Finds the longest word in the dictionary that starts with the given prefix.

        :param prefix: The prefix to search for in the dictionary.
        :return: The longest word starting with the prefix, or None if no such word exists.
        """
        longest_key = None
        for key in self.dictionary:
            if key.startswith(prefix):
                if longest_key is None or len(key) > len(longest_key):
                    longest_key = key
        return longest_key

