        if not node:
            return curr_length

        if node.char >= prev_char:
            left_length = dfs(node.left, node.char, curr_length + 1)
            right_length = dfs(node.right, node.char, curr_length + 1)
            return max(left_length, right_length)
        else:
            return curr_length

