from collections import defaultdict, deque

def sum_at_max_depth(n, edges):
    if not edges:
        return n  # Only one node in the tree

    # Building graph using adjacency list representation
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Breadth-First Search (BFS) to find nodes at the maximum depth
    visited = set()
    queue = deque([(1, 0)])  # Starting BFS from node 1 at depth 0
    max_depth = 0
    max_depth_nodes = []

    while queue:
        node, depth = queue.popleft()

        if depth > max_depth:
            max_depth = depth
            max_depth_nodes = [node]
        elif depth == max_depth:
            max_depth_nodes.append(node)

        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append((neighbor, depth + 1))

    return sum(max_depth_nodes)

