def magicalString(N):
    if N == 0:
        return 0
    if N <= 3:
        return 1

    s = [1, 2, 2]
    head = 2
    tail = 3
    num = 1
    while tail < N:
        for _ in range(s[head]):
            s.append(num)
            tail += 1
            if tail >= N:
                break
        num ^= 3  # switch between 1 and 2. 1^3=2, 2^3=1
        head += 1

    return s[:N].count(1)

