def can_cross(nums):
    """
    Determines if the frog can reach the last stone in the river.

    Parameters:
    nums (List[int]): List representing the positions of stones along a river.

    Returns:
    bool: True if frog can reach last stone, False otherwise.
    """
    if not nums:
        return False

    stone_positions = {x: set() for x in nums}
    stone_positions[0].add(0)

    for stone in nums:
        for jump in stone_positions[stone]:
            for step in range(jump - 1, jump + 2):
                if step > 0 and (stone + step) in stone_positions:
                    stone_positions[stone + step].add(step)

    return len(stone_positions[nums[-1]]) > 0

