def longest_substring_with_at_least_k_repeats(s, k):
    def helper(s, k, start, end):
        if end - start < k:
            return 0

        count = [0] * 26
        for i in range(start, end):
            count[ord(s[i]) - ord('a')] += 1

        for mid in range(start, end):
            if count[ord(s[mid]) - ord('a')] >= k:
                continue

            mid_next = mid + 1
            while mid_next < end and count[ord(s[mid_next]) - ord('a')] < k:
                mid_next += 1

            return max(helper(s, k, start, mid), helper(s, k, mid_next, end))

        return end - start

    return helper(s, k, 0, len(s))

