def four_sum(nums, target):
    """
    Given a list of integers `nums`, return a list of all 0-indexed quadruplets [a, b, c, d] such that
    nums[a] + nums[b] + nums[c] + nums[d] == target. The solution should not contain duplicate quadruplets.
    """
    nums.sort()
    quadruplets = set()
    n = len(nums)

    for i in range(n):
        for j in range(i + 1, n):
            left, right = j + 1, n - 1
            while left < right:
                total = nums[i] + nums[j] + nums[left] + nums[right]
                if total == target:
                    quadruplets.add((nums[i], nums[j], nums[left], nums[right]))
                    left += 1
                    right -= 1
                elif total < target:
                    left += 1
                else:
                    right -= 1

    return [list(quad) for quad in quadruplets]

class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Inserts a new key into the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        """Helper method to insert a key recursively."""
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert(node.right, key)

    def delete(self, key):
        """Deletes a key from the BST."""
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        """Helper method to delete a key recursively."""
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.val = self._min_value_node(node.right).val
            node.right = self._delete(node.right, node.val)

        return node

    def _min_value_node(self, node):
        """Helper method to find the node with the minimum key value."""
        current = node
        while current.left is not None:
            current = current.left
        return current

    def inorder_traversal(self, node, traversal_order):
        """Helper method for in-order traversal."""
        if node is not None:
            self.inorder_traversal(node.left, traversal_order)
            traversal_order.append(node.val)
            self.inorder_traversal(node.right, traversal_order)

    def get_inorder(self):
        """Returns a list of keys in the BST in in-order traversal order."""
        traversal_order = []
        self.inorder_traversal(self.root, traversal_order)
        return traversal_order

def min_sessions(tasks, sessionTime):
    def backtrack(i, current_sessions):
        if i == len(tasks):
            return len(current_sessions)
        min_sessions_needed = float('inf')
        for j in range(len(current_sessions)):
            if current_sessions[j] + tasks[i] <= sessionTime:
                current_sessions[j] += tasks[i]
                min_sessions_needed = min(min_sessions_needed, backtrack(i + 1, current_sessions))
                current_sessions[j] -= tasks[i]
        current_sessions.append(tasks[i])
        min_sessions_needed = min(min_sessions_needed, backtrack(i + 1, current_sessions))
        current_sessions.pop()
        return min_sessions_needed

    tasks.sort(reverse=True)
    return backtrack(0, [])

def count_distinct_in_subarrays(arr, k):
    """
    Returns the number of distinct integers in all the subarrays of length k of `arr`.
    """
    if k == 0 or k > len(arr):
        return []

    result = []
    window = {}
    distinct_count = 0

    for i in range(len(arr)):
        if arr[i] in window:
            window[arr[i]] += 1
        else:
            window[arr[i]] = 1
            distinct_count += 1

        if i >= k:
            if window[arr[i - k]] == 1:
                del window[arr[i - k]]
                distinct_count -= 1
            else:
                window[arr[i - k]] -= 1

        if i >= k - 1:
            result.append(distinct_count)

    return result

import heapq

class WaterVolumeCalculator:
    def __init__(self, heightMap):
        self.heightMap = heightMap
        self.m = len(heightMap)
        self.n = len(heightMap[0]) if self.m > 0 else 0

    def trapWater(self):
        if not self.heightMap or not self.m or not self.n:
            return 0

        visited = [[False for _ in range(self.n)] for _ in range(self.m)]
        minHeap = []
        waterTrapped = 0
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        # Add all the boundary cells to the heap and mark them as visited
        for i in range(self.m):
            for j in range(self.n):
                if i == 0 or i == self.m - 1 or j == 0 or j == self.n - 1:
                    heapq.heappush(minHeap, (self.heightMap[i][j], i, j))
                    visited[i][j] = True

        while minHeap:
            height, x, y = heapq.heappop(minHeap)
            for d in directions:
                nx, ny = x + d[0], y + d[1]
                if 0 <= nx < self.m and 0 <= ny < self.n and not visited[nx][ny]:
                    visited[nx][ny] = True
                    waterTrapped += max(0, height - self.heightMap[nx][ny])
                    heapq.heappush(minHeap, (max(height, self.heightMap[nx][ny]), nx, ny))

        return waterTrapped

    def updateHeight(self, row, col, newHeight):
        self.heightMap[row][col] = newHeight

