def calculate_factorial(n):
    """
    Calculate the factorial of a given non-negative integer n using recursion.

    Parameters:
    n (int): The non-negative integer for which the factorial is to be calculated.

    Returns:
    int or str: The factorial of n if n is non-negative, otherwise an error message.
    """
    if n < 0:
        return "Input is invalid. Please enter a non-negative integer."
    elif n == 0 or n == 1:
        return 1
    else:
        return n * calculate_factorial(n - 1)

class Queue:
    def __init__(self):
        self.items = []

    def enqueue(self, item):
        """Adds an item to the end of the queue."""
        self.items.append(item)

    def dequeue(self):
        """Removes and returns the item from the front of the queue. Returns None if the queue is empty."""
        if self.is_empty():
            return None
        return self.items.pop(0)

    def is_empty(self):
        """Returns True if the queue is empty, False otherwise."""
        return len(self.items) == 0

    def size(self):
        """Returns the number of items in the queue."""
        return len(self.items)

