def min_length_subarray_at_least(actions, threshold):
    prefix = [0]
    for x in actions:
        prefix.append(prefix[-1] + x)

    from collections import deque
    dq = deque()
    ans = len(actions) + 1

    for i, cur in enumerate(prefix):
        while dq and cur - prefix[dq[0]] >= threshold:
            ans = min(ans, i - dq.popleft())
        while dq and prefix[dq[-1]] >= cur:
            dq.pop()
        dq.append(i)

    return -1 if ans == len(actions) + 1 else ans

def count_subarrays_with_exactly_m_distinct(scans, m):
    from collections import defaultdict

    def at_most(k):
        freq = defaultdict(int)
        left = 0
        total = 0
        distinct = 0
        for right, val in enumerate(scans):
            if freq[val] == 0:
                distinct += 1
            freq[val] += 1
            while distinct > k:
                freq[scans[left]] -= 1
                if freq[scans[left]] == 0:
                    distinct -= 1
                left += 1
            total += right - left + 1
        return total

    return at_most(m) - at_most(m - 1)

def min_checkout_cost(prices: list[int]) -> int:
    n = len(prices)
    if n == 0:
        return 0
    if n == 1:
        return prices[0]

    dp0, dp1 = 0, prices[0]
    for i in range(2, n + 1):
        dp0, dp1 = dp1, min(dp1 + prices[i - 1], dp0 + prices[i - 2] + prices[i - 1])
    return dp1

def max_profit(prices: list[int]) -> int:
    """
    Calculate the maximum profit from a single buy and sell transaction.

    :param prices: List of integers representing daily stock prices.
    :return: Maximum possible profit. Returns 0 if no profit can be made.
    """
    if not prices or len(prices) < 2:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

