    """
    Validates whether the given IP address is a valid IPv4 address.

    :param ip_address: A string representing the IP address to be validated.
    :return: True if the IP address is valid, False otherwise.
    """
    parts = ip_address.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit() or not 0 <= int(part) <= 255:
            return False
        if part != str(int(part)):
            return False
    return True

def extract_values(json_data, key):
    """
    Extracts all values associated with a specified key from a nested JSON object.

    :param json_data: A dictionary representing the JSON object.
    :param key: The key to search for in the JSON object.
    :return: A list of all values associated with the specified key.
    """
    values = []

    def _extract_values(obj, k):
        if isinstance(obj, dict):
            for o_key, o_value in obj.items():
                if o_key == k:
                    values.append(o_value)
                _extract_values(o_value, k)
        elif isinstance(obj, list):
            for item in obj:
                _extract_values(item, k)

    _extract_values(json_data, key)
    return values

def flatten_json(y):
    """
    Flattens a nested JSON object into a single dictionary with keys representing the nested path.

    :param y: The JSON object to flatten.
    :return: A dictionary with flattened keys and values.
    """
    out = {}

    def flatten(x, name=''):
        if isinstance(x, dict):
            for a in x:
                flatten(x[a], name + a + '.')
        elif isinstance(x, list):
            for i, a in enumerate(x):
                flatten(a, name + str(i) + '.')
        else:
            out[name[:-1]] = x

    flatten(y)
    return out

