def get_nested_keys(d, target, path=None):
    """
    Retrieves all the keys from a nested dictionary `d` that match the `target` key.

    Parameters:
    - d (dict): The nested dictionary to search.
    - target (str): The target key to find.
    - path (list, optional): The current path in the dictionary. Defaults to None.

    Returns:
    - list of tuples: Each tuple represents the path to the `target` key in the dictionary.
    """
    if path is None:
        path = []

    keys = []

    if isinstance(d, dict):
        for k, v in d.items():
            current_path = path + [k]
            if k == target:
                keys.append(tuple(current_path))
            keys.extend(get_nested_keys(v, target, current_path))
    elif isinstance(d, list):
        for i, item in enumerate(d):
            keys.extend(get_nested_keys(item, target, path + [i]))

    return keys

