def count_rectangles(grid):
    """
    Function to count the number of distinct rectangles that can be formed using only fertile cells.

    Parameters:
    grid - list of list of int: The n x m grid representing the farm

    Returns:
    int - Number of distinct rectangles that can be formed using only fertile cells
    """
    if not grid:
        return 0

    n, m = len(grid), len(grid[0])
    count = 0

    for top in range(n):
        for bottom in range(top, n):
            consecutive_ones = 0
            for col in range(m):
                if all(grid[row][col] == 1 for row in range(top, bottom + 1)):
                    consecutive_ones += 1
                    count += consecutive_ones
                else:
                    consecutive_ones = 0

    return count

from collections import deque

def word_transformation_length(start, end, word_list):
    """
    Returns the minimum number of transformations needed to convert start to end,
    where each transformation changes exactly one character at a time and each
    intermediate word must exist in word_list.
    """
    if end not in word_list:
        return -1

    word_list = set(word_list)
    queue = deque([(start, 1)])

    while queue:
        current_word, level = queue.popleft()

        if current_word == end:
            return level

        for i in range(len(current_word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                intermediate_word = current_word[:i] + c + current_word[i+1:]

                if intermediate_word in word_list:
                    queue.append((intermediate_word, level + 1))
                    word_list.remove(intermediate_word)  # mark as visited

    return -1

def min_characters_to_form(words, target):
    def can_form_with_fewest_removals(word, target):
        it = iter(target)
        return all(char in it for char in word)

    best_index = -1
    min_removals = float('inf')

    for i, word in enumerate(words):
        if can_form_with_fewest_removals(word, target):
            current_removals = len(target) - len(word)
            if current_removals < min_removals:
                min_removals = current_removals
                best_index = i

    return best_index

