def sqrt(x):
    """
    Returns the square root of x. If x is not a perfect square, returns the floor value of the square root.

    :param x: int
    :return: int
    """
    if x < 0:
        raise ValueError("Input should be a non-negative integer")

    if x == 0 or x == 1:
        return x

    low, high = 0, x
    result = 0

    while low <= high:
        mid = (low + high) // 2
        mid_squared = mid * mid

        if mid_squared == x:
            return mid
        elif mid_squared < x:
            low = mid + 1
            result = mid
        else:
            high = mid - 1

    return result

