def longest_consecutive_subarray(arr):
    """
    Returns the length of the longest contiguous subarray that can be rearranged
    to form a sequence of consecutive integers.
    """
    if not arr:
        return 0

    max_len = 1
    for i in range(len(arr)):
        min_val = max_val = arr[i]
        unique_elements = {arr[i]}

        for j in range(i + 1, len(arr)):
            if arr[j] in unique_elements:
                break
            unique_elements.add(arr[j])
            min_val = min(min_val, arr[j])
            max_val = max(max_val, arr[j])

            if max_val - min_val == j - i:
                max_len = max(max_len, j - i + 1)

    return max_len

class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def findGCA(root, p, q):
    if not root or root == p or root == q:
        return root

    left = findGCA(root.left, p, q)
    right = findGCA(root.right, p, q)

    if left and right:
        return root

    return left if left else right

