def three_sum(arr, target):
    """
    Returns true if there are three integers in the array `arr` that add up to `target`,
    otherwise returns false.
    """
    arr.sort()
    n = len(arr)

    for i in range(n - 2):
        if i > 0 and arr[i] == arr[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            curr_sum = arr[i] + arr[left] + arr[right]
            if curr_sum == target:
                return True
            elif curr_sum < target:
                left += 1
            else:
                right -= 1
    return False

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def reverse_k_group(head, k):
    def reverse_linked_list(start, end):
        prev, curr = end, start
        while curr != end:
            curr.next, prev, curr = prev, curr, curr.next
        return prev

    dummy = ListNode(0)
    dummy.next = head
    group_prev = dummy

    while True:
        kth = group_prev
        for _ in range(k):
            kth = kth.next
            if not kth:
                return dummy.next

        group_next = kth.next
        reverse_linked_list(group_prev.next, group_next)

        new_group_prev = group_prev.next
        group_prev.next.next = group_next
        group_prev.next = kth
        group_prev = new_group_prev

    return dummy.next

def catalan_number(n):
    """
    Returns the nth Catalan number.
    """
    if n == 0:
        return 1
    catalan = [0] * (n + 1)
    catalan[0] = 1
    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - 1 - j]
    return catalan[n]

def num_valid_parentheses(n):
    """
    Returns the number of valid parentheses strings of length 2n.
    """
    return catalan_number(n)

