def ways_to_write_sum(n, x):
    """
    Returns the number of ways to write n as the sum of exactly x positive integers.
    Each unique permutation is considered.
    """
    # Use dynamic programming to solve this problem
    if x == 0 and n > 0:
        return 0
    if x == 0 and n == 0:
        return 1
    if n == 0 and x > 0:
        return 0

    dp = [[0 for _ in range(n + 1)] for _ in range(x + 1)]
    dp[0][0] = 1  # There's exactly one way to sum to 0 using 0 elements.

    for i in range(1, x + 1):
        for j in range(1, n + 1):
            for k in range(1, j + 1):
                dp[i][j] += dp[i - 1][j - k]

    return dp[x][n]

