def num_islands_after_conversions(grid, positions):
    rows, cols = len(grid), len(grid[0])

    # Function to perform DFS to mark visited islands
    def dfs(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] != 1:
            return
        grid[r][c] = '#'
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    # Convert given positions from 0 to 1
    for x, y in positions:
        grid[x][y] = 1

    num_islands = 0

    # Count the number of islands
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                dfs(r, c)
                num_islands += 1

    return num_islands

