def unique_participants(participants):
    seen = set()
    result = []
    for name in participants.split(';'):
        lowered = name.strip().lower()
        if lowered and lowered not in seen:
            seen.add(lowered)
            result.append(lowered)
    return ','.join(result)

def min_capacity_for_exact_window_length(weights, m):
    n = len(weights)
    if m <= 0 or m > n:
        return -1

    prefix = [0]
    for w in weights:
        prefix.append(prefix[-1] + w)

    def max_len(cap):
        total = 0
        left = 0
        best = 0
        for right, w in enumerate(weights):
            total += w
            while total > cap and left <= right:
                total -= weights[left]
                left += 1
            best = max(best, right - left + 1)
        return best

    lo, hi = 0, prefix[-1]
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if max_len(mid) >= m:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1

    return ans

def unique_substrings(s):
    """
    Generate all unique substrings of the input string s and return them in alphabetical order.

    :param s: Input string
    :return: List of unique substrings sorted alphabetically
    """
    substrings = set()
    n = len(s)

    for i in range(n):
