def word_count(input_string: str) -> dict:
    """
    Returns a dictionary with each unique word from the input string as keys
    and their counts as values. The comparison is case-insensitive.

    :param input_string: A string containing words separated by spaces.
    :return: A dictionary with words as keys and their counts as values.
    """
    input_string = input_string.lower()
    words = input_string.split()
    word_counts = {}

    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1

    return word_counts

def flatten_dict(d, parent_key='', sep='.'):
    """
    Flattens a nested dictionary into a single-level dictionary with concatenated keys.

    :param d: The dictionary to flatten.
    :param parent_key: The base key string for recursion (used internally).
    :param sep: The separator to use between keys.
    :return: A flattened dictionary.
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

