def generate_primes(n):
    """
    Generate a list of the first n prime numbers.

    Parameters:
    n (int): The number of prime numbers to generate.

    Returns:
    list: A list containing the first n prime numbers.
    """
    def is_prime(num, primes):
        if num < 2:
            return False
        for prime in primes:
            if prime * prime > num:
                break
            if num % prime == 0:
                return False
        return True

    primes = []
    candidate = 2
    while len(primes) < n:
        if is_prime(candidate, primes):
            primes.append(candidate)
        candidate += 1
    return primes

