class Graph:
    def __init__(self):
        """Initialize an empty graph with an adjacency list."""
        self.adjacency_list = {}

    def add_node(self, node):
        """Add a new node to the graph if it doesn't already exist."""
        if node not in self.adjacency_list:
            self.adjacency_list[node] = []

    def add_edge(self, node1, node2):
        """Add an undirected edge between node1 and node2 if both nodes exist."""
        if node1 in self.adjacency_list and node2 in self.adjacency_list:
            self.adjacency_list[node1].append(node2)
            self.adjacency_list[node2].append(node1)
        else:
            raise ValueError("One or both of the nodes do not exist in the graph.")

    def dfs(self, start_node):
        """Perform DFS traversal starting from the specified node and return the set of visited nodes."""
        if start_node not in self.adjacency_list:
            raise ValueError("Start node does not exist in the graph.")

        visited = set()
        self._dfs_helper(start_node, visited)
        return visited

    def _dfs_helper(self, current_node, visited):
        """Recursive helper function for DFS traversal."""
        visited.add(current_node)
        for neighbor in self.adjacency_list[current_node]:
            if neighbor not in visited:
                self._dfs_helper(neighbor, visited)

