def parse_config(json_config):
    """
    Parses a JSON configuration object and returns a dictionary containing only the keys
    'hostname', 'interfaces', and 'routing'. If any of these keys are missing, they default
    to an empty list.

    :param json_config: A dictionary representing the JSON configuration of a network device.
    :return: A dictionary with keys 'hostname', 'interfaces', and 'routing'.
    """
    return {
        'hostname': json_config.get('hostname'),
        'interfaces': json_config.get('interfaces', []),
        'routing': json_config.get('routing', [])
    }

