class Matrix:
    def __init__(self, data):
        """
        Initialize the matrix with given data.

        :param data: List of lists representing the matrix elements.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def __str__(self):
        """
        Return a string representation of the matrix.

        :return: String representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

    def __add__(self, other):
        """
        Add two matrices.

        :param other: Another Matrix object.
        :return: New Matrix object representing the sum.
        :raises ValueError: If matrices are not of the same size.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same size to add")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __sub__(self, other):
        """
        Subtract two matrices.

        :param other: Another Matrix object.
        :return: New Matrix object representing the difference.
        :raises ValueError: If matrices are not of the same size.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same size to subtract")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __mul__(self, other):
        """
        Multiply two matrices.

        :param other: Another Matrix object.
        :return: New Matrix object representing the product.
        :raises ValueError: If number of columns in the first matrix is not equal to the number of rows in the second.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to the number of rows in the second")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def transpose(self):
        """
        Transpose the matrix.

        :return: New Matrix object representing the transpose.
        """
        result = [
            [self.data[j][i] for j in range(self.rows)]
            for i in range(self.cols)
        ]
        return Matrix(result)

    def determinant(self):
        """
        Calculate the determinant of the matrix.

        :return: Determinant of the matrix.
        :raises ValueError: If the matrix is not square.
        """
        if self.rows != self.cols:
            raise ValueError("Only square matrices have determinants")

        def det(matrix):
            if len(matrix) == 1:
                return matrix[0][0]
            elif len(matrix) == 2:
                return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
            else:
                det_sum = 0
                for c in range(len(matrix)):
                    sub_matrix = [
                        row[:c] + row[c+1:] for row in matrix[1:]
                    ]
                    sign = (-1) ** c
                    sub_det = det(sub_matrix)
                    det_sum += sign * matrix[0][c] * sub_det
                return det_sum

        return det(self.data)

