def sort_by_vowels(strings):
    """
    Sorts a list of strings based on the number of vowels in each string.
    If two strings have the same number of vowels, they are sorted lexicographically.

    :param strings: List of strings to be sorted.
    :return: Sorted list of strings.
    """
