def find_min_diff_indices(nums, target):
    """
    Returns two distinct indices i and j (1-based) such that nums[i-1] * nums[j-1] equals target
    and the difference |i - j| is minimized. If no such pair exists, returns [-1, -1].
    """
    min_diff = float('inf')
    result = [-1, -1]
    n = len(nums)

    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] * nums[j] == target:
                diff = abs(i - j)
                if diff < min_diff:
                    min_diff = diff
                    result = [i + 1, j + 1]
                elif diff == min_diff and i + 1 < result[0]:
                    result = [i + 1, j + 1]

    return result

def minMovesToBalanceArray(arr, k):
    """
    Returns the minimum number of moves required to make the array balanced or -1 if it is not possible.
    """
    n = len(arr)

    if n < 2:
        return 0

    for i in range(n - 1):
        if abs(arr[i] - arr[i + 1]) > k:
            return -1

    return 0

