def populateNext(root: TreeNode) -> None:
    """
    Populates each next pointer to point to its next right node.
    """
    leftmost = root

    while leftmost:
        curr = leftmost
        prev, leftmost = None, None

        while curr:
            # Establish first child of the next level
            if not leftmost:
                leftmost = curr.left if curr.left else curr.right

            if curr.left:
                if prev:
                    prev.next = curr.left
                prev = curr.left

            if curr.right:
                if prev:
                    prev.next = curr.right
                prev = curr.right

            curr = curr.next

