class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def max_level_sum(root):
    if not root:
        return -1

    max_sum = float('-inf')
    max_level = 0
    current_level = 0

    queue = deque([(root, 0)])

    while queue:
        level_sum = 0
        level_size = len(queue)

        for _ in range(level_size):
            node, level = queue.popleft()
            level_sum += node.val

            if node.left:
                queue.append((node.left, level + 1))
            if node.right:
                queue.append((node.right, level + 1))

        if level_sum > max_sum:
            max_sum = level_sum
            max_level = current_level

        current_level += 1

    return max_level

