def find_kth_missing(arr, k):
    """
    Returns the k-th missing positive integer from the sorted array of unique integers arr.
    """
    current = 1  # The number we are currently checking for missing status
    missing_count = 0  # Counter for missing numbers

    for num in arr:
        while current < num:
            missing_count += 1
            if missing_count == k:
                return current
            current += 1
        current = num + 1  # Move to the next number after the current element in arr

    # If we haven't found the k-th missing number in the range of the array, continue the count
    while missing_count < k:
        missing_count += 1
        if missing_count == k:
            return current
        current += 1

