def longest_substring_with_one_replacement(s: str) -> int:
    """
    Returns the length of the longest possible substring that can be
    achieved by replacing at most one character in `s`.
    """
    n = len(s)
    max_len = 0

    for char in set(s):
        left, count = 0, 0

        for right in range(n):
            if s[right] != char:
                count += 1

            while count > 1:
                if s[left] != char:
                    count -= 1
                left += 1

            max_len = max(max_len, right - left + 1)

    return max_len

