class SubarrayAverage:
    def __init__(self, nums):
        self.nums = nums
        self.prefix_sum = self._compute_prefix_sum(nums)

    def _compute_prefix_sum(self, nums):
        prefix_sum = [0]
        for num in nums:
            prefix_sum.append(prefix_sum[-1] + num)
        return prefix_sum

    def query(self, queries):
        results = []
        for L, R, k in queries:
            find_avg_k = False
            for start in range(L, R + 1):
                for end in range(start, R + 1):
                    subarray_sum = self.prefix_sum[end + 1] - self.prefix_sum[start]
                    subarray_length = end - start + 1
                    if subarray_sum / subarray_length == k:
                        find_avg_k = True
                        break
                if find_avg_k:
                    break
            results.append(find_avg_k)
        return results

