def count_repeated_messages(logs):
    seen_by_session = {}
    freq = {}
    for session_id, message in logs:
        seen_by_session.setdefault(session_id, set())
        if message in seen_by_session[session_id]:
            continue
        seen_by_session[session_id].add(message)
        freq[message] = freq.get(message, 0) + 1

    return sum(1 for v in freq.values() if v >= 2)

def shortest_encoded_length(s: str) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def dp(sub: str) -> int:
        n = len(sub)
        if n < 5:
            return n
        best = n
        for i in range(1, n):
            best = min(best, dp(sub[:i]) + dp(sub[i:]))
        doubled = (sub + sub).find(sub, 1)
        if doubled != -1 and doubled < n:
            repeat = n // doubled
            if repeat * doubled == n:
                best = min(best, len(str(repeat)) + 2 + dp(sub[:doubled]))
        return best

    return dp(s)

def is_balanced(s):
    """
    Determines if the input string s is balanced with respect to parentheses, brackets, and braces.

    :param s: A string containing only the characters '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is balanced, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if not stack or bracket_map[char] != stack.pop():
                return False
        else:
            return False  # In case the string contains characters other than brackets

    return not stack

