def max_subarray_sum(array, m):
    """
    Returns the maximum sum of any subarray of length exactly m.
    """
    if len(array) < m or m <= 0:
        return 0

    max_sum = current_sum = sum(array[:m])

    for i in range(m, len(array)):
        current_sum = current_sum - array[i - m] + array[i]
        if current_sum > max_sum:
            max_sum = current_sum

    return max_sum

