def calculate_event_durations(logs):
    """
    Calculate the total duration of each event.

    Parameters:
        logs (list): List of strings in the format "id status timestamp"

    Returns:
        dict: Dictionary where key is the event 'id' and value is the total duration of the event.
    """
    events = {}
    # Dictionary to store the start time of each event.
    start_times = {}

    for log in logs:
        log_parts = log.split()
        event_id = log_parts[0]
        status = log_parts[1]
        timestamp = int(log_parts[2])

        if status == "start":
            start_times[event_id] = timestamp
        elif status == "end":
            if event_id in start_times:
                duration = timestamp - start_times[event_id]
                events[event_id] = duration

    # For events that have a start time but no end time, set their duration to 0.
    for event_id in start_times:
        if event_id not in events:
            events[event_id] = 0

    return events

def min_operations_to_avoid_consecutive(s):
    """
    Returns the minimum number of operations required to avoid three consecutive identical characters in the string.
    """
    operations = 0
    i = 0

    while i < len(s) - 2:
        if s[i] == s[i+1] == s[i+2]:
            operations += 1
            i += 2
        else:
            i += 1

    return operations

