                stack.append(sign * num)
                num = 0
            elif token == '+':
                sign = 1
            elif token == '-':
                sign = -1
            elif token == '(':
                num = evaluate(tokens)
                stack.append(sign * num)
                num = 0
            elif token == ')':
                break
        return sum(stack)

    # Remove the spaces and convert to list of tokens
    tokens = list(s.replace(' ', ''))
    return evaluate(tokens)

