def count_construct(target, words):
    """
    Returns the number of ways to construct the target using the words from the words array. 
    Each word can be used multiple times.
    """
    memo = {}

    def helper(t):
        if t in memo:
            return memo[t]
        if t == "":
            return 1

        count = 0

        for word in words:
            if t.startswith(word):
                suffix = t[len(word):]
                count += helper(suffix)

        memo[t] = count
        return count

    return helper(target)

