def unique_paths_with_obstacles(obstacle_grid):
    """
    Returns the number of unique paths to reach from the top-left corner to the bottom-right corner,
    navigating through a grid with obstacles.
    :param obstacle_grid: List[List[int]]
    :return: int
    """
    if not obstacle_grid or obstacle_grid[0][0] == 1:
        return 0

    m, n = len(obstacle_grid), len(obstacle_grid[0])
    dp = [[0 for _ in range(n)] for _ in range(m)]
    dp[0][0] = 1  # Starting point

    for i in range(m):
        for j in range(n):
            if obstacle_grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

