def longest_contiguous_sequence(nums):
    if not nums:
        return 0

    max_length = 1
    current_length = 1
    is_increasing = None

    for i in range(1, len(nums)):
        if nums[i] > nums[i-1]:
            if is_increasing is None or is_increasing:
                current_length += 1
            else:
                current_length = 2
            is_increasing = True
        elif nums[i] < nums[i-1]:
            if is_increasing is None or not is_increasing:
                current_length += 1
            else:
                current_length = 2
            is_increasing = False
        else:
            current_length = 1
            is_increasing = None

        max_length = max(max_length, current_length)

    return max_length

class ParenthesisGenerator:
    def __init__(self, pairs):
        self.pairs = pairs

    def generateCombinations(self):
        result = []
        self._generate(self.pairs, self.pairs, "", result)
        return result

    def _generate(self, open, close, current, result):
        if open == 0 and close == 0:
            result.append(current)
            return
        if open > 0:
            self._generate(open-1, close, current + "(", result)
        if close > open:
            self._generate(open, close-1, current + ")", result)

def pacificAtlantic(heights):
    if not heights:
        return []

    m, n = len(heights), len(heights[0])
    pacific_reachable = [[False] * n for _ in range(m)]
    atlantic_reachable = [[False] * n for _ in range(m)]

    directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]

    def dfs(row, col, reachable):
        reachable[row][col] = True
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if (0 <= new_row < m and 0 <= new_col < n and 
                not reachable[new_row][new_col] and 
                heights[new_row][new_col] >= heights[row][col]):
                dfs(new_row, new_col, reachable)

    for i in range(m):
        dfs(i, 0, pacific_reachable)
        dfs(i, n-1, atlantic_reachable)

    for j in range(n):
        dfs(0, j, pacific_reachable)
        dfs(m-1, j, atlantic_reachable)

    result = []
    for i in range(m):
        for j in range(n):
            if pacific_reachable[i][j] and atlantic_reachable[i][j]:
                result.append([i, j])

    return result

