def max_increasing_subsequence_with_diff(arr, k):
    """
    Returns the length of the maximum increasing subsequence with 
    adjacent elements having a difference of at most k.
    """
    if not arr:
        return 0

    n = len(arr)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and arr[i] - arr[j] <= k:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

