def evaluate_boolean_expression(expression: str) -> bool:
    def eval_sub_expression(tokens):
        stack = []
        for token in tokens:
            if token == 'T' or token == 'F':
                stack.append(token == 'T')
            elif token == '!':
                stack.append(not stack.pop())
            elif token == '&':
                right = stack.pop()
                left = stack.pop()
                stack.append(left and right)
            elif token == '|':
                right = stack.pop()
                left = stack.pop()
                stack.append(left or right)
        return stack[0]

    def to_tokens(expression):
        output = []
        stack = []
        prec = {'!': 3, '&': 2, '|': 1, '(': 0}
        for char in expression:
            if char == 'T' or char == 'F':
                output.append(char)
            elif char == '(':
                stack.append(char)
            elif char == ')':
                while stack and stack[-1] != '(':
                    output.append(stack.pop())
                stack.pop()
            else:
                while stack and prec[char] <= prec[stack[-1]]:
                    output.append(stack.pop())
                stack.append(char)
        while stack:
            output.append(stack.pop())
        return output

    tokens = to_tokens(expression)
    return eval_sub_expression(tokens)

