class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def add_child(parent, child, is_left, nodes):
    if is_left:
        parent.left = child
    else:
        parent.right = child
    nodes[child.value - 1] = child

def find_max_depth_node(relations):
    if not relations:
        return -1  # Edge case: no relations, e.g. empty tree input

    nodes = [TreeNode(i + 1) for i in range(max(max(relations, key=lambda x: max(x[:2]))[:2]))]

    for parent_value, child_value, is_left in relations:
        parent = nodes[parent_value - 1]
        child = TreeNode(child_value)
        add_child(parent, child, is_left, nodes)

    def dfs(node, depth):
        if not node:
            return (depth - 1, float('inf'))
        if not node.left and not node.right:
            return (depth, node.value)

        left_depth, left_value = dfs(node.left, depth + 1)
        right_depth, right_value = dfs(node.right, depth + 1)

        if left_depth > right_depth:
            return (left_depth, left_value)
        elif right_depth > left_depth:
            return (right_depth, right_value)
        else:
            return (left_depth, min(left_value, right_value))

    root = nodes[0]
    max_depth, max_depth_node_value = dfs(root, 0)
    return max_depth_node_value

