def four_sum(nums, target):
    """
    Returns all unique quadruplets [a, b, c, d] in `nums` such that a + b + c + d equals `target`.
    """
    nums.sort()
    quadruplets = []
    length = len(nums)

    for i in range(length - 3):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        for j in range(i + 1, length - 2):
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue
            left, right = j + 1, length - 1
            while left < right:
                total = nums[i] + nums[j] + nums[left] + nums[right]
                if total == target:
                    quadruplets.append([nums[i], nums[j], nums[left], nums[right]])
                    while left < right and nums[left] == nums[left + 1]:
                        left += 1
                    while left < right and nums[right] == nums[right - 1]:
                        right -= 1
                    left += 1
                    right -= 1
                elif total < target:
                    left += 1
                else:
                    right -= 1
    return quadruplets

def can_form_strings(unique_words, strings):
    """
    This function checks if all the strings can be formed using permutations of the unique words provided.
    """
    from collections import Counter

    def word_counter(strings_list):
        """
        This function constructs a counter dictionary of letters from a list of strings.
        """
        return Counter(''.join(strings_list))

    # Get a counter for the letters in the unique words
    unique_word_counter = word_counter(unique_words)

    for s in strings:
        if word_counter([s]) != unique_word_counter:
            return False
    return True

