def has_pair_with_difference(arr, x):
    """
    Given an array of integers 'arr' and an integer 'x', find if there exist two distinct elements
    in the array whose absolute difference is 'x'. Return True if such a pair exists, otherwise return False.
    """
    value_set = set(arr)
    for num in arr:
