def closestPalindrome(num):
    """
    Returns the closest integer palindrome to the given number.
    If there are multiple palindromes at the same distance, returns the smaller one.
    """
    if str(num) == str(num)[::-1]:
        return num

    lower = num - 1
    upper = num + 1

    while True:
        if str(lower) == str(lower)[::-1]:
            return lower
        if str(upper) == str(upper)[::-1]:
            return upper
        lower -= 1
        upper += 1

