def evaluate_expression(s):
    """
    Evaluates an arithmetical expression given as a string and returns the result as an integer.
    """
    # Helper function to perform the basic arithmetic
    def operate(a, b, op):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return int(a / b)  # Truncate towards zero

    # Tokenize the string by spaces
    tokens = s.split()
    values = []
    operations = []

    i = 0
    while i < len(tokens):
        token = tokens[i]

        if token.isdigit():
            values.append(int(token))
        elif token in "+-":
            while (operations and operations[-1] in "+-*/"):
                values.append(operate(values.pop(-2), values.pop(), operations.pop()))
            operations.append(token)
        elif token in "*/":
            while (operations and operations[-1] in "*/"):
                values.append(operate(values.pop(-2), values.pop(), operations.pop()))
            operations.append(token)
        elif token == '(':
            operations.append(token)
        elif token == ')':
            while operations[-1] != '(':
                values.append(operate(values.pop(-2), values.pop(), operations.pop()))
            operations.pop()  # Remove '(' from stack

        i += 1

    while operations:
        values.append(operate(values.pop(-2), values.pop(), operations.pop()))

    return values[0]

def min_subarray_length_with_elements(arr, x, y):
    """
    Returns the length of the smallest contiguous subarray of `arr` 
    containing at least one occurrence of both elements `x` and `y`.
    If such a subarray does not exist, returns -1.
    """
    n = len(arr)
    min_length = float('inf')
    last_x, last_y = -1, -1

    for i in range(n):
        if arr[i] == x:
            last_x = i
        if arr[i] == y:
            last_y = i
        if last_x != -1 and last_y != -1:
            current_length = abs(last_x - last_y) + 1
            min_length = min(min_length, current_length)

    if min_length == float('inf'):
        return -1
    return min_length

def has_arithmetic_progression(nums):
    """
    Determines if there are three integers in the array that form an arithmetic progression.
    """
    n = len(nums)
    if n < 3:
        return False

    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                if nums[j] - nums[i] == nums[k] - nums[j]:
                    return True
    return False

