def largest_rectangle(grid):
    """
    Function to find the largest rectangle in a grid where all characters are the same.
    """
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    max_area = 0

    for i in range(rows):
        for j in range(cols):
            char = grid[i][j]
            width = cols

            for k in range(i, rows):
                if grid[k][j] != char:
                    break
                width = min(width, len([x for x in grid[k][j:cols] if x == char]))
                height = k - i + 1
                max_area = max(max_area, width * height)

    return max_area

def longest_k_distinct_substring(s, k):
    """
    Returns the longest substring where the number of distinct characters is exactly k.
    If there are multiple substrings with the same length, return the first one encountered.
    If no such substring exists, return an empty string.
    """
    if k == 0 or not s:
        return ""

    char_count = {}
    left = 0
    max_length = 0
    max_substr = ""

    for right in range(len(s)):
        char = s[right]
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

        while len(char_count) > k:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        if len(char_count) == k:
            if right - left + 1 > max_length:
                max_length = right - left + 1
                max_substr = s[left:right + 1]

    return max_substr

def four_sum(nums):
    """
    Returns a list of unique quadruplets that sum up to zero.
    """
    nums.sort()
    results = []
    length = len(nums)
    for i in range(length - 3):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        for j in range(i + 1, length - 2):
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue
            left = j + 1
            right = length - 1
            while left < right:
                total = nums[i] + nums[j] + nums[left] + nums[right]
                if total == 0:
                    results.append([nums[i], nums[j], nums[left], nums[right]])
                    while left < right and nums[left] == nums[left + 1]:
                        left += 1
                    while left < right and nums[right] == nums[right - 1]:
                        right -= 1
                    left += 1
                    right -= 1
                elif total < 0:
                    left += 1
                else:
                    right -= 1
    return results

