def is_palindrome(s):
    return s == s[::-1]

def max_sum_of_palindromic_substrings(s):
    n = len(s)
    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        for j in range(i):
            if is_palindrome(s[j:i]):
                dp[i] = max(dp[i], dp[j] + int(s[j:i]))

    return dp[n]

from collections import deque

def shortestBridge(grid):
    def in_bounds(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0])

    def dfs(x, y, q):
        grid[x][y] = 2
        q.append((x, y, 0))
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if in_bounds(nx, ny) and grid[nx][ny] == 1:
                dfs(nx, ny, q)

    found = False
    q = deque()

    # Step 1: Find one island and mark it
    for i in range(len(grid)):
        if found:
            break
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                dfs(i, j, q)
                found = True
                break

    # Step 2: Use BFS to find the shortest path to the second island
    while q:
        x, y, dist = q.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if in_bounds(nx, ny):
                if grid[nx][ny] == 1:
                    return dist
                if grid[nx][ny] == 0:
                    grid[nx][ny] = 2
                    q.append((nx, ny, dist + 1))
    return -1

